WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[57646] = { title = "The Tithelord", description = "With his army defeated, the Tithelord is vulnerable. Now, he has but a small contingent to protect him. Let us strike him down decisively. \n\nHe draws power from these anima wells, keeping it all for himself. If you can hold his attention, I can not only empower you to defeat him but also disable the wells.\n\nSpeak to me when you are ready to begin. When the time is right, the baroness will lead our new recruits into battle.", objectives = "Slay The Tithelord and collect the Medallion of Envy.", progress = "An Archlich? This complicates things.", completion = "A Maldraxxus archlich manipulating our Harvesters... This cannot go unanswered.\n\nI am pleased that Baroness Draka is equally eager to strike at Kel'Thuzad directly.\n\nGeneral Draven will ready our armies while Laurent repairs the mirror. Be ready and take these as we prepare. We will ensure vengeance is met alongside our new allies." }
WordHunterWoW_QuestEN[57648] = { title = "The Impossible Plan", description = "Everything is in place for us to seize a necropolis. I will coordinate our efforts and meet you at the Seat of the Primus. \n\nDraka will undoubtedly commend you on your success. I, however, will do so once our mission is complete.", objectives = "Report back to Draka at the Seat of the Primus.", completion = "You've done well, Maw Walker." }
WordHunterWoW_QuestEN[57649] = { title = "Whisper of Hope", description = "Akarek's demise has cast a dark shadow upon our house... but it is in the shadows where we thrive.\n\nI know that not all the Eyes have perished. They could lie in wait, hidden for eternity, if such was demanded of them.\n\nBut it is time to reclaim our destiny. Take my sigil through the wreckage and awaken any Eyes who remain.\n\nWe will seize our victory.", objectives = "Use Vashj's Sigil to rally survivors of the House of Eyes.", completion = "The baroness inspires great dedication. I trust in her plans." }
WordHunterWoW_QuestEN[57650] = { title = "Better Off Dead", description = "Our defense is tenuous at best, but the enemy is still hesitant to attack.\n\nAs long as they fear us, they won't be probing our defenses. \n\nYou must keep the pressure on the enemy.  Attack their positions all along our line.Upon completion of this quest you will gain:", objectives = "Eliminate Enemy forces and positions." }
WordHunterWoW_QuestEN[57651] = { title = "Trouble in the Banks", description = "Ah, be welcome in my glade, Maw Walker. You are safe here.\n\nWhile it is regrettable that Sorcha must wait for her weapons, it is of paramount importance that I keep my charges safe. I will do anything to prevent them from suffering as the rest of Ardenweald.\n\nPerhaps I could ask a small favor of you. I have not heard from the gatherers at the Banks of Life in some time. Would you mind checking on them to make sure they are well? I would go myself, but I must deal with Sorcha. Seek out Foreman Thorodir.", objectives = "Find Foreman Thorodir near the Banks of Life.", completion = "Ah, the Lady sent you? Well, I have some bad news." }
WordHunterWoW_QuestEN[57652] = { title = "Supplies Needed: Amber Grease", description = "Foreman,\n\nOur supply of gris is running low. You know as well as I do that there is no end to Glitterfall Basin's need of it.\n\nI've overheard from some of the other workers that you have a bit of a gorm problem. But the bigger the gorm, the bigger the gris, right?\n\nIf you happen to harvest some more, we can certainly put it to good use.\n\n<The work order is signed: \"Cavina.\">", objectives = "Collect 6 Giant Gorm Gris.", progress = "Do you have something for me?", completion = "It really is a remarkable substance. We use it in practically everything! Construction, mending, crafts, and it can even be added to rations." }
WordHunterWoW_QuestEN[57653] = { title = "Unsafe Workplace", description = "You've returned just in time! Fae are in danger!\n\nIt seems our actions have enraged the gorm. They are even more aggressive than they were before!\n\nWhile some fae were able to evacuate, there are still many who are trapped down there.\n\nTake this jar and slather anyone you find with a generous helping. That should heal their wounds and give them a chance to escape.", objectives = "Heal 10 wounded sylvar in the Banks of Life.", completion = "Thank you for rescuing them." }
WordHunterWoW_QuestEN[57655] = { title = "Supplies Needed: More Husks!", description = "I need more husks, Thorodir! The Lady herself wants to make sure we are outfitted with the finest armor.\n\nThey've been soaking in the waters long enough to be workable. Find some time to retrieve them before our hunters find themselves without adequate protection.\n\n<The work order is signed: \"Cavina.\">", objectives = "Collect 6 Treated Gorm Husks.", progress = "What's that you have there?", completion = "I'm glad you found my note. Husks such as these need to soak in running water for several days before they can be shaped without breaking.\n\nAt least you were able to salvage something." }
WordHunterWoW_QuestEN[57656] = { title = "Gifts of the Forest", description = "These gorm have gone out of control! We need to stop them.\n\nI have a plan, but I cannot do it on my own. We lure the gormlings to the Banks of Life by using special totems that are drained of their anima. If you can retrieve the wood required for the totem, I can prepare the ritual.\n\nTake these pipes. Find the Culex trees growing on the banks and play a song for them. You will recognize them by their pale green leaves. The wood must be given freely for the ritual to work.", objectives = "Collect 3 Culexwood Branches.", progress = "We need that lure for my clever plan. It's very clever, you're going to love it.", completion = "Good. This should do it!" }
WordHunterWoW_QuestEN[57657] = { title = "Tied Totem Toter", description = "Hope you've caught your breath.\n\nThe totem is now a big, tasty beacon to all the nearby gorm. They're going to want to eat it and you're going to be carrying it!\n\nWe need to rehome the smaller ones. If they stay here they're just going to get big and angry again. If you can drop off a few groups of them outside the Banks of Life we can make sure they find their way to more balanced feeding grounds.\n\nLet Thorodir know when you're done. I will let him know the plan.", objectives = "Lure 30 gormlings to the wrangler in the Banks of Life.", completion = "Fluttercatch always was a clever one. Well done." }
WordHunterWoW_QuestEN[57658] = { title = "The Final Leg", description = "Please, I must get to Glitterfall Basin.\n\nI thought I was being careful. I did not realize I was being hunted until it was too late. Such is the nature of the forest.\n\nI am too close to fall here. The Lady herself invited me to come join her. She said I would be safe.\n\nCan you take me to her?", objectives = "Deliver Windchaser to Glitterfall Basin." }
WordHunterWoW_QuestEN[57659] = { title = "Bring Your Friends!", description = "This is only the beginning, friend.\n\nI must thank you again for rescuing me. Now that we have found a safe route, I am but the first of many. Druids from all around Ardenweald have heard of the safety of this glade, and I wish to bring them all here.\n\nI have known Roriel for most of my time in this place. She is a capable healer, despite her appearance. She would be a fine addition to this place.\n\nShe was last seen near Tirna Fein to the west. Please let her know the way is clear.", objectives = "" }
WordHunterWoW_QuestEN[57660] = { title = "The Grove of Creation", description = "I probably would have been digested if not for you. And while that sounds like a fascinating phenomenon, I am glad I did not experience it... firsthand.\n\nYou have a knack for solving problems and you're not afraid to get your hands dirty with our tools. Might I suggest paying a visit to Glitterfall Basin, to the west? It is home to our finest minds and workshops, and I am sure they could use your help in this drought.\n\nThe Lady of the Falls is droman there. She will know where you can best help!", objectives = "Speak with the Lady of the Falls in Glitterfall Basin.", completion = "Master Sha'lor sent you? Such a darling.\n\nNext time you see him you can tell him that it's perfectly safe here." }
WordHunterWoW_QuestEN[57661] = { title = "Silk Shortage", description = "We are running short on silk! We use it for so many things, like instruments, weapons, and tools. But our supply has dried up!\n\nWe are in desperate need for fresh silk.\n\nOur main hub of silk production is in the Gossamer Cliffs. If you could, seek out Caretaker Lillythistle, and see what the holdup is!", objectives = "Find Lillythistle in the Gossamer Cliffs.", completion = "Of course silk shipments have stopped!\n\nThe entire glade has been attacked by changelings and spriggans! Our poor silkstriders are so stressed out, we can't get any silk from them!\n\nCan you help us?" }
WordHunterWoW_QuestEN[57663] = { title = "Blackthorn Blackout", description = "I don't know what caused the Blackthorn to attack, but I can't allow them to just come in here and take over my operation. Think you could help me out? I'll give you a little something for your trouble.\n\nThe Blackthorn Droman has three powerful witches that serve as his enforcers. Take them out and you'll send the tribe into disarray. \n\nOf course, this could just get their leader to show up and make an already bad situation even worse but I'm willing to risk it.", objectives = "" }
WordHunterWoW_QuestEN[57670] = { title = "Unbeelievable Quality", description = "<Now that your harvester has matured, the Honeyback hive is creating additional honey.\n\nSomeone in Brennadam could certainly find a use for this honey.>", objectives = "Take the Collected Tidebloom Honey to \"Nasty\" Buck in Brennadam.\n\nProvided item:", completion = "I don't believe it! Honey from bees instead of those... blobs... at the meadery?\n\nI'll make sure this gets to Raimond." }
WordHunterWoW_QuestEN[57671] = { title = "Meeting Blightcaller", description = "There's no time to rest, <name>.\n\nOur troops are returning from our latest skirmish against the Alliance. Many are dead or severely injured. \n\nOur warchief, the Dark Lady Sylvanas Windrunner, has requested aid in this war against the Alliance.\n\nI recommended you for an operation that is planned. Nathanos Blightcaller is waiting to speak with you.\n\nBefore you go, I'll catch you up on what has happened.", objectives = "Speak with Warleader Breka, then meet Nathanos Blightcaller.", completion = "Hmph, so you're the recruit that saved Breka's son from an island? I thought you'd be taller.\n\nThe Dark Lady has need of capable soldiers. Breka recommended you for this task.\n\n<Nathanos sneers>\n\nWe'll see how long you last." }
WordHunterWoW_QuestEN[57676] = { title = "The Things That Haunt Us", description = "As you will soon learn, a ritual cleansing can be a... painful process.\n\nIn most cases, the upwelling of emotion is harmless. It can even generate anima under the right circumstances.\n\nHowever... sometimes the result is far less pleasant. Negative memories can take a form of their own and manifest in a violent fashion.\n\nI fear Pelagos' attempt at cleansing has brought forth such monsters. You must destroy them, and quickly.", objectives = "Slay 12 memories.", progress = "Is it done?", completion = "The things that bind us can be violent. The insight we gain is no reason to let them run rampant." }
WordHunterWoW_QuestEN[57677] = { title = "A Soulbind In Need", description = "Pelagos is my Soulbind. He is my brother, my closest friend, my mentor, and my student. He knows me completely, and I him. It is a bond stronger than any other.\n\nThat he now struggles is a torment to me, but I am forbidden from intervening. An aspirant must succeed or fail on their own merits, or the trial is forfeit.\n\nI am bound by this law... but you are not.\n\nPlease bring Pelagos back to me. This will not be his last trial. Not when he may finally have a chance.", objectives = "Rescue Pelagos.", completion = "I owe you a great debt, <name>." }
WordHunterWoW_QuestEN[57686] = { title = "The Eternal Traveler", description = "Hail, mortal.\n\nFor untold ages, my kind has traversed the myriad realms of reality. We have beheld phenomena that you cannot begin to comprehend. But there is much you must learn of what awaits you on the horizon.\n\nThe power of Death is on the rise. The veil weakens between your world and the Shadowlands.\n\nWhen a mortal life expires, an echo of it remains behind. The most powerful mortals leave the most resonant echoes.\n\nBring these to me, that I might study them... to both our benefits.", objectives = "Gather Echoes of Mortality from living creatures.", progress = "One can glean so much knowledge from the mortal realm.", completion = "Mortal lives are so fragile... and yet, any one of them can alter the fabric of reality." }
WordHunterWoW_QuestEN[57689] = { title = "Prince Renathal", description = "You! They say you are a Maw Walker. Well, time to put that to the test.\n\nMy master, Prince Renathal, was the one who started the rebellion. He knew Denathrius was working towards something truly nefarious, and attempted to stop him.\n\nThe rebellion failed, and Renathal was flung into the Maw.\n\nI propose you and I venture into the Maw. There is an old device here that only you will be able to use. Together, we can recover my Prince. You need him, if you are to have any hope of success.", objectives = "Enter the Maw to find Prince Renathal.", progress = "Your fighting style lacks... finesse.", completion = "So this is the Maw. I can feel it leeching my essence. Be on your guard." }
WordHunterWoW_QuestEN[57690] = { title = "Cages For All Occasions", description = "Okay, do not lose focus. I can feel Renathal's presence. It is faint but I can sense he is outside of the tower, at least.\n\nCome, let's find him and get out of here.", objectives = "Find Prince Renathal.", completion = "I recognize you. Azeroth has been very busy lately, and her champions have been very much at the forefront of events. We must talk as soon as time allows." }
WordHunterWoW_QuestEN[57691] = { title = "A Royal Key", description = "I am not about to question whatever twist of fate led you to me. Your timing could not be better.\n\nThis cage was custom built to contain me. There is one key, and of course it is on the armor of that large brute over there.\n\nVanquish him and take the key. Be swift, the Jailer's eyes are always on this area.", objectives = "Recover Renathal's Cage Key.", progress = "There was an age when I knew how to pick a lock even this elaborate. Sadly that was so long ago I seem to have fallen out of practice.", completion = "Well, you are quite resourceful. Give me twenty five of your kind and some proper gear and we could defeat the Master." }
WordHunterWoW_QuestEN[57692] = { title = "Prisoner Transfers", description = "While I appreciate the rescue, I am not the only one we must recover. When I was cast in to the Maw, those most loyal to me were also condemned to this place.\n\nUntil recently they were in this camp. I do not know where they were taken but I am sure one of these denizens has a scroll elaborating on their location. The Jailer's forces are nothing if not thorough in their organizational skills.\n\nCan you find the transfer orders?", objectives = "" }
WordHunterWoW_QuestEN[57693] = { title = "Torghast, Tower of the Damned", description = "My allies were taken into the Tower of the Damned, and so we must follow.\n\nI do not think we must venture deep into those halls, which is good as I do not believe either of us is in shape for a fight like that.\n\nCome, let us find our way to one of the most dangerous towers in all of existence.", objectives = "Recover Renathal's Allies from Torghast, Tower of the Damned.", completion = "It is only a matter of time before the Master detects my presence. We must be swift and violent of action if we are to stop Sire Denathrius." }
WordHunterWoW_QuestEN[57694] = { title = "Refuge of Revendreth", description = "Sinfall is more than a ruin. It was once a place of dark magic and experimentation.\n\nWhen the Light retaliated and scorched the Ember Ward, the walls of this place stood. It is fortified, supplied, and filled with secrets. A perfect staging ground for our upcoming conflict.\n\nBut first, take me to meet these allies who led you to Vorpalia. We must take stock of what resources we have to work with.", objectives = "Gather your allies.", completion = "So few left, but we will make do." }
WordHunterWoW_QuestEN[57700] = { title = "Tracking Quest", description = "[PH] I saw some bees tussling over a much larger jelly deposit. It's probably worth bringing one to the Hivemother and seeing what happens.", objectives = "Acquire 1 Rich Jelly and return it to the Hivemother.[PH] I saw some bees tussling over a much larger jelly deposit. It's probably worth bringing one to the Hivemother and seeing what happens." }
WordHunterWoW_QuestEN[57701] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[57702] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[57703] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[57709] = { title = "The Aspirant's Crucible", description = "I have given Kalisthene's words some thought.\n\nIf you are to learn our ways, we should proceed as if you were an aspirant yourself. The next step is to journey through the Aspirant's Crucible.\n\nIt is a place of reflection, training, and cleansing. For an aspirant, it is where they prepare for the long journey ahead. For you... I hope you will learn how you might help us in this time of crisis.\n\nWord of your arrival has likely spread. We will not keep them waiting.\n\nTake my steed, and go in service.", objectives = "Ride Theonara to Aspirant's Crucible.", completion = "<The Forgelite studies you for a moment, then nods.>\n\nWelcome. You are not what we expected, but we are glad to have you nonetheless." }
WordHunterWoW_QuestEN[57710] = { title = "A Life of Service", description = "Curious. You are unlike any aspirant that has come before, that much is certain.\n\nYou will notice that we have an audience. It has been a long time indeed since we welcomed another to the path. We are all eager to see what deeds brought you to us.\n\nSimply approach the dais before you and gaze into the flame. The Watcher will pull forth your memories of those you served in life, and you will be transported back to those moments to aid them once more.", objectives = "Witness memories of your past life.", progress = "Such a display is certain to raise our spirits.", completion = "I confess... I was hoping for a small spectacle to lift the spirits of the aspirants in my care.\n\nI was not expecting to have my own lifted, as well. Thank you for that." }
WordHunterWoW_QuestEN[57711] = { title = "A Forge Gone Cold", description = "I have seen firsthand that you are a most capable soul.\n\nKleia has told me of your purpose here. She has spoken of the hopes she places in you. I am not yet certain if I am ready to do the same.\n\nThere is one small task that I would set before you, however. My forge has grown cold without anima to keep it burning bright. I long to practice my craft again.\n\nMy helper, whom you have met before, can elaborate on our needs.\n\nYou will find Sika near the forge. I will follow shortly.", objectives = "Speak to Sika.", completion = "Hello again! This one is glad to see you!" }
WordHunterWoW_QuestEN[57712] = { title = "Suggested Reading", description = "Greetings. You must be the new aspirant everyone is talking about.\n\nI thought you might like to learn more about us. There are three tomes that would serve you well as a starting point, but they are not currently in the library.\n\nAspirant Leda was the last to hold \"Worlds Beyond Counting.\" Aspirant Ikaran has yet to return \"The Infinite Treatises.\"\n\nIt seems \"Bear Witness: The Watcher's Code\" went missing some time ago. I would search the village.\n\nOnce returned, you can read them at your leisure.", objectives = "Retrieve \"The Infinite Treatises\", \"Worlds Beyond Counting\", and \"Bear Witness: The Watcher's Code.\"", progress = "Did you find the scrolls I suggested?", completion = "I will see that they are returned to their proper places for everyone to enjoy.\n\nI appreciate your help in retrieving them, and I hope they were informative." }
WordHunterWoW_QuestEN[57713] = { title = "The Work of One's Hands", description = "Too long have my hands been idle!\n\n<Forgelite Sophone smiles warmly at you.>\n\nYou cannot know what this means to me, but I might be able to show you. For your aid in restoring my forge, please allow me to craft you a piece of armor.\n\nIt will not be an extravagant affair, but through good works we grow to know ourselves better.\n\nI will need your aid once more. Sika and I will guide you on the specifics. All you need to do is listen and do as instructed.\n\nWhat do you say?", objectives = "Assist Forgelite Sophone in crafting a piece of armor.", progress = "There is no greater pleasure than creating something from nothing.", completion = "I hope you like it. It is far from my finest work, but it will serve you well while you are here." }
WordHunterWoW_QuestEN[57714] = { title = "Assessing Your Spirit", description = "It is clear to all that you are indeed a skilled combatant.\n\nThere is one challenge here that continues to test even the strongest among us. I would have you attempt to best a well-known centurion, beloved by all aspirants. It is called Athanos.\n\nConsider this a test of your spirit.\n\nIf you can withstand this trial, then I will deem you ready for what lies ahead.", objectives = "Challenge Athanos.", progress = "<Kleia watches you impassively.>", completion = "This is always a painful lesson. We do not think less of you for it." }
WordHunterWoW_QuestEN[57715] = { title = "The Archon's Answer", description = "Your cleansing is complete, and you are whole.\n\nOur plan was a success. Undergoing such a rite, so soon after your arrival, has attracted Kalisthene's attention once more. \n\nNow is our opportunity to request an audience with the Archon.\n\nStand before her and be proud of what you have accomplished. No matter what happens now, you have done all that any aspirant could hope to.", objectives = "Speak to Kalisthene.", completion = "You are worthy of Bastion's grace, <name>. May it serve you well." }
WordHunterWoW_QuestEN[57716] = { title = "A Wayward Disciple?", description = "While you are here and as yet unaffected by this--rash of doubt, we shall call it--there is one other errand I would ask of you.\n\nI sent one of the disciples to investigate reports of the fallen fleeing our temple. For their own safety, they must be taken to the Temple of Loyalty.\n\nDisciple Nikolon has yet to return. If he is to be found nearby, it will be near the border of our temple to the north.\n\nPlease, seek him out and ensure that he is not injured or in peril.", objectives = "Locate Disciple Nikolon.", progress = "Have you located Disciple Nikolon?", completion = "Thank you for bringing him to me, <name>. He is in a worse state than any of us might have guessed." }
WordHunterWoW_QuestEN[57717] = { title = "Step Back From That Ledge, My Friend", description = "This disciple... such emotion...\n\n<Eridia stares at Nikolon for a long moment.>\n\nRarely do ascended require such rigorous cleansing, but I cannot deny what is readily apparent. This disciple will fall if I do not intervene.\n\nThere is no time to lose. Come. I will instruct you.\n\n... I only hope we are not too late.", objectives = "Assist Eridia in cleansing Disciple Nikolon.", completion = "<Eridia grips her hammer with pale knuckles.>\n\nHow... how are they so numerous?" }
WordHunterWoW_QuestEN[57718] = { title = "Bound in Stone", description = "Some of our warriors were camped in the small settlement near Guo-Lai when the Baruk invaded the area. Some managed to escape, but they returned with tales of their brothers and sisters in arms being petrified by the mogu stoneshapers into living statues!\n\nWe can't leave our warriors behind! \n\nThe stoneshapers must carry some means to reverse the spell and free them from their stone prisons. Bring our soldiers back!", objectives = "Collect Stoneshaper Rods from Baruk Stoneshapers and use them to free 5 Petrified Warriors in the Ruins of Guo-Lai.", completion = "Your deeds honor us, <name>. \n\nI can't imagine what fate would've befallen our warriors if left to the Baruk." }
WordHunterWoW_QuestEN[57719] = { title = "Dangerous Discourse", description = "<The scroll's runes shift and change as you attempt to read it. At first glance, it appears illegible.\n\nSimilar scrolls have appeared all over the Temple of Purity.\n\nEridia will be interested in these.>", objectives = "Collect 6 Dark Sermons.", progress = "We must defend the temple, <name>.", completion = "These words... this voice...\n\nHow do I know this voice?" }
WordHunterWoW_QuestEN[57720] = { title = "Champions of the Mogu", description = "These lesser clans warring with each other in the Vale need to be taught their place.\n\nSeek out their champions and eliminate them. Show them that only the Rajani have rightful claim here!", objectives = "Defeat 3 rare enemies while the Mogu are invading the Vale of Eternal Blossoms.", completion = "The wayward clans should learn that such fate awaits all that would oppose the Rajani.\n\nTake your reward, outsider. We are done here." }
WordHunterWoW_QuestEN[57721] = { title = "Spoils of War", description = "The warring clans are relentless and our warriors are going through armor faster than I can keep it repaired.\n\nIf you find yourself in battle with the other clans, see if you can salvage any undamaged armor pieces from their soldiers. We should not let good resources go to waste.", objectives = "Collect 12 pieces of Salvaged Mogu Armor from mogu enemies in the Vale of Eternal Blossoms.", progress = "What have you managed to salvage, outsider?", completion = "The wayward clans should learn that such fate awaits all that would oppose the Rajani.\n\nTake your reward, outsider. We are done here." }
WordHunterWoW_QuestEN[57722] = { title = "Empty Stables", description = "Just look at the stables, <name>! Empty! The Stormpike Brigade has no rams to ride - the cavalry is defunct.\n\nYou must help us, soldier. Take this training collar and enter the wilds of this valley. Locate the Alterac rams that roam throughout the area and use the collar to snare one. When you have captured a ram, return it to me and I shall place it in our stable.\n\nWhen we have enough rams, the ram rider commander will be notified. With your help, the cavalry will be reborn!", objectives = "Locate an Alterac Ram in Alterac Valley. Use the Stormpike Training Collar when you are near the Alterac Ram to 'tame' the beast. Once tamed, the Alterac Ram will follow you back to the Stable Master. Speak with the Stable Master to earn credit for the capture.", progress = "Without your help, the Stormpike Ram Riders would not have mounts to ride into battle. You do us a great service!", completion = "The stables will be full in no time at all. Keep up the good work!" }
WordHunterWoW_QuestEN[57723] = { title = "Empty Stables", description = "The war in the valley has taken its toll on our soldiers. We must revitalize our forces!\n\nIf we can fill up the stables, the Wolf Riders will once more be able to ride out into the field of battle.\n\nTake this muzzle and track down the frostwolves that inhabit the nearby forest. Once you find a wolf, use the muzzle to tame the beast. Bring the tamed beast back to me so that I may place it in the stable.\n\nWhen we have enough wolves stabled, the Wolf Riders will rejoin their patrol on our front lines.", objectives = "Locate a Frostwolf in Alterac Valley. Use the Frostwolf Muzzle when you are near the Frostwolf to 'tame' the beast. Once tamed, the Frostwolf will follow you back to the Frostwolf Stable Master. Speak with the Frostwolf Stable Master to earn credit for the capture.", progress = "Without your help, the Frostwolf Wolf Riders would not have mounts to ride into battle. You do us a great service!", completion = "I can only hope that those charged with collecting ram hides are as determined as you, <name>.\n\nAt this rate, we will have the stables full in a matter of hours!" }
WordHunterWoW_QuestEN[57724] = { title = "Securing Sinfall", description = "They're all still active...\n\nThe stoneborn, the gargon, the stone fiends... All of 'em!\n\nDon't got much time. They're always watching.\n\n<Breakfist points up.>\n\nVulca told me to follow that big beam of Light in the sky.\n\nGoes to a tower guarded by a big old brute, though. Couldn't get in.", objectives = "Clear out Sinfall and make it safe for Theotar and the other venthyr.", completion = "Now that we have cleared out the Master's forces, let us continue the search for Prince Renathal!" }
WordHunterWoW_QuestEN[57727] = { title = "Stonevigil Unrest", description = "Greetings, {name}. I'm sure you've met my associate, Baroness Draka.\n\nI have recruited her to help us with the growing threat of the Tithelord.  His involvement with the Maldraxxi renegades is troubling.\n\nOne conspiracy begets another. So I recruited Draka to help us end it.\n\nWe must not treat this situation lightly. We first need to put an end to his oppression of Stonevigil Overlook. That way we can we win over the hearts and minds of his subjects.", objectives = "Meet Prince Renathal and Baroness Draka at Stonevigil Overlook.", completion = "Thank you for your quick arrival, <name>." }
WordHunterWoW_QuestEN[57728] = { title = "Assault: The Endless Swarm", description = "The mantid swarm is surging! There's no way the Golden Lotus will be able to handle this many of them.\n\nWe must do something to drive them back!", objectives = "Drive back the Mantid Assault in the Vale of Eternal Blossoms.", progress = "Are you with me?", completion = "It looks like they're retreating. That was a close one. \n\nThe Vale should be safe, for now." }
WordHunterWoW_QuestEN[57729] = { title = "To the Estate", description = "A window of opportunity has presented itself to us, {name}.\n\nWith his supply line cut off, Vartox dead, and people turned against him, the Tithelord should be no match for us. However, I must admit I do fear what tools he may have acquired from his Maldraxxi cohorts.\n\nHis base of operations is just down the road: the Caretaker's Manor, named for the Harvester whom he replaced.\n\nWe will meet you there.", objectives = "Meet Prince Renathal at The Caretaker's Manor.", completion = "Let us finish what we started." }
WordHunterWoW_QuestEN[57730] = { title = "Zinfizzlex's Portable Shredder Unit", description = "I'm as anxious as you are to try out my portable shredder unit, <race>, but before I can make the kit, I'm going to need materials - lots of materials!\n\nTo be exact, I'm going to need a mountain of thorium, mithril, and iron. I will also need one steamsaw per unit. You'll have to get those at the lumber mill.\n\nWhen I was nosing around in here (before my capture) I noticed a pile of steamsaws at the Frostwolf lumber camp.", objectives = "Master Engineer Zinfizzlex wants you to bring him the following:\n\n*30 Thorium Bars.\n\n*50 Mithril Bars.\n\n*75 Iron bars.\n\n*1 Steamsaw.", progress = "Mountain is a technical term. It's a goblin engineer thing...", completion = "Here you go, <name>. Due to the, um, unstable nature of the jiggamadoos and sprockolozings of the unit, I can only guarantee that it will work for three days. After that..." }
WordHunterWoW_QuestEN[57731] = { title = "Zinfizzlex's Portable Shredder Unit", description = "I'm as anxious as you are to try out my portable shredder unit, <race>, but before I can make the kit, I'm going to need materials - lots of materials!\n\nTo be exact, I'm going to need a mountain of thorium, mithril, and iron. I will also need one steamsaw per unit. You'll have to get those at the lumber mill.\n\nWhen I was nosing around in here (before my capture) I noticed a pile of steamsaws at the Stormpike lumber camp.", objectives = "Master Engineer Zinfizzlex wants you to bring him the following:\n\n*30 Thorium Bars.\n\n*50 Mithril Bars.\n\n*75 Iron bars.\n\n*1 Steamsaw.", progress = "Mountain is a technical term. It's a goblin engineer thing...", completion = "Here you go, <name>. Due to the, um, unstable nature of the jiggamadoos and sprockolozings of the unit, I can only guarantee that it will work for three days. After that..." }
WordHunterWoW_QuestEN[57733] = { title = "Pocketfuls of Silk", description = "The Blackthorn are stealing all of our silk stores. Without that silk it's going to be impossible for us to build any more aether extractors!\n\nSuffice to say, we're going to need to get that silk back!", objectives = "" }
WordHunterWoW_QuestEN[57737] = { title = "Ramkahen Rescue", description = "Mar'at was overrun by those foul K'thir before we could safely evacuate our citizens. \n\nI fear the worst has happened to them.\n\nPlease, if anyone is left alive within the city, tell them to come to Ramkahen.", objectives = "Rescue 6 Mar'at Villagers.", completion = "I appreciate your effort in rescuing our people, <name>." }
