WordHunterWoW_QuestEN[57766] = { title = "War with the Horde", description = "Good to see you've received proper training as a {class}.\n\nWe'll need it for what's next. The Alliance's war with the Horde has reached a fevered pitch... and we've lost a lot of good soldiers.\n\nKing Anduin is looking for aid in an operation to bolster our forces. I told him you'd be a good fit for the job.\n\nBefore you meet him, let me get get you caught up on what has been happening so far.", objectives = "Speak with Captain Garrick to find out what is happening between the Horde and Alliance." }
WordHunterWoW_QuestEN[57768] = { title = "Conquest's Reward", description = "", objectives = "Your prowess on the field of battle is without peer." }
WordHunterWoW_QuestEN[57769] = { title = "Conquest's Reward", description = "", objectives = "Your prowess on the field of battle is without peer." }
WordHunterWoW_QuestEN[57771] = { title = "An Unwelcome Incursion", description = "The Tithelord sent his stoneborn to further reap the anima from these citizens. How long has this been going on? These acts reek of unfathomable greed.\n\nThere is but one answer to this dilemma: to send a message. Crush these oppressors. Drain their anima and return it to Stonevigil's anima well.\n\nThe incursion will be dealt with and the downtrodden's spirits lifted. Two birds, one stone.\n\n<Draka hands you an anima container.>\n\nTake this. I stole it from one of the guards earlier.", objectives = "Drain anima from 12 Stonevigil stoneborn. Then, refuel the anima well in the town center.", completion = "Stone to rubble. \n\nGreat work." }
WordHunterWoW_QuestEN[57772] = { title = "Fangs and Minds", description = "The denizens of Stonevigil have been wrung dry by the Tithelord's greed. \n\nWhile some have taken up arms against these injustices, most are too downtrodden to act. We need them on our side to take him down.\n\n<Prince Renathal hands you a heavy scroll dripping with anima.>\n\nGo, show them the hypocrisy of their oppressor! Send them to me with the promise of sanctuary.", objectives = "Use Renathal's Decree to inspire 8 Stonevigil Citizens.", completion = "More hands for the rebellion. They can taste the truth." }
WordHunterWoW_QuestEN[57773] = { title = "Close to Tears", description = "Our warriors have observed foul manifestations coming forth from numerous void tears within the surrounding jungle. \n\nThey have been but mere weaklings, clearly intended to test our defenses before the real forces arrive.\n\nIf we do not deal with this threat now, however, it will only be a matter of time until we are overrun by their fodder.\n\nFind a way to close those portals!", objectives = "Find and close 3 Void Tears in Uldum.", progress = "Have you had any luck with the portals yet?", completion = "That should help to hold back the tide... for now." }
WordHunterWoW_QuestEN[57774] = { title = "Nine Lives", description = "Scouts have returned recently, nearly on the verge of death, with reports that I find... disconcerting.\n\nNeferset have been spotted wandering the streets of their city to the south.\n\nThis would normally be no cause for alarm, except the Neferset were completely wiped out.\n\nI must ask you to investigate further... and if by some foul magic these reports turn out to be true, you must do whatever you can to contain this threat!", objectives = "Destroy 8 Neferset Denizens.", progress = "Have you news of Neferset City?", completion = "I cannot believe what I am hearing... \n\nThis is truly much worse than I feared." }
WordHunterWoW_QuestEN[57778] = { title = "The Maldraxxian Job", description = "We cannot hope to hold the Seat without a necropolis. Khaliiq reports that Vashj is ready to set her plan in motion.\n\nMeet with her and the other Eyes at Nurakkir. Do what must be done.", objectives = "Meet with Whisperer Vyn at Nurakkir.", completion = "We are pleased to see your return." }
WordHunterWoW_QuestEN[57787] = { title = "Keep to the Path", description = "That's everything on the list for this part of the forest. Lady Moonberry said to meet her in Tirna Vaal. It's just down the road; I'm going to fly ahead so everyone knows to expect you.\n\nJust stay on the path and you won't be eaten. Probably. See you soon!", objectives = "Continue down the road toward Tirna Vaal.", progress = "Hey! You survived!", completion = "Featherlight says you've kept up your end of our deal. That's great to hear!\n\nI have some news to share about getting you an audience with the Queen." }
WordHunterWoW_QuestEN[57816] = { title = "Dreamweaver", description = "Troubled winds sweep across Tirna Vaal. The boughs tremble in concern over the Queen's arrival. All must be as it should be.\n\nDreamweaver's wings droop with the weight of worry. Chaos swirls around the wildseeds under his care.\n\nCalm the churning waters of the grove. Bring harmony to discord and let Dreamweaver flutter once more.", objectives = "Speak with Dreamweaver in the Tranquil Pools.", completion = "You're new, aren't you? Not a fae, not a soul, nor are you bound for a wildseed.\n\nAnd the droman sent you here to help me? Well, this just got very interesting." }
WordHunterWoW_QuestEN[57818] = { title = "Nothing Goes to Waste", description = "The gormlings are industrious creatures. Naturally, they are our source of gorm gris.\n\nGormlings are cute, small, and hungry, like Gloober here! Except he is not hungry right now, because I just fed him. Look at that little belly...\n\n<Ahem>. I digress.\n\nGormlings will be drawn to consume anything that is not brimming with anima. They find it simply delicious. \n\nTake that wildseed there, and bring it into their pen. Then, see if you can get the gormlings to feast upon it!", objectives = "Collect the Depleted Wildseed, place it in the gormling pen, and coax gormlings to eat it.", progress = "Have you fed the gormlings?", completion = "Well done!\n\nThe gormlings may be easily distracted, sometimes, but they are such helpful little creatures.\n\nThat is, when they are small.\n\nThe big ones are a different matter. But don't worry about those! I'm sure we won't have to deal with them." }
WordHunterWoW_QuestEN[57824] = { title = "Collection Day", description = "Now, we can collect the gorm gris for Guardian Kota!\n\nOnce the gormlings have eaten something, we can 'encourage' them to give it back up. What they produce, we call gorm gris!\n\nMy Gormherd Branch should encourage them to do this safely. \n\nGo on, give it a try on good ol' Gloober first.\n\nWhat has me worried is how the other gormlings might behave. They have been acting so strangely lately!", objectives = "Use the Gormherd Branch on Gloober, then collect gorm gris from the Gorged Gormlings.", progress = "I wonder what would happen if I overcharged the Gormherd Branch... would that be more efficient? Or would it make things explode?\n\n... probably explode.", completion = "Oh, this isn't right at all! The gormlings are supposed to return to their normal, adorable little selves.\n\nWhat in the Queen's name is happening to them?\n\nAnd there's no more gorm gris to give to Kota! This won't do at all." }
WordHunterWoW_QuestEN[57825] = { title = "Delivery for Guardian Kota", description = "This is most disturbing, indeed. The gorm are just too... wild, now!\n\nI wonder if the drought is making everything delicious to them, and that is why.\n\nThis isn't enough gorm gris, either. And I do not want to disappoint Kota..\n\nBut, I also don't want to put you through more trouble collecting it. I will go myself into the burrows nearby, to see if I can find any more for her.\n\nWould you take this gorm gris to her for me, please?", objectives = "Deliver the gorm gris to Guardian Kota in Tirna Vaal.\n\nProvided item:", completion = "Master Sha'lor has gone to the burrows himself, to try and find more gorm gris?\n\n... for me?\n\nThat reckless, thick-horned sylvar! He will get himself killed!" }
WordHunterWoW_QuestEN[57850] = { title = "Storied Partnerships", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[57852] = { title = "Dungeon Adventure", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[57853] = { title = "Battleforged Team", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[57860] = { title = "How to Become Forsworn", description = "The Forsworn have taken control of Kalliope's Rest and are looting its antiquities. They must be looking for the Spear of Kalliope, a relic of great power.\n\nTheir numbers are far too great and we are no match. Perhaps there is another way? \n\nA small group of aspirants is removing artifacts from the shrine. If you gather uniform pieces and an insignia from them, we can get you inside the shrine unnoticed.", objectives = "Collect 3 Forsworn Uniform Pieces and a Quartermaster's Insignia from within Kalliope's Rest.", progress = "Do you have everything we need to make a disguise?", completion = "What did you do to this armor? You are a savage, yet effective, fighter it seems." }
WordHunterWoW_QuestEN[57861] = { title = "Just Act Natural", description = "With this disguise you will blend right in. I... know a Forsworn artificer on the inside who should prove useful. You need to remain convincing, however.\n\nThe most important thing is to get to Kalliope's spear before the Forsworn manage to do so. The shrine has many defenses, but it's only a matter of time before they find it.\n\nI am somewhat ashamed. Many of the aspirants here used to be friends. So much has been lost.", objectives = "Find Artificer Ligiea farther into Kalliope's Rest.", completion = "What is it? Don't just mill about.\n\nOh, it's you..." }
WordHunterWoW_QuestEN[57865] = { title = "Ages-Echoing Wisdom", description = "Hmph. Even if I wanted to give her weapons, I cannot. My glade is under attack!\n\nMost of my people were driven out during the attack on the growthworks but a few of the elders stayed behind. Whether to delay the enemy or see the friends to safety, they are not here where it is safe.\n\nEach elder can perform extraordinary works and could make the weapons in no time at all. Rescue the elders and then we'll talk about using their talents for the good of Ardenweald.", objectives = "Locate Elder Gwenna, Elder Finnan, and Groonoomcrooek.", completion = "Good! I am glad you found them alive. Of course, we will be unable to put them to work until the threat is dealt with and they are able to continue their crafts in peace. I'm sure Sorcha will understand." }
WordHunterWoW_QuestEN[57866] = { title = "Idle Hands", description = "If you want my help then you are going to need to help me first.\n\nThere is a group of spriggans that have assaulted the growthworks to the northeast. They are causing all manner of havoc and I simply will not abide this trespass into my lands.\n\nGo there and teach them a lesson. If they will not flee, then slay them on the spot!", objectives = "Slay 12 Brittlebark invaders in the Growthworks.", completion = "Good. It is the way of nature for the stronger to prevail." }
WordHunterWoW_QuestEN[57867] = { title = "The Sweat of Our Brow", description = "Ah, an outsider! You are perfect for this task.\n\nThe spriggans are known for their mischief. They have been cursing our tools and supplies and trapping unsuspecting workers!\n\nLike our curses, they must obey the rules. You'll need shimmerdust for baskets, thread made of gossamer for harps, and minty fresh breath for the soulwebs. How odd.\n\nGood luck and let the Lady of the Falls know when you're done. She'll be delighted to hear it!", objectives = "Disarm 6 trapped tools.", completion = "Cursed tools? And you brought them back? Un-cursed!? I must say, I was not entirely expecting you to be quite so successful." }
WordHunterWoW_QuestEN[57868] = { title = "Craftsman Needs No Tools", description = "Oh, I am quite all right! There's just one little thing....\n\nOne of these fiends made off with my lucky mallet! I simply cannot leave my mallet behind. I do not even use it much any more, but it is quite lucky and I always keep it with me.\n\nPlease, I cannot even think about building anything without it. Do keep an eye out for it, will you?", objectives = "Find Finnan's Lucky Mallet.", progress = "It is small, and quite lucky. I am sure you will know it when you see it.", completion = "Oh, you found it! How lucky, do you see?" }
WordHunterWoW_QuestEN[57869] = { title = "Spirit-Gathering Labor", description = "You are not like the others.\n\nThe waters here carry deep power. Power most have forgotten. But the tirnenn forget very little.\n\nPower flows through the earth just as water flows with power. Flows can be trapped for a time, dripping. Drop by drop they drip into vessels.\n\nSearch for the vessels beneath the falls. Collect the power.", objectives = "Collect 6 River Sediment.", progress = "Drip, drip, go the falls. Drop, drop, goes the power. Power of the earth.", completion = "Much power courses through. We need only the smallest dustings. Your labors please me." }
WordHunterWoW_QuestEN[57870] = { title = "The Games We Play", description = "Do not worry about me. We have a bigger problem.\n\nI heard their leader around here somewhere during the attack. I have been keeping watch from here but I have not been able to see them. They must be using some sort of glamour to hide themselves.\n\nI have yet to meet a spriggan who can resist a game. If you find one eager to play and can win, then perhaps you can learn something about their leader.", objectives = "Win the game of wits by using emotes to correctly answer the Playful Trickster's riddles.", completion = "Very interesting. This will be quite useful." }
WordHunterWoW_QuestEN[57871] = { title = "Outplayed", description = "Now we can strike down their leader, friend.\n\nIt just so happens that I have a large pouch of puffpetal powder right here. Why don't you take it and toss a few handfuls around the workshop floor at the top of the falls? If they are still there, I imagine they will have an... unfortunate reaction.\n\nWhile you do that I will gather the other elders and make our way to Glitterfall Basin. Speak with the Lady when your task is done.", objectives = "Defeat Wicked Wort.", completion = "Ah, the hero of the hour returns! Thank you for liberating my supplies. Our grove desperately needs them in these trying times." }
WordHunterWoW_QuestEN[57872] = { title = "Bring More Friends!", description = "This is only the beginning, friend.\n\nI must thank you again for rescuing me. Now that we have found a safe route, I am but the first of many. Druids from all around Ardenweald have heard of the safety of this glade, and I wish to bring them all here.\n\nI have known Roriel for most of my time in this place. She is a capable healer, despite her appearance. She would be a fine addition to this place.\n\nShe was last seen near Tirna Fein to the west. Please let her know the way is clear.", objectives = "Locate Roriel.This is only the beginning, friend.\n\nI must thank you again for rescuing me. Now that we have found a safe route, I am but the first of many. Druids from all around Ardenweald have heard of the safety of this glade, and I wish to bring them all here.\n\nI have known Roriel for most of my time in this place. She is a capable healer, despite her appearance. She would be a fine addition to this place.\n\nShe was last seen near Tirna Fein to the west. Please let her know the way is clear.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[57873] = { title = "Word from Orsis", description = "As you can see, {name}, we have our hands full here dealing with these disgusting bugs.\n\nOur caravans from the south have stopped arriving and we have received disturbing news from the few who've made it back recently.\n\nI've sent a patrol toward Orsis to investigate; they are past due for a report back.\n\nCan I ask you to check in on them for me?", objectives = "Investigate the situation in Orsis.", completion = "If the sun didn't take me, the bugs surely would have. Thank you <name>." }
WordHunterWoW_QuestEN[57875] = { title = "Mark of Humility", description = "Quartermaster, you've arrived.\n\nThose fools over there still haven't gotten past the first barrier. We need to get into that cave to have any chance at recovering the Spear of Kalliope.\n\nOur research discovered the phrase, \"Only the humble find their way. Even heroes kneel before virtue.\" But those fools have been working on that clue for ages.\n\nGo figure out the problem and get inside that cave. We need its mark to open the final vault.", objectives = "Obtain the Mark of Humility from within the First Chamber of Kalliope.", progress = "Have you acquired the mark?", completion = "Well done, quartermaster. Well done. The Spear of Kalliope is almost within my grasp!" }
WordHunterWoW_QuestEN[57876] = { title = "The End of the Beginning", description = "<Renathal struggles to speak, his wounds evident.>\n\nI knew Denathrius had hoarded anima, but this... this is beyond imagining.\n\nThe Jailer will surely use this power to shatter his bonds. Should he break free of the Maw, all the realms of Death will fall.\n\nWe must continue to press the fight against Denathrius. Alas, we cannot hope to succeed alone.\n \nReturn to Oribos with Draven and speak to the Honored Voice, Tal-Inara. Tell her what you have seen this day and implore her to action.", objectives = "Speak with the Voice of the Arbiter, Tal-Inara, in Oribos.", completion = "We have sensed something horrific has happened. Quickly, tell me everything." }
WordHunterWoW_QuestEN[57877] = { title = "The Looming Dark", description = "It is good you have returned safely from Revendreth, {name}. We sensed a betrayal that has shifted the infinite threads of fate.\n\nThe Maw surges with power. We must know the cause.", objectives = "Reveal the Jailer's plan.", progress = "As the bearer of this news, you must bear this burden as well.", completion = "You have done well. See that you continue to do so." }
WordHunterWoW_QuestEN[57878] = { title = "Choosing Your Purpose", description = "Each covenant is vital to the Shadowlands. Though they often seem at odds with one another, this too is part of the Purpose.\n\nAll the covenants need to grow strong to face the threat of the Jailer. But your efforts cannot be divided. They must be focused upon a single path. Other mortals may make a different choice.\n\nThe time has come for you to take a side. \n\nSpeak to your allies. Then make your choice at the map of the Shadowlands before me.", objectives = "Speak to the Covenants. Decide how your path is entwined with the Purpose.", progress = "Have you made your decision yet?", completion = "All is as expected. Trust always in the Arbiter's plan." }
WordHunterWoW_QuestEN[57880] = { title = "An Estate Within the Old Gate", description = "I believe I know how we can obtain the Countess's medallion and avoid making any new enemies.\n\nBefore being cast out into the Light, I held a prominent position within the Countess's court. She bestowed upon me an estate with direct access to her private chambers. \n\nIf the estate still stands, you can use it to sneak into the Countess's manor and steal the medallion without ever drawing your weapon. \n\nTake this note to my trusted butler, Bogdan. He will provide whatever assistance you need.", objectives = "Deliver Theotar's Note to Bogdan within the Old Gate.", progress = "What is this? A note from the Duke?", completion = "<Bogdan reads the words quickly, his eyes welling with tears as a smile spreads across his face.>\n\nThe Duke lives? What splendid news!" }
WordHunterWoW_QuestEN[57881] = { title = "The Key to Rebuilding", description = "If we plan to revive the estate, we'll first need the keys!\n\nWhen Theotar was exiled to the Ember Ward, he lost all titles and property, meaning that the estate fell into the hands of another aristocrat. \n\nThe new owner is a mystery to me, but household staff almost always carry keys on them as they do their business within the Old Gate. \n\nRecover the key and we'll be on our way to rebuilding the manor.", objectives = "Recover an Ornate Key from Redelav house staff within the Old Gate.", progress = "Have you recovered the key?", completion = "Ah, this is it! We should have no trouble accessing the manor now." }
WordHunterWoW_QuestEN[57882] = { title = "Reestablishing the Household", description = "Unfortunately, when ownership of the estate changed hands, the staff were all displaced and forced to find new work. Some of us found suitable roles within favorable households. After all, everyone needs a sommelier! \n\nOthers were not so lucky. They're still here in the Old Gate, taking odd jobs to survive. I'm sure they'll be eager to work for the Duke again once they learn we're reestablishing the household.\n\nSeek them out and present this offer of employment.", objectives = "Deliver offers of employment to Dumitra, Elena, and Florin.", completion = "Don't worry about Florin. He'll come around." }
WordHunterWoW_QuestEN[57884] = { title = "Reclaiming Thornhill Manor", description = "I've done some digging and discovered that Viscount Nicolae is the new inhabitant of Thornhill Manor. \n\nA vile thing, he is. It'll take us weeks to rid the estate of his stench!\n\nHopefully, you can rid us of him in a much timelier fashion. \n\nI'll gather the rest of the staff and together we can reclaim Thornhill Manor.", objectives = "Kill Viscount Nicolae and reclaim Thornhill Manor.", progress = "I cannot stand the thought of someone else occupying Thornhill Manor.", completion = "Why would our lady choose such a lout as her paramour? Regardless, Thornhill Manor is ours once again." }
WordHunterWoW_QuestEN[57885] = { title = "A Discreet Entrance", description = "I can assure you--this is not how we left the place. Never would we ever let the manor fall into such a state. \n\nAt least the mirror is still intact, that's what's important. You can use it to enter the Countess's private chambers discreetly and recover the medallion. \n\nGo, quickly, before word spreads of what we've done. We'll do our best to restore the manor while you're gone.", objectives = "Enter the Countess's chambers by using the ornate mirror.", completion = "How nice it is to finally come face to face with the revered Maw Walker." }
WordHunterWoW_QuestEN[57886] = { title = "A Meal and A Deal", description = "Even though you arrived here uninvited, you weren't unexpected. I know all that goes on within my district. \n\nAs such, let us share a meal and speak of the matters at hand.\n\nI believe there's a way in which we can both get what we want.", objectives = "Enjoy The Countess's hospitality while listening to her proposal.", progress = "Please, enjoy my hospitality.", completion = "So, we have a deal then?" }
WordHunterWoW_QuestEN[57887] = { title = "Killing the Messenger", description = "I make it my business to know what is going on within my district. \n\nTraditionally we use stone fiends to relay messages, but my informants have alerted me to some suspicious communications going on within the Old Gate. \n\nA venthyr has been hired to run missives between two undisclosed parties. When someone puts that much effort into concealing their identity, it can never be good.\n\nFind this courier and recover whatever missives they might be carrying.", objectives = "Recover a Treasonous Missive from a Redelav Courier.", progress = "Has it been done?", completion = "<The Countess maintains a stoic expression as she carefully scans the missive, her grip tightening the longer she reads.>\n\nThis letter was penned by Andrei of House Iremoore. I'd know that scrawl anywhere. And it would appear he's plotting to overthrow me." }
WordHunterWoW_QuestEN[57888] = { title = "An Invitation to Treachery", description = "While the missive made it clear that Andrei is displeased with my position, nothing in the letter identifies his co-conspirator. \n\nAll we really know is that they are trying to gain access to my soiree this evening so they can carry out their plans. Let's make it easy for them, shall we? \n\nHead into the Redelav District and deliver an invite to the prominent houses. This way, we'll be sure the traitors show up.", objectives = "Deliver invitations to each of the noble houses within the Redelav District.", completion = "No one will be able to turn down an invite to one of my infamous soirees." }
WordHunterWoW_QuestEN[57889] = { title = "\"Accidental\" Arson", description = "It's no use trying to get Andrei to tell us who he's working with. He won't talk, and we can't risk alerting his accomplice. \n\nWe need to get rid of him, and it needs to look like an accident. \n\nOnce Andrei's been dealt with, set fire to his rug and let the whole estate burn down.  \n\nAndrei isn't someone you want coming into power. He's as ruthless as he is cruel.", objectives = "Kill Lord Andrei and set fire to his estate.", completion = "You're quite thorough, aren't you? I can see the flames from here. While you were out I took the liberty of having some proper leg wear altered to fit you. I am sure I have you sized up properly." }
WordHunterWoW_QuestEN[57890] = { title = "Beautiful, But Deadly", description = "The Redelav District is home to the most affluent venthyr in all of Revendreth. Its denizens spare no expense on the upkeep of their extravagant gardens.\n\nWell worth the effort, I must say. For the Redelav District is the only place where Duskmire mushrooms can grow. They are as beautiful as they are deadly.\n\nWould you mind collecting a few? Their uses are varied, and it's always a good idea to have some on hand.", objectives = "Collect 50 Duskmire Mushrooms from gardens within the Redelav District.", progress = "Do you have the mushrooms?", completion = "<The Countess inspects the mushrooms with a wry smile.>\n\nA rich color means the spores will be potent." }
WordHunterWoW_QuestEN[57891] = { title = "Mix, Mingle, and Meddle", description = "Once the party begins, I will be occupied with a plethora of nobles that wish to cling to my side. \n\nThis is why I need you to mingle. Speak with the attendees and see if you can determine which house is conspiring against me. \n\nBe warned, invited guest or not, these aristocrats can smell an outsider. You won't receive a warm welcome from everyone.", objectives = "Attend the Countess's soiree and speak with guests to uncover the traitorous house.", progress = "One among my guests is the traitor. I need you to find out who.", completion = "Have you identified the traitorous house?" }
WordHunterWoW_QuestEN[57892] = { title = "Enacting Immediate Justice", description = "There are likely many in attendance who wish me harm. \n\nI trust you have done your job in determining which house has been working with Andrei?\n\nOnce they are named, I trust you will enact immediate justice.", objectives = "Name the traitorous house and enact justice.", progress = "The traitorous house will be uncovered and swiftly dealt with.", completion = "Justice has been served, and an uprising quelled." }
WordHunterWoW_QuestEN[57893] = { title = "Neither Enemy nor Ally", description = "I hope you now see the importance of the role I play. \n\nMy parties serve a greater purpose. Keeping the influential and elite entertained helps quell uprisings. If their minds are consumed by trivial things, they don't have time to plot or plan. \n\nSometimes, battles are best fought before they begin. Giving you my medallion is an example of that. \n\nWe may not be allies, but we are not enemies, either.", objectives = "Deliver the medallion to Prince Renathal in Sinfall.", progress = "Have you secured the medallion?", completion = "The Countess gave it up without a fight? We might have an ally in her yet..." }
WordHunterWoW_QuestEN[57895] = { title = "Elysian Hold", description = "One more step yet remains before your initiation is complete.\n\nYou must now enter Elysian Hold, entryway to the rest of the Spires of Ascension and the vantage point from which the ascended safeguard Bastion and our aspirants in training.\n\nOnce there, we shall ensure you are fully acquainted with the hold's offerings. Since you lack wings, I shall escort you there.", objectives = "Travel with Polemarch Adrestes to Elysian Hold.", completion = "Welcome home, <name>." }
WordHunterWoW_QuestEN[57897] = { title = "Dangerous to Go Alone", description = "There is one last thing you must do before we can act to clean up Denathrius's chaos.\n\nYou must have a soulbind.\n\nAll kyrian undergo this sacred ritual--albeit typically many aeons before they stand before the Archon herself.\n\nSoulguide Daelia will guide you in this process. Seek her out in the chamber below.", objectives = "Speak with Soulguide Daelia in the Sanctum of Binding.", completion = "I see even now that your soul burns brighter than most." }
WordHunterWoW_QuestEN[57898] = { title = "Soul Meets Body", description = "To soulbind with another is not an irrevocable bond. However, it is not to be entered into lightly.\n\nYou will experience one another's pasts. Your hopes, fears, dreams, your very memories--if any still linger. You will become kindred spirits in the truest sense.\n\nOnce complete, your connection will transcend physical space and make you stronger in more than mere brawn.", objectives = "Complete the soulbinding ritual.", progress = "Take your time. This is a significant step in your journey to ascension.", completion = "Your journey together is just beginning." }
WordHunterWoW_QuestEN[57899] = { title = "More Work?", description = "Your world has a saying that \"you cannot be in two places at once.\"\n\nWithout a soulbind, that is true. Thankfully we have resolved that matter. Such physical limitations are a mortal construct.\n\nChristen our newest addition to the Hold in the ramparts above, then seek out Koros and you will see.", objectives = "Activate the Command Table.", completion = "I am Koros, head communicator of the hold. A pleasure." }
WordHunterWoW_QuestEN[57900] = { title = "Across the Shadowlands", description = "As kyrian we are responsible for ensuring that every last soul that enters the Shadowlands is sent to their appropriate eternity.\n\nHowever, our eternal charge does not end in Oribos.\n\nThere are countless matters in the Shadowlands that need attention--far more than any one of us can handle. That, my friend, is where I come in.\n\nConsider me your eyes in the field. Allow me to demonstrate with a simple task, so that you may both reap the benefits of my services.", objectives = "Use the Command Table to start an adventure.", progress = "Good things are worth waiting for.", completion = "You see, my mortal friend, it truly is that simple!" }
WordHunterWoW_QuestEN[57901] = { title = "All That Remains", description = "Just as you must work with your soulbind in an eternal partnership to ensure peace in our realm, so must you work to restore the flow of anima in the sky above.\n\nCapheus, one of the great Mikanikos's students, has specialized in the craft of directing what anima we have to the temples that need it most.\n\nGiven the great drought of anima that plagues us if anyone could use assistance, it would be her.", objectives = "Activate the Anima Conductor.", progress = "Yes, yes, you! You can help!", completion = "The others speak of you! Come! Let me know you too!" }
WordHunterWoW_QuestEN[57903] = { title = "Power in the Sky", description = "This device you see here can be used to send anima to our temples and aid our people.\n\nAs each temple regains its flow of anima, it will begin to function once more. You may find these functions useful in your journeys, or you may even find new challenges that await you.\n\nOnce you have brought some anima to our sanctum, use the device to direct it to a temple, and see the results for yourself.", objectives = "Use the Anima Conductor to channel anima to a location in Bastion.", progress = "Does the anima flow?", completion = "Good, anima is flowing again. You will want to return to the device periodically and channel more anima.\n\nAs you gather more anima and channel it into Bastion, the flows will grow stronger. Though they will not last for long right now, eventually you will be able to reinforce the channel, making a permanent connection.\n\nOnce, the skies of Bastion were alight with the flows of anima. With your help, they will be again." }
WordHunterWoW_QuestEN[57904] = { title = "Our Eternal Charge", description = "You have been fully inducted into our sacred covenant, Maw Walker, and may stand tall forevermore as a kyrian. There will be many challenges ahead of us--we shall face them together.\n\nFor now, return to Polemarch Adrestes and inform him that your training is complete. We are few in number as of late and I am sure he will have need of you. \n\nGo in service, {name}.", objectives = "Return to Polemarch Adrestes.", completion = "On behalf of our glorious Archon, may you follow the path always towards a brighter tomorrow." }
WordHunterWoW_QuestEN[57905] = { title = "A Unique Opportunity", description = "All the anima in the Shadowlands will not restore Elysian Hold to its full glory without willing souls to ensure its many capabilities function properly.\n\nSoulguide Daelia is one of our most veteran watchers. She has been tasked with bringing souls to these halls once more.\n\nYou should pay her a visit within the Sanctum of Binding to see if you might be of aid.", objectives = "Speak to Soulguide Daelia in the Sanctum of Binding.", completion = "Your arrival is most timely, Maw Walker." }
WordHunterWoW_QuestEN[57908] = { title = "The True Crucible Awaits", description = "I confess, {name}. I had little hope when you first arrived.\n\nKleia is convinced that your presence here is a sign of things finally improving in Bastion. I was... skeptical.\n\n<The Forgelite gestures to her forge.>\n\nWhat you have done for me will not soon be forgotten. There is a path beyond the Crucible. To walk it, you must overcome a trial. It will be difficult. Such a thing takes eons for most.\n\nYou are not most.\n\nKleia and Pelagos will tell you more. They await you near the sparring grounds.", objectives = "Speak to Kleia and Pelagos in Aspirant's Crucible.", completion = "The Forgelite's gratitude goes deeper than you know.\n\nNow. You must turn your attention back to our purpose here." }
WordHunterWoW_QuestEN[57909] = { title = "Assessing Your Stamina", description = "The trial ahead will test you on many levels. I, like Kleia, wish to assess your willingness to endure.\n\nLook around you. All the aspirants here train for the very trial you are to attempt. Some have been here, honing their skills, for centuries. Ages. Some grow quickly, some do not.\n\nYour task is to engage them in friendly, armed combat. Among the kyrian this is known as a combat meditation.\n\nHelp them find focus, and they shall help you do the same.\n\nReturn to me when you feel ready to continue.", objectives = "Participate in 8 combat meditations.", progress = "Trust in the process, <name>.", completion = "To fight so many, in so short a time, is truly a feat of stamina.\n\nI am tired just looking at you.\n\n<Pelagos laughs.>" }
WordHunterWoW_QuestEN[57912] = { title = "Baron of the Chosen", description = "Our forces at the Spearhead are under siege from Margrave Gharmal's vanguard. If Vyraz himself is leading the defense, then the situation must be dire.\n\nThe House of Constructs shapes flesh to forge bodies for its forces. They were once an indispensable ally, but have become a fearsome enemy.\n\nMargrave Krexus trusts your might. No doubt you will have need of it.", objectives = "Meet with Baron Vyraz at the Spearhead.", completion = "I expect much of you, mortal. Help lead our frontal assault on the construct forces!" }
WordHunterWoW_QuestEN[57914] = { title = "Mark of Knowledge", description = "There is another matter for which I need your assistance. My researchers and interrogators have been tirelessly working on the second chamber. So far they don't have any leads.\n\nI need you to speak to them and see if they've made any progress. Tell them, if they have nothing to show, then they will soon find themselves at the end of my sword.\n\nGet me that mark, quartermaster!", objectives = "Obtain the Mark of Knowledge.", progress = "Did you bring the mark? If not, then why are we speaking?", completion = "One step closer to my goal." }
WordHunterWoW_QuestEN[57915] = { title = "Search for Survivors", description = "The bugs came from everywhere... There wasn't any time to react.\n\nMany of my friends died where they stood, while others tried to fight with our meager tools.\n\nI'm a coward. I fled in the commotion instead of trying to help.\n\nNow, here I am, out of food and water and too scared to look for survivors.\n\nPlease, I beg you to help anyone you find left alive in Orsis...", objectives = "Check 8 Wastewanders in Orsis.", completion = "I am in no shape to face those creatures right now. I appreciate your help <name>." }
WordHunterWoW_QuestEN[57917] = { title = "[DNT] Test - JAM", description = "", objectives = "" }
WordHunterWoW_QuestEN[57918] = { title = "The Absolution of Souls", description = "Do you not yet understand the purpose of Revendreth, Maw Walker?\n\nThe souls under our care teeter on the brink of permanent damnation. Even with perfect attention and careful processing, not every soul can escape the Maw and be elevated to a higher destiny.\n\nThat is true under the best of circumstances.\n\nCurrently, due to your installation of the Chamberlain at the Halls of Atonement, we're instead witnessing the worst of circumstances.\n\nWe must return to the Halls of Atonement and enforce order.", objectives = "Meet the Accuser at Absolution Crypt.", completion = "It is worse than I feared." }
WordHunterWoW_QuestEN[57919] = { title = "An Abuse of Power", description = "The souls have suffered tremendously under the Lord Chamberlain.\n\nWe venthyr subjugate souls to our will so that we may lead each to the absolution it requires--willing or not.\n\nThe Lord Chamberlain, however, has been using our relics and rituals to abuse the souls under his authority. He binds the souls to their sinstones, perverting their very essence!\n\nUse these ritual chains on the abused soul and subjugate it to your will. We must attempt to absolve it.", objectives = "Subjugate the Abused Soul.", progress = "Every lost soul is a tragedy.", completion = "That soul is now lost forever. Such wasted potential...\n\nThe Lord Chamberlain will answer for this offense." }
WordHunterWoW_QuestEN[57920] = { title = "The Proper Souls", description = "We must save as many souls as we can from the fate we have just witnessed.\n\nSearch the halls for souls who have escaped the Lord Chamberlain's perverse rituals. Subjugate them and bring them to me inside the Halls of Atonement.\n\nTogether, we will make certain that each soul is appropriately processed and cared for.", objectives = "Subjugate 4 Fugitive Souls and deliver them to the Accuser.", progress = "If even one soul can be saved, it is worth it.", completion = "Every lost soul must be tended to." }
WordHunterWoW_QuestEN[57921] = { title = "The Proper Tools", description = "There are very specific procedures that we must follow to best tend to the souls under our care. You and I will follow them exactly.\n\nI can mask your garish appearance, but you must acquire the necessary ritual tools on your own.\n\nRequisition them from the depraved venthyr serving the Lord Chamberlain nearby.", objectives = "Collect Venthyr Ritual Robes, Dagger, and Tome.", progress = "We will do this the proper way.", completion = "Good. You are ready for the ritual." }
WordHunterWoW_QuestEN[57922] = { title = "The Proper Punishment", description = "Thankfully, I am not the only one who remembers the high calling of the Halls of Atonement and its servants.\n\nThese avowed ritualists have been working covertly to preserve the integrity of the halls.\n\nThey report that the Lord Chamberlain relies on a particularly gifted soulflayer to teach other ritualists how to corrupt the souls.\n\nGive him the reward he deserves.", objectives = "Kill Fata the Soulflayer.", completion = "His just reward would be the Maw, but this will have to do." }
WordHunterWoW_QuestEN[57923] = { title = "Ritual of Absolution", description = "The ritual of absolution is a sacred rite that forces souls to discard the burdens of their mortal lives.\n\nThe soul must be a willing participant if the ritual's effect will be meaningful and long-lasting. We often spend ages preparing a soul for a single absolution ritual.\n\nThe Lord Chamberlain has neglected his duty. These souls are overdue for absolution, practically bursting with anima.\n\nWe will perform the ritual ourselves, and hurry these souls along their journey.", objectives = "Help the Accuser complete the ritual of absolution.", progress = "Absolution is where mercy meets justice.", completion = "Absolution does not come easy. Nor should it." }
WordHunterWoW_QuestEN[57924] = { title = "Ritual of Judgment", description = "After all rituals of absolution are complete, each soul must face its final judgment in Revendreth.\n\nThere are three potential verdicts:\nIf proven unworthy, it is condemned to the Maw for eternity.\n\nIf fully absolved of its sins, it is either elevated to a venthyr or returned to the Arbiter to be assigned its new destination.\n\nOur most sacred ritual, the judgment, determines this fate.\n\nOne such ritual is happening now. I will disguise you and we will participate to ensure a just verdict.", objectives = "Participate in the ritual of judgment.", completion = "I sacrificed more than you realize to save this soul.\n\nI would do it again, because it is right. Do you understand yet?" }
WordHunterWoW_QuestEN[57925] = { title = "Archivist Fane", description = "Well, our disguises are superfluous now. We will not be welcome after disrupting their depraved ritual.\n\nDespite what we've observed here, some steadfast venthyr do still remain within these halls. Those who have not forsaken our vocation, and carry on with our calling.\n\nArchivist Fane is one such as these. Aid his endeavors however you can. We will need his insight to loosen the Lord Chamberlain's grip over these halls.\n\nI must tend to Gresit. He has much to learn.", objectives = "Introduce yourself to Archivist Fane.", completion = "Some very angry judges recently passed through here.\n\n<Archivist Fane grins.>\n\nTell me everything you did to antagonize them. Don't skip a single detail!" }
WordHunterWoW_QuestEN[57926] = { title = "The Sinstone Archive", description = "You said Inquisitor Traian oversaw the ritual?\n\n<Archivist Fane searches the massive archives in this chamber.>\n\nWe archivists maintain strict records of every soul that passes through these halls.\n\nOr at least we're supposed to. The sinstones of powerful venthyr tend to go \"missing.\"\n\n<Archivist Fane rolls his eyes.>\n\nI don't see his sinstone here. He might've stolen it, or someone could be hoarding it as blackmail.\n\nHelp me complete my archives, and I'll get you any sinstone you need.", objectives = "Collect 100 Sinstone Records.", progress = "Sinstones are the most powerful weapon in Revendreth.", completion = "<Archivist Fane's eyes light up when you hand him the archives.>\n\nThis is a lot of potential leverage..." }
WordHunterWoW_QuestEN[57927] = { title = "Rebuilding Temel", description = "Revendreth demands penance from all, and it would appear that even you are not exempt.\n\n<Cryptkeeper Kassir grins.>\n\nDo not fear, I have no intention of exacting revenge for the violence you inflicted upon me.\n\nBut I cannot offer you Temel either.\n\nThe Lord Chamberlain--who you so wisely chose to install as master of these halls--deemed Temel a threat to his control.\n\nHis thugs bashed Temel to bits and scattered the pieces among these crypts. It's not the first time I've had to rebuild him.", objectives = "Collect Temel's Head, Body, and Wings.", progress = "No matter how broken Temel is, I can rebuild him.", completion = "<Cryptkeeper Kassir inspects the pieces of Temel you brought him.>\n\nThey bashed you real good, didn't they, Temel? Nothing I cannot fix..." }
WordHunterWoW_QuestEN[57928] = { title = "Atonement Crypt Key", description = "<This key is marked with a sigil that matches the crypts in the Halls of Atonement. What is the Lord Chamberlain hiding away in there?>", objectives = "Open an Atonement Crypt.", completion = "The atonement crypts are meant to be used as storage for souls who require additional... processing before their next ritual.\n\nThe Lord Chamberlain's idiots are using them like prison cells and treasure rooms. You are doing us all a favor by opening them whenever you find a key." }
WordHunterWoW_QuestEN[57929] = { title = "Hunting an Inquisitor", description = "You may have noticed that inquisitors are protected by the Lord Chamberlain's magic. A potent consequence of wielding the Master's medallion.\n\nBut now that we have access to Inquisitor Traian's sinstone from the archives, we have the power needed to break through those defenses.\n\nLocate the inquisitor, and order Temel to read out from his sinstone. Declaring the true name and sins of the inquisitor will shatter his defenses and make him vulnerable for a short window of time.\n\nBe ready to strike.", objectives = "Kill Inquisitor Traian.", progress = "Truth, wielded properly, is a potent weapon.", completion = "Decorous and deserved.\n\nI hope this will be the first of many corrupt inquisitors we fell together." }
WordHunterWoW_QuestEN[57931] = { title = "Phalynx Malfunction", description = "As part of their training, I order my phalynx units to march the fields, keeping an eye on the wildlife and any goings-on.\n\nUnfortunately, last time they returned they were one fewer in number.\n\nPlease search the Golden Pasture and search for the missing unit, then return it here.", objectives = "Find Gatamatos in the Golden Pasture and return him to his pedestal in Forgefire Outpost.", progress = "My phalynx units require occasional repairs to keep them operational. If one is overlooked, it may malfunction.", completion = "This unit seems to be malfunctioning. We will have to perform some repairs." }
WordHunterWoW_QuestEN[57932] = { title = "Resource Drain", description = "Usually repairs easy. Anima everywhere!\n\nExcept drought means we can't just pull it from air. Other sources needed!\n\nTake this. Drain anima from cloudstriders. Not ideal, but desperate times.", objectives = "Drain anima from Gilded Cloudstriders 5 times.", progress = "Drought has big effects. Feel bad for cloudstriders.", completion = "This is enough to repair Gatamatos, and then some!" }
WordHunterWoW_QuestEN[57933] = { title = "We Can Rebuild Him", description = "Gatamatos needs numerous repairs to meet functional standards.\n\nUpkeeping phalynx is part of the role. Lend a hand so we may finish the repairs thoroughly and quickly.", objectives = "Aid Pelodis in repairing Gatamatos.", progress = "As long as you keep your phalynx in working condition, they will obey without hesitation.", completion = "He may appear to be returned to perfect shape, but he must be re-tested and trained." }
WordHunterWoW_QuestEN[57934] = { title = "Combat Drills", description = "Our phalynx units excel in combat. They are thoroughly trained in taking foes down by the legs, as well as hunting down beasts gone awry.\n\nI need you to take stock of Gatamatos's fighting routines. Take him into the cavern below and practice his combat against the wyrms there.", objectives = "Kill 8 Agitated Etherwyrms in the Hall of Beasts with Gatamatos.", completion = "Excellent. His combat routines are acceptable." }
WordHunterWoW_QuestEN[57935] = { title = "Laser Location", description = "Phalynx have precise detection mechanisms that allow for excellent scouting.\n\nIn the cave below we have scattered gems that our units are trained to locate. Escort Gatamatos to run some drills and recalibrate his training.", objectives = "Bring Gatamatos to the Hall of Beasts, then direct him to locate 6 Training Gems.", progress = "The technical process behind phalynx tracking and locating their targets is quite fascinating.\n\nHowever... you do not seem the type who is interested in the details.", completion = "I would like to see a larion track that accurately!" }
WordHunterWoW_QuestEN[57936] = { title = "Superior Programming", description = "Phalynx listen to their orders. Never disobey!\n\nLarions are wild beasts. Can attack. Could eat a steward, probably!\n\nUntamed larion lives close. Has chased many stewards, very scary! Please take care of it.", objectives = "Kill Leonid in the Hall of Beasts.", progress = "Wild beasts. Terrifying! No thank you! I work with very safe phalynx.", completion = "Can be at peace, no wild larion to eat me. Hoo..." }
WordHunterWoW_QuestEN[57937] = { title = "Tactical Formation", description = "The principal step of our training regiment for our phalynx is formational drills. They must recall standard kyrian battle formations, and how to flow from one to the next.\n\nFormational training is the final piece of information that Gatamatos is still missing. Please aid in retraining him.", objectives = "Aid Gatamatos in taking the correct position in three formations.", progress = "A good soldier marches in order.", completion = "And with that, I believe that Gatamatos is once again functioning at standard.\n\nThank you for your aid." }
WordHunterWoW_QuestEN[57947] = { title = "Spirits of the Glen", description = "Animals of the forest, mortal souls given form, frolic in the glen. Their anima, a boon to the weald, given freely as rain on the leaves.\n\nBut danger lurks in the shadows. A dark storm of malice and enmity tears at the trees. Creatures seeking shelter find only peril.\n\nRescue them.", objectives = "Find Choofa in the Spirit Glen.", completion = "What's this? What's this?\n\nThe Tall Tree has sent you to help us? Help us!" }
WordHunterWoW_QuestEN[57948] = { title = "Nothing Left to Give", description = "Oh no, oh no!\n\nMy friends, they gave so much. So much of their anima, they lost their forms! We all take a form when we come here, you see. Something that suits us!\n\nBut we give our anima, we give! To help the groves. And we give so much... sometimes too much.\n\nI still have some anima. I still have my form! Get me to my friends! We can get THEIR forms back!", objectives = "Restore soul shapes to Slanknen, Rury, and Awool in the Spirit Glen.", progress = "Oh dear, oh dear. My friends are in trouble!", completion = "You found them! You found my friends! They have their forms!\n\nNow we have one last thing to do. One last thing!" }
WordHunterWoW_QuestEN[57949] = { title = "They Need to Calm Down", description = "Spriggans! Nasty spriggans. They came to the grove. They messed it all up!\n\nThey took the anima from the soul webs! We were collecting it, yes. Collecting it for the Tall Tree and their grove. The spriggans have to pay!\n\nBeat them up! Then use this soulweb to take back the anima. We need it! They don't!", objectives = "Defeat Spriggans and use the Soulweb to drain them of stolen anima in Spirit Glen.", progress = "Did you destroy them? Did you make them pay?", completion = "Stolen! They stole the anima! They ran like crazy and...\n\nWait that's normal. They're always that bad. Stupid spriggans!" }
WordHunterWoW_QuestEN[57950] = { title = "Mizik the Haughty", description = "Bad spriggans! Bad! They take our anima. We lose our forms! And one is worst of all.\n\nMizik! He tells the others what to do. And he rides a gorm! Big, nasty gorm!\n\nGet him. Get him!", objectives = "Defeat Mizik the Haughty.", completion = "Gone! The bad spriggan is gone! Spirit Glen will be ours again.\n\nNow to leave. We have to leave." }
WordHunterWoW_QuestEN[57951] = { title = "Souls Come Home", description = "To the tree, to the tree! It is time for us to return to the grove.\n\nWe have our anima. We have our forms. The Tall Tree needs the anima. The Tall Tree will be happy!\n\nI will see you there!", objectives = "Report your success to Droman Tashmur in Tirna Vaal.", completion = "From acorns grow forests, from souls comes vital anima. Small though they be, on them our fates depend.\n\nThe forest sighs in gratitude." }
WordHunterWoW_QuestEN[57952] = { title = "In Need of Gorm Gris", description = "Our neighboring grove at Glitterfall Basin has sent out a desperate plea for gorm gris.\n\nIt may have humble origins, but it is an important ingredient for our artisans and crafters. As this drought goes on, it has become increasingly difficult to collect.\n\nI would like to help them out, with the resources that we are able to spare.\n\nPlease, find Master Sha'lor out by the Tranquil Pools, where he keeps our little gormling population.\n\nAsk him for more gorm gris.", objectives = "Seek out Master Sha'lor by the Tranquil Pools.", completion = "Kota has asked for gorm gris?\n\n<Master Sha'lor beams with excitement.>\n\nI would be happy to oblige her request! Come, let me show you how this works." }
WordHunterWoW_QuestEN[57954] = { title = "Burn the Bodies", description = "The bugs seem to be indiscriminately laying eggs all over the nearby corpses.\n\nThey are using them as food to spawn more of those horrible things. Disgusting!\n\nWe can mourn the dead later, but if any more bugs are allowed to hatch we may not live long enough to do so.\n\nBurn the bodies and destroy those eggs!", objectives = "Burn 10 Egg-bearing corpses.", completion = "Grisly work to be sure, but we were left with no choice. Thank you <name>." }
WordHunterWoW_QuestEN[57955] = { title = "To Ankhaten Harbor", description = "I fear that I don't yet have the strength to ride out into the sands and face those monsters again.\n\nRide to the south and find Tracker Samara in the excavation camp formerly known as Schnottz's Landing.\n\nTell her to halt any caravans that plan to pass this way, lest others are ambushed and met with the same grisly fate.\n\nWe must get the word out across Uldum before our forces are further divided!", objectives = "Find Tracker Samara in Ankhaten Harbor.", completion = "Orsis is lost you say!? This is truly worse than I feared." }
WordHunterWoW_QuestEN[57956] = { title = "Wastewander Hosts", description = "The bugs have been laying eggs in the corpses of our soldiers, it's absolutely terrifying!\n\nSome of them are rising from the ground as putrid, bloated, hideous monstrosities.\n\nWe have to stop them before they continue to bolster their ranks with our fallen.\n\nIt's not a pleasant task... but I have to ask you to help me destroy them. Completely.\n\nGrab some bombs behind me, if you'd like.", objectives = "Kill 6 Wastewander Hosts.", completion = "Blech. I can clearly see that you killed them all, thank you for bringing back that truly awful smell." }
WordHunterWoW_QuestEN[57959] = { title = "Heroic Warfront: The Battle for Darkshore", description = "Darkshore belongs to the Horde! We must hold that ground to maintain our dominance over Kalimdor.\n\nPrepare yourselves. Battle awaits!", objectives = "Defeat the Alliance at the Battle for Darkshore.", completion = "Well fought, <name>, though I'm sure it won't be long before the Alliance try to reclaim Darkshore. When they do, we will be ready to fight!" }
WordHunterWoW_QuestEN[57960] = { title = "Heroic Warfront: The Battle for Darkshore", description = "We will not tolerate further Horde aggression in our territories.\n\nThe night elves will not stand alone this day. Darkshore will be theirs once more.\n\nFor the Alliance!", objectives = "Defeat the Horde at the Battle for Darkshore.", completion = "The day is ours thanks to you, but this war is far from over.\n\nFor the Alliance!" }
WordHunterWoW_QuestEN[57961] = { title = "Heroic: Battle for Darkshore", description = "", objectives = "" }
WordHunterWoW_QuestEN[57962] = { title = "Heroic: Battle for Darkshore", description = "", objectives = "" }
WordHunterWoW_QuestEN[57964] = { title = "Revenge Is Easy", description = "There's still a lot of us here, trying to survive in these ruins.\n\nThese constructs have been encroaching on us constantly. They steal what they can, and haul off any of us they capture to be recycled in their labs.\n\nThe solution here requires an extensive use of violence, by you!", objectives = "Kill 15 bonefused forces.", progress = "I still see a lot of abominations walking around.", completion = "You can kill more of them if you want." }
WordHunterWoW_QuestEN[57966] = { title = "You Go First", description = "You've proven useful. So, I am going to require you to disarm the defenses of this hall. \n\nPlease take care not to die too quickly. I'd like to have the spear before the end of this eon.", objectives = "Disarm the traps within the Third Chamber of Kalliope and make your way to the final hall.", progress = "Continue to be of use and you just might make it out of this intact.", completion = "Your efforts have brought me what I desire. For your reward, I won't kill you." }
WordHunterWoW_QuestEN[57967] = { title = "Rightful Resting Place", description = "You have truly proven yourself a hero in the eyes of those who are its absolute judge.\n\nI thank you for giving me the honor of holding it, even for this briefest moment. However, it is only proper that you be the one to enshrine the spear at it's rightful resting place.\n\nLet us meet at Elysian Hold where you can do the honors.", objectives = "Enshrine the Spear of Kalliope in its rightful place at Elysian Hold.", progress = "<The resting place of the spear lies before you.>", completion = "<Place the Spear of Kalliope in its rightful place knowing that only a true hero can do so.>" }
WordHunterWoW_QuestEN[57968] = { title = "The Wastewandering Dead", description = "Is there no end to these foul monsters!?\n\nI cannot abide the desecration of our dead, especially not as fodder for this disgusting insect army.\n\nDestroy as many as you can, preferably with fire!", objectives = "Kill 6 Wastewander Hosts.", progress = "I hope you've been keeping count of your kills.", completion = "There is just no end to them..." }
WordHunterWoW_QuestEN[57969] = { title = "Tend the Wounded", description = "My friend, as you can see here, we are besieged by these terrible creatures.\n\nMany of our comrades have fallen prey to the monsters, but fortunately, we have enough warriors here to keep the threat at bay... for now.\n\nIf you are able to assist us, please, tend to our wounded and help clear a path for them to escape the ruins.", objectives = "Heal 8 Wastewander Laborers.", completion = "You are a true hero, my friend." }
WordHunterWoW_QuestEN[57970] = { title = "Ruinator Xok'nixx", description = "Ar'kali and a group of our warriors are engaged with a most behemothic creature in the heart of the ruins.\n\nShe can hold her own against nearly any foe, but I fear it is only a matter of time before this monster is able to wear them down.\n\nAlthough the creature is occupied for now, if our warriors fall, the ruins will be lost to us.\n\nPlease, make haste, with your help they can surely fell this titanic foe.", objectives = "Kill Ruinator Xok'nixx.", completion = "You are a capable fighter. Thank you for assisting our warriors!" }
WordHunterWoW_QuestEN[57971] = { title = "Ruins of Ammon", description = "These things seem to be everywhere and all at once!\n\nEither this was an organized attack, or there are far more of them than we can even comprehend.\n\nRegardless, this is bad for us... really, really bad.\n\n{name}, I need you to travel to the Ruins of Ammon and find out what the situation is like over there.\n\nIf they need help, please try to lend a hand!", objectives = "Travel to the Ruins of Ammon.", completion = "Seeing you here is like stumbling across an oasis in the desert, my friend!" }
WordHunterWoW_QuestEN[57973] = { title = "Heroic: Battle for Darkshore", description = "", objectives = "" }
WordHunterWoW_QuestEN[57974] = { title = "Heroic: Battle for Darkshore", description = "", objectives = "" }
WordHunterWoW_QuestEN[57976] = { title = "Lead By Example", description = "Margrave Krexus expects much of you, mortal. Show these soldiers how a true champion of the arena vanquishes their foes and claims victory!\n\nMeet these traitorous constructs head on. Leave none standing!", objectives = "Kill 12 Steelskin Vanguard or Steelskin Brutalizers.", progress = "What?", completion = "That should strike fear into their stolen hearts." }
WordHunterWoW_QuestEN[57977] = { title = "A Temple in Need", description = "<Eridia peers down at you.>\n\nYour face is new to me.\n\n<Eridia frowns.>\n\nI regret that this shall be your introduction to our temple. As my disciple has informed you, we seek the aid of all available aspirants to tend to those in our care.\n\nDo not trouble yourself over the specifics of the work that is needed. Those devoted to this temple will guide you. Seek out the disciples within.\n\nYou may find me within the temple when you have given your aid.", objectives = "Aid the disciples within the Temple of Purity.", progress = "Have you lent my disciples your aid?", completion = "You have proven yourself adept at this task. You have my gratitude." }
WordHunterWoW_QuestEN[57978] = { title = "Forward and Back", description = "", objectives = "" }
WordHunterWoW_QuestEN[57979] = { title = "Offensive Behavior", description = "Fine work, {name}. We've advanced with minimal casualties. \n\nFrom this new forward position, we can strike directly at the enemy commander. The troops you rallied will join the attack. Together, we will bring this battle to a decisive end.\n\nLocate General Alver and sound the horn.", objectives = "Kill General Alver.", completion = "Your leadership is inspiring. These troops would follow you anywhere!" }
WordHunterWoW_QuestEN[57982] = { title = "Breaking Down Barriers", description = "As I suspected, Stitchflesh's assistants are carrying on his work. Whatever they're building, we need to destroy it.\n\nThey've secured the chamber with a soul barrier and several bile spewers. We must find a way through!\n\nThales said he may have a suggestion.", objectives = "Find a way past the Soul Barrier.", progress = "Is the barrier down?", completion = "It seems these kyrian are more stalwart than I expected. Let us avenge their fallen kin." }
WordHunterWoW_QuestEN[57983] = { title = "Archon Save Us", description = "Most of the aspirants were slaughtered and dismembered on arrival. They were the lucky ones. \n\nThe lead surgeon decided that the only things worth taking from me... were my eyes. I was discarded afterward and left to my rot. Archon save me, the screaming...\n\nI think there are other survivors being held nearby. Can you aid me in freeing them?", objectives = "Save the souls in the Holding Pens.", progress = "Yes?", completion = "Only four survivors... I know I should be grateful that there were any at all, but...\n\nWhat sort of monsters would do this to anyone, let alone to their own people?" }
WordHunterWoW_QuestEN[57984] = { title = "The Ones in Charge", description = "They have been collecting kyrian... and our corpses... for some dark purpose.\n\nWhatever they are planning, we must put a stop to it.\n\nI have overheard mention of three individuals who seem to be in charge. We need to find them and eliminate them.", objectives = "Slay Doctor Hivvil, Tabulator Hymeris, and Leacher Cvan.", completion = "It seems one of the house's barons is overseeing this operation... and he is unaware that we are free. \n\nWe have a chance to strike him down!" }
WordHunterWoW_QuestEN[57985] = { title = "Give Them a Hand", description = "The corpses are brought to this pit for processing. Their flesh is liquified and congealed before being shaped into new constructs.\n\nWe can hinder their production by extracting the animates from the pool prematurely. Use this hook to do so.\n\nDo not let Baron Halis catch you. He has a reputation for cruelty, even within his own house.", objectives = "Destroy 10 Vestigial Animates.", progress = "The weak make way for the strong, such is the way of Maldraxxus.", completion = "Slowing the production of new constructs should earn our soldiers some reprieve, however brief." }
WordHunterWoW_QuestEN[57986] = { title = "A Burden Worth Bearing", description = "Mevix may be here for blood, but what I want is to spare my fallen kin from a terrible fate.\n\nMost of my fellow kyrian were either slain in combat or shortly after arriving here. If their corpses were bound for this pit, then perhaps we can recover them before they are thrown into it.\n\nTake the stewards with you and gather the bodies of my brethren. I will not allow them to be made into monsters.", objectives = "Help Kou and Koa retrieve 6 Lost Kyrian.", progress = "Were there any left?", completion = "Thank you, <name>. Though they are lost, at least their remains will not be defiled." }
WordHunterWoW_QuestEN[57987] = { title = "A Deadly Distraction", description = "Vyraz's assault on the House of Constructs may have failed, but we can still make them bleed now that we're inside.\n\nSlaughter as many as you can. I will hunt down the masterminds behind these new production efforts.", objectives = "15 Warstitched forces slain.", completion = "Complacency is every soldier's worst enemy. No one is safe in times of war, not even within the walls of their own fortress." }
WordHunterWoW_QuestEN[57989] = { title = "The Spear of Kalliope", description = "The Spear of Kalliope is finally in my grasp!\n\nWith it, I will lay waste to all the Forsworn's enemies. Now behold while I take my prize!", objectives = "Defeat Artificer Ligiea and earn the Spear of Kalliope.", progress = "Did you find the spear?", completion = "The spear! You've saved it from the hands of the Forsworn." }
WordHunterWoW_QuestEN[57990] = { title = "Obelisk of the Sun", description = "I have one more thing I must ask of you, my friend. Completion of this task is critical to our survival here.\n\nOur comrade, Zahra, has taken it upon herself to climb the plateau just east of us to secure one of the old bombers left up there.\n\nSo far, our attempts to get word back to Arik have failed. \n\nHowever, if you can help her get one of those planes working, we might just have a chance.\n\nHopefully they can send aid before we are overrun...", objectives = "Locate Exterminator Zahra at the Obelisk of the Sun.", completion = "Old man Dyrin sent you, 'eh? Well, I'm glad to have your assistance." }
WordHunterWoW_QuestEN[57993] = { title = "Two of Them, Two of Us", description = "A construct made entirely of kyrian flesh...\n\nThis betrays everything Maldraxxus stands for! We are meant to defend the Shadowlands and all within it, not slaughter and exploit them!\n\nCome, {name}! We end this now!", objectives = "Defeat Sharrex the Fleshcrafter and First Apprentice Malkrex.", completion = "I sense something within this construct... something familiar..." }
WordHunterWoW_QuestEN[57994] = { title = "In The Flesh", description = "The souls of the fallen kyrian... I can sense their pain and confusion. They yet exist within the construct!\n\nPlease, we must not destroy it. Doing so would consign the souls within it--the souls of my brethren--to oblivion. \n\nPerhaps... perhaps they can aid us in escaping to freedom. I will soothe the souls within the construct while you direct its actions.", objectives = "Take control of the Soulfused Construct and escape the House of Constructs.", progress = "My fallen kin...", completion = "We escaped!\n\nWe will recuperate here for now. At least until we find a way to return to Bastion.\n\nThank you for showing me what courage is, my friend." }
WordHunterWoW_QuestEN[58007] = { title = "Eyes on the Problem", description = "Our enemies rally at our gates. We cannot rely on daring air strikes to hold them at bay.\n\nVashj has a plan to permanently bolster our defenses. With your help, it might actually succeed.\n\nDo what you can to assist her. She seems more... agreeable toward you than she is with me.", objectives = "Speak with Vashj and put her plan into action.", completion = "Our foes will regret opposing us." }
WordHunterWoW_QuestEN[58008] = { title = "All Gassed Up", description = "So, I was checkin' all these planes... and you are never gonna believe this, but none of them have any fuel in the tanks!\n\nSaw a few canisters scattered around nearby, surely some a' them have some gas left.\n\nWas gonna collect 'em myself, but these damned bugs came outta nowhere and started swarmin' the place.\n\nToo many here now to deal with on my own, think you'd be able to lend a hand?", objectives = "Collect 6 Fuel Canisters.", progress = "Yo, you got them fuel cans yet?", completion = "Well hot damn, you did great finding all of these!" }
WordHunterWoW_QuestEN[58009] = { title = "To the Moon", description = "Alright! It's time to high tail it outta here.\n\nWe gotta get back to camp and tell Arik what's been going on out here as soon as possible.\n\nHead for the bomber and let's fuel 'er up. \n\nI'll letcha have the gunner seat, but I'm drivin', so let's try to blow up a few bugs on the way back!", objectives = "Remove the Aqir threat from Obelisk of the Moon.", completion = "What in the blazing sands were you doing up there!?" }
WordHunterWoW_QuestEN[58010] = { title = "More Bits, More Bits!", description = "We need more Aqir samples, {name}. As many as you can get your hands on!\n\nI've made some fascinating discoveries already, but there's so much more to learn.\n\nWith further study and a bit of good luck, perhaps we can slowly begin to uncover some of their weaknesses.", objectives = "Collect 16 Aqir Bits.", progress = "Have you obtained any additional samples?", completion = "Excellent, thank you for collecting these samples." }
WordHunterWoW_QuestEN[58011] = { title = "Bug Bites", description = "Margrave Stradama eagerly awaits the completion of our latest potion!\n\nHowever, I seem to have misplaced my stockpile of venom sacs. How embarrassing! I have felt a touch out of sorts lately...\n\nWould you please do me a favor and fetch some more? We cannot continue our work without them!", objectives = "Collect 6 Bloated Venom Sacs.", progress = "Now where did I put my venom sacs...", completion = "You found my venom sacs! What a helpful apprentice you are!" }
WordHunterWoW_QuestEN[58016] = { title = "Spores Galore", description = "My brightest apprentice, you return to me at last!\n\nYou worried me--you see, I heard the loudest clatter while working on one of my experiments... Before I knew it, I was here, and you'd disappeared!\n\nWherever you went is no matter. You're back now, and we have much to do!\n\nCome, my apprentice--we must fetch our ingredients first.\n\nCan you smell the spores germinating around us? We should pull some up to use in our endeavors!", objectives = "Harvest 8 Stringy Spores.", completion = "Such marvelous spores, my apprentice!" }
WordHunterWoW_QuestEN[58022] = { title = "Finish What He Started", description = "Finding Sha'lor is our main priority. But there is another opportunity.\n\nTake the Gormherd Branch that he dropped. I know he was tinkering with it so that it would work on wild gorm.\n\nUse it on the gorm in the burrows, and see if you can collect any of their gorm gris.\n\nDon't bother with the little ones; get the really potent stuff from the bigger gorm.\n\nPerhaps if we can collect enough, and find that silly sylvar, he will not rush horns-first into the burrows again.", objectives = "Use the Gormherd Branch to collect Wild Gorm Gris from gorm in the Dusty Burrows.", progress = "Have you had any luck?", completion = "Well done. You've collected enough gorm gris to hopefully keep Sha'lor from venturing into the burrows all by himself, again.\n\nAnd we should be able to send some to our friends in Glitterfall, once all this is over. \n\nThank you." }
WordHunterWoW_QuestEN[58023] = { title = "One Big Problem", description = "We must go after Master Sha'lor. Tirna Vaal needs him! And I... I...\n\nI will report to the droman. They must know that Sha'lor is in danger. Then, I will enter the burrows myself from the south and help you defeat it.\n\nFor now, see what you can find. I refuse to believe that he is gone.\n\nThat monster will know the fury of a vorkai.", objectives = "Hunt down the Gorm Matriarch.", progress = "What's gotten into these gorm?", completion = "Well done. You drove the beast hard enough that she spat out Sha'lor. Now she hides in her den.\n\nShe has nowhere else to run.\n\nNow we end this." }
WordHunterWoW_QuestEN[58024] = { title = "Burrows Away", description = "<The ground has been freshly dug, and there are signs of more tunnels all over the place.\n\nCollapsing a few burrows would go a long way toward keeping Tirna Vaal safe from gorm infestation.>", objectives = "Collapse Gorm Burrows in the Dusty Burrows.", completion = "The gorm are digging even MORE burrows beneath Ardenweald? This is very bad news indeed. \n\nThank you for taking it upon yourself to close them down. That should give us some time to reinforce our defenses." }
WordHunterWoW_QuestEN[58025] = { title = "Queen of the Underground", description = "You tracked the massive gorm here to her den, and we've found Master Sha'lor.\n\nPerhaps not entirely unscathed, but he lives. That is enough.\n\nOne last task remains. Let us end this.", objectives = "Slay the Gorm Matriarch.", progress = "Tirna Vaal will not be safe with that monstrosity about.", completion = "How is that possible? The matriarch she... they feasted on the pods. What if there are others like her out there in Ardenweald?\n\nWe must report this immediately." }
WordHunterWoW_QuestEN[58026] = { title = "When a Gorm Eats a God", description = "There is nothing more we can do here. I will get Master Sha'lor safely back to Tirna Vaal.\n\nWhen you get there, report to the droman what we found here. \n\nIf the gorm have started to eat the dead wildseeds, and are absorbing the power of the spirits within, we are all in serious danger.", objectives = "Report back to Droman Tashmur in Tirna Vaal.", completion = "Those that speak, think. A different kind of Queen is born.\n\nThe forest worries. For this will surely not be the last." }
WordHunterWoW_QuestEN[58027] = { title = "Slime, Anyone?", description = "While I know we're both eager to complete our potion, I believe the best lesson I can share with you is patience.\n\nPatience and slimes, of course!\n\nWith the help of slimes, we'll have our laboratory back in working condition. It's just as I taught you: combine your ingredients in the cauldron. Mix until the viscosity is just right...\n\nOh, listen to me--acting as if you've never concocted your own sentient being!\n\nGo on, my apprentice! The slimes are calling!", objectives = "Craft a Plagueborn Slime in Marileth's cauldron.", progress = "Go on, now! You can do it!", completion = "What a precious slime!" }
WordHunterWoW_QuestEN[58031] = { title = "Applied Science", description = "<What appears to be an old journal sits on Marileth's table, now mangled and missing pages.\n\nThe entries that are legible seem to have been written by Marileth when he was still sane, before the fall of his house.\n\nPerhaps if you find the journal's missing pages, you will gain more insight into what befell the House of Plagues.>", objectives = "Collect the lost pages of Marileth's journal from Plague-doused Remnants.", completion = "Oh--and what are these?" }
WordHunterWoW_QuestEN[58036] = { title = "Hazardous Waste Collection", description = "Ah, slimes: the dearest of friends and infinitely useful! They will help us craft our potion.\n\nBut it seems our tools have been scattered around, doused in toxic refuse. Margrave Stradama would be so disappointed at my lack of respect for lab safety!\n\nYour slime can comb through the refuse, diluting the plague's harmful agents. Simply pull the cleaned equipment from the body of your slime!\n\nSlimes... what would we do without them?", objectives = "Collect 6 pieces of Laboratory Equipment.", progress = "Has your slime been useful? I'm sure it has!", completion = "You and your slime are bonding!" }
WordHunterWoW_QuestEN[58037] = { title = "Part of the Pride", description = "Pelodis insists that phalynx are superior to all autonomous beings, taking orders without fail.\n\nBut where is the nuance? Where is the reward for your effort?\n\nLarions make fantastic companions, but you must build a relationship with them. Introduce yourself to my pride. You will see that each has a personality of their own.", objectives = "Introduce yourself to 5 Tamed Larions.", progress = "Larions are free-thinking beings. They will decide whether you are accepted within the pride.", completion = "My pride is generally wary of newcomers, but they seem to accept your presence." }
WordHunterWoW_QuestEN[58038] = { title = "All Natural Chews", description = "A huge part of larion care is providing for them and keeping them happy.\n\nLarions need to keep their teeth sharp and healthy, and for that they need to chew. If you do not give them proper things to chew on, they can get destructive.\n\nOne of their favorite chew toys are the antlers from the cloudstriders in the nearby field. Please, collect some antlers for the pride to enjoy.", objectives = "Collect 5 Cloudstrider Antlers from Gilded Cloudstriders in the Golden Pasture.", progress = "Antlers are great for keeping my pack's teeth sharp and clean.", completion = "The larions will be ecstatic to have more antlers to chew on!" }
WordHunterWoW_QuestEN[58039] = { title = "Larion at Large", description = "Some larions are more particular about the people they bond with than others.\n\nLentios is my companion, the larion I trust most with my life. I love the others as well, but he is a part of my soul.\n\nOne of my pride, Andira, has posed a struggle for me to bond with. She ran off into the pastures once again, and I fear she's gotten into something she shouldn't have.\n\nWould you mind finding her and bringing her home?", objectives = "Find Andira in the Golden Pasture and return her to Nemea's Retreat.", progress = "Andira and I do not see eye to eye. I know she will be a loyal companion... but perhaps to somebody else.", completion = "Incredible! It seems Andira has taken a liking to you. Perhaps you would be interested in bonding with her further?" }
WordHunterWoW_QuestEN[58040] = { title = "With Lance and Larion", description = "Say what you want about phalynx, but Larion will always have one major advantage.\n\nWings!\n\nA bonded larion will hunt alongside you whether you are on the ground or in the air. \n\nTake my javelin and Andira then go out into the fields to hunt the cloudfeathers there. You'll feel the boon of larion companionship firsthand!", objectives = "Kill 5 Cloudfeather Greatwing in Greatwing Roost.", completion = "It is such a satisfying experience to see your larion take wing to help take down your prey." }
WordHunterWoW_QuestEN[58041] = { title = "Providing for the Pack", description = "Even beings of the Shadowlands need to eat. They may not do so quite like your world, but it is similar enough.\n\nThe pride's favorite prey is the juvenile cloudfeathers found nearby. Prove to Andira that you are a contributing member of the pride by taking her out to hunt for their next meal.", objectives = "Collect 10 Cloudfeather Essence.", progress = "Larions bond through hunting. Working together with Andira to collect food is vital to your relationship.", completion = "Providing for the pride is an important step on your path to earning your loyalty here." }
WordHunterWoW_QuestEN[58042] = { title = "On Larion Wings", description = "As a flightless being, you will unfortunately never feel the joy of flying alongside your companion.\n\nHowever... you could still fly with Andira.\n\nIt seems you have earned Andira's trust more than I've seen her with anybody else. Would you like to try a flight course?\n\nTake wing with Andira, then fly through the rings. Don't stray off course or take too much time to get between rings or she will leave you behind!", objectives = "Mount Andira, then complete the flight course.", progress = "I set up the flight course to train the larions to listen to aerial commands. They know where to go!", completion = "The feeling of soaring through the air, the gentle flap of your larion's wings...\n\nEven though I have my own wings, there's no feeling quite like it." }
WordHunterWoW_QuestEN[58045] = { title = "Plague is Thicker Than Water", description = "Come closer, my apprentice... I have a mission of dire import!\n\nA necromancer came to our house recently, sent by the lich Margrave Sin'dane! He seemed so polite, always eager to lend a hand in my lady's most volatile creations.\n\nBut I grew wise, my apprentice. The way he skulked around, prodding for our most sensitive experiments...\n\nHe was trying to steal our slimes! I know it!\n\nYou should admonish him quite harshly. Show that no harm will come to our friends!", objectives = "Kill Korrim the Cunning.", progress = "Have you chided the defiler?", completion = "Our slimes will be safe, my dear apprentice!" }
WordHunterWoW_QuestEN[58060] = { title = "The Night Market", description = "<Dracho motions to keep your voice down.>\n\nI need some assistance, I promise you will be paid handsomely. \n\nAt the edge of The Banewood lies some ruins. These ruins are home to a marketplace run by some brokers. They won't let me back there. Let's just say that my goods were deemed to not be up to their authenticity metrics. \n\nBut you... you're a Maw Walker! Bring them this package and exchange it for some Surberries from Ardenweald. \n\nJust don't say I sent you.", objectives = "Bring the Hastily Wrapped Package to Ta'ruca at The Night Market in Revendreth.\n\nProvided item:", completion = "Ah, Briar Thorn Roses! Excellent. \n\nDon't go just yet. We need to talk." }
WordHunterWoW_QuestEN[58062] = { title = "A Very Special Guest", description = "Listen. It is obvious you are doing this deal on Dracho's behalf. \n\nI believe Ta'xera, the boss around here, would be very interested in striking a deal with someone of your talents.\n\nShe resides in the manor at the top of the hill. I recommend you don't keep her waiting.", objectives = "Speak to Ta'xera at The Night Market.", completion = "I have hoped for your eventual arrival, Maw Walker. \n\nDracho is no longer a partner of ours. Normally we would extend this punishment to you for attempting to subvert our rules. But you being who you are... changes things.\n\nLet's strike a deal. \n\nYou bring things of interest to me directly. No middlemen. No tricks. \n\nWe provide payment and our wares when necessary. Do we have a deal?" }
WordHunterWoW_QuestEN[58068] = { title = "...Even The Most Ridiculous Request!", description = "A fan of the competition, are you? Perhaps you would like to be more than a mere spectator?\n\nI will give you a small task... one that not only benefits me, but that also gives you a chance to meet some of the storied competitors here.\n\nAs you can see, our three remaining houses have sent champions to attend the Contest of Conquest. Talk with them and attend to what needs they might have.", objectives = "See to the needs of the Promenade Champions.", progress = "What now?", completion = "We would be so lost without your help. Truly." }
WordHunterWoW_QuestEN[58069] = { title = "Favor: The Venthyr Diaries", description = "This item will be of great interest to the brokers. \n\nPer your previous deal with The Night Market, you should bring it to Ta'xera.\n\nYou will be fairly compensated.", objectives = "Bring The Venthyr Diaries to Ta'xera at The Night Market in Revendreth.\n\nProvided item:", completion = "<Ta'xera perks up at your offer.>\n\nAh, what lies in these pages? \n\nPersonal diary entries it seems. Very interesting. There's even one from the Accuser in here!\n\nThis will be a treat to tear through." }
WordHunterWoW_QuestEN[58070] = { title = "Favor: Soul Hunter Blade", description = "This item will be of great interest to the brokers. \n\nPer your previous deal with The Night Market, you should bring it to Ta'xera.\n\nYou will be fairly compensated.", objectives = "Bring the Soul Hunter Blade to Ta'xera at The Night Market in Revendreth.\n\nProvided item:", completion = "What have you brought me today?\n\nOh, I see. The blade from a soul hunter's rapier. This holds great value to those looking to learn more about their dueling techniques. \n\nThank you, <name>. My contacts will be most pleased." }
WordHunterWoW_QuestEN[58071] = { title = "Favor: Vial of Dredger Muck", description = "This item will be of great interest to the brokers. \n\nPer your previous deal with The Night Market, you should bring it to Ta'xera.\n\nYou will be fairly compensated.", objectives = "Bring the Vial of Dredger Muck to Ta'xera at The Night Market in Revendreth.\n\nProvided item:", completion = "What is that horrible smell?!\n\n<You present Ta'xera with the vial.>\n\nWell then. While that odor is vile, the contents of that vial are pristine. The very primordial ooze that dredgers are made from.\n\nI'll pay you double whatever anyone else has already offered." }
WordHunterWoW_QuestEN[58072] = { title = "Favor: Petrified Stonefiend", description = "This item will be of great interest to the brokers. \n\nPer your previous deal with The Night Market, you should bring it to Ta'xera.\n\nYou will be fairly compensated.", objectives = "Bring the Petrified Stonefiend to Ta'xera at The Night Market in Revendreth.\n\nProvided item:", completion = "Is that what I think it is?\n\n<Ta'xera examines the stonefiend closely.>\n\nIn perfect condition! I can't wait to study every intricacy." }
WordHunterWoW_QuestEN[58073] = { title = "Favor: Portrait of The Sire", description = "This item will be of great interest to the brokers. \n\nPer your previous deal with The Night Market, you should bring it to Ta'xera.\n\nYou will be fairly compensated.", objectives = "Bring the Portrait of The Sire to Ta'xera at The Night Market in Revendreth.\n\nProvided item:", completion = "This is good. You can make out every detail.\n\nMost wonderful find, <name>." }
WordHunterWoW_QuestEN[58074] = { title = "Favor: Ledger of Souls", description = "This item will be of great interest to the brokers. \n\nPer your previous deal with The Night Market, you should bring it to Ta'xera.\n\nYou will be fairly compensated.", objectives = "Bring the Ledger of Souls to Ta'xera at The Night Market in Revendreth.\n\nProvided item:", completion = "A very dense list of names you have here. This will prove useful in my studies." }
WordHunterWoW_QuestEN[58075] = { title = "Favor: Dredger's Toolkit", description = "This item will be of great interest to the brokers. \n\nPer your previous deal with The Night Market, you should bring it to Ta'xera.\n\nYou will be fairly compensated.", objectives = "Bring the Dredger's Toolkit to Ta'xera at The Night Market in Revendreth.\n\nProvided item:", completion = "Hmm, what's this? Ah, the proverbial tools of the trade.\n\nThis is of no interest to me, but my contacts interested in infrastructure would be most interested in this collection." }
WordHunterWoW_QuestEN[58077] = { title = "Favor: Perfected Hand Mirror", description = "This item will be of great interest to the brokers. \n\nPer your previous deal with The Night Market, you should bring it to Ta'xera.\n\nYou will be fairly compensated.", objectives = "Bring the Perfected Hand Mirror to Ta'xera at The Night Market in Revendreth.\n\nProvided item:", completion = "So finely crafted.\n\nThis must be the work of Laurent. Perfect for the transportation of persons around Revendreth in an inconspicuous manner. \n\nWe will make great use of this." }
WordHunterWoW_QuestEN[58078] = { title = "Favor: Bottle of Redelav Wine", description = "This item will be of great interest to the brokers. \n\nPer your previous deal with The Night Market, you should bring it to Ta'xera.\n\nYou will be fairly compensated.", objectives = "Bring the Bottle of Redelav Wine to Ta'xera at The Night Market in Revendreth.\n\nProvided item:", completion = "How decadent! Redelav wine! \n\nI'm torn on whether to keep it for my own collection or use this sought after wine for some valuable artifacts elsewhere.\n\nNevermind, here's your payment." }
WordHunterWoW_QuestEN[58079] = { title = "Favor: Pristine Dredbat Fang", description = "This item will be of great interest to the brokers. \n\nPer your previous deal with The Night Market, you should bring it to Ta'xera.\n\nYou will be fairly compensated.", objectives = "Bring the Pristine Dredbat Fang to Ta'xera at The Night Market in Revendreth.\n\nProvided item:", completion = "What do you have here? Ah, an intact dredbat fang.\n\nPretty rare considering how... bitey they can be. Thank you for this." }
WordHunterWoW_QuestEN[58080] = { title = "Favor: Glittering Primrose Necklace", description = "This item will be of great interest to the brokers. \n\nPer your previous deal with The Night Market, you should bring it to Ta'xera.\n\nYou will be fairly compensated.", objectives = "Bring the Glittering Primrose Necklace to Ta'xera at The Night Market in Revendreth.\n\nProvided item:", completion = "Oh how gorgeous. Very interesting.\n\n<Ta'xera inspects the necklace closely.>\n\nWhere did they get this material? I've not seen it in a long time. There is much to learn from it." }
WordHunterWoW_QuestEN[58081] = { title = "Favor: Love and Terror", description = "This item will be of great interest to the brokers. \n\nPer your previous deal with The Night Market, you should bring it to Ta'xera.\n\nYou will be fairly compensated.", objectives = "Bring Love and Terror to Ta'xera at The Night Market in Revendreth.\n\nProvided item:", completion = "Poems? From a venthyr?! \n\nSurprising to say the least. I can't wait to dig into the writing styles." }
WordHunterWoW_QuestEN[58084] = { title = "Soul Snares", description = "", objectives = "" }
WordHunterWoW_QuestEN[58086] = { title = "The Master of Lies", description = "Once more unto the fangs of death himself, sword drawn, peace with oblivion made. Let us meet death together and bring him low.\n\nBe sure you are prepared for a sustained assault. For once we reveal ourselves, there will be no stopping. \n\nWhen you are ready, direct the Focal Mirror at the gates of Castle Nathria. Let us descend upon our burning enemies with ferocity and swiftness of action.", objectives = "Defeat Sire Denathrius.", completion = "What has he done?" }
WordHunterWoW_QuestEN[58087] = { title = "Destroying the Source", description = "Tidecaller Nezara is running the show. If we take her out, the remaining naga will break rank, but getting to her won't be easy. She's protected by a magical barrier that's drawing power from powercells nearby. \n\nIf we can destroy the source, we can destroy Nezara.", objectives = "Destroy 3 Nazeshi Powercells within Dreadpearl Shallows.", completion = "Tidecaller Nezara can't hide behind her barrier now!" }
WordHunterWoW_QuestEN[58088] = { title = "Juicing Up", description = "I've conceived a task befitting of your \"talents\".\n\nHave you heard of the House of Plague? Crafters of toxins and potions. They suffered a tragic accident--a true, true shame.\n\nHerein lies the problem: I have long used the work of the plague devisers to bolster my arena performance. Without a potion of their creation, I'd find the fight unnecessarily taxing.\n\nThe brokers do have such potions, but they \"do not like my face.\" Could you obtain such a potion for me?", objectives = "Find someone at the Challenger's Promenade who has enhancement potions.", completion = "I know Scrapper Minoire sent you. She always enhances herself to win the fight." }
WordHunterWoW_QuestEN[58089] = { title = "Test Quest", description = "A quest!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "" }
WordHunterWoW_QuestEN[58090] = { title = "Side Effects", description = "Scrapper Minoire's use of enhancers creates unpredictable betting implications. It is quite unhealthy... for our profits!\n\nFor a nominal fee, Au'larrynar can provide you with a \"special\" enhancer that Minoire will not be able to resist: a potion that turns the one who imbibes it into the ultimate combatant... and teaches them a lesson in restraint, as well.\n\nI cannot wait to see Minoire's next match in the arena!", objectives = "Deliver the potion to Scrapper Minoire.", progress = "This is an unexpected turn of events.", completion = "Scrapper Minoire will have to forfeit her spot in the contest." }
WordHunterWoW_QuestEN[58092] = { title = "Halls of Atonement: Your Absolution", description = "The depravity outside of these halls is only a whisper of the true horrors being committed under the Lord Chamberlain's guidance inside the Halls of Atonement.\n\nIf you truly wish to curb this corruption, you must dethrone the imposter that you installed here.\n\nAtone for your own mistake. Kill the Lord Chamberlain, so that we may begin to restore permanent order to this place.", objectives = "Kill the Lord Chamberlain inside the Halls of Atonement.", completion = "A large step in our journey to reclaim the honor of these halls... but not the last.\n\nI shall send word to the Accuser immediately." }
WordHunterWoW_QuestEN[58093] = { title = "Our Forgotten Purpose", description = "I have no quarrel with you, Maw Walker.\n\nThe Lord Chamberlain and his abhorrent followers have debased these halls with their perversions of the rituals. Abusing souls and destroying their potential for pathetic mockeries of power.\n\nThe Accuser would never have allowed this. I have heard rumors that you may still be in contact with her. If so, please inform her of the situation here.\n\nShe will bring these depraved dogs to heel.", objectives = "Meet the Accuser at Absolution Crypt.", completion = "I am already working to undo the Lord Chamberlain's mistakes.\n\nYes, you may assist me." }
WordHunterWoW_QuestEN[58095] = { title = "Theater of Pain: Help Wanted", description = "Oh, bother--the Lich champion has withdrawn from the contest.\n\nWell, then... It appears we have an opening! Would anyone like to enter in her stead?\n\nPerhaps to increase the odds for their house?\n\nAnyone?\n\nOh, {name}! So kind of you to volunteer. No better way to get experience than to just jump right in unprepared!\n\nRemember, we can't all be winners.", objectives = "Enter the Theater of Pain dungeon, and defeat the champions within.", completion = "A spectacular show, Maw Walker." }
WordHunterWoW_QuestEN[58096] = { title = "Supplies from the Rajani", description = "The Rajani appreciates all the help you've given us.\n\nPlease take these supplies as a token of our gratitude, and a promise of more to come, should you continue to help us.", objectives = "Speak with Zhang Ku in Vale of Eternal Blossoms for your reward.", completion = "The Rajani stand with Ra-den against the forces of N'zoth. \n\nWe shall endeavor to assist you in any way we can for now take these supplies to assist you in the continuing battle." }
WordHunterWoW_QuestEN[58097] = { title = "Supplies from the Uldum Accord", description = "The Uldum Accord appreciates all the help you've given us.\n\nPlease take these supplies as a token of our gratitude, and a promise of more to come, should you continue to help us.", objectives = "Speak with Provisioner Qorra in Uldum for your reward.", completion = "The accord is standing strong in the face of this threat. All of Azeroth is in your debt for the heroic efforts you are making. \n\nThank you champion!" }
WordHunterWoW_QuestEN[58103] = { title = "Pride or Unit", description = "I hope that working with my phalynx has swayed you, {name}.\n\nLet us meet with Nemea. There you can decide whose way of life is superior, and which you would prefer to pursue.", objectives = "Meet with Pelodis and Nemea, then pick a side.", progress = "Surely you must agree that the ease of phalynx companionship suits you.", completion = "It is done." }
WordHunterWoW_QuestEN[58104] = { title = "Show, Don't Tell", description = "As a new champion of the Court, you'll need to be properly introduced to the rest of the Night Fae. And that calls for something big. Bold. Memorable. A demonstration of who you are and where you've come from. Something with... flair.\n\nNormally, we spend ages crafting a masterpiece presentation. But we don't have time for that! We'll just have to improvise.\n\n<Moonberry winks.>\n\nCommune with me so I can pick up the highlights! I'll make sure it's a show to remember!", objectives = "Commune with Lady Moonberry.", completion = "Oh good! You're here! No time to rehearse, but that shouldn't be too much of a problem." }
WordHunterWoW_QuestEN[58122] = { title = "For the Horde", description = "What an adventure, {class}!\n\nThere is so much to explore... so much to discover. These are such exciting times!\n\nWe'll show our allies in the Horde the value of having some clever Vulpera around.\n\nPlease meet with the ambassador at the Orgrimmar embassy. \n\nI'll meet you there, {name}!", objectives = "Meet Ambassador Blackguard at the Orgrimmar Embassy.", completion = "Are you the new one? I'm supposed to welcome you.\n\n<Blackguard lets out an exasperated sigh.>" }
WordHunterWoW_QuestEN[58124] = { title = "Stranger in a Strange Land", description = "Hi. I'm Ambassador Blackguard.\n\nI am honored to welcome you to Orgrimmar, {race}.\n\n<He smiles unconvincingly.>\n\nAs a lifetime of adventure unfolds before you, be assured that... uh...\n\nYou know what? I've been saying this same greeting all day. Enough's enough.\n\nTalk to Chromie on top of the hourglass, then talk to your emissary. Run along.", objectives = "Talk to Chromie.", progress = "This city is huge!", completion = "So many options for you!\n\nAnd by you, I mean us. I bet there are some fascinating curiosities to be found...\n\nBe careful out there!" }
WordHunterWoW_QuestEN[58127] = { title = "Inquisitor Sinstone", description = "", objectives = "With my archives, it shouldn't be too challenging to identify and recreate the sinstone of an inquisitor.", progress = "With my archives, it shouldn't be too challenging to identify and recreate the sinstone of an inquisitor.", completion = "A strong Maw Walker like yourself should have no problem taking down an inquisitor.\n\nHappy hunting." }
WordHunterWoW_QuestEN[58128] = { title = "High Inquisitor Sinstone", description = "", objectives = "Even with my archives, it could be difficult to identify and recreate the sinstone of a high inquisitor.", progress = "Even with my archives, it could be difficult to identify and recreate the sinstone of a high inquisitor.", completion = "High Inquisitors are powerful enemies. Bring a friend or two if you plan on challenging one directly.\n\nHappy hunting." }
WordHunterWoW_QuestEN[58129] = { title = "Grand Inquisitor Sinstone", description = "", objectives = "The Grand Inquisitors are incredibly protective of their secrets. We will need to expend exceptional resources to identify and recreate one of their sinstones.", progress = "The Grand Inquisitors are incredibly protective of their secrets. We will need to expend exceptional resources to identify and recreate one of their sinstones.", completion = "Grand Inquisitors Nicu and Aurica are the most powerful venthyr walking these halls, Maw Walker.\n\nDo not face them alone. Bring allies. Lots of them." }
WordHunterWoW_QuestEN[58144] = { title = "Battered and Bruised", description = "", objectives = "" }
WordHunterWoW_QuestEN[58146] = { title = "For the Alliance", description = "As High Tinker, and leader of both Gnomes and Mechagnomes, I am proud to welcome you to the Alliance!\n\nA world of adventure awaits you beyond the walls of Mechagon City.\n\nWhen you are ready, step on the teleporter. Ambassador Moorgard will be awaiting your arrival at the Stormwind Embassy.\n\nThere will be many potential avenues of advancement available to you.\n\nChoose wisely, improve, and remember to share your data.", objectives = "Meet Ambassador Moorgard at the Stormwind Embassy.", progress = "Welcome to Stormwind, <race>.", completion = "Ah, there you are, <name>! We've been inspecting--err--expecting you!" }
WordHunterWoW_QuestEN[58147] = { title = "Stranger in a Strange Land", description = "Welcome to Stormwind, {class}. I invite you to explore our fair city. Say, you look like someone who enjoys the night life. We have many popular taverns and a vibrant music scene! \n\nAh, but that can wait, a bronze dragon has asked to talk to you. She is sitting under the nearby tree, on an hourglass of all things!\n\nAfter that, an emissary of the Mechagnomes is waiting to welcome you to the city. Sounds like a busy day for you!\n\nHave a pleasant stay, {name}!", objectives = "Find Chromie in Stormwind City.", progress = "So, how does Stormwind suit you?", completion = "You will be an excellent representative of what it means to be a <race>.\n\nStay shiny out there, friend." }
WordHunterWoW_QuestEN[58151] = { title = "Minions of N'Zoth", description = "The howling winds that surround us may some day be drowned out, masked by these increasingly dark, yet familiar whispers.\n\nSomething must be done.\n\nEnter the darkness, {name}, and strike down the enemy.", objectives = "Defeat 20 minions of N'Zoth within the vision.", progress = "The winds envelop us, comforting, calming... but beneath it all lurks a great, ever-present darkness.", completion = "Your work will not go unnoticed. Of that, I am certain." }
WordHunterWoW_QuestEN[58155] = { title = "A Hand in the Dark", description = "Imagine being trapped in a world you didn't know existed--a reality unbeknownst to even yourself.\n\nThoughts, fears, and dark desires cloud the mind, coupled with irresistible temptation.\n\nSo many are lost to the darkness, unable to resist these temptations, but not all.\n\nDo what you can to preserve those that fight against the darkness. We mustn't allow them to fall.", objectives = "Rescue 8 souls from the vision.", progress = "It is best not to linger in darkness.", completion = "The withering whispers lie in wait. Remain vigilant, <name>." }
WordHunterWoW_QuestEN[58156] = { title = "Vanquishing the Darkness", description = "The darkness grows. The cycle continues.\n\nDo what you can to stay N'Zoth's efforts. If we do not stand against the corruption we may some day find ourselves drowning in darkness.", objectives = "Repel N'Zoth's corruption within the vision.", progress = "We both know what must be done.", completion = "Your dedication to stemming the corruption remains invaluable, <name>." }
WordHunterWoW_QuestEN[58157] = { title = "Break a Leg", description = "The show is about to begin! You... that's what you're going to wear? Well, I suppose it works.\n\nFor your grand introduction, we will re-enact recent victories and events that took place on Azzinoth. Er, Azeroth. That's where you're from, right?\n\nThe Starlight Company has graciously volunteered to assist us in this production. We've recruited some special guests as well! \n\nDon't worry about the script. This is your story, after all!\n\nJust try not to get too much blood on stage. It's hard to clean.", objectives = "Reenact the Third Invasion of the Legion on Azeroth.", progress = "Well, that wasn't... terrible.", completion = "Not bad! Not great, but not bad. Quickly now, we'll need to help set the stage for the next act!" }
WordHunterWoW_QuestEN[58158] = { title = "The Fourth Wall, er, War", description = "It's time for the next act of your theatrical introduction: the Grand Drama Of Azereth!\n\nAzeroth. Right. All these worlds are hard to tell apart.\n\nHelp set the stage, then come back here. You'll need to play a few other characters before you appear as yourself again.\n\nGet a move on! We have a lot to cover!", objectives = "Set the Stage then help the reenactment of events after the Legion's fall.", progress = "Come on, come on! We have a crowd to please!", completion = "I can honestly say I have never seen a performance quite like this.\n\nNow... On to our grand finale! A battle for your world that is certain to make the court sit up and take notice!" }
WordHunterWoW_QuestEN[58159] = { title = "What's My Motivation?", description = "Now for our finale! A thrilling performance of the most recent trials on Azathoth!\n\n<Featherlight checks his notes.>\n\nAzeroth. Whatever. It features an artificial god, a powerful magic ice princess, an infamous queen, and an eldritch abomination of unspeakable terror! Who doesn't love a good drama with a dash of existential horror?\n\nYou're back to playing yourself, so just... do whatever heroes are supposed to do!", objectives = "Perform the final acts!", progress = "Well! That was exciting.", completion = "A fair enough performance! \n\nI think everyone's more acquainted with your world and the role you've played within it.\n\nNext time, the set design will be a bit more... prepared. But for now...\n\n<Moonberry nods at Ysera.>\n\nI think your friend wishes to have a word. Don't take too long. We still have to hold the final induction ceremony at the Heart of the Forest." }
WordHunterWoW_QuestEN[58160] = { title = "For Queen and Grove!", description = "A stunning performance... in more ways than one.\n\nSo much has transpired on Azeroth in my absence. But there was one dream I did not see portrayed onstage.\n\nI dreamt of Tyrande, engulfed in darkness, twisted by anger and a thirst for vengeance. I witnessed a forbidden ritual, the rise of a new Night Warrior, and a hunt that can end only in tragedy. That too must be real.\n\n<Ysera shakes her head.>\n\nThe Winter Queen awaits you in the Heart of the Forest. We had best be on our way.", objectives = "Travel with Ysera back to the Heart Tree to join the Covenant.", progress = "Welcome to the Hunt.", completion = "Your actions here will echo beyond the veil. Aid the forest, and all mortal worlds may yet be saved." }
WordHunterWoW_QuestEN[58161] = { title = "Forest Disappearances", description = "A moment of your time, friend?\n\nA short while ago a sylvar named Partik came seeking the aid of our grove. He said his village was under attack by the gorm and was in danger of crumbling away altogether. I told him we could not spare any soldiers, but their people were welcome to take refuge with us.\n\nHowever, it has been some time since he left and I have not seen or heard anyone from that region since.\n\nCan you go investigate? He came from the northeast.", objectives = "Find Partik.", completion = "No, no... what is happening!?" }
WordHunterWoW_QuestEN[58162] = { title = "Mysterious Masks", description = "The village, my friends, gone. They are no more.\n\nI came back from the nearby grove to find them... like this. Even Lavrash, my best friend! He came at me with only violence in his heart.\n\nThey are all wearing these masks now, and they are not themselves anymore.\n\nPlease, deliver them from this fate. Bring me their masks and perhaps we can decipher this mystery.", objectives = "Collect 15 Featureless Masks.", progress = "For so many to fall, I did not think I was gone that long....", completion = "These masks must contain some secret to the possession." }
WordHunterWoW_QuestEN[58163] = { title = "A Desperate Solution", description = "<A well-made, if well-worn, journal catches your eye.\n\nThumbing through the pages, it is clear that this journal once belonged to someone prominent from this group of night fae. The last few pages are torn out of the book.\n\nPerhaps if the rest of the pages were located then Partik could help decipher what happened here.>", objectives = "Find the missing journal pages.", progress = "What's that you've got there?", completion = "<Partik quickly reads over the last few pages. His face turns pale.>" }
WordHunterWoW_QuestEN[58164] = { title = "Cult of Personality", description = "Some of my people are still alive! We must rescue them!\n\nThe prisoners are kept in cages throughout the ridge, waiting for this horrible fate to befall them.\n\nPlease, set them free. We cannot let what happened to Lavrash happen to them!", objectives = "Rescue 8 trapped night fae.", completion = "So few.... But each one is one more friend we can bring to bear against this madness!" }
WordHunterWoW_QuestEN[58165] = { title = "Cut the Roots", description = "It's just as I feared, friend. The entire village is turned, just like Lavrash.\n\nLewor would have transformed the other elders as soon as possible. They are all strong in their own right. Brave Fiona, clever Bitterfly....\n\nIt pains me to say this, but they must be destroyed. For the good of Ardenweald and the forest, slay our former leaders before they can infect the rest of the land!", objectives = "Slay Bitterfly, Fiona Bleakthorn, and Wildtwister Lewor.", progress = "If they fell, then what hope do we have?", completion = "<Partik gulps and turns pale.>\n\nThat's all of them, then? Good." }
WordHunterWoW_QuestEN[58166] = { title = "Unknown Assailants", description = "This must be the stone he found. I do not recognize the mark.\n\nYou should bring this to the nearby droman. They are wise and retain much of the knowledge of the forests and the realms beyond. They will know what to do.", objectives = "Bring the Strange Runestone to Droman Tashmur in Tirna Vaal.\n\nProvided item:", completion = "What rustles you so, young one?" }
WordHunterWoW_QuestEN[58167] = { title = "Preventative Measures", description = "Waves of darkness continue their assault on the shores of our world. I am afraid the waters at our feet may soon wash over us. Perhaps it is time for a different approach.\n\nMake your way into the twisted realm and seek out their dark portals. If we are able to slow their advance it might just buy us the time needed to expose a fatal weakness.", objectives = "Destroy 3 Void Portals within the vision.", progress = "Darkness lurks beneath the waters.", completion = "A brief reprieve to catch our breath. Let us hope it lasts." }
WordHunterWoW_QuestEN[58168] = { title = "A Dark, Glaring Reality", description = "Their eyes are upon us, {name}, watching every move from the shadows. It is no wonder our efforts thus far have felt... lacking.\n\nThe fault is by no means your own. We should have suspected this was the case long ago.\n\nIf we are to continue our efforts with meaningful expectations we must go undetected.\n\nOur old friend has offered an elixir to aide in exposing our enemy. While there may be a few... unknown side effects, the result provides the imbiber true sight in the darkness.", objectives = "Defeat 6 Darkglare Watchers within the vision.", progress = "Seeing things more clearly?", completion = "Keep your eyes open, <name>." }
WordHunterWoW_QuestEN[58173] = { title = "What Are They Hiding?", description = "", objectives = "" }
WordHunterWoW_QuestEN[58174] = { title = "All An Aspirant Can Do", description = "I think we can agree that such a reply feels... somewhat hollow.\n\nI choose to take faith that we have done all we can. All of us. I do not know what comes next, but perhaps the path will reveal itself. In the meantime, Pelagos and I will return to Aspirant's Rest for a moment of respite.\n\nWe will meet you there, though there is no need to hurry.", objectives = "Return to Aspirant's Rest.", completion = "<Kleia smiles warmly at you.>\n\nDoes this mean you intend to stay?" }
WordHunterWoW_QuestEN[58175] = { title = "The Eternal Forge", description = "The Forgelite Prime has taken up the mantle of building our new Crest of Ascension.\n\nNo ordinary tools or materials will do. He will require Phaestus, Genesis of Aeons, Hammer of the First Forgelite. It sits at the shrine to the First Forgelite in the Eternal Forge.\n\nThe Forsworn have taken over this forge to create their own endless centurion army. You must meet Mikanikos at the forge, push back the Forsworn, and retrieve Phaestus for our own uses.", objectives = "Meet Mikanikos at the Eternal Forge.", completion = "<name>! Can you believe what the Forsworn have done to my forge?\n\nMust find Phaestus and halt their operation!" }
WordHunterWoW_QuestEN[58176] = { title = "Stewards of a Feather", description = "You! Maw Walker!\n\nThe forge was bustling. Many forgehands, on task!\n\nThen Forsworn came. Some followed their demands, turned to their side.\n\nBut not all! Yes, rescue forgehands so they can aid us. Work to be done!", objectives = "Free 5 Captured Forgehands.", progress = "I tried to save, but am no hero. Can only try to organize chaos.", completion = "You did it! Many forgehands return today. Maybe one day the rest return too?\n\nWe will help." }
WordHunterWoW_QuestEN[58177] = { title = "Refining Ego", description = "I will locate Phaestus. In the meantime, task for you!\n\nThe Forsworn use my forge to make their centurion army. Their vile intentions warp the metals we use!\n\nDestroy their centurions, take their parts. Smelt them down in the forge to purify the metals, then return to me.\n\nI need much metal for my plan.", objectives = "Collect 8 Purified Metal by collecting Tainted Centurion Components from centurion units and smelting them down at the Eternal Forge.", progress = "I keep my resources here. The Forsworn stole from me! I cannot let this stand.", completion = "We shall use this metal for many purposes. For the Crest, and for my goliath!" }
WordHunterWoW_QuestEN[58178] = { title = "A Partner for Eternity", description = "Before returning to the Hold, one more thing to do.\n\nDefeat the Forsworn and their centurion army!\n\nThis goliath here can help with just that. My finest creation yet!\n\nI need an extra pair of hands. Yours will do.", objectives = "Help Mikanikos finish his finest creation.", progress = "Trust he is no ordinary goliath. An extension of my hand itself!", completion = "A partner that embodies my inner strength.\n\nA worthy centurion indeed!" }
WordHunterWoW_QuestEN[58179] = { title = "Instruments of Perfection", description = "Mikanikos is no ordinary steward. He is wise! Talented! The smartest of us all!\n\nAlso very particular!\n\nHe cannot work without his tools. The Forsworn scattered them around the forge!\n\nYou need to rebuild Crest? Retrieve his tools!", objectives = "Collect Mikanikos's Soulsteel Clamps, Sparkling Driftglobe Core, and Gracepetal Incense Burner.", progress = "I cannot work in these conditions.", completion = "Sika sent you to retrieve my tools?\n\nShe knows what I need to be productive." }
WordHunterWoW_QuestEN[58180] = { title = "Phaestus, Genesis of Aeons", description = "Sika reports the Forsworn are widespread. They not only took over production, but the rise as well!\n\nThey organize their armies from the cliffs, send word back to their leaders.\n\nThey've ransacked our shrine to the First Forgelite and took her hammer. My hammer!\n\nDefeat their commander, retrieve Phaestus. You must go now!", objectives = "Collect Phaestus, Genesis of Aeons from Overseer Atticus.", progress = "Without Phaestus, we cannot work on the Crest.", completion = "Phaestus returns! Glorious day.\n\nMany thanks, friend. This hammer has been passed down for eons! It belongs in my masterful hands." }
WordHunterWoW_QuestEN[58181] = { title = "Building the Base", description = "The Crest is almost complete.\n\nI give you the honor of the final touch.\n\nYou have done much. Please, take Phaestus and give the final blow!", objectives = "Complete the Crest of Ascension.", progress = "Please care. Phaestus is older than you could dream!", completion = "Perfection!\n\nIt is beautiful, yes? Not done yet, but much work led to great reward." }
WordHunterWoW_QuestEN[58182] = { title = "Dismantling the Opposition", description = "The Forsworn mobilize!\n\nWe cannot allow them to march.\n\nAttune to Bron, share your power with him.\n\nBetween the three of us, we shall destroy this new centurion army!", objectives = "Ride Bron, then defeat 30 Forsworn forces and dismantle 2 Colossus in the Eternal Forge.", progress = "Bron was not meant as a tool of destruction, but will excel at it with you!", completion = "Exhilarating! Bron grows stronger with your power." }
WordHunterWoW_QuestEN[58183] = { title = "Friend to the Forgelite", description = "With Phaestus in hand, we can start building Crest.\n\nLet us return to Elysian Hold. Triumphant!", objectives = "Return to Polemarch Adrestes in Elysian Hold.", completion = "Mikanikos returned not long ago with his new centurion. Quite the unique unit.\n\nOf course, the return of Phaestus to kyrian hands is good news indeed. The Archon will be pleased." }
WordHunterWoW_QuestEN[58184] = { title = "Antiquated Methodology", description = "You possess the correct mindset for retraining a phalynx. I believe you could find great success here.\n\nBefore you commit, I implore you to go across the hill and introduce yourself to my rival, Nemea. She believes that her unreasonable, free-willed larions are better partners than my perfect phalynx.\n\nExperience her lifestyle so that you may know how much greater my work is.", objectives = "Talk to Nemea at Nemea's Retreat.", completion = "Pelodis sent you, did he?\n\nSure his phalynx follow orders, but where is their depth?" }
WordHunterWoW_QuestEN[58185] = { title = "Success Without Soul", description = "The larions seem to truly enjoy your company, Andira most of all.\n\nI hope you've come to understand and appreciate the nuance of working with a beast with free will.\n\nNow you must spend time with Pelodis, down the hill. His phalynx may be effective, but working with them only brings hollow satisfaction.\n\nI am sure working with the phalynx will only strengthen your appreciation of larions.", objectives = "Talk to Pelodis at Forgefire Outpost.", completion = "I understand you met with Nemea first.\n\nTake solace in the fact that you will not be working with crazed beasts here." }
WordHunterWoW_QuestEN[58207] = { title = "Buggin' Out", description = "", objectives = "" }
WordHunterWoW_QuestEN[58208] = { title = "Brace for Impact", description = "That's it for warming up. You and the other new recruits are a promising bunch, I'll tell you that much.\n\nHold on... what's that sound? I think something big is headed our way!", objectives = "Find Lady Jaina Proudmoore inside the ship.", completion = "This ship may not make it to the island.\n\nHold on to something sturdy and stick with your fellow recruits. We'll get through this." }
WordHunterWoW_QuestEN[58209] = { title = "Stand Your Ground", description = "I hope this rain isn't a bad omen... this is supposed to be a simple rescue mission.\n\nYou'll be sparring with me today. We have to make sure you can handle yourself once we make landfall.\n\nLet's see what you've got!", objectives = "Spar with Private Cole.", progress = "Having trouble? Happens to the best of us. Just stay calm, select your target, and use one of your abilities on it.\n\nMake sure your target is in front of you. We don't want another incident like when Bjorn tried to throw an axe over his shoulder.", completion = "You're a skilled <class>, recruit. I think you'll prove a welcome addition to the main rescue team." }
WordHunterWoW_QuestEN[58211] = { title = "Pumped Up", description = "When this necropolis collapsed, plenty of its parts got submerged in the riverbed flowing just outside. I hope you're really dedicated to fixing this place, because we're gonna dredge those parts back up!\n\nTake this pump. If you find any places bubbling in that sludge, that's a good sign parts will be there!\n\nJust be careful with whatever you pull up! You could face some resistance.", objectives = "Collect 15 Salvaged Gear by using the Sludge Pump near bubbling sludge.", progress = "Have you recovered anything useful?", completion = "You love to see it!" }
WordHunterWoW_QuestEN[58214] = { title = "Urgent Care", description = "Excellent timing, {name}.\n\nKelsey Steelspark has been sending communications to the capital cities looking for aid.\n\nMekkatorque's condition is quite dire and time is of the essence.\n\nHurry to Boralus Harbor, she will be watching for you.", objectives = "Find Kelsey Steelspark in Boralus Harbor.", completion = "You are just in time." }
WordHunterWoW_QuestEN[58216] = { title = "Consuming Maw", description = "", objectives = "" }
WordHunterWoW_QuestEN[58221] = { title = "Gettin' Even", description = "", objectives = "" }
WordHunterWoW_QuestEN[58229] = { title = "A Rallying Cry", description = "Our lands have been infested by the minions of the Old Gods. They strike at every front, even assailing the very minds of our soldiers.\n\nOur forces cannot handle this for long. We must strike a decisive blow to try to salvage some of their morale.\n\nFind the biggest, slimiest, tentacle-faced monstrosities that you can and bring them down. My men will rally to your example.", objectives = "Kill 3 rare minions of N'Zoth in Uldum.", completion = "My men will look to your victories this day to bolster their spirits. \n\nRamkahen owes you a debt, <class>." }
WordHunterWoW_QuestEN[58230] = { title = "Blind the Eyes", description = "Strange forces have been interfering with my visions of late. The ever-watching eyes pierce through the veil, shattering my clairvoyance.\n\nThe eyes of our enemy peer into our very souls and pierce our minds. We must rip them out, if we truly wish to be rid of the curse on this land.", objectives = "Kill 6 Foul Observers in the Akhenet Fields in Uldum.", progress = "Is it done?", completion = "The eyes are closed, and my clairvoyance returns.\n\nThank you, <class>." }
WordHunterWoW_QuestEN[58231] = { title = "Wisdom From Madness", description = "In my visions I hear... voices...\n\nTheir words are nonsense, but over time patterns arise. I believe there is something important behind what these voices say, but I have yet to decipher a word.\n\nWe will need to learn from the source. Find any writings you can among the cultists who travel with these dark creatures. Their ramblings may be the key to understanding the message beneath this madness.", objectives = "Collect 10 Maddened Writings from Black Empire Cultists in Uldum.", progress = "Have you found the writings?", completion = "As I suspected, the writings of the cultists appears to be completely incoherent.\n\nLet us hope some truth lies within this madness." }
WordHunterWoW_QuestEN[58232] = { title = "Order Among Chaos", description = "It has been a long time since the tol'vir have squared off against the forces of an Old God, so our tactical knowledge of their forces is limited.\n\nHowever, one tenet of combat always holds true -- striking down those that issue the orders will weaken the foe much greater than the rank and file. \n\nI have observed that the larger faceless minions act as commanders of the Old Gods' forces. Silence them, and perhaps we can sow a different kind of chaos in their ranks.", objectives = "Kill 6 faceless minions of N'Zoth in Uldum.", completion = "A decisive strike against their commanders should buy us some time.\n\nThank you, <class>." }
WordHunterWoW_QuestEN[58233] = { title = "Twisted Corruptors", description = "While the fleshbeasts that accompany the invading forces appear to be no more than a nuisance, they carry within themselves a deep connection to the corrupting powers of the Old Gods. \n\nLike a pestilence, they spread the N'Zoth's corruption wherever they tread, slowly twisting the very land to their form.\n\nThey must be eradicated.", objectives = "Kill 10 fleshbeasts in Uldum.", completion = "Uldum breathes a sigh of relief with each twisted manifestation of N'Zoth slain." }
WordHunterWoW_QuestEN[58234] = { title = "Questionable Sourcing", description = "My clairvoyance provides a great strategic asset to the people of Ramkahen. However, the potency of my visions of late has proven taxing to my health.\n\nI have devised a tonic that may serve to dull the harm these visions cause, but it will require the coalesced essence of the Old Gods' corruption.\n\nIf you could retrieve some samples of this for me, it could prove invaluable in our efforts.", objectives = "Collect 8 Coalesced Corruption from slimes in Uldum.", progress = "Have you acquired the reagent?", completion = "You've returned with the samples? Excellent.\n\nLet us hope this has the intended effect." }
WordHunterWoW_QuestEN[58235] = { title = "Anchors of the Black Empire", description = "This invasion struck us without warning, with structures reminiscent of the Black Empire materializing out of nothing, pouring out the forces of the Old Gods. We have no idea how they came to be or where they came from.\n\nHowever, whenever a new structure appears, it is preceded by malefic obelisks. We believe these obelisks act as anchors to usher in more of the Old Gods' forces.\n\nIf we truly wish to stem the tide of this invasion, we must destroy the obelisks.", objectives = "Destroy 6 Black Empire Obelisks in Uldum.", completion = "While the threat has far from subsided, it is comforting to know that our enemy's reinforcements have been slowed. \n\nWe may just survive to see an end to this battle." }
WordHunterWoW_QuestEN[58236] = { title = "Symbolic Destruction", description = "The cultists that follow this dark legion befoul our lands with symbols of the tyrants they follow. \n\nTheir mindless followers flock to these banners, worshipping them as unholy idols.\n\nBurn them down, and cleanse their taint from our lands.", objectives = "Destroy 6 Banners of the Black Empire in Uldum.", completion = "Good. It will be a fine day when these disgraceful sigils no longer befoul our land." }
WordHunterWoW_QuestEN[58237] = { title = "Cleansing Uldum", description = "Every moment that N'Zoth's forces remain in Uldum, his corruption seeps further into the land itself.\n\nEven if we were to drive back his minions, the damage he has done to Uldum may be irreversible. \n\nWe must seek out his corruption where it festers and eliminate it.", objectives = "Destroy 6 Corruption Tumors in Uldum.", progress = "We must put a stop to N'Zoth's Corruption.", completion = "Even now, I sense N'Zoth's corruption waning.\n\nYou have done well." }
WordHunterWoW_QuestEN[58238] = { title = "Lost and Tormented", description = "Our citizens here in Ramkahen have managed to escape the brunt of N'Zoth's assault. \n\nOur brothers in the Lost City were not so fortunate. Those not immediately slain have been held captive only to be tortured by N'Zoth's minions.\n\nI know that you will be taking the fight to N'Zoth's forces. If you can free our allies as well, Ramkahen will be in your debt.", objectives = "Free 6 Ramkahen Citizens from Torment Cells within the Lost City of Tol'vir in Uldum.", completion = "Our citizens owe you a debt they may never be able to repay, <name>.\n\nRamkahen thanks you for this service." }
WordHunterWoW_QuestEN[58239] = { title = "Lessons in Brigandry", description = "The Wastewanders have spent many generations as brigands, whether on land or sea. Though we have decided to hang up that life for a chance at a more peaceful existence, we have not forgotten the lessons we've learned in those days.\n\nOne such lesson I feel is particularly relevant now -- when faced with a superior opponent, it often helps to use their weapons against them.\n\nFind their hidden caches and take whatever you can carry. You may just find something that can turn the tide of this battle.", objectives = "Loot 3 Black Empire Caches in Uldum.", progress = "Found anything worthwhile?", completion = "I hope you found what you were looking for.\n\nWe can use all the help we can get in this fight." }
WordHunterWoW_QuestEN[58256] = { title = "Consuming Maw", description = "", objectives = "" }
WordHunterWoW_QuestEN[58257] = { title = "Consuming Maw", description = "", objectives = "" }
WordHunterWoW_QuestEN[58258] = { title = "Consuming Maw", description = "", objectives = "" }
WordHunterWoW_QuestEN[58260] = { title = "Queens And Future Kings", description = "A swarm of marrowbore queens have been laying eggs atop the ruins of our house. We may be able to use this to our advantage.\n\nWith Twigin's help, eliminate the queens and recover larvae from the eggs.\n\nI have a plan for the larvae that may allow us to use the marrowbore to our advantage.", objectives = "Slay 1 marrowbore queens, and collect 5 marrowbore larvae.", progress = "It's dirty work, but we need those larvae.", completion = "Now to put these to a useful purpose." }
WordHunterWoW_QuestEN[58264] = { title = "Wake Up, Get Up, Get Out There", description = "They need your help!\n\nNot all of the faeries have been turned yet. Some remain prisoner, but they have these masks on their faces....\n\nYou've got to help them! I'm not strong enough to pry off the masks, but you could! You could stop the guards from getting us too!", objectives = "Aid 8 subdued faeries.", completion = "You saved my friends!\n\n<Primrose gives you a small grin.>\n\nWe... we make a pretty good team, huh?" }
WordHunterWoW_QuestEN[58265] = { title = "Blooming Villains", description = "Something stinks, traveler. The air to the west is rotten with malice.\n\nShimmerbough has long been a peaceful way station along the Path of Rebirth. The faeries there delight in revelry and celebration. But now their glade has fallen silent.\n\nScouts bring reports of the strange masked night fae. I know little other than that they are a threat.\n\nFor the sake of Ardenweald, they must be eliminated. Slay any you encounter.", objectives = "Slay 15 masked night fae in Shimmerbough.", completion = "Grim work, but necessary. May they be reborn into useful vassals of Ardenweald once more." }
WordHunterWoW_QuestEN[58266] = { title = "Break It Down", description = "I've seen the ritual. It's... terrifying.\n\nBut the altars seem to be the key. If only I had my pyrotechnic powder, I could blast them to bits!\n\n<Primrose is silent for a moment, then takes a deep breath.>\n\nIf you could get the powder and guard me, we could blow up those altars.\n\nI stashed as much as I could in our dwellings. They don't seem to care any more.\n\nYou don't have wings, but a pinch of faerie dust should work for a short time.\n\nLet's do this before I change my mind!", objectives = "Use Primrose's Pyrotechnic Powder to destroy 5 Ritual Altars.", completion = "We did it! All the altars are destroyed!" }
WordHunterWoW_QuestEN[58267] = { title = "Beneath the Mask", description = "It's time to end this.\n\nWhen I first hid, I saw a dark shape on the northeast platform. I think that's their leader.\n\nNow that they can't perform any more rituals, we should be able to scare them off.\n\n<Primrose pauses for a moment.>\n\nI... I just wanted to say thank you. I never could have done this without your help. Now, let's drive out this enemy and retake the village!", objectives = "Confront the leader of the possessed fae in Shimmerbough.", completion = "I see. This is terrible news." }
WordHunterWoW_QuestEN[58268] = { title = "Take the High Ground", description = "The commander of the constructs, General Alver, is a master tactician. A frontal assault has no chance of victory against him. It will be a bloodbath.\n\nHis forces have flanked us and secured the high ground. From that position, he can rain destruction upon us unopposed.\n\nWe will take the ridge from him before that can happen.", objectives = "Destroy the three enemy positions.", completion = "With that ridge clear, we'll be safe to advance." }
WordHunterWoW_QuestEN[58271] = { title = "Voidflame Ritual", description = "", objectives = "" }
WordHunterWoW_QuestEN[58272] = { title = "Words Have Power", description = "The Stoneborn Rebels have left behind recruitment pamphlets. Recovering these for the venthyr may earn some much needed favor.", objectives = "Collect 9 Rebellion Pamphlets.", progress = "Uncouth and vile documents, but written in a rather elegant hand. The Prince always had better penmanship than sense.", completion = "Ugh, vile things. Give them to me and I will see them properly disposed of.\n\nHere, for your troubles. Perhaps this reward will help wipe the filth of these documents from your fingertips." }
WordHunterWoW_QuestEN[58273] = { title = "Servant of N'Zoth", description = "{class}...\n\nI have watched you... I have felt your bloodlust. \n\nBut you serve false prophets... the Horde is an illusion... I am a god!\n\nProve to me you are worthy of my gift... kill those who are to betray you...\n\nKill... the Horde!", objectives = "Use the N'lyeth, Sliver of N'zoth to change your faction from Horde to become devoted to N'Zoth. Then slay 10 Horde players without dying." }
WordHunterWoW_QuestEN[58274] = { title = "Servant of N'Zoth", description = "{class}...\n\nI have watched you... I have felt your bloodlust. \n\nBut you serve false prophets... the Alliance is an illusion... I am a god!\n\nProve to me you are worthy of my gift... kill those who are to betray you...\n\nKill... the Alliance!", objectives = "Use the N'lyeth, Sliver of N'zoth to change your faction from Alliance to become devoted to N'Zoth. Then slay 10 Alliance players without dying." }
WordHunterWoW_QuestEN[58275] = { title = "Monstrous Summoning", description = "", objectives = "" }
WordHunterWoW_QuestEN[58276] = { title = "Mar'at In Flames", description = "", objectives = "" }
WordHunterWoW_QuestEN[58277] = { title = "Dark Deceivers", description = "The Old Gods have many faceless minions at their disposal, but none so deceiving as the ones they call k'thir.\n\nThough not nearly as imposing as their brethren, the k'thir manipulate in the shadows, bending the wills of men and even reality itself.\n\nWe must not allow their machinations to go unchecked.", objectives = "Kill 8 K'thir minions in Uldum.", completion = "We cannot let these creatures roam Uldum unhindered.\n\nYou have done well to cull their numbers." }
WordHunterWoW_QuestEN[58279] = { title = "Quartermaster's Bounty", description = "To defeat the enemy, you will need to keep your equipment in peak condition. If you have been unable to acquire more powerful arms, I can requisition from the quartermaster on your behalf.", objectives = "To defeat the enemy, you will need to keep your equipment in peak condition. If you have been unable to acquire more powerful arms, I can requisition from the quartermaster on your behalf.", progress = "To defeat the enemy, you will need to keep your equipment in peak condition. If you have been unable to acquire more powerful arms, I can requisition from the quartermaster on your behalf.", completion = "Victory at any cost." }
WordHunterWoW_QuestEN[58281] = { title = "Ancient Armaments", description = "Fighting a war on several fronts has taken its toll on our supplies. Our blacksmiths cannot repair and replace our soldiers' armor quickly enough, which is leaving us ill-equipped to face so many foes.\n\nThough the Amathet's armor is ancient, it is titan-forged and formidable. If we were able to salvage any, it could prove very useful to our defensive efforts.\n\nCan you help?", objectives = "Collect 10 pieces of Amathet Armor from armored Amathet tol'vir in Uldum.", progress = "Have you returned with the armor?", completion = "Thank the Light you've returned! Our soldiers need this armor badly. \n\nYour efforts will safeguard the lives of many in Ramkahen, <class>." }
WordHunterWoW_QuestEN[58282] = { title = "Down From the Sky", description = "The archers of Ramkahen are highly skilled, but the bows of the Amathet have the advantage of range. This makes our incursions into their territory highly dangerous.\n\nYou have a knack for fighting behind enemy lines. If you could thin out their ranks, it could provide us an opportunity to push their lines back for once.\n\nWill you help?", objectives = "Kill 8 Amathet Bowmen in Uldum.", completion = "The Amathet's arrows no longer darken our skies.\n\nWe must take this opportunity to strike!" }
WordHunterWoW_QuestEN[58283] = { title = "Blind Leading the Blind", description = "The Sun Priests are an ancient order for the tol'vir who have walked among all of the tribes. \n\nThose that follow the Amathet, however, have twisted our beliefs and weaponized them to justify their crusade against Ramkahen. Their soldiers follow them blindly, never questioning.\n\nThey must be stopped.", objectives = "Kill 8 Amathet priests in Uldum.", completion = "I take no joy in the deaths of my brethren, but the Amathet must be stopped.\n\nYou have my thanks." }
WordHunterWoW_QuestEN[58284] = { title = "Writs of the Sun King", description = "Very little is known about the Sun King that leads the Amathet. Our observations suggest that those closest to him are the \"Suntouched,\" a unique caste of solar magic practitioners.\n\nI would like very much to learn more about this Sun King but, unlike some members of the Explorers' League, I'm not willing to risk the lives of my researchers to do so. \n\nYou seem to be able to hold your own, though. If you happen upon any records about the Sun King, I'd gladly take them off your hands.", objectives = "Collect 6 Writs of the Sun King from Suntouched Amathet in Uldum.", progress = "Have you found anything interesting?", completion = "The markings on these are fascinating!\n\nI'll have my researchers begin deciphering these right away!" }
WordHunterWoW_QuestEN[58285] = { title = "Unearthed Artifacts", description = "Ever since the Amathet came out of their tombs, they've been busy unearthing titan relics from the surrounding areas. \n\nI'm not sure what they intend to do with them or if they're just hoarding it so we can't have them. Sufficed to say the Explorers' League would love to study some of what they found!\n\nOf course, we can't get anywhere close to them without the Amathet trying to stick an axe in us, but that's not a problem for you, is it? \n\nCare to help?", objectives = "Collect 6 Titan Artifacts in Uldum.", progress = "Any luck with the titan artifacts?", completion = "You really do come through, don't you?\n\nYou know, we could use some reliable folks like you in the League..." }
WordHunterWoW_QuestEN[58286] = { title = "Far From Home", description = "The Amathet's conquest of eastern Uldum was sudden, and we were unable to reach some of our farthest settlements in time. \n\nFortunately, many of the tol'vir who lived in the conquered territories were not killed, instead being put to work under the Amathet's whip. \n\nWe must take any opportunity we can to free them and return them to their homes.", objectives = "Free 6 Enslaved Tol'vir in Uldum.", completion = "We have seen the return of many of our people, thanks to you.\n\nYou have my gratitude." }
WordHunterWoW_QuestEN[58287] = { title = "A Smashing Plan", description = "Reports from my scouts mention various idols and monuments that the Amathet use to channel their solar magic. \n\nI don't know exactly what they're up to, but we should take away any possible advantage they have. So, I want you to go over there, and break anything that looks remotely magical.\n\nJust don't tell the Explorers' League. I'll never hear the end of it.", objectives = "Destroy 4 Amathet Idols and 2 Suntouched Obelisks in Uldum.", completion = "Good work, <class>.\n\nSlowly but surely, we chip away at the Amathet's resolve." }
WordHunterWoW_QuestEN[58288] = { title = "The Sun King's Chosen", description = "On the surface the Amathet appear to be unwavering, but all soldiers have their breaking point. We need to send a message to their forces that we are not to be trifled with.\n\nSeek out the strongest of their numbers and bring them down in front of their eyes. \n\nWe will show them the strength of Uldum!", objectives = "Defeat 3 rare Amathet enemies in Uldum.", completion = "Well struck, <class>!\n\nWe will find a way to break the Amathet yet!" }
WordHunterWoW_QuestEN[58289] = { title = "Guarded Secrets", description = "From what we know about the Amathet, they must've been locked away in their tombs for thousands of years. Just think of what we could learn from them!\n\nOf course, that would be a lot easier if they weren't trying to kill us. \n\nIf you happen upon any caches of Amathet relics in your travels, let me know. I'd love to see what sort of mysteries they contain!", objectives = "Loot 3 Amathet Caches in Uldum.", completion = "Fascinating find!\n\nI can't wait until the situation here calms down enough that we can get a look into these old tombs ourselves!" }
WordHunterWoW_QuestEN[58290] = { title = "Champions of the Amathet", description = "The soldiers of Ramkahen are hearty and reliable. \n\nI would stand them up against any footman of the Amathet, but some of their higher-caste fighters are too much for even our toughest to handle.\n\nI don't think they'd be a problem for you, though. It would be a boon to our defense efforts if you could handle them while my soldiers engage the rank and file.", objectives = "Kill 6 elite Amathet enemies in Uldum.", completion = "Good work, <class>. My soldiers should be able to take care of the rest." }
WordHunterWoW_QuestEN[58291] = { title = "Encroaching Poachers", description = "The Wastewanders used the pelts of the local hyenas to construct our armor. Unfortunately since the Amathet arrived, their hunters have overrun our normal hunting grounds.\n\nWe need those pelts, and will pay handsomely for them. Either take them from the hunters or skin the hyenas yourself, if you have the skill.", objectives = "Collect 6 Rugged Hyena Pelts from Amathet Hunters or by skinning hyenas in Uldum.", progress = "Have you brought back the pelts?", completion = "You're a life-saver, friend.\n\nHere's your reward, as promised." }
WordHunterWoW_QuestEN[58297] = { title = "Faceless Mask of the Daredevil", description = "The hunter never sought to lead yet sought a challenge in life at every turn. He directed his allies with a deft hand and never shied from diving in to the melee himself. The prowess he showed made him as well as my other minions much more deadly. Return this mask to the altar of the Daredevil to challenge your own resolve in battle as your foes attacks cut even more deep.", objectives = "Return the Faceless Mask of the Daredevil to the altar within a Horrific Vision.", progress = "Place the Faceless Mask of the Daredevil on the altar.", completion = "The path of the Daredevil is available to you if you dare." }
WordHunterWoW_QuestEN[58314] = { title = "Faceless Mask of the Burned Bridge", description = "The displaced warrior is always on uneasy footing, especially one who is removed from her home world. The void makes this unsteadiness a reality where one step can lead into the abyss or drain you to your core.", objectives = "Return the Faceless Mask of the Burned Bridge to the altar within a Horrific Vision.", progress = "Place the Faceless Mask of the Burned Bridge on the altar.", completion = "The treacherous path of the Burned Bridge will be available to you if you wish to tread it." }
WordHunterWoW_QuestEN[58316] = { title = "Faceless Mask of the Dark Imagination", description = "These magi, twisting their magic to manipulate and conquer the world. Imagining greater power, they tread along the lines of the Void's domain. In these pursuits, this magi came to the realization that in the depths of one's imagination lie truly dark and terrible things.", objectives = "Return the Faceless Mask of the Dark Imagination to the altar within a Horrific Vision.", progress = "Place the Faceless Mask of the Dark Imagination on the altar.", completion = "The risks at the edges of your sanity will now manifest if you so choose to engage them." }
WordHunterWoW_QuestEN[58317] = { title = "Faceless Mask of the Pained", description = "Trading in secrets, trading in lies, operating on the fringes are all the Spymaster knows. His lost passions, lost loves are all gone, crushed under his own duty and loyalty to the crown. Nothing is left, nothing but the pain. Pain is an apt tutor and tool and one in which the void knows intimately. Return my mask if you dare to feel the many forms pain can take.", objectives = "Return the Faceless Mask of the Pained to the altar within a Horrific Vision.", progress = "Place the Faceless Mask of the Pained on the altar.", completion = "As my madness and torment is not enough, feel free to invite even more pain in the future." }
WordHunterWoW_QuestEN[58318] = { title = "Faceless Mask of the Long Night", description = "The endurance needed to make it this far is extraordinary and the feat of a long experienced adventurer. Yet, the longest night is nigh and with it our ultimate conquest. Those that fight the coming of eternal twilight know only futility, for in the Longest Night they will be on the edge of sanity forever.", objectives = "Return the Faceless Mask of the Long Night to the altar within a Horrific Vision.", progress = "Place the Faceless Mask of the Long Night on the altar.", completion = "Taking a step towards the Longest Night is already acknowledging the sanity you have lost. Do you risk the rest on such a fools errand?" }
WordHunterWoW_QuestEN[58321] = { title = "Uncommon Core", description = "Our scouts have reported that the Amathet are constructing new titanic watchers. \n\nWe had long thought this art was lost to the sands of time. It would appear we were mistaken.\n\nI needn't tell you what a boon it would be to have the aid of watcher constructs in our battles for Uldum. We must unlock the secrets of their construction!\n\nThe power of a titanic watcher lies in its core. I ask that you bring one to me, so that our artificers might divine its construction.", objectives = "Collect a Titanic Core from an Ivory Watcher in Uldum.", progress = "Have you obtained the core?", completion = "Marvelous! I have never seen its like!\n\nI will have this sent to my artificers at once! With luck, they can unlock the lost knowledge within." }
WordHunterWoW_QuestEN[58325] = { title = "Watcher Emil", description = "Watcher Emil is my trusted overseer of the catacombs. Before I was thrown into the Maw, half of the mirror was entrusted to him.\n\nI had him stationed at the Catacombs of Regret. But I do not know where in the sprawl he is.\n\nThere is a guard station near the entrance to the catacombs. Start the search there. There is an officer who can help us, I--I can't remember who. That is, provided they survived this whole mess.\n\nYou must find Emil at once. We may not have much time.", objectives = "Search for Watcher Emil in the Catacombs of Regret.", progress = "A friend of the Curator?", completion = "That wasn't the first assassin I've had to deal with so far. And it won't be the last.\n\nThe Curator must have sent you. Someone has turned our allies at Archivam against us... \n\nI have the mirror shard she entrusted to me. We must move quickly, friend." }
WordHunterWoW_QuestEN[58326] = { title = "Combing the Catacombs", description = "When the anima drought began, our defenses began to fail. \n\nOur guards, weakened by the lack of anima, became overrun as the sinstones this land is built upon rose up around us. Not to mention the manifestations of the souls who can no longer be tended to are running wild.\n\nYou may be able to help us, mortal. Please, we can barely hold this position... and I don't know for how much longer.", objectives = "Kill 12 Manifestations and 3 Sinstone Rampagers in the Catacombs of Regret.", completion = "Thank you. Do me a favor and don't tell the Curator? She won't be pleased with the state of things." }
WordHunterWoW_QuestEN[58327] = { title = "Snacks for Stonehead", description = "<Stonehead has amassed a wide variety of half-eaten oddities.\n\nHe'd certainly appreciate you bringing some new, creative snacks for him to try.>", objectives = "Collect a sampling of snacks from across the Ember Ward for Stonehead.", progress = "Tummy rumbly...", completion = "<Stonehead's eyes light up when he sees the massive pile of semi-edible delicacies you brought him.>\n\nYou best bud! Best bud free to go wherever he want!" }
WordHunterWoW_QuestEN[58328] = { title = "TBD", description = "Bribe Boulderfoot", objectives = "TBDBribe BoulderfootYou will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[58334] = { title = "Mistfall In Flames", description = "", objectives = "" }
WordHunterWoW_QuestEN[58337] = { title = "Break Out", description = "Our reinforcements never came, leaving us unable to tend to the souls here. They have begun to break out of their cells. Many of them are not ready for the next step in the process.\n\nTake these iron chains. They can be used to rein them under your control. \n\nOnce you have a soul bound, you can return them to any intact cage you can find.", objectives = "Use the Chains of Regret on Escaped Captives and bring them to any intact Catacombs Cage.", completion = "Thank you, <name>. The souls are filled with vanity, rage, and sadness.\n\nSome more confinement will help them confront their past." }
