WordHunterWoW_QuestEN[58351] = { title = "The Hills Have Eyes", description = "The other houses have yet to launch a full scale assault, but do not mistake their cowardice for incompetence.\n\nAny tactician worth their weight in maldracite knows the value of espionage. I suspect that the agents of our foes skulk within our own ranks as we speak.\n\nTake one of my hounds. It will know our enemies by their scent. Once the pests have been discovered, exterminate them.", objectives = "Uncover hidden spies with the Chosen Corpsehound.", progress = "Get moving!", completion = "If they cannot properly evade detection, then they do not deserve to survive." }
WordHunterWoW_QuestEN[58352] = { title = "Conquest's Reward", description = "", objectives = "Your prowess on the field of battle is without peer." }
