WordHunterWoW_QuestEN[58370] = { title = "Empowered Demolisher", description = "", objectives = "" }
WordHunterWoW_QuestEN[58372] = { title = "Lead the Way", description = "We must move now. That won't be the last assassin we face.\n\nI can provide some cover of darkness, but mind that the spell is not infallible.\n\nEnough talking. The Curator needs us and my mirror shard to get to her as soon as possible.", objectives = "Escort Watcher Emil out of the Catacombs of Regret.", completion = "Thank you for bringing him here safely, <name>. I am glad he is alive.\n\nWith his mirror shard in hand, we now have the unfortunate task of obtaining Mateo's mirror shard.\n\nI cannot believe he betrayed us. Many venthyr have reverted to their sinful ways it seems..." }
WordHunterWoW_QuestEN[58373] = { title = "Ny'alotha: MOTHER's Guidance", description = "Ny'alotha does not obey the rules of space and time, and we may be able to use this to our advantage.\n\nMOTHER theorizes that if we obtain specific objects from N'Zoth's chosen, we can utilize them to bend space and expedite our passage here in the future. Though, it is doubtful they will relinquish these items willingly.", objectives = "Collect 4 Titan Cores from Ra-Den, 4 Dragon Hearts from Vexiona and 4 Prophetic Eyes from Il'gynoth within Ny'alotha, the Waking City on Normal Difficulty.", progress = "Without the items MOTHER cannot guarantee safe passage.", completion = "With these items, MOTHER can guarantee safe access to this area." }
WordHunterWoW_QuestEN[58374] = { title = "Ny'alotha: MOTHER's Guidance", description = "Ny'alotha does not obey the rules of space and time, and we may be able to use this to our advantage.\n\nMOTHER theorizes that if we obtain specific objects from N'Zoth's chosen, we can utilize them to bend space and expedite our passage here in the future. Though, it is doubtful they will relinquish these items willingly.", objectives = "Collect 4 Titan Cores from Ra-Den, 4 Dragon Hearts from Vexiona and 4 Prophetic Eyes from Il'gynoth within Ny'alotha, the Waking City on Heroic Difficulty.", progress = "Without the items MOTHER cannot guarantee safe passage.", completion = "With these items, MOTHER can guarantee safe access to this area." }
WordHunterWoW_QuestEN[58375] = { title = "Ny'alotha: MOTHER's Guidance", description = "Ny'alotha does not obey the rules of space and time, and we may be able to use this to our advantage.\n\nMOTHER theorizes that if we obtain specific objects from N'Zoth's chosen, we can utilize them to bend space and expedite our passage here in the future. Though, it is doubtful they will relinquish these items willingly.", objectives = "Collect 4 Titan Cores from Ra-Den, 4 Dragon Hearts from Vexiona and 4 Prophetic Eyes from Il'gynoth within Ny'alotha, the Waking City on Mythic Difficulty.", progress = "Without the items MOTHER cannot guarantee safe passage.", completion = "With these items, MOTHER can guarantee safe access to this area." }
WordHunterWoW_QuestEN[58376] = { title = "Construct Part: Necromantic Oil", description = "<This could be used to construct a powerful abomination. Perhaps Rathan will know how we can use it.>", objectives = "Deliver this part to Rathan in Butchers Block.\n\nProvided item:", completion = "This ingredient can help construct a very powerful abomination. You should save it incase we find a use for it." }
WordHunterWoW_QuestEN[58379] = { title = "Construct Part: Indomitable Hide", description = "<This could be used to construct a powerful abomination. Perhaps Rathan will know how we can use it.>", objectives = "Deliver this part to Rathan in Butchers Block.\n\nProvided item:", completion = "This ingredient can help construct a very powerful abomination. You should save it incase we find a use for it." }
WordHunterWoW_QuestEN[58382] = { title = "Someone Worth Saving", description = "Are you familiar with Kael'thas Sunstrider? He was a powerful leader on your world for a time.\n\nThe immense anima of that lingering power attracted the Master's attention, to the eternal detriment of Kael'thas's soul.\n\n<The Accuser's lip curls in disgust.>\n\nEvery soul deserves a chance at redemption, {name}.\n\nIf you do not believe that, believe me when I say that this soul is immensely powerful and still at risk of self-destruction.\n\nRelease him so that we may walk his path of redemption together.", objectives = "Release Kael'thas Sunstrider in Sinfall.", completion = "It shall not be easy to redeem Kael'thas Sunstrider, and the outcome is far from guaranteed.\n\nBut we must attempt it nonetheless." }
WordHunterWoW_QuestEN[58383] = { title = "The Many Sins of Kael'thas Sunstrider", description = "Kael'thas Sunstrider was on the verge of destruction when we rescued him from Castle Nathria.\n\nDenathrius had infused Kael'thas with unimaginable amounts of anima, each bit carrying with it the sins of others.\n\nIt made his soul strong, but unstable--confused and pushed to the edge of its own existence.\n\nTrust me when I tell you that Kael'thas Sunstrider has enough sins of his own.\n\nAssist me in identifying which of the many sins heaped on his soul are truly his burden to bear.", objectives = "Help the Accuser identify the sins of Kael'thas Sunstrider.", completion = "To be clear: We did not absolve Kael'thas Sunstrider of any of these sins.\n\nHe might never be absolved of them. It must ultimately be his choice to change.\n\nBut we did stabilize his soul, which means he will at least have the opportunity to make that choice." }
WordHunterWoW_QuestEN[58384] = { title = "Dredgers Left Behind", description = "When Prince Renathal fled Darkwall Tower, he was forced to leave many people and belongings behind.\n\nThe powerful relics and weapons were long ago carted off to the Master's lair. But the Prince's dredgers were forced to stay and serve the Master's traitorous lackeys here instead.\n\nYou will be a welcome sight to them--a sign that the Prince has not forgotten them.\n\nIf they are willing to fight, help them escape and I will ensure they are brought safely to Sinfall.", objectives = "Help 10 dredgers escape Darkwall Tower.", completion = "I must admit, I did not expect the dredgers to be quite so eager to fight for their own freedom.\n\nThe Prince inspires all of us, I suppose." }
WordHunterWoW_QuestEN[58385] = { title = "Learning to Sacrifice", description = "Kael'thas remains unstable in his current state, bursting at the seams with anima.\n\nHe is also an arrogant, selfish moron.\n\nThankfully, I have a lesson that can address both concerns.\n\nTrue leaders sacrifice of themselves to empower those under their care.\n\nMany stoneborn and gargon, including the Prince's own pet, were left dormant in Darkwall by the Master's forces.\n\nOrder Kael'thas to forfeit portions of the anima trapped inside of him to reanimate those dormant stoneborn to aid us.", objectives = "Help Kael'thas reanimate the Prince's pet, Vrednic, and other dormant stoneborn in Darkwall Tower.", completion = "Kael'thas Sunstrider may be ready for the ritual of absolution now." }
WordHunterWoW_QuestEN[58386] = { title = "Use My Strengths", description = "<Kael'thas looks around to make sure the Accuser is out of earshot.>\n\nThe Accuser is so obsessed with my negative traits that she has failed to see my strengths!\n\nEven in death, I am incredibly powerful. The Accuser herself said that Denathrius infused me with anima to make me strong.\n\nLet us use that strength for good while I have it!\n\nThis tower once belonged to the Prince of this realm, correct? Let us find his usurper and gain vengeance!\n\nVengeance is a virtue I have always appreciated.", objectives = "Help Kael'thas confront Usurper Simona.", progress = "Yes?", completion = "I do not expect Kael'thas to agree or even understand the value of mercy immediately.\n\nAbsolution is a long, slow process. This was only the first step." }
WordHunterWoW_QuestEN[58387] = { title = "We Each Must Carry Our Own Sins", description = "The Master chained Kael'thas's sinstone to his soul via a dark, corruptive process that left Kael'thas scarred and overburdened.\n\nHe bears the weight of not only his own sins, but the sins of countless other souls on his back. That would be a crushing burden for even the most noble of souls--which Kael'thas is not.\n\nLet us hope your time with Kael'thas has prepared his soul for my ritual.\n\nI must break that cursed burden by removing the foreign sins from his soul, or else we'll lose him forever.", objectives = "Complete the ritual of extraction on Kael'thas Sunstrider.", progress = "This must work.", completion = "I cannot comfortably call this a success, but it is likely the best outcome we could have hoped for. Carrying one's sins is no small feat, yet it can be liberating.\n\nTake this chain, if you wish, to display your commitment to owning your own sins. Kael'thas needs it no longer." }
WordHunterWoW_QuestEN[58388] = { title = "Blackbale Betrayers", description = "When the Prince made his final stand at Darkwall Tower, he called for aid from the many noble houses here in the Chalice District.\n\nNone came.\n\nMost simply avoided the conflict, out of self-preservation. A shameful, but understandable choice.\n\nHowever, one house took action. Lord Blackbale replied with cruel mockery and sent his stoneborn to aid the Master's armies instead.\n\nPrince Renathal has not forgotten that betrayal.\n\nKael'thas seeks vengeance? Let him have some. Start with the stoneborn.", objectives = "Kill 4 Blackbale Overseers.", completion = "Did any of the Blackbale venthyr show signs of regret?\n\nWe had hoped to recruit some to our cause eventually." }
WordHunterWoW_QuestEN[58389] = { title = "Maldraxxian Weapons", description = "<The weapon you find seems unlike those wielded by most venthyr, yet the marks it bears are unmistakably familiar...\n\nIt would be wise to seek out more such weapons and bring them to the Accuser.>", objectives = "Collect 8 Maldraxxian Weapons.", progress = "What are you carrying? Those do not belong here...", completion = "The Blackbale venthyr are wielding the weapons of the Maldraxxi army?\n\nThat would mean..." }
WordHunterWoW_QuestEN[58391] = { title = "Reconnaissance... for my, uh, Recovery", description = "It appears I am at your mercy once more, {name}.\n\nFar be it from me to tell you the best way to absolve my sins as the Accuser insists we do.\n\nHowever...\n\nIn that note, the Tithelord arranged a meeting with his contact in Darkhaven. Do you know where that is?\n\nIf you do, we could investigate, gather more information, and present that information to the Accuser and Prince Renathal.\n\nI imagine that would be quite useful to them.\n\nAnd a very selfless act of assistance on my part, do you not agree?", objectives = "Spy on the Tithelord's meeting with his Maldraxxian contact.", completion = "A lich? So close?\n\nCan you feel its presence? I once could..." }
WordHunterWoW_QuestEN[58392] = { title = "Death's End Destruction", description = "It appears we have discovered a common enemy to pursue, {name}.\n\nWherever that necromancer ran off to is no doubt filled with traitors, undead armies from another realm, and at least one lich...\n\nIt cannot be a sin to kill such as these. To demolish the camp of these invaders and betrayers must be a virtue.\n\nA virtue I crave. Let us pursue it with haste.", objectives = "Destroy the Maldraxxian camp in Death's End.", progress = "I hope they put up a fight.", completion = "Traitors and cowards. I have time for neither!" }
WordHunterWoW_QuestEN[58393] = { title = "Strategic Executions", description = "I confess that I do not comprehend the full array of potential consequences wrought by the Tithelord's anima-sharing arrangement.\n\nBut I am very aware of the dangers posed by a lich with access to power.\n\nI am also very aware that resolving this situation is important to the Accuser, which, given my current situation, makes it important to me.\n\nWe should eliminate the muscle behind the anima transfer logistics. Without that, the shipments will halt.", objectives = "Kill the dredger giants in Death's End.", progress = "They really do grow their monsters big here, do they not?", completion = "The bigger they are... the bigger the explosion at the end. Ha!" }
WordHunterWoW_QuestEN[58394] = { title = "Lady Ouix'Ara", description = "Can you feel it? The chill in your bones... the energy... power...\n\nShe's here. The lich.\n\nTake me to her. I must speak with her, in my own way.", objectives = "Kill Lady Ouix'Ara.", progress = "No good has ever come from a lich, <name>.", completion = "It was unlikely that she'd tell us anything useful, but I had to try." }
WordHunterWoW_QuestEN[58395] = { title = "Enough Vengeance For One Day", description = "After the Sunwell's destruction and the near extermination of my people, I vowed to claim vengeance upon Arthas and Kel'Thuzad. But I needed power to see that happen, and to seize that power I...\n\n<Kael'thas grows quiet.>\n\nI... am ready to return to Sinfall. I must recover my strength for what lies ahead.\n\nAs the Accuser is so fond of reminding me, I have... much to ponder.\n\nLet us inform our allies of the enemy we have revealed.", objectives = "Deliver Kael'thas to Sinfall and report to Prince Renathal.", completion = "Maldraxxus is sworn to defend Revendreth from outside invaders, not siphon off our anima.\n\nAccept this gift for your role in bringing this conspiracy to light, <name>.\n\nWe will need time to calculate our next move, but I am certain that you will be a key part of it." }
