WordHunterWoW_QuestEN[58405] = { title = "Find KT's Phylactery", description = "TBD", objectives = "" }
WordHunterWoW_QuestEN[58406] = { title = "Mirror to Maldraxxus", description = "I've received word that Laurent's made substantial progress with his repairs. \n\nOnce the mirror has been restored, we can realize our efforts to recover the final medallion. \n\nHead to the ramparts and see if his work is near completion.", objectives = "Find Laurent on the Sinfall ramparts.", completion = "This mirror is my greatest achievement. It links directly to the necropolis that floats above the bone fields of Maldraxxus." }
WordHunterWoW_QuestEN[58407] = { title = "The Medallion of Dominion", description = "Laurent speaks the truth. We must not delay. \n\nThis mirror is our entryway into the heart of Maldraxxus. \n\nTogether with Kael'thas, we will find Kel'Thuzad and rip the Medallion of Dominion from his undeserving grasp.", objectives = "Use Laurent's mirror to enter Maldraxxus and recover the Medallion of Dominion from Kel'Thuzad.", completion = "Revendreth can now begin the return to its true purpose. May we walk into brighter futures together.\n\n<Prince Renathal smiles.>\n\nI could not help but notice that Vrednic, my loyal gargon, has taken an affinity to you, as I have.\n\nIf you would have him, I am certain he would enjoy accompanying you. Together, you shall instill fear into our enemies as he bears you into our next battle." }
WordHunterWoW_QuestEN[58420] = { title = "A Foul Annoyance", description = "The Hozen are opportunistic and weak. It does not surprise me that some of their kind have thrown their lot in with the Old Gods.\n\nWe should take care of them before they become more than a nuisance.", objectives = "Kill 7 Squidtail hozen in the Vale of Eternal Blossoms.", completion = "Good. The Vale is better off without their filth." }
WordHunterWoW_QuestEN[58421] = { title = "Special Access", description = "Mateo will have the other mirror shard we need to access the medallion. He is likely in my former manor in Archivam.\n\nIt is guarded by Nourman, a loyal dredger. Nourman is ever committed to his duties, regardless of the situation.\n\nMateo likely maintained the same rule to access the manor--possess the fangs of those granted access. If you collect the fangs of the commanders of his operation, Nourman will let you pass.", objectives = "Collect the fangs of Examiner Daciana, Examiner Boian, and Examiner Ionata.", progress = "Oi, you want to access the manor? Let me see your fangs.", completion = "<Nourman carefully inspects the fangs.>\n\nChecks out. Strange that you got so many. \n\nSay, you don't look like a venthyr. \n\n<Nourman shrugs.>\n\nDon't matter to me. You got the fangs, you go inside. Them's the rules." }
WordHunterWoW_QuestEN[58422] = { title = "Mark of the Conquerors", description = "The invading minions of N'Zoth lay claim to lands they are not entitled to. \n\nThe Vale will not be conquered while even one of the Rajani still draws breath.\n\nBurn down their banners as a reminder of this.", objectives = "Burn 6 Banners of the Black Empire in the Vale of Eternal Blossoms.", progress = "Have you sent our message?", completion = "Good.\n\nThese invaders should know that we are not so easily conquered." }
WordHunterWoW_QuestEN[58423] = { title = "The Strongest Among Them", description = "You have shown great strength in your conquests, but new enemies assail the Vale with each day.\n\nSeek out the strongest that our foes have sent forth, and bring them down for their allies to see.", objectives = "Defeat 3 rare minions of N'Zoth in the Vale of Eternal Blossoms.", progress = "Tell me of your victories.", completion = "Even minions of the Old Gods must take pause when their champions are laid out before them.\n\nRemember this as the battle rages on." }
WordHunterWoW_QuestEN[58424] = { title = "An Eye for an Amulet", description = "Archivam has been overrun by Denathrius's lackeys. \n\nWe must eliminate these intruders. From the look of things, they have resorted to tearing Archivam down to the core for any evidence of the Curator's medallion.\n\nGo, {name}. Stop them before it is too late.", objectives = "Kill 12 Archivam Intruders and 5 Excavation Enforcers in Archivam.", progress = "Are they dead?", completion = "Yes! The rest of those rats will think twice about working with Denathrius." }
WordHunterWoW_QuestEN[58426] = { title = "In the Shadow of our Failures", description = "I will personally tend to the absolution of Kael'thas Sunstrider. His current state and trauma requires nothing short of perfect intervention and instruction to correct.\n\nI would welcome your assistance in this. I sense a bond between Kael'thas and yourself. I think your presence may help inspire him down a better path.\n\nIf you're willing, meet us at Darkwall Tower.\n\nPrince Renathal suffered a great defeat there once. Perhaps a better fate will be found this time.", objectives = "Meet the Accuser and Kael'thas at Darkwall Tower.", completion = "I'm pleased you came. Let's begin." }
WordHunterWoW_QuestEN[58428] = { title = "Crypt Crashers", description = "There's one more thing I forgot to mention. Apologies, {name}.\n\nThe mirror, once complete, is inherently cursed by design. \n\nYou need to locate my Death Lotus Powder. It was in one of the crypts in Archivam... I cannot recall which one. \n\nI'm afraid you may have to brute force this one, {name}.", objectives = "Collect Stonebreaker Mallets to destroy crypt doors in search of Death Lotus Powder.", progress = "Do you have the powder?", completion = "Excellent. Now we can enter the mirror safely." }
WordHunterWoW_QuestEN[58431] = { title = "Pool of Potions", description = "I shall teach you about the Pool of Potions. The potions we create here have a variety of beneficial effects.\n\nKill the slimes in the surrounding ruins and collect the Oozing Ingredient: Viscous Oil they may drop. Each slime can produce a great quantity of oil, so you'll only be able to carry one slime's worth at a time. \n\nDeliver this oil to the Pool of Potions and toss it in.", objectives = "Deliver three Oozing Ingredient: Viscous Oil to the Pool of Potions.", progress = "Have you brought enough oil?", completion = "We shall all share in this fabulous brew you have created!" }
WordHunterWoW_QuestEN[58432] = { title = "Something Old, Something Used", description = "Want new luckydos? Chordy is best at finding luckydos!\n\nWant to go look around with Chordy?\n\n<Chordy looks at you pleadingly with his large eye.>", objectives = "Use Chordy to locate and collect 10 valuable salvage in Maldraxxus.", progress = "Did we find anything good?", completion = "These are valuable resources. Thank you, Maw Walker." }
WordHunterWoW_QuestEN[58433] = { title = "Anima Attrition", description = "This is not some simple raid or protest. These stoneborn mean to steal the anima this convoy was carrying.\n\nThat anima was destined to be tithed to the Master. There is a drought on and we cannot let these vagabonds and miscreants steal our hard-earned anima.\n\nRecover the tithe if you can and I will see to your notoriety.", objectives = "Recover the Anima Canister.", progress = "What have you found?", completion = "Well done, mortal. Stoneborn require anima to exist. Without it, they return to their stone form. This supply hurt them more than destroying thirty of their rebels." }
WordHunterWoW_QuestEN[58435] = { title = "Heritage of the Vulpera", description = "The Horde has come to truly value the Vulpera, thanks to your efforts. \n\nYou are the most... vulperan vulpera that I know!\n\nVisit me in the Vulpera Hideaway in Vol'dun. Kiro had me put together a small memento in appreciation of your efforts.", objectives = "Meet Hagashi at the Vulpera Hideaway in Vol'dun.", completion = "Your sense of adventure, you skill, your drive to explore... you just make us so proud. The Horde is better for having us!\n\nWith that in mind, <name>, take this gift. You carry us with you, wherever you go." }
WordHunterWoW_QuestEN[58436] = { title = "Heritage of the Mechagnome", description = "{name}, we could not be more pleased with your progress. You represent us well with the Alliance.\n\nReturn to Mechagon City at your earliest convenience. Waren has created a gift for you.", objectives = "Meet Prince Erazmin in Mechagon City.", completion = "Continue in this manner, and our people will continue to advance at a rapid pace. \n\nThere is so much left to discover! Continue to learn and grow, <name>!" }
WordHunterWoW_QuestEN[58437] = { title = "Parts to a Whole", description = "Damien has some great dreams, but without more abominations, this training facility will not succeed! \n\nI have a plan though!  If we can't recruit more abominations, then we shall make them ourselves!\n\nI need you to make some corpses, then mark them for harvesting with a flag. I will do the rest.Upon completion of this quest you will gain:", objectives = "Mark 15 corpses for harvesting" }
WordHunterWoW_QuestEN[58438] = { title = "Consuming Maw", description = "", objectives = "" }
WordHunterWoW_QuestEN[58439] = { title = "Consuming Maw", description = "", objectives = "" }
WordHunterWoW_QuestEN[58440] = { title = "Mirror, Mirror...", description = "We have what we need to get you through, {name}.\n\nMy medallion lies on the other side of the mirror. Once through, my medallion will be there... somewhere. \n\nPlease be careful. My mind may be weakened, but I do remember working with the Accuser to protect the crypt's interior.\n\nI should be able to tell you everything about this place, but I am afraid that just is not the case anymore.", objectives = "Enter the Curator's mirror. Then, collect the Medallion of Avarice.", progress = "My medallion? Do you have it?", completion = "You found the medallion! I wish you had found it under better circumstances. I do miss celebrating.\n\nBut I should reward you. Yes, a reward! You must take these. May they serve you well!" }
WordHunterWoW_QuestEN[58442] = { title = "Consuming Maw", description = "", objectives = "" }
WordHunterWoW_QuestEN[58443] = { title = "Continued Care of Kael'thas", description = "Kael'thas is free from the twisted corruption of the Master, but he is not truly \"free\" yet.\n\nHe carries more than enough burdens from his own sins to condemn him to the Maw.\n\nWe must be vigilant in encouraging and forcing him to atone for his mistakes. If he cannot right the many wrongs of his mortal life, he will be doomed forever.\n\nYou are having a positive effect on him. Please, accompany us down to the Chalice District for his next lesson.", objectives = "Meet the Accuser and Kael'thas in the Chalice District.", completion = "We're ready to begin our next lesson." }
WordHunterWoW_QuestEN[58444] = { title = "Return to Sinfall", description = "{name}, we must get the medallion back to Sinfall as soon as possible. \n\nWe saw how fierce Mateo's forces were, just imagine what destruction Denathrius will bring if we linger around.\n\nI will return to Absolution Crypt in a moment. With all the work you've done, I can begin to resume my duties.\n\nMy first order of business will be to recruit a new sinkeeper. Oh how I dread interviews...", objectives = "Bring the medallion to Prince Renathal at Sinfall.", progress = "Did you retrieve the Medallion of Avarice?", completion = "Excellent work, <name>.\n\nWith the Curator's medallion in hand, we are one step closer to victory." }
WordHunterWoW_QuestEN[58445] = { title = "Containing the Night", description = "It is fortunate you are here, {name}.\n\nThiernax believes he may know how to save Tyrande from the fate he himself suffered as the Night Warrior.\n\nLet us hear what he has to say.", objectives = "Listen to Thiernax's plan.", progress = "It cannot be easy for Thiernax to share his memories of becoming the Night Warrior... or the pain that followed.", completion = "Thiernax suggests a bold plan. Locating the other former Night Warriors will not prove easy." }
WordHunterWoW_QuestEN[58446] = { title = "Tracker Tracking", description = "We will require the aid of an expert tracker if we are to find the other Night Warriors.\n\nThe Wild Hunt possesses legendary skills in such matters. No quarry can elude them.\n\nSpeak with Lord Herne. With one of his hunters at your side, your search will surely be successful.", objectives = "Speak with Lord Herne and locate the Wild Hunt tracker.", completion = "Ah, yes. I know of whom you speak." }
WordHunterWoW_QuestEN[58447] = { title = "Monster Hunting", description = "Make ready, {class}. We hunt a worldeater.\n\nThey are the largest of devourers, massive beings who can drain anima from an entire region within a matter of moments. \n\nWith Ardenweald suffering from the drought, a worldeater's presence could prove disastrous.\n\nStill, we must not rush into battle without first understanding our prey. Tread the Elder Stand with me. Even creatures such as these leave spoor.\n\nKnowing our quarry will be what allows us to slay it.", objectives = "Search for clues and tracks to learn more about the worldeater.", completion = "This problem just got a lot larger. We need a new plan." }
WordHunterWoW_QuestEN[58449] = { title = "Acid Reflux", description = "We will need to be properly prepared before we can face Voras.\n\nThe digestive juices of Ardenweald's gorm dissipate the anima in their food. Ingesting them causes devourers no small discomfort.\n\nFor a beast of that size, we will need a lot of it to have any effect. There should be plenty of gorm in the hive to the east.\n\nLong ago, an artisan gave me a tool that he said would be useful against the gorm, should I ever need it. You may borrow it.", objectives = "Use the Gormherd Branch on gorm in Gormhive to retrieve 50 Bulging Digestive Sacs.", progress = "We will need those digestive sacs if we are to disrupt the worldeater enough to slay it, <name>.", completion = "<Reldorn hefts the sacs, which bulge uncomfortably.>\n\nSo many? Just how big is this thing you two are hunting, anyway?" }
WordHunterWoW_QuestEN[58450] = { title = "Anima Instincts", description = "Voras is clearly content to roam the Elder Stand. We will need a way to lure it to us once we are ready to fight.\n\nDid you notice the wildseeds in the clearing where we spotted it? Voras must be feasting on the concentrated anima contained within them.\n\nThere should still be some expended wildseeds from before the drought in the Gormhive. Let us create bait too tempting for Voras to ignore.", objectives = "Collect 8 Life-Hardened Anima.", progress = "It may take several wildseeds, but with enough concentrated anima, we should be able to lure out Voras.", completion = "I am amazed that this contains so much concentrated anima. You will surely lure a devourer to you with this!" }
WordHunterWoW_QuestEN[58451] = { title = "Voras, The Realm Eater", description = "We have everything we need, {name}. Now only the kill remains.\n\nWe set the lure, weaken the beast, and land the final blow.\n\nHunting is a battle of wills. Life or death hangs in the balance for all of us. It has always been this way, on Azeroth as in Ardenweald.\n\nLet the hunt begin.", objectives = "Slay Voras.", progress = "Voras cannot continue to leech anima from Ardenweald. We must stop it now.", completion = "The hunt is over. We have prevailed." }
WordHunterWoW_QuestEN[58452] = { title = "Tracking the Shadows", description = "The quarry has been slain, and my duties fulfilled. The tirnenn are more than capable of defending their home from the lesser devourers. Nature will take its course.\n\nI will report back to Lord Herne and meet you at the Heart of the Forest. There we shall see what I will be hunting next.", objectives = "Speak with Ysera in the Heart of the Forest.", completion = "Even in the afterlife, the legend of Huln Highmountain continues to grow.\n\nYou have done well to secure his aid, <name>. Now let our search begin." }
WordHunterWoW_QuestEN[58454] = { title = "Spoiling For A Fight", description = "Your contribution of anima has aided our operation here greatly. Several of our more famous competitors have come here lured by the flow of new anima.\n\nWould you like to test yourself versus the famous Sabriel? There could be much profit for everyone, if you were to defeat her.\n\nI can add her to the schedule, she will appear soon if you defeat the other challengers.", objectives = "Defeat Sabriel the Bonecleaver in the Theater of Pain." }
WordHunterWoW_QuestEN[58455] = { title = "Shadowy Showdown", description = "This is our time! We've found where these Shadowy Figures have been hiding, and it's time for us to take the fight to them and stop whatever their plans are. Their base of operations is in Blackrock Depths. It's all up to you.", objectives = "Find Burt Macklyn outside of the entrance to Blackrock Depths in Blackrock Mountain.", completion = "These Shadowy Figures have been an annoyance for too long now. Get in there, and stop them." }
WordHunterWoW_QuestEN[58456] = { title = "Shadowy Showdown", description = "This is our time! We've found where these Shadowy Figures have been hiding, and it's time for us to take the fight to them and stop whatever their plans are. Their base of operations is in Blackrock Depths. It's all up to you.", objectives = "Find Burt Macklyn outside of the entrance to Blackrock Depths in Blackrock Mountain.", completion = "These Shadowy Figures have been an annoyance for too long now. Get in there, and stop them." }
WordHunterWoW_QuestEN[58457] = { title = "Shadows of Blackrock", description = "We've finally tracked those pesky Shadowy Figures down, they should all be in there. They seem highly skilled, you're going to need to bring your best teams in there if you have any chance of winning.\n\nLet me know when you are ready.", objectives = "Stop the Shadowy Figures.", progress = "I can teleport you in, but after that, you're on your own.", completion = "Amazing, you stopped them! Who knows what crazy things they would have done had we not intervened, and at just the right moment. Well done!" }
WordHunterWoW_QuestEN[58458] = { title = "Pet Battle Challenge: Blackrock Depths", description = "Those Shadowy Figures are up to no good again, are you sure you want to face them? If you really want to go back in there, I'm not going to stop you.", objectives = "Stop the Shadowy Figures.", progress = "I can teleport you back in there, but you're on your own once you're inside. Good luck.", completion = "Amazing, you stopped them! Who knows what crazy things they would have done had we not intervened, and at just the right moment. Well done!" }
WordHunterWoW_QuestEN[58460] = { title = "Marshals of Madness", description = "The n'raqi have long served as the commanders and taskmasters of the Old Gods' forces. Their presence on the field of battle shows that this invasion is a coordinated effort rather than a random outbreak of corruption.\n\nLed by these faceless masters, the chaotic forces of the Old Gods transform into capable military.\n\nWe must make it a priority to fell these creatures. Only then might we take the upper hand against N'Zoth.", objectives = "Kill 6 faceless minions of N'Zoth in the Vale of Eternal Blossoms.", completion = "The loss of their leaders should prove to scatter N'Zoth's forces in the Vale.\n\nThis should provide us with the advantage we need to crush them once and for all." }
WordHunterWoW_QuestEN[58461] = { title = "Tomes of Ancient Madness", description = "In times like these, it becomes necessary for all of the denizens of the Vale to pitch in and do their part. Unfortunately, I have never been much of a fighter, so my usefulness in times of war is limited.\n\nHowever, I may be able to do some good. You see, we know very little about the invaders we face, and knowledge can be a very powerful weapon.\n\nI think I have seen tomes carried by some of the k'thir. If you could bring some to me, I may be able to glean something useful from their writings.", objectives = "Collect 8 Tomes of Ancient Madness from k'thir enemies in the Vale of Eternal Blossoms.", progress = "Have you managed to procure the tomes?", completion = "Yes, this is exactly what I was looking for! I'll start researching these at once!\n\nAh, it's good to feel useful!" }
WordHunterWoW_QuestEN[58462] = { title = "Windows to the Soul", description = "Were it not enough for our enemy to apply deadly force against us, their minions also strike into the very heart of our defenders.\n\nI speak, of course, of the eyes. They peer into the souls of our warriors and produce their darkest fears against them.\n\nIf we have any hope to defeat this foe, they must be destroyed.", objectives = "Kill 6 Eyes of the Empire in the Vale of Eternal Blossoms.", progress = "Is your task complete?", completion = "The foul eyes are no more, and our warriors' courage is restored.\n\nThank you, <name>." }
WordHunterWoW_QuestEN[58463] = { title = "Spawns of Madness", description = "To see the Vale of Eternal Blossoms recover from the Sha to its former beauty, only to see it tainted by the Old Gods once more, it makes the blood boil!\n\nWe must root out the Old God's corruption before it can take hold of this land again. I have seen the fleshbeasts that accompany N'Zoth's forces spreading his corruption where they tread.\n\nMake sure they tread no longer.", objectives = "Kill 10 fleshbeasts in the Vale of Eternal Blossoms.", progress = "I will not see the Vale fall again!", completion = "You have done well.\n\nWe must not let N'Zoth take hold of this land!" }
WordHunterWoW_QuestEN[58464] = { title = "Deephive Decimation", description = "A sect of the mantid swarm calling themselves the \"Deephive\" have taken hold of the Big Blossom mine. These mantid have fully given themselves up to the Old Gods' corruption, making them especially dangerous.\n\nWe cannot allow the Deephive to run amok in the Vale. Do what must be done.", objectives = "Kill 10 Deephive mantid within the Big Blossom Mine in Vale of Eternal Blossoms.", completion = "The mantid are incessant, but we will drive them back.\n\nAt least you've taken care of the worst of their numbers." }
WordHunterWoW_QuestEN[58465] = { title = "Corruption Manifest", description = "The corruption of the Old Gods is often so foul it manifests itself in physical form. \n\nWe have seen this with the Sha. This time is no different.\n\nCull this corruption wherever you see it spread. It must not be left to flourish.", objectives = "Kill 8 Putrid Ichors in Vale of Eternal Blossoms.", completion = "I can see the stains of N'Zoth's corruption on your weapons.\n\nWell struck, <class>." }
WordHunterWoW_QuestEN[58466] = { title = "Torment From Beyond", description = "As if it were not bad enough that N'Zoth seeks to dominate those living in the Vale, my scouts report they now seek to dominate the dead!\n\nThe Shado-Pan have their hands full defending the living. Can we rely on you to put an end to this disgrace?", objectives = "Release 6 Ancient Pandaren Spirits in the Vale of Eternal Blossoms.", progress = "N'Zoth must be stopped.", completion = "I had my misgivings about your people at first, but it seems you truly have Pandaria's well-being at heart.\n\nThank you, <class>." }
WordHunterWoW_QuestEN[58467] = { title = "Prisoners of Mind and Body", description = "N'Zoth's forces struck the Vale suddenly. By the time I and my Shado-Pan arrived, many of the Golden Lotus had already been taken captive by the Old God's forces.\n\nEven with our combined might, we have only been able to hold off the invaders from taking more of our people. Those already taken, however, are still within the clutches of the Old God.\n\nI know we have had our differences, {name}, but if you could aid us in their recovery, the Shado-Pan would be in your debt.", objectives = "Rescue 6 captive pandaren in the Vale of Eternal Blossoms.", progress = "Any news of the captives?", completion = "I do not wish to dwell upon the fate that would have otherwise befell those you rescued.\n\nYou are a true champion of pandaria, <class>." }
WordHunterWoW_QuestEN[58468] = { title = "A Growing Darkness", description = "Shado-Pan scouts have spotted evidence of a new mantid hatchery within the Big Blossom mine. It seems these Deephive mantid are looking to create new corrupted spawn to serve N'Zoth.\n\nIf these eggs were allowed to hatch, a new swarm empowered by the Old God could blacken the skies of the Vale and plunge Pandaria into darkness.\n\nWe will not allow that to happen, will we?", objectives = "Destroy 6 Corrupted Incubators in the Big Blossom Mine in the Vale of Eternal Blossoms.", completion = "The swarm has been abated, for now.\n\nKeep an eye out for any new hatcheries. We cannot afford to leave the Deephive unchecked." }
WordHunterWoW_QuestEN[58469] = { title = "Tears in the Vale", description = "As N'Zoth's influence spreads within the Vale, our very reality begins to break down. \n\nThe Old God's power has created tears in the fabric our world, acting as doorways for his minions to invade from his dark realm.\n\nAs long as these tears exist, we will never be free from N'Zoth's grasp. Close them, and stem the tide of his corruption!", objectives = "Close 3 Void Tears within the Vale of Eternal Blossoms.", progress = "Our reality weakens with each passing day.", completion = "The paths are closed, and the Vale is more itself again.\n\nThank you, <name>." }
WordHunterWoW_QuestEN[58470] = { title = "Corrupted Curiosities", description = "I understand that the Black Empire poses a grave threat to Pandaria, but we may also use this as an opportunity!\n\nThough we've faced them several times before, very little is known about the Old Gods or N'Zoth's mysterious realm of Ny'alotha. \n\nWhen studying ancient civilizations, we often rely on artifacts to unlock the deepest mysteries lost to time. I wonder if some such artifacts could be found among the Old God's forces?\n\nIt can't hurt to check, right?", objectives = "Collect 3 Artifacts of the Black Empire from Black Empire Caches in the Vale of Eternal Blossoms.", progress = "Did you find anything interesting?", completion = "Spendid! Just think of what ancient mysteries we could learn from these artifacts!\n\nI hope you didn't go through too much trouble to get these." }
WordHunterWoW_QuestEN[58471] = { title = "Aggressive Notation", description = "Even given the Sha's origins with the Old Gods, we in Pandaria still know very little of them.\n\nI would like to take this opportunity to add whatever information I can about them to the archives of the Lorewalkers. Of course, that becomes a bit problematic when they're trying to kill us.\n\nThat doesn't seem to be a problem for you, though. Could you do me a favor and jot down some notes about what you encounter out there?  It could help a great deal towards understanding what we're fighting.", objectives = "Use the Lorewalker's Notebook to gather notes about the faceless, k'thir, and fleshbeasts in the Vale of Eternal Blossoms.", completion = "Fantastic! This is very thorough!\n\nI must ask, though, how do you maintain such impeccable penmanship in the heat of battle?" }
WordHunterWoW_QuestEN[58472] = { title = "A Farewell to Arms", description = "The Maldraxxi toil away just behind us. I care not if you consider them allies or traitors, so long as you remove them from Revendreth.\n\nDestroy their encampment. Purge it from our soil, and ensure such an affront never occurs again.\n\nThe means are not important. All that matters is that these heretics remember the consequences of trifling with true power.", objectives = "Destroy the Maldraxxi encampment at Death's End.", progress = "Well?", completion = "Let this prove our sense of honor." }
WordHunterWoW_QuestEN[58473] = { title = "Echoes of Tirna Noch", description = "It is clear that we need more anima than this grove can provide. I may know of a way we can acquire some.\n\nMany of the masked fae have been collecting anima for some unknown purpose. I propose we take it back from them.\n\nThe Wild Hunt has tracked them to Tirna Noch... my former grove.\n\nLong has it been since I walked beneath its boughs. Not since it was left to wither so that other groves might survive.\n\nI remember it well...", objectives = "Meet Ara'lon in Tirna Noch.", completion = "I never thought I would return to Tirna Noch. The place of so many memories. So many regrets...\n\nBut now is not the time for sentimentality. Now is the time for action." }
WordHunterWoW_QuestEN[58476] = { title = "Bringing the Thunder", description = "All of the mogu clans are formidable, to be sure, but it is the Zan-Tien that pose the most direct threat to the Golden Lotus. \n\nEven now, their numbers are amassing outside the Golden Pagoda. Many of our warriors are fresh-faced and inexperienced. They would not withstand a mogu assault for long.\n\nAn experienced {class} like you could serve to slow them down significantly. \n\nCare to help?", objectives = "Kill 12 Zan-Tien mogu in the Vale of Eternal Blossoms.", progress = "What's the word from the front?", completion = "You've probably saved the lives of many Golden Lotus warriors today." }
WordHunterWoW_QuestEN[58477] = { title = "Through Blood and Dirt and Bone", description = "The Dokani see themselves fit to wield the ancient magic of anima, but their golems and manifestations are but a fraction of anima's true power.\n\nLiberate them of their prized substance, so that the Rajani may put it to better use.", objectives = "Collect 100 Anima Globule from Dokani mogu and their allies in the Vale of Eternal Blossoms.", progress = "What do you bring?", completion = "This will do.\n\nGo now. I am sure you are needed elsewhere." }
WordHunterWoW_QuestEN[58478] = { title = "No Stone Unbroken", description = "When the warring clans came into the Vale, the Baruk deigned themselves worthy to lay claim to the ancient grounds of Guo-Lai.\n\nThey are not.\n\nShow these usurpers their place, and you may earn a modicum of favor with the Rajani.", objectives = "Kill 10 Baruk mogu in the Vale of Eternal Blossoms.", completion = "The Baruk will soon learn their place under the foot of the Rajani.\n\nWell done." }
WordHunterWoW_QuestEN[58479] = { title = "Lightning Crashes", description = "The Zan-Tien like to claim mastery over the power of storms, yet they resort to machines to harness lightning from the sky.\n\nShow these pretenders that the true power of storm and thunder comes from within. Break their toys, and see how they fare without.", objectives = "Destroy 6 Lightning Rods in the Vale of Eternal Blossoms.", completion = "Hah! Let's see how these so-called \"masters of storm\" fare without their precious contraptions!\n\nThis should be entertaining." }
WordHunterWoW_QuestEN[58480] = { title = "Read the Roots", description = "When my grove withered, I answered the Queen's call and joined the Wild Hunt.\n\nNothing can be done for Tirna Noch. But it wounds me to see it crawling with foes of the forest.\n\nWe need a great deal of anima. The masked fae must be keeping a stockpile somewhere within the grove--we just need to find it.\n\nThey likely used soulwebs to collect and move the anima. If I examine them, I should be able to pick up the trail.", objectives = "Investigate the Depleted Soulwebs in Tirna Noch, to find the greatest concentration of anima in the grove.", progress = "I sometimes mourn what was lost. And then I remember what work there is still left to do.", completion = "The Drust have stolen more anima than I expected. To think that they have deprived us of this much in the midst of a drought...\n\nWe must take back whatever we can. Not only for the sake of the wildseed, but to also thwart whatever the Drust intend to do." }
WordHunterWoW_QuestEN[58481] = { title = "Rituals of Blood", description = "Anji and I have fought in many battles, so we know how to handle a few mogu, but the blood magic used by these Dokani is just unsettling!\n\nAs if it weren't bad enough for them to kill everyone in their path, but to use their corpses to fuel their unholy rituals? I just can't stomach it!\n\nDo me a favor. If you ever come across any of these rituals, put a stop to them! Even our enemies don't deserve to be defiled with their dark magic.", objectives = "Destroy 6 Blood Fonts in the Vale of Eternal Blossoms.", progress = "I hope you were able to do something about those rituals.", completion = "It is a relief to know that you've put an end to those rituals.\n\nJust thinking about them turns my stomach." }
WordHunterWoW_QuestEN[58483] = { title = "Mementos", description = "At Heartwood Grove, I heard tales about the fall of Tirna Noch. I never thought that I would see it with my own eyes.\n\nIt brings me great sadness. And I wonder... if this is the fate that awaits my old grove as well.\n\nI can't believe that everything that was once here is truly gone. \n\nPerhaps there are still some mementos that can be recovered. Something to remember the fallen.", objectives = "Collect Stolen Mementos from slain enemies in Tirna Noch.", progress = "Is this what lies in store for Heartwood Grove? For my old home?", completion = "Thank you.\n\nI know these are just objects, but they mean so much. Sometimes just holding a piece of one's past can be a comfort.\n\nIt means not everything is lost." }
WordHunterWoW_QuestEN[58484] = { title = "Take What You Can", description = "We know that these invaders have taken over the remains of the grove. \n\nBut why? Why are they gathering anima and bringing it all to one place?\n\nAnd how did they enter Ardenweald?\n\nWe should stay alert and take as much anima as we can find. Perhaps some good can come out of all this loss.", objectives = "Take Plundered Anima from stores in Tirna Noch.", progress = "I sometimes mourn what was lost. And then I remember what work there is still left to do.", completion = "This anima will help Dreamweaver complete his ritual... and perhaps save spirits who otherwise would have been lost.\n\nGood work." }
WordHunterWoW_QuestEN[58485] = { title = "Built to Fall", description = "The Baruk use the forbidden arts of necromancy to trap souls of fallen mogu into the statues that fight for them. \n\nThese tactics are a disgrace to our people, and cannot be allowed to continue.\n\nBreak their precious statues, and give them no vessels with which to contaminate with their stolen spirits.", objectives = "Destroy 6 Mogu Statues in the Vale of Eternal Blossoms.", completion = "As their statues crumble, so too shall their clan.\n\nYou have performed adequately." }
WordHunterWoW_QuestEN[58486] = { title = "He's Drust in the Way", description = "Only the heart of a grove can hold the sheer massive quantity of anima I'm sensing. \n\nWhen my grove was sacrificed, the anima within its heart was reclaimed. Now it brims with anima once again.\n\nAnima that was stolen from other groves.\n\nWe must secure the heart not just for our own sake, but for the entire forest.\n\nI suspect that we will not be allowed to simply trot our way in there. Be prepared for anything.", objectives = "Slay Vroth, Bulwark of Thros, and make your way to the Heart of the Fallen Tree.", completion = "We made it to the heart. Well done.\n\nIf that is what all the Drust are truly like, then Ardenweald is in a dire situation, indeed." }
WordHunterWoW_QuestEN[58487] = { title = "Plunder the Plunderers", description = "Our raids on Lei Shen's treasuries did much to ensure the Thunder King's downfall. I think we should employ the same strategy here.\n\nSeek out the hoarded plunder of the mogu clans and relieve them of it. \n\nWe must do all we can to disrupt their advance.", objectives = "Loot 3 Mogu Plunder from the Vale of Eternal Blossoms.", completion = "Well done. We should continue to keep these supplies out of our enemies hands.\n\nEven the smallest measures taken to disrupt our enemy can turn the tide of battle." }
WordHunterWoW_QuestEN[58488] = { title = "Go for the Heart", description = "I was right! A great deal of anima has been stored inside the heart of the grove.\n\nThe Drust must have collected it from all over Ardenweald.\n\nAnd now, we will take it back.\n\nQuickly, destroy that barrier and grab the heart. Niya and I will protect you.", objectives = "Destroy the barrier and collect the Heart of Tirna Noch.", progress = "We will reclaim this anima. The Drust will not use it for their own ends.", completion = "Now that we have the heart, we need to find a way out of this place.\n\nAnd I hear the distinct sound of approaching enemies..." }
WordHunterWoW_QuestEN[58490] = { title = "Deadly Reminder", description = "Our defense is tenuous at best, but the enemy is still hesitant to attack.\n\nAs long as they fear us, they won't be probing our defenses. \n\nYou must keep the pressure on the enemy.  Attack their positions all along our line.Upon completion of this quest you will gain:", objectives = "Eliminate Enemy forces and positions." }
WordHunterWoW_QuestEN[58496] = { title = "An Unwelcome Advisor", description = "<The envelope contains a message from King Anduin Wrynn.>\n\n{name},\n\nEven with the forces of the Horde and Alliance working together, we still have found no trace of N'Zoth's forces. Ever since his release, the Old God has evaded us at every turn.\n\nThe Light only knows what ill he has in store for Azeroth.\n\nMeet me in Stormwind Keep. We must put a plan together to uncover N'Zoth's schemes before it is too late!\n\nLight grant you haste,\nKing Anduin Wrynn", objectives = "Speak with King Anduin Wrynn in Stormwind Keep.", progress = "What is it?", completion = "It would appear that N'Zoth's corruption is already reaching its way into our minds. We have no time to waste.\n\nGo with Magni and Wrathion and see what you can uncover. I will ensure that our forces are ready to defend against any attack.\n\nGood luck." }
WordHunterWoW_QuestEN[58498] = { title = "Return of the Warrior King", description = "Ye've done a great deal fer Azeroth, hero, but unfortunately I'm gonna have tae ask ye tae do more. N'Zoth is on the loose, an there's no tellin' when or where he'll strike.\n\nThis battle is one ye can't face alone. When the time comes, ye'll have my hammer at yer side!\n\nBut first, we'll need tae fetch it.", objectives = "Walk with Magni and retrieve Fearbreaker in Stormwind Keep.", progress = "Need something, champion?", completion = "It'll be good tae be back in the action again. \n\nLet's get goin!" }
WordHunterWoW_QuestEN[58502] = { title = "Where the Heart Is", description = "It's time we put Wrathion's plans in tae motion. \n\nHe'll be headin' back tae the Chamber of Heart, so we should meet him there.", objectives = "Return to the Chamber of Heart.", completion = "All right, the gang's all here. \n\nLet's get started!" }
WordHunterWoW_QuestEN[58504] = { title = "Accusatory Missive", description = "We have received word from Revendreth. It seems that Maldraxxi conspirators have been found skulking within their realm.\n\nAn emissary from Sinfall wishes to discuss the anima reserves we discovered. \n\nJoin me. We depart immediately.", objectives = "Meet with the Accuser in the Halls of Atonement in Revendreth.", completion = "The pleasure is mine." }
WordHunterWoW_QuestEN[58505] = { title = "Planned Demise", description = "Our defense is tenuous at best, but the enemy is still hesitant to attack.\n\nAs long as they fear us, they won't be probing our defenses. \n\nYou must keep the pressure on the enemy.  Attack their positions all along our line.Upon completion of this quest you will gain:", objectives = "Eliminate Enemy forces and positions." }
WordHunterWoW_QuestEN[58506] = { title = "Network Diagnostics", description = "Unfortunately, we've got no clue where N'Zoth has been lurking since his escape. We do, however have an idea where he might strike.\n\nBack when the keepers were imprisoning the Old Gods, they built defense mechanisms against their corruption into the titan forges. If N'Zoth wants tae corrupt Azeroth, he'll have tae go through them first.\n\nFortunately, we've got ourselves hooked up tae them now, so we can monitor them from here. Go ahead an' take a look.", objectives = "Activate the Titan Consoles in the Chamber of Heart to check the status of the titan forges throughout Azeroth.", progress = "The consoles should tell ye how the forges are holdin' up.", completion = "I was hopin' we'd have more time tae prepare.\n\nLooks like now's the time tae act." }
WordHunterWoW_QuestEN[58515] = { title = "Scrounging for Scrolls", description = "The kyrian are known for their collection of scrolls and writings. I'm particularly interested in their texts regarding those who have joined their ranks.\n\nWhy is it that some of the greatest fighters are sent to Bastion and not to Maldraxxus?\n\nPerhaps research can divine the answer.", objectives = "Collect information on the kyrian from the Temple of Humility.", progress = "Let's see, where did that paper go?", completion = "This will be very helpful. It's a shame so many people aren't willing to share their knowledge. Hoarding it is simply foolish." }
WordHunterWoW_QuestEN[58516] = { title = "[UNUSED]", description = "", objectives = "" }
WordHunterWoW_QuestEN[58517] = { title = "[UNUSED]", description = "", objectives = "" }
WordHunterWoW_QuestEN[58518] = { title = "There's Always a Paper Trail", description = "I noticed that you were surprised to find those strange weapons here.\n\nI sense the essence of their power as well. It is strangely familiar...\n\nWe must discover where the weapons came from and who imbued them with such power.\n\n<Kael'thas smiles.>\n\nIf you and I present the proof to the Accuser together, perhaps she shall allow us to hunt down whoever is behind all of this!", objectives = "Discover proof of who's supplying the venthyr with Maldraxxian weapons.", progress = "You found something?", completion = "A lich?! The Tithelord is working with a lich from Maldraxxus?!\n\nHow? To what ends?\n\n<The Accuser composes herself.>\n\nDo you appreciate how troubling this is, <name>?\n\nThis has never happened. This is not supposed to happen.\n\nPrince Renathal will know what to do." }
WordHunterWoW_QuestEN[58523] = { title = "You're Dead To Me", description = "Your cooperation is expected, but I await results.\n\nOur reconnaissance has revealed a Maldraxxi encampment in the Endmire. We speculate that your kind have been siphoning the Master's stockpiles of anima.\n\nI have called for a carriage to take us there. Let us make haste.", objectives = "Follow the Accuser to the Maldraxxi encampment.", completion = "We have arrived. Let us not dally." }
WordHunterWoW_QuestEN[58524] = { title = "Sparkles Rain from Above", description = "You found the heart of the grove! And it's full of anima!\n\nThe Drust don't seem to like the idea of you taking it from them. They're massing in great numbers all over the forest!\n\nWe need to get you and the others out of here safely.\n\nI can help. How do you feel about dishing out a little sparkly mayhem?", objectives = "Speak with Lady Moonberry and escape Tirna Noch.", completion = "You found and took their anima right from the heart of the grove? Impressive.\n\nDreamweaver will be most pleased. But I expect that we will soon encounter some unhappy visitors.\n\nWe must move quickly to aid the spirit in this wildseed... before we are overrun." }
WordHunterWoW_QuestEN[58525] = { title = "The Two Sides of History", description = "You mortals always say that history is written by the victors. But in the Shadowlands, I have found that to be untrue.\n\nEveryone has their own version of events. I would like to know them all. \n\nThere was an author of history books who made her abode in Revendreth's  Darkfall Tower. She wrote from the venthyr's perspective of various incursions and battles alongside the Primus. \n\nIf we could find copies of her works...", objectives = "Find copies of \"On Bone and Stone\" and \"The Malice of Maldraxxus.\"", completion = "You found them! What wonderful insight into the minds of the venthyr." }
WordHunterWoW_QuestEN[58530] = { title = "Hidden Mirror", description = "If Renathal is going to put the Harvesters' medallions to use, he's going to need a conduit to focus that power. Denathrius's corruption taints the forges of Revendreth. Our best option is in Bastion.\n\nAs denizens of Revendreth, Bastion will not allow us to enter through Oribos. \n\nWe will need you to activate a mirror hidden away there long ago. Take this.\n\nWe concealed it at a rarely used site, the Veiled Enclave. There should be no one there, especially with the drought.", objectives = "Use Laurent's Compact Looking Glass to reveal the Hidden Mirror in Bastion.", completion = "It's been quite a while since I've seen these plains. \n\nI am surprised the illusion lasted as long as it did. It was concealed here many years ago for operations in the Master's name.\n\nNo matter, let us make haste. We are not here on a simple observation mission." }
WordHunterWoW_QuestEN[58555] = { title = "A Tense Reunion", description = "We are looking for the forgelite prime, Mikanikos.\n\nOnly he will be able to craft the device we need. I've seen some of his creations. Truly impressive constructs and weaponry that rival even the mightiest of us stoneborn.  \n\nWhen last I encountered him, it was at his workshop. A place of wonders known as the Eternal Forge.\n\nWe will meet you there. Traveling as a group may draw too much attention.", objectives = "Meet General Draven and Theotar at the Eternal Forge.", completion = "Just let me do the talking. One wrong move and they will surely revoke this trust.\n\nNow is not the time for more bloodshed between realms." }
WordHunterWoW_QuestEN[58557] = { title = "Assistance from Sinfall", description = "In order to defeat the Forsworn, the Crest needs an artifact that embodies repentance, atoning for past mistakes and moving forward.\n\nI have an artifact in mind. \n\nLong ago, many souls from Revendreth arrived in Bastion. Purer souls than we have ever received from Revendreth.\n\nThey bore the mark of the Seal of Contrition, a focus that expedited their cleansing.\n\nGo to Revendreth and find this seal so that we may harness its power.", objectives = "Meet with The Curator in Darkhaven in Revendreth.", completion = "I am truly sorry I do not have more answers... the Maw scattered my mind quite a bit.\n\nI will help to the best of my ability." }
WordHunterWoW_QuestEN[58558] = { title = "Overhead Intelligence", description = "The Countess knows the fates and goings-on of every noble in Revendreth. It is the best way to keep them in her debt.\n\nHowever, she has a dark secret. Despite what she may say... she was once mortal.\n\nWe will need to find where she keeps her sinstone. No easy feat, of course.\n\nWe will need to gather some intel. The venthyr of the Chalice District are constantly gossiping. Collect their letters from the couriers until you learn something of interest.", objectives = "Collect the Rumors of Favor from Chalice Couriers in the Chalice District.", completion = "Three houses that find themselves in the Countess's favor... Peculiar.\n\nSounds like you are going to explore the Redelav District!" }
WordHunterWoW_QuestEN[58559] = { title = "Eyes of the Master", description = "I worry about entering the city. I'm sure you have noticed how well we... stand out here.\n\nDenathrius's loyalists have eyes everywhere, and no more dedicated soldiers than the stoneborn.\n\nTheir eyes and ears watch over the Chalice District. Take out their leaders so none can report our presence here before we acquire the seal.", objectives = "Kill Evaala the All-Seeing, Guardian Mastrus, and Keraal the Ripper in the Chalice District.", progress = "The stoneborn forces can never be truly defeated, but they can be quelled for a time.", completion = "This city makes my skin crawl. I feel like I am constantly being watched, that people are whispering behind my back.\n\nTaking out the stoneborn leaders should slow the flow of information back to Denathrius's loyalists." }
WordHunterWoW_QuestEN[58560] = { title = "Gothic Fashion", description = "Making my way into the city unseen was not as simple as I thought.\n\nI trekked through some mud, where I came across these... small men.\n\nPerhaps Kleia is right. I draw far too much attention here to be of much use. \n\nPerhaps I can disguise myself? Please, help me by gathering some venthyr clothing as a disguise.", objectives = "Collect 5 articles of venthyr clothing from Chalice Residents and Garment Trunks in the Chalice District.", completion = "<Pelagos sifts through the clothing you brought him.>\n\nSuch fine fabric... I believe this could work!" }
WordHunterWoW_QuestEN[58561] = { title = "Shards of the Countess", description = "The venthyr travel long distances through enchanted mirrors. The keys we look for are not as we have in Bastion, but rather shards of a mirror that will lead to the sinstone's location.\n\nBased on the intel you found, we know which three houses hold these shards.\n\nPrimrose, Darkvein, and Sinfang.\n\nGo to their manors and retrieve the shards. We will find the frame to piece them into.", objectives = "Collect the 3 Shards of the Countess.", completion = "I am sure you caused quite a ruckus amongst the nobility. We must work quickly." }
WordHunterWoW_QuestEN[58562] = { title = "Collecting Dust", description = "If I know the Countess, which I do, her sinstone will have stronger protection than mere keys.\n\nShe is quite fond of curses to protect her gateways. I am capable of creating a residue that should protect us, but it requires the petals of a specific flower you can find in Redelav gardens.\n\nCollect the petals of these flowers so that I may protect us from the dangers to come.", objectives = "Collect 30 Death Lotus Petals from Death Lotuses in the Redelav District.", progress = "I will need many petals to protect the four of us.", completion = "<The Curator sifts through the petals.>\n\nIt may be a stretch, but I believe I can make this work." }
WordHunterWoW_QuestEN[58563] = { title = "Through Glass", description = "The mirror frame rests at the bottom of Redelav Hall. Kleia and Pelagos wait there.\n\nWith these shards, I can piece it together.\n\nWe will go through, grab the sinstone, and go face the Countess. Let nothing stand in our way.", objectives = "Go through the mirror, then collect the Countess's Sinstone.", progress = "Venthyr carry their pasts as a burden, a weight upon them.\n\nThe kyrian stand free of ours.", completion = "So much power in one stone.\n\nYour past can be used against you. This is why we free ourselves." }
WordHunterWoW_QuestEN[58564] = { title = "Sins of the Past", description = "The Countess built her reputation on being a native venthyr, never a soul.\n\nRevealing her sinstone to the world would be catastrophic. This is the leverage we need for the information we seek.\n\nShe will tell us where Alwin is. Where the seal is.\n\nThis mirror leads to her estate. I will follow behind you as backup, but the kyrian shall wait here.\n\nDon't let her threaten you. You hold the power.", objectives = "Go through the mirror and face the Countess.", progress = "You are lucky that the Curator is by your side, Maw Walker.\n\nIf you dared this stunt on your own, you would never see your precious Bastion again.", completion = "I shall tell you the story of the Seal of Contrition.\n\nThen you are to leave. Immediately." }
WordHunterWoW_QuestEN[58565] = { title = "Land of Light", description = "The Ember Ward is filled with outcasts from Revendreth society, whether they rebelled, crossed a noble, or simply looked at Denathrius wrong.\n\nIt is a Light-scorched land that drives venthyr mad, unless they manage to stay within the shadows.\n\nIf Alwin is there, it may be too late.\n\nLet us visit Theotar at the Sanctuary of the Mad. I'm sure he will be pleased to see you.", objectives = "Meet Theotar at the Sanctuary of the Mad in the Ember Ward.", completion = "Ah, <name>, welcome back to Revendreth!\n\nAllow me to connect you with someone who may be of service." }
WordHunterWoW_QuestEN[58566] = { title = "Actions Speak Louder than Words", description = "<The ash ghoul inspects you, checking your weapons and armor closely.\n\nHe shifts his eyes from you to your kyrian companions before checking back in with Theotar, who nods to him.\n\nAlwin motions for you to follow him.>", objectives = "Follow Mindscorched Alwin through the Ashen Traverse.", completion = "<Alwin looks to you, then to Kleia.\n\nHe nods, resolve in his eyes.>" }
WordHunterWoW_QuestEN[58567] = { title = "Skulking in the Darkness", description = "I had only heard tales of the Ember Ward before now.\n\nIt's breathtaking... yet terrible.\n\nThe Light burns the venthyr here, scorching their flesh and driving them mad.\n\nThe only reprieve is darkness, but thugs have taken over every inch of shelter outside of this sanctuary.\n\nThere is no redemption for them. Only justice.", objectives = "Kill 8 outcast venthyr in the Ashen Traverse.", completion = "When people fall to their vices, they must be judged accordingly." }
WordHunterWoW_QuestEN[58568] = { title = "Light Respite", description = "We passed many ash ghouls on the way here, screaming in pain from their Light-dispensed burns.\n\nAnd after meeting Alwin and the others here, my heart aches for them.\n\nThey have lost much of who they once were, and suffer daily for it.\n\nPlease, collect some berries from the Ashen Traverse. I believe I could impart anima into them to create a healing salve to soothe their wounds.\n\nIt is the least I can do.", objectives = "Collect 25 Brushberries from the Ashen Traverse.", progress = "The denizens of the Ember Ward have suffered enough for their mistakes.\n\nThe Light goes too far in its punishment.", completion = "It is my duty to help those in pain. This salve shall help." }
WordHunterWoW_QuestEN[58569] = { title = "The Folly of Envy", description = "<Alwin points at a venthyr on the ledge above.\n\nHe lets out a slight, low rumble.>", objectives = "Kill Duke Vielle and retrieve the Seal of Contrition.", progress = "Alwin has brought us far. We must retrieve the Seal!", completion = "Could it really be? The object of our long search..." }
WordHunterWoW_QuestEN[58570] = { title = "Parting Words", description = "With the seal in hand, we must return to Bastion.\n\nAlwin has received his justice. He has bequeathed the seal to our care.\n\nLet us say our goodbyes at the Sanctuary of the Mad, then head home.\n\nI look forward to returning to the blue skies and open fields of Bastion.", objectives = "Speak to the Curator at Sanctuary of the Mad, then return to Elysian Hold.", progress = "You return! With good news, I hope?", completion = "Concern about Kalisthene's report... but not my problem! Seal should work perfectly." }
WordHunterWoW_QuestEN[58571] = { title = "The Seal of Contrition", description = "Preparations for the Seal are complete.\n\nGo, insert it into the Crest. Be delicate, yet firm! Move with purpose, but a steady hand.", objectives = "Place the Seal of Contrition in the Crest of Ascension.", progress = "<The orb hangs in front of you. The Seal in your hand pulses quickly.>", completion = "<You see the Seal of Contrition flash with power as you pull your hand away from it.\n\nOne singular item, connecting the denizens of Bastion and Revendreth in more ways than the obvious.>" }
WordHunterWoW_QuestEN[58575] = { title = "Stuff We All Get", description = "A lot of competitors meet their end in the Theater of Pain. But their weapons are still good as new!\n\nIt can get expensive to equip a fresh recruit, especially if you're not sure they'll survive their first bout. That's why we outfit them with \"slightly used\" armaments.\n\nGather them up for me, would you? Can't let a good weapon go to waste!", objectives = "Collect 12 Weapons of the Fallen.", progress = "The weapons you collect could be wielded by a future champion!", completion = "These weapons will be put to good use. Hopefully, we won't have to collect some of them again." }
WordHunterWoW_QuestEN[58582] = { title = "Return of the Black Prince", description = "<The envelope contains a message from Valeera Sanguinar.>\n\n{name},\n\nI have just returned from a meeting with King Wrynn in Stormwind.\n\nWe have much to discuss.\n\nMeet me at the Great Seal with haste.\n\nAl diel shala,\nValeera", objectives = "Speak with Valeera Sanguinar at the Great Seal in Dazar'alor.", progress = "Yes?", completion = "I hope that Wrathion's expertise can lead us to the Old God.\n\nWe have precious little else to go on otherwise." }
WordHunterWoW_QuestEN[58583] = { title = "Where the Heart Is", description = "The Speaker has requested that I send you to aid him and Wrathion in their efforts.\n\nYou have proven yourself a great ally to Azeroth, and I suspect you will have a big part to play in the coming battles.\n\nLet us hope that the rest of the Horde and Alliance can put aside their squabbles to face a common enemy.", objectives = "Meet Magni Bronzebeard in the Chamber of Heart.", completion = "Ah, ye made it! An' just in time!\n\nWrathion's got a plan on how we might be able tae outmaneuver N'Zoth. When the Old God shows his face though, we're gonna need ye tae take the hurt to 'em!\n\nLet's get started!" }
WordHunterWoW_QuestEN[58584] = { title = "Right our Wrongs", description = "General Kaal was sent here on a mission for Denathrius long ago.\n\nOn that mission, they concealed anima siphons, making their presence impossible to detect, to limit the amount of anima this workshop could use. That destabilized this area. The Forsworn must have noticed this and exploited the weakness.\n\nThese previous actions are in opposition to our goal. Take Theotar and destroy those siphons.", objectives = "Speak to Theotar at the Eternal Forge. Then, reveal and destroy 5 Concealed Anima Siphons.", completion = "The job is done. \n\nThis should allow the anima to return. \n\nYour dedication to our cause is great. I cannot think of one more fitting to wear this cloak." }
WordHunterWoW_QuestEN[58585] = { title = "No Friend of Mine", description = "Tools. I cannot work without my tools!\n\nFamos, my former apprentice, stole them all when she went to the Forsworn.\n\nIt breaks my heart. She had so much promise.\n\nShe must be stopped.", objectives = "Kill Famos in the Eternal Forge and collect Mikanikos's Toolchest.", progress = "I need my tools. My work cannot be done without them.", completion = "My tools. At least Famos took care of them." }
WordHunterWoW_QuestEN[58586] = { title = "The Right Stuff", description = "Building something that can help in your mission will require some metal.\n\nThe constructs of the Forsworn have metal parts, suitable for what we need. Tainted by the Forsworn, they will need some additional work.\n\nCollect their metal and smelt them in the flames of the Eternal Forge to purge the corruption.", objectives = "Kill Forsworn constructs and collect and smelt 5 Tainted Centurion Components.", progress = "Do you have the metal?", completion = "Metal will do. Good work." }
WordHunterWoW_QuestEN[58589] = { title = "The Restless Dreamer", description = "Now that we have the anima we need, we must attune the heart of Tirna Noch to the shrines of Hibernal Hollow. \n\nThen we can bring the wildseed's nightmares into the light and dispel them.\n\nTake the heart to the shrines just outside of Hibernal Hollow, in the Dreamshrine basin. Then bring the heart back to the wildseed to complete the preparations for the ritual.\n\nBut be careful. Minions of the Drust seem to be amassing near the grove.", objectives = "Attune the filled heart of the tree at the shrines in the Dreamshrine Basin.", progress = "The spirit dreams.", completion = "You're a natural at this. Now we can bring the spirit's nightmares into the open and deal with them directly.\n\nIf we succeed, she will be so much more at peace." }
WordHunterWoW_QuestEN[58590] = { title = "Visions of the Dreamer: Origins", description = "The spirit within the wildseed dreams of her birth and youth, in the primordial days of her world.\n\nGo to the first Dreamshrine outside of Hibernal Hollow. Meditate at the shrine, and soothe this vision of how her life began.", objectives = "Grapple with the spirit's vision of their origin.\n\nIf you leave the Vision, interact with a Dreamer's Vision portal in Dreamshrine Basin to enter again.", completion = "We all start somewhere. Sometimes in unexpected places. Me, I just popped out of the ground like a flower." }
WordHunterWoW_QuestEN[58591] = { title = "Despoilers", description = "Your efforts at Tirna Noch have enraged the Drust. \n\nThose creatures of decay and destruction swell at our borders, and already they pierce our defenses.\n\nNow we see their real faces, and know the true nature of our foe.\n\nStrike at them. It will buy us time for you to conduct Dreamweaver's ritual.", objectives = "Slay Witherscorn Drust and Blighted, and vanquish Skell the Despoiler.", completion = "This is just the beginning of their attack. But it is still a heavy blow dealt to them. Thank you." }
WordHunterWoW_QuestEN[58592] = { title = "Caring for the Caretakers", description = "The Drust attacked so quickly, they captured some of the spirit tenders of this grove!\n\nIt's not an easy job to do, between the drought and monsters and everything. I should know.\n\nPlease, see if you can get them out of whatever terrible magic those invaders have cast on them.", objectives = "Free Spirit Tenders in the Dreamshrine Basin.", completion = "Those Drust really are cruel to us fae! Those spirit tenders were just trying to do their job...\n\nThank you for helping them." }
WordHunterWoW_QuestEN[58593] = { title = "End of the Dream", description = "The time has come. The ritual will be complete when you have fully entered into the spirit's dreams.\n\nIt will be as if you are her, in every aspect.\n\nShe relives the moment of her death over and over again. It torments her. Something about how she ended... she had no control over her actions. She hurt the ones she loved.\n\nSpeak to me when you are ready to immerse yourself in her nightmare of the end.", objectives = "Witness the end of the spirit's life.", progress = "Have you entered into the spirit's final dream and witnessed her fate?", completion = "What a terrible end for such a majestic spirit... \n\nBut that was why she connected with you! Because you are of the same world! Azeroth!\n\nNow, I can finally feel her nightmares wane. At last, she knows some peace.\n\nThank you, my friend." }
WordHunterWoW_QuestEN[58595] = { title = "Pillars of Oblivion", description = "In ages past, the black obelisks of the Old Gods would herald the coming of their forces. The dark conjurers among the k'thir and n'raqi would utilize these monuments to establish footholds in our world and usher in more of the Old Gods' minions.\n\nToday, we see these very same obelisks littering the battlefields. So long as they stand, N'Zoth's forces will be without end.\n\nMake sure they do not.", objectives = "Destroy 6 Black Empire Obelisks in the Vale of Eternal Blossoms.", progress = "Is your task complete?", completion = "You've destroyed the obelisks? Good, the Old Gods must be given no ground.\n\nRemember this in your battles." }
WordHunterWoW_QuestEN[58596] = { title = "Specter Of War: Visectus", description = "We have conjured Visectus to lead our attack, but we need your help to prepare it properly.\n\nWe require more anima-bound wraps to strengthen the summons.", objectives = "" }
WordHunterWoW_QuestEN[58599] = { title = "Drive A Dredge Between Them", description = "First, we ruin their operation. Questions can come later.\n\nI scouted from the overlook as we rode in. Necromancers charge crystals full of siphoned anima. Three dredgers stack them onto carts.\n\nKill those dredgers and everything will grind to a halt.", objectives = "Kill the 3 large dredgers.", progress = "Are you ready?", completion = "Well done." }
WordHunterWoW_QuestEN[58600] = { title = "A Perfect Circle", description = "I've come up with the perfect design to fit your needs--a crown capable of channeling the powers of the Harvesters.\n\nI need one more tool to put it together, a mold. Circular objects difficult to get right.\n\nGo up to my old storage. A perfect mold exists there. I'm sure of it.\n\nPerhaps in one of my old trunks. Go rummage around for it, will you?", objectives = "Search for the Perfected Circlet Mold.", progress = "Crown must be perfect!", completion = "Perfectly crafted. Just what we need." }
WordHunterWoW_QuestEN[58601] = { title = "Web of Information", description = "", objectives = "" }
WordHunterWoW_QuestEN[58603] = { title = "Phaestus, Genesis of Aeons", description = "Missing something sacred.\n\nForsworn ransacked our shrine to the First Forgelite and took her hammer. My hammer!\n\nDefeat their commander, retrieve Phaestus. You must go now!", objectives = "Collect Phaestus, Genesis of Aeons from Overseer Atticus.", progress = "Without Phaestus, we cannot forge your crown!", completion = "Phaestus returns! Glorious day.\n\nMany thanks, friend. This hammer has been passed down for eons! It belongs in my masterful hands." }
WordHunterWoW_QuestEN[58605] = { title = "Amateur Night", description = "", objectives = "" }
WordHunterWoW_QuestEN[58606] = { title = "A Bit of Investigation", description = "{name}, this may be the discovery of a lifetime!\n\nI cannot yet say with absolute certainty, but I have a suspicion that these insects are known as the aqir.\n\nThe League has few intact records, but the last mention of these creatures describes a great war waged between the C'Thraxxi, aqir, and early troll civilizations.\n\nWe had assumed they were driven to extinction, but they may have simply been... rebuilding.\n\nCould you please collect some samples for me to examine?", objectives = "Collect 16 Aqir Bits.", progress = "Have you managed to acquire the samples?", completion = "Marvelous! Your contributions to the League will be duly noted." }
WordHunterWoW_QuestEN[58608] = { title = "It's Treason, Then", description = "We've halted their efforts, but we still have more to do.\n\nSin'dane must have sent someone to oversee the encampment.\n\nFind and slay whoever is in charge. Only then can we be sure their work has ended.", objectives = "Kill Lady Ouix'ara.", progress = "Still more schemes...", completion = "The Banished One... The Pauldrons of Imperium...\n\nThis lich, Kel'Thuzad, meddles with powerful forces." }
WordHunterWoW_QuestEN[58609] = { title = "Taking The Seat", description = "A wise choice, {name}. Under your command, we will restore honor and glory to Maldraxxus.\n\nYour strength can change the Shadowlands for the better. Only with the Necrolords will you reach your full potential.\n\nFor now, make your way to the Seat of the Primus. Baroness Draka will meet you there and guide you further.", objectives = "Report to Baroness Draka at the Seat of the Primus in Maldraxxus.", completion = "Welcome back to the fight, <name>." }
WordHunterWoW_QuestEN[58610] = { title = "The Speaker of Elune", description = "Fortune smiles upon us, {name}. We have found a soul in Ardenweald who was once a Night Warrior in life, as Tyrande is now. \n\nHis name is Thiernax. I am told he assists in tending to the spirits resting in the Garden of Night.\n\nSeek him out and petition him for aid. I pray he will have wisdom to share.", objectives = "Find Thiernax near the Queen's Garden.", progress = "Oh, dear.", completion = "<Qadarin watches Thiernax race off. He sighs before turning to you.>\n\nMy apologies. Thiernax may have seemed curt, but there is a reason for his reluctance to speak of the Night Warrior.\n\nIf you have a moment to help me out in the garden, I can elaborate. Then I will see what can be done to convince Thiernax to help your mother." }
WordHunterWoW_QuestEN[58615] = { title = "Whispers in the Dark", description = "Did ye hear that as well? That cannae be good.\n\nIf N'Zoth gains access tae this chamber, we'll all be done for! \n\nWe need tae figure out where he's accessing the chamber and shut it down, before he does more than just whisper at us!", objectives = "Find the source of N'Zoth's whispers in the Chamber of Heart.", completion = "What have we done?\n\nIf it weren't for Ra-den's sacrifice, N'Zoth would've had the chamber, and Azeroth would've been his for the takin'." }
WordHunterWoW_QuestEN[58616] = { title = "Forging a Champion", description = "Of all the souls who have reached that stone, only you discovered its true purpose.\n\nI am no zealot, but clearly there is a deeper meaning in this. We would be wise to investigate further.\n\nFind Bonesmith Heirmir at her forge. She is the most renowned smith in Maldraxxus, and the last remaining apprentice of the Primus himself.\n\nShe will know what course to take.", objectives = "Speak with Bonesmith Heirmir about your runeblade.", progress = "Something else?", completion = "This is going to take a bit of work." }
WordHunterWoW_QuestEN[58617] = { title = "Maintaining Order", description = "Communication is the key to victory. The greatest strategists are rendered useless if their orders go unheard.\n\nDeliver my orders to Summoner Perex, Drill Sergeant Telice, and Secutor Mevix.\n\nAnd do it quickly. Every moment we waste is one our enemy will have to their advantage!", objectives = "Deliver orders to Summoner Perex, Drill Sergeant Telice, and Secutor Mevix.", completion = "That should ensure we stand ready for war." }
WordHunterWoW_QuestEN[58618] = { title = "Ossein Enchantment", description = "A potent blade requires potent components. I know of something that would suit our needs.\n\nRecently a monstrosity trained by the constructs was snared by our soldiers at the eastern side of our stronghold. Vyraz insists we can siphon \"intelligence\" from the beast's mind.\n\nHmph. The will of the Primus trumps the desires of an ambitious baron!\n\nThe bones of that beast would forge the perfect hilt for this blade. I say you lay claim to them.", objectives = "Slay Marrowjaw and collect an Empowered Bone from its corpse.", progress = "Brave enough to manage this?", completion = "Good! I knew that beast would prove no challenge for you." }
WordHunterWoW_QuestEN[58619] = { title = "Read Between the Lines", description = "Ah, mortal, how fortunate that I, humble Ta'eran, happen to be standing here just as you, the outsider everyone is talking about, happens to wander by!\n\nIn the spirit of cooperation and mutual interests, there is a matter I wish to discuss.\n\nA nearby structure called the Sepulcher of Knowledge was built as a repository for military strategy. I fear the knowledge contained within may soon be lost.\n\nIf you would do me the honor of escorting me to the Sepulcher, I can share what else I know.", objectives = "Follow Ta'eran to the Sepulcher of Knowledge and hear his proposal.", completion = "Mortal, are you ready to help me save these valuable writings?" }
WordHunterWoW_QuestEN[58620] = { title = "Slaylines", description = "Gaining entrance to the Sepulcher is no easy feat, {name}!\n\nNot only were guardians put in place, but an elaborate magical lock was created to seal the door. \n\nTo open the way, the two obelisks which control the lock must be fed anima. Fortunately, there are some empowered crystals in the area we can use for this purpose.\n\nLocate the focus crystals and redirect their anima flow into the obelisks. Then the secrets of the Sepulcher will soon be ours!", objectives = "Connect the anima flow to the Unlocking Obelisks.", progress = "Have you activated the two obelisks?", completion = "You have done it! The door is unlocked!" }
WordHunterWoW_QuestEN[58621] = { title = "Repeat After Me", description = "The Primus placed guardians in the area around the Sepulcher to protect the knowledge within. Each embodied the virtues of one of the five houses.\n\nTo gain entrance, you must prove yourself worthy by besting these protectors. \n\nSeek out the rune stones that represent the houses of Maldraxxus. Pay attention to the words inscribed on each stone, then pay deference each house's values.\n\nIf you honor the stone, its protector will come forth. Defeat each of them.", objectives = "Read the rune stones of the five houses, then honor them by performing the correct /emote at each stone.", progress = "The Primus was clever indeed.", completion = "Now that those guardians are dispatched, we can focus on unlocking the door." }
WordHunterWoW_QuestEN[58622] = { title = "Secrets Among the Shelves", description = "Now that the door to the Sepulcher is unlocked, we can venture inside.\n\nAnd by \"we\", I mean \"you\". Until it's safe, at least.\n\nThe volumes within contain the collected wisdom of the greatest military minds of Maldraxxus. For the good of the Necrolords, do whatever is needed to gather these precious volumes.\n\nIt is safe to assume that the books will be protected by traps. The Primus wouldn't want just anyone laying their hands on this knowledge.\n\nOnce you clear a path, I'll join you.", objectives = "Recover volumes of the tomes kept within the Sepulcher.", progress = "Were you successful?", completion = "Fine work so far.\n\nAccess to the secret archives is almost ours!" }
WordHunterWoW_QuestEN[58623] = { title = "A Complete Set", description = "This is only volume one?\n\nWe can't just take the first volume. A rare item like this is only useful if it's in a complete set!\n\nGrab as many of the other volumes as you can, I will have to prepare a larger expedition to remove all of these volumes.", objectives = "Collect Volumes of Victory.", progress = "Did we get all the volumes?", completion = "So much valuable knowledge saved, and it would not have happened without your help." }
WordHunterWoW_QuestEN[58624] = { title = "Pauldrons of Imperium", description = "Now we know who is responsible for the unrest in Maldraxxus.\n\nIf Kel'Thuzad has allied with the Banished One, then he wields greater power than anyone realizes. \n\nWe must lay siege to the House of Rituals, but we need time to prepare. Attacking without a flawless strategy will only ensure our defeat.\n\nFor now, return the pauldrons to the Seat of the Primus. I will meet you there.", objectives = "Return to the Seat of the Primus with the Pauldrons of Imperium.", completion = "The battle has only just begun." }
WordHunterWoW_QuestEN[58625] = { title = "Connecting the Dots", description = "The old baron for the House of the Chosen? Ah, yes! I do think I remember seeing him! An angry soul, but very good at fighting.\n\nHe went off to meet with some member of the House of Rituals. There were a few of his guards with him.\n\nWhile it's been quite some time since he passed this way, you may be able to find some signs of where he went towards the old footpath up the mountains.", objectives = "Search the Forgotten Wounds for the previous baron." }
WordHunterWoW_QuestEN[58630] = { title = "Crown of the Harvesters", description = "Power you seek to focus is volatile. Need the Eternal Forge's flames to get it done. \n\nWithout the blessing of the flames, I fear it will overwhelm the wearer.\n\nBring venthyr friend. His magic will prove useful. Need you to absorb impurities. \n\n<Mikanikos hands you an elegant container.>\n\nUse this to capture imperfections that burn off during the process.", objectives = "Meet Mikanikos at the Eternal Forge. Then, assist him with forging the Crown of the Harvesters.", progress = "It is done then?", completion = "Perfection." }
WordHunterWoW_QuestEN[58631] = { title = "Into Dreams", description = "I cannae believe that Ra-den sacrificed himself to save us. We cannae give up on him!\n\nThere must be a way tae find out where he went. \n\nLet's see if MOTHER can track him down!", objectives = "Speak with MOTHER in the Chamber of Heart to track Ra-den's location.", progress = "We're runnin' outta time!", completion = "That portal must be the entrance tae N'Zoth's realm.\n\nThis may be our only chance tae get Ra-den back and take out N'Zoth once and fer all!" }
WordHunterWoW_QuestEN[58632] = { title = "Ny'alotha, the Waking City: The Corruptor's End", description = "Usin' the mogu's research, MOTHER and Ra-den found a way tae focus the forge's Origination Protocol through the Chamber of Heart. The only problem was findin' out where tae shoot it.\n\nThat is, until now.\n\nTake these anchors and head through that portal. Ye'll need tae find some prominent landmarks tae place 'em so we can focus the weapon. Once they're set, we'll be ready tae fire.\n\nYe'll only get one shot. Make it count!", objectives = "Defeat N'Zoth in Ny'alotha, the Waking City.", progress = "It's time tae blast N'Zoth back tae the void he came from!", completion = "Ye did it! N'Zoth's forces are scattered and his grip on our world is fading!\n\nYe truly are the champion of Azeroth!" }
WordHunterWoW_QuestEN[58634] = { title = "Opening the Gateway", description = "The fabric of reality is torn. But there's no need for me to tell you that, {name}. You've seen it firsthand. \n\nIt's only a matter of time before these realities become one, veiled in eternal darkness. Instead of hiding, perhaps it's time we embraced the darkness.\n\nWith the help of our titan friend here we may be able to thread the needle of this reality through the fabric of another, creating a bridge of sorts.\n\nAfter all, the key to understanding an enemy's weakness is to understand their intentions.", objectives = "Speak with MOTHER to establish the Tenebrous Gateway in the Chamber of Heart.", progress = "Uncertainty comes before discovery.", completion = "The time has come for us to confront the darkest of these manifestations." }
WordHunterWoW_QuestEN[58636] = { title = "Eyes on the Amathet", description = "On behalf of the Explorers' League, I'd like tae thank ye for helping establish the Uldum Accord and buying us some cooperation from Ramkahen.\n\nIn the interest of better understanding our foes, Ramkahen has allowed the exploring of the Amathet tombs. Unfortunately, though, their forces are spread too thin to provide protection.\n\nI was hopin' ye could help out with that. \n\nThink ye could spare some time tae see what they're all about? We can start with an aerial look.", objectives = "Scout the Amathet territories with High Explorer Dellorah in Uldum.", progress = "To the skies!", completion = "So much tae take in! I just wish it wasn't so hard tae write notes on gryphon-back.\n\nStill, I think we've only uncovered the tip of the iceberg." }
WordHunterWoW_QuestEN[58638] = { title = "A Deeper Dive", description = "Something just isn't adding up about these Amathet. Why would protectors of titan works attack and damage the Forge of Origination?\n\nI think we need tae take a closer look. I think I saw a monument on the terrace over there. Perhaps the writings there could tell us more about these tol'vir.", objectives = "Defend High Explorer Dellorah as she deciphers the Amathet Monument at Sunstone Terrace.", progress = "I'm ready when ye are, <class>.", completion = "This monument was a good start, but it still doesn't explain what we're looking for.\n\nFortunately, uncovering mysteries is what the Explorer's League does best!" }
WordHunterWoW_QuestEN[58639] = { title = "Buried History", description = "Since the Amathet came from this region, it would only stand to reason that artifacts from their civilization would be left behind here, hidden beneath the sands.\n\nIt looks like it's time for a good old-fashioned dig!\n\nThe dunes near here must have covered up a large swath of the Amathet's former territory. Let's see what we can dig up there!", objectives = "Uncover and collect 6 Amathet Artifacts in Uldum.", progress = "What have ye turned up?", completion = "Yes! The markings on these artifacts confirm my hypothesis. \n\nThere's definitely more to this than we first thought." }
WordHunterWoW_QuestEN[58640] = { title = "A Crack in the Armor", description = "The artifacts you helped excavate show the Amathet as a tribe who prided themselves on protecting the works of the titans. \n\nThis confirms our assumptions, and indicates that something drastic must have happened to them to cause them to damage the very works they swore to protect.\n\nWe should continue to track down their writings. I think I saw a more recent monument outside the Halls of Origination.", objectives = "Defend High Explorer Dellorah as she deciphers the Amathet Monument outside the Halls of Origination.", progress = "I cannae wait tae solve this mystery!", completion = "Someone, or something, has been manipulating the Amathet from within. \n\nSounds familiar, don't you think?" }
WordHunterWoW_QuestEN[58641] = { title = "Seekers of Corruption", description = "If anyone would know more about the \"corruption\" the tablet spoke of, it would be the Suntouched that were put in charge of rooting it out.\n\nOf course, I doubt they'll be willing to turn over any information voluntarily.\n\nLuckily for me, you're a bit of a specialist at brute force investigation, aren't you?", objectives = "Collect the Sun King's Decree from Suntouched Amathet in Uldum.", progress = "Found anything from the Suntouched?", completion = "So the Amathet aren't working with N'Zoth after all! That's a relief!\n\nOf course, that doesn't make them any less hostile to us, but it's a start!" }
WordHunterWoW_QuestEN[58642] = { title = "Shared Goals", description = "The decree you found made mention of a plan to defeat the Old Gods. \n\nI know that the Amathet aren't likely to work with us toward that goal, but if they have a plan tae take out N'Zoth, it's worthwhile for us tae look at it.\n\nThe decree mentions the Engine of Ascension. I think that might be what they call that solar empowering device we saw earlier. We should take a peek underneath and see if we can figure out what they're planning!", objectives = "Defend High Explorer Dellorah as she deciphers the Amathet Tablets within the Chamber of the Stars.", progress = "Let's see what we can find in the Chamber of the Stars.", completion = "These Amathet are off their rockers! \n\nThey've decided that Azeroth is too far gone for saving!" }
WordHunterWoW_QuestEN[58643] = { title = "Mutually Assured Destruction", description = "The Amathet want tae re-take the Forge of Origination so they can use it tae end all life on Azeroth, Old God or otherwise! \n\nThey could strike at any moment. We have tae warn the defenders of the Forge!", objectives = "Warn the defenders of the Halls of Origination about the Amathet's plan.", completion = "The Amathet... charged on our position.  \n\nWe were... outmatched..." }
WordHunterWoW_QuestEN[58644] = { title = "Gather Our Forces", description = "I've finished the mirror!\n\nInform the others that we are ready to invade Maldraxxus!", objectives = "" }
WordHunterWoW_QuestEN[58645] = { title = "A World Worth Saving", description = "We could not stand against them. Their warriors... wreathed in the sun's flames...\n\nThey want the forge... to end all...\n\nGo... I will... endure...", objectives = "Stop the Amathet from taking the Halls of Origination.", completion = "You did it! I cannae believe that we were mere moments away from the end of life as we know it!\n\nThank ye for yer help with my research, <class>. If ye weren't here I don't want tae know how this would've ended!\n\nNow, if ye'll excuse me, it's goin' tae take weeks tae catalogue all we've found!" }
WordHunterWoW_QuestEN[58646] = { title = "Chew On This!", description = "These mangy hyena will gnaw on anything they dig up, including priceless artifacts!\n\nWe cannae allow the history of Uldum tae go tae the dogs, so tae speak.\n\nI'm afraid we're gonna have tae thin out their numbers.", objectives = "Kill 8 Scavenging Dunerunners in Uldum.", progress = "Did ye take care of the hyenas?", completion = "That was a regrettable thing, but necessary.\n\nThank ye, <name>." }
WordHunterWoW_QuestEN[58647] = { title = "Broken Webs", description = "My husband once served our people as the Speaker of Elune--until he became the Night Warrior. His feelings on the matter are... complicated, to say the least.\n\nSpriggans have been ripping the garden's soulwebs. Would you please help me repair them? I will recount our story as we work.", objectives = "Help repair soul webs.", progress = "Just one more.", completion = "Thank you, <name>. This task is much easier with help.\n\n\n\nI hope you do not think too poorly of Thiernax. His history with the Night Warrior ritual is rife with misplaced guilt and remorse, but I am certain I can get him to see sense and offer his aid." }
WordHunterWoW_QuestEN[58654] = { title = "A Plea to the Harvesters", description = "You come during strange times. Every day the tithes we must pay to the Tithelord increase, and our ability to get anima dwindles. \n\nWhat souls we have to work with here are near their final judgment and we lack the resources to harvest them without endangering the hamlet.\n\nIf you have the ear of Lord Chamberlain, then you might be able to pass a message to the Master himself. \n\nHere, take this letter. Please see that it makes it to the hands of the Chamberlain.", objectives = "Deliver Mihaela's Note to the Lord Chamberlain.\n\nProvided item:", completion = "Oh, the peasants have asked for help have they? \n\nThose who are loyal would know that sacrifices are essential to the survival of Revendreth. Yes, these are dark times with anima and new souls both being in short supply. \n\nBut we must all do our part, no matter how painful." }
WordHunterWoW_QuestEN[58656] = { title = "Heavy is the Head...", description = "Crown is unstable due to Sire's lingering influence from the medallions. A test run should solve.\n\nSocketed one of your medallions. Witness its power focused into a weapon of destruction. \n\nPerfect opportunity. Forsworn finished colossi construction. Destroy them.  Bring the Forsworn the end they crave. \n\nCareful. Theotar informed me how powerful magic this is. The crown will hunger, must control it.", objectives = "Test the Crown of the Harvesters and defeat the Operational Colossi.", progress = "Bring the Forsworn the destruction they crave.", completion = "You're alive. The crown started to feed off your soul.\n\nLooks like there is still work to do. Mikanikos says the Sire's influence remains present in the crown. \n\nHe says he has a plan." }
WordHunterWoW_QuestEN[58660] = { title = "Burrowing Terrors", description = "", objectives = "" }
WordHunterWoW_QuestEN[58661] = { title = "Burrowing Terrors", description = "", objectives = "" }
WordHunterWoW_QuestEN[58662] = { title = "Burrowing Terrors", description = "", objectives = "" }
WordHunterWoW_QuestEN[58664] = { title = "Ultimate Makeover", description = "We now control the Apparatus of Abominable Construction! We can use it to create new constructs to contain worthy souls.\n\nEmeni is the best choice to be first. Her combat skills are unmatched, and you may need her to help secure the Stitchyard.\n\nYou will assist me in rebuilding Emeni's construct.", objectives = "Help Rathan rebuild Emeni's Construct." }
WordHunterWoW_QuestEN[58665] = { title = "Rebellious Souls", description = "Please hear us out, Maw Walker.\n\nWhen Margrave Gharmal launched his attack on Bastion, there were many, such as Emeni and myself, that opposed his actions. \n\nFearing dissent, Gharmal removed many souls from their constructed bodies and imprisoned them. Emeni escaped the prison, but most did not.\n\nHelp us free the other souls, and we can build you an army of constructs far greater than any that serve Gharmal.", objectives = "Meet Rathan and Emeni at Sixfold Recluse.", completion = "Do not let Emeni's sour disposition deter you. Your aid is greatly appreciated, Maw Walker!" }
WordHunterWoW_QuestEN[58667] = { title = "Obsidian Extraction", description = "", objectives = "" }
WordHunterWoW_QuestEN[58668] = { title = "Find The Way", description = "I apprenticed at the Stitchyard for many eons. I even worked in the Body Banks with surgeon Stitchflesh to design Emeni's last construct.\n\nIf we gain control of the Body Banks, we will have the parts necessary to rebuild Emeni and create new bodies for other souls we rescue. \n\nLead us to there and we'll see if we can get it operational.", objectives = "Lead Rathan and Emeni to the Body Banks.", completion = "I never imagined myself returning to this place." }
WordHunterWoW_QuestEN[58669] = { title = "A Little Pruning", description = "Spriggans sometimes invade the garden to spread mischief and mayhem. There is no end to the trouble they bring with them.\n\nUsually, the Wild Hunt keeps them in check... but their huntsmen and huntresses have had far more pressing concerns as of late. Thiernax and I have been helping to keep the garden clear, but he's run off somewhere to brood.\n\n<Qadarin shakes his head.>\n\nYou would be doing me a favor if you helped me clear the Queen's garden of these vermin.", objectives = "Slay 15 Sicklethorn spriggan.", progress = "At least here we only have to worry about spriggans. Other parts of the forest are not so fortunate.", completion = "Hopefully they'll get the message and go back from whence they came!" }
WordHunterWoW_QuestEN[58670] = { title = "The Slaughter Daughter", description = "When I was locked up, I made a list of all the constructs that betrayed me... it is a lengthy list!\n\nHelp me teach these constructs the mistake they made. I want to destroy everyone on my list, along with Yardmaster Pralak, who is number one on the list!", objectives = "Help Emeni slaughter everyone on her list.", completion = "I feel like we've made our point, <name>." }
WordHunterWoW_QuestEN[58671] = { title = "Bottled Up Inside", description = "There were many souls that opposed Margrave Gharmal's attack on Bastion. Those of us that spoke out, were stripped our bodies, imprisoned in the Etheric Vault, till our souls faded away, starved of anima.\n\nMy friends are still imprisoned in the vaults. We will free them, and build an army of constructs to fight for you!", objectives = "Rescue 10 Imprisoned Souls in the Etheric Vault.", completion = "We make a good team, <name>." }
WordHunterWoW_QuestEN[58672] = { title = "A Gathering of Champions", description = "The leaders of the Horde are gathering together in Orgrimmar to nominate a new Warchief of the Horde.\n\nAs a champion of the Horde, your presence at the meeting has been requested. The gathering will be held at the embassy in Orgrimmar.\n\nI will be going on ahead. Come speak with me when you arrive in Orgrimmar, I'll be waiting with the others.\n\nMake haste, champion. The future of the Horde is about to be decided...", objectives = "Speak with Valeera Sanguinar in Orgrimmar.", completion = "You got here just in time. The meeting is about to begin." }
WordHunterWoW_QuestEN[58673] = { title = "Warchief of the Horde", description = "The meeting to decide the next Warchief of the Horde is about to begin.\n\nThe other leaders of the Horde have already arrived. They are waiting for you inside the embassy.\n\nSpeak with me when you are ready, and we will greet the others together.", objectives = "Witness the gathering of champions.", completion = "It has been decided, then. There will no longer be a Warchief of the Horde.\n\nIt seems that we have been made witnesses to the beginning of a new era..." }
WordHunterWoW_QuestEN[58674] = { title = "A Gathering of Champions", description = "King Wrynn has called for an audience with the Alliance leaders in Stormwind.\n\nYour presence at the meeting has been specifically requested. The gathering will be held at the embassy.\n\nCome speak with me when you arrive in Stormwind, I'll be waiting with the others.\n\nDo hurry, {name}. It would be ill-advised to keep the king waiting...", objectives = "Speak with Master Mathias Shaw in Stormwind.", completion = "You got here just in time. The king is about to begin his address." }
WordHunterWoW_QuestEN[58675] = { title = "The Price of Peace", description = "The king will be addressing us shortly with news from his diplomatic mission to the Horde.\n\nThe other leaders of the Alliance have already arrived. I am sure they are eager to hear what King Wrynn has to say.\n\nSpeak with me when you are ready, and we will greet the king together.", objectives = "Witness King Wrynn's address.", completion = "Hmm... the meeting did not seem to go quite as the king expected. We know where Genn and Tyrande stand, but I wonder what the others have to say." }
WordHunterWoW_QuestEN[58676] = { title = "Dormant Destroyer", description = "", objectives = "" }
WordHunterWoW_QuestEN[58677] = { title = "Skin in the Game", description = "This task is probably above your capabilities, but listen anyway.\n\nAs a construct I was feared throughout the Shadowlands. The magnificent skin of my construct was impervious to mortal weapons, it was a work of art that took years to perfect.\n\nWhen I was removed from my construct, it was Faldo Iscar who took great delight in stealing that skin. He keeps it on himself as a souvenir.\n\nKill Faldo Iscar, and get my skin back!", objectives = "Emini's Magnificent Skin obtained", progress = "When I was alive, you might have been my friend... or maybe my dinner.", completion = "My cold blood warms to you. You may be a suitable ally." }
WordHunterWoW_QuestEN[58679] = { title = "Dormant Destroyer", description = "", objectives = "" }
WordHunterWoW_QuestEN[58680] = { title = "Loose Threads", description = "We're missing a few tools and parts for sewing a construct. We need these items if we're to rebuild my construct!\n\nSearch the surrounding area. See if you can find us what we need.\n\nSearch tables for the Skewering Needles, you can find haulers that carry Razorthread Spools, and look for Clotting Patches on constructs you kill.", objectives = "Locate Skewering Needles, Razorthread Spools and Clotting Patches.", progress = "You are good at this.", completion = "You should consider a constructed body, perhaps I can design you one someday." }
WordHunterWoW_QuestEN[58686] = { title = "Weapon of Mass Construction", description = "We are in luck!\n\nSurgeon Stitchflesh and his assistant have not returned from Bastion.  The entire Stitchyard is lightly guarded.\n\nWe must work fast. See if you can get the equipment operational. Once it is active, we can begin the construction process.", objectives = "Get the assembly lab operational.", progress = "We will control the means of production!", completion = "We're almost done! Just one more step to complete the construction!" }
WordHunterWoW_QuestEN[58704] = { title = "The Garden of Night", description = "That should take care of things out here. Now we must tend to the inner garden. Once we're done, I'll sort out my recalcitrant husband.\n\nHopefully, any remaining spriggans will have cleared out on their own after hearing us dispatch the others.", objectives = "Slay spriggans in the central garden.", progress = "This is my fault... just like before...", completion = "I should have never left! He's told me time and again that I should face my...\n\nNever mind. I can deal with that later.\n\nThe situation would have been much more dire if the two of you were not here." }
WordHunterWoW_QuestEN[58705] = { title = "Grand Empress Shek'zara", description = "", objectives = "" }
WordHunterWoW_QuestEN[58706] = { title = "Dressing the Kill", description = "<Huln listens to your explanation, then pauses thoughtfully.>\n\nI believe I understand, {name}. But I cannot help you right now.\n\nAllow me to explain. In the meantime, will you carve up this carcass with me? Your prey always has something to teach you.", objectives = "Help Huln Highmountain carve up the devourer.", progress = "The more quickly you carve, the more quickly I can help you.", completion = "Excellent. This confirms my suspicions." }
WordHunterWoW_QuestEN[58707] = { title = "Sorting Through Visions", description = "", objectives = "" }
WordHunterWoW_QuestEN[58708] = { title = "Fame Waits for Gnome One", description = "Tinkmaster Overspark requests your assistance on an important research expedition. \n\nWorking with the esteemed Tinkmaster will certainly be of benefit to your career. It's done wonders for mine!", objectives = "Meet with Tinkmaster Overspark in Boralus.", completion = "Now we can begin the expedition." }
WordHunterWoW_QuestEN[58714] = { title = "The Forest Has Eyes", description = "That dream! With the teeth and the claws and the heart... heart-wrenching sacrifice?\n\n<Moonberry chokes up for a moment then collects herself.>\n\nSorry! While we were in dreamland, possessed spies have snuck into Hibernal Hollow! \n\nThey must be hunted down and slain before they can report back on the grove's defenses.\n\nHere, borrow a bit of my magic. Seek out the ones hidden in the shadows and smite them!", objectives = "Slay hidden Possessed Spies throughout Hibernal Hollow.", progress = "Have you uncovered all those pesky spies yet?", completion = "These Drust are bold to send spies into my grove! Very bold... and very foolish." }
WordHunterWoW_QuestEN[58717] = { title = "Bell of Remembrance", description = "<The bell is scratched and damaged. You remember the Curator being very interested in this item.\n\nMaybe someone at the Crypt of the Forgotten will know more.>", objectives = "Find someone who knows more about the bell at the Crypt of the Forgotten.", completion = "Greetings, Maw Walker.\n\nWhy have you come to me? I have heard so much about you." }
WordHunterWoW_QuestEN[58719] = { title = "The Droman's Call", description = "Our enemies close in swiftly, {name}. We must sound the call to defend the grove!\n\nUse this horn to call upon our protectors. Summon the Wild Hunt to slay those who would attack us.", objectives = "Use the Droman's Horn to summon the Wild Hunt at the entrances to the grove.", progress = "The Hunt will hear our call and ride to defend the grove!", completion = "The Wild Hunt rides to our aid... but not from the west?\n\nThat is where Hunt-Captain Korayn was tracking a dangerous foe. She and her hunting party must have been waylaid." }
WordHunterWoW_QuestEN[58720] = { title = "Missing!", description = "The Wild Hunt has answered the call to defend us... except for Hunt-Captain Korayn and her forces.\n\nShe had led her hunting party to the west, on the trail of a powerful foe. They may have encountered trouble.\n\nFind her and provide whatever aid she requires. \n\nWe need her hunters and her leadership if our defenses are to hold.", objectives = "Find Hunt-Captain Korayn on the Path of Rebirth.", completion = "These Drust thought to send a force to strike us from behind. \n\n<Korayn smirks.>\n\nYour call brought my fellow huntsmen and huntresses to reinforce us. Our foes were the ones caught by surprise." }
WordHunterWoW_QuestEN[58721] = { title = "Awaken the Dreamer", description = "Much of the Queen's focus has centered on the Grove of Awakening, where rejuvenated spirits emerge from their wildseeds and return to their worlds.\n\nPerhaps it is fitting you carry a wounded spirit with you.\n\n<Lord Herne studies Ysera's wildseed for a moment before a slow grin spreads across his face.>\n\nThis one fights with all of her being. Even now she clings to existence. \n\nCome, stranger, let us see what fate the Queen will decree for this one.", objectives = "Travel to the Grove of Awakening.", completion = "<The Winter Queen turns her gaze upon you.>\n\nHow curious to see someone like you in my forest." }
WordHunterWoW_QuestEN[58723] = { title = "The Court of Winter", description = "My Court informs me that you bear an important message.\n\nYou may now deliver it.", objectives = "Give the Primus's message to the Winter Queen.", progress = "The ancient enemy has not been idle...", completion = "The Banished One stirs and Ardenweald's power withers in drought." }
WordHunterWoW_QuestEN[58724] = { title = "The Queen's Request", description = "Dire portents indeed. \n\nI have used what little anima we possess to save our groves and the spirits they nurture. So many were lost... all as the Heart of the Forest grew ever weaker.\n\nKeeping the Banished One bound within the Maw will require more anima than Ardenweald can spare.\n\n<The Queen considers for a moment.>\n\nSire Denathrius is a master of anima extraction. Journey to Revendreth and inform him of our plight. I know he will lend us his aid.\n\nYour allies in Oribos can open the way.", objectives = "Return to Tal-Inara in Oribos.", completion = "What has transpired in Ardenweald? Tell me everything." }
WordHunterWoW_QuestEN[58725] = { title = "Sinkeeper", description = "This is a Bell of Remembrance. Before the recent... \"events\" we used them to beckon souls from the Crypt of the Forgotten to deem their fate. \n\nIf they are less arrogant than they were before, they may continue in the process. If not, they must spend additional time in the crypt.\n\nLet's put this one to use, shall we? It's pretty beat up, let's hope we can get at least one use out of it.", objectives = "Use the Bell of Remembrance to beckon a soul from the Crypt of the Forgotten. Then, deem the soul's fate.", completion = "Thank you, <name>. You have helped that soul, even if it does not feel like it." }
WordHunterWoW_QuestEN[58726] = { title = "Thick Skin", description = "The Primus forged a fine blade, but it will do you no good in its current state.\n\nFortunately for you, I possess the skill to finish his work!\n\nThat being said, I will require materials. The other Chosen have been too preoccupied with their combat drills to assist me at the forge, even as they demand more weapons and armor.\n\nThat's where you come in. You want a new blade? You'll have to earn it.", objectives = "Collect 40 Pulsating Hide Scraps from Overgrown Masses.", progress = "Can't be that difficult, can it?", completion = "You work quickly, don't you? I could use more assistants like you." }
WordHunterWoW_QuestEN[58727] = { title = "A Place To Call Home", description = "You didn't end up on my list... so, I guess we're friends... for the moment.\n\nRathan took the soul you freed to Butchers Block near the Seat of the Primus. \n\nLet us meet him there and plan our next step together.", objectives = "Meet up with Rathan and Emeni at Butchers Block.", completion = "This spot will do great for us. We can build new constructs, and a home for ourselves." }
WordHunterWoW_QuestEN[58728] = { title = "A Promising Lead", description = "Your arrival is timely, {name}. Huln has just returned from his search.\n\nLet us hear his report and find more Night Warriors. We cannot afford to delay.", objectives = "" }
WordHunterWoW_QuestEN[58729] = { title = "Night and Day", description = "A Night Warrior? Never heard of it.\n\nI'm afraid that I don't remember any of that! Perhaps you could help me jog my memory. \n\nWill you walk with me while I make my rounds? There's so much to do around here, but I can usually manage. I won't say no to some helping hands, though.", objectives = "" }
WordHunterWoW_QuestEN[58730] = { title = "Deep Thoughts", description = "Do not look so worried, {name}! Of course I'll help you and your friends.\n\nI'm still not entirely sure how to do that, but I felt a deep memory when you mentioned this Tyrande. It is clear that she has friends who care deeply about her, and I want to help!\n\nMemories this ancient can only be safely retrieved at the Archival of Memory to the east. Meet me there and let's see who I was during my lifetime!", objectives = "" }
WordHunterWoW_QuestEN[58731] = { title = "A Shattered Vessel", description = "There is a machine that can extract the memory, but we will need to bring a few things.\n\nMemories in Bastion are stored in glass prisms, to be archived for eternity. We will need one of our own to make the device function properly.\n\nNormally this wouldn't be a problem, but I think with all of... this... going on, finding an intact crystal will be difficult.\n\nNot to worry though! If we can get enough pieces of glass, the machine should be able to repair them.\n\nGrab as many pieces as you can find!", objectives = "" }
WordHunterWoW_QuestEN[58732] = { title = "The Stuff of Memories", description = "We're going to need a lot of anima to make this work.\n\n<Selendis's voice drops to a conspiratorial whisper>\n\nI don't know if anyone has told you, but we're running a little short on it at the moment.\n\nAnima is required to make the machine work, not to mention we'll need some to rebuild the memory prism, and honestly more anima never hurt anybody.\n\nThe devices here are attuned to dealing with memories, so any anima you can get from this area will be particularly useful. Good luck!", objectives = "" }
WordHunterWoW_QuestEN[58733] = { title = "Animamnesis", description = "We have everything we need to begin the ritual.\n\nI... I don't know what's going to happen. I thought my memories were all gone, but clearly some are buried deeper than any of us knew.\n\nThe device will pull the memories out for us to confront. Once we begin, there is no going back.\n\nSpeak to me when you're ready.", objectives = "" }
WordHunterWoW_QuestEN[58734] = { title = "[PH] Get Memories from Archives", description = "We are going to need a little bit of preparation before we can face Voras.\n\nThe gorm of Ardenweald have developed special digestive juices that can isolate and dissipate anima in their food. It causes the devourers no small discomfort.\n\nFor a beast of that size, we will need a lot of the stuff to have any effect. Let us head to <HIVE MIND> and find a suitable one.\n\nAre you familiar with the use of a rod of reclamation? It is quite useful against the gorm. You can borrow mine.", objectives = "" }
WordHunterWoW_QuestEN[58735] = { title = "Path of Totality", description = "There's no turning back now, friend.\n\nThat prism contains the truth. The truth of the Night Warrior. My past.\n\nThe only way to remember is to relive it. Let's use the prism and find out who I really am.", objectives = "" }
WordHunterWoW_QuestEN[58736] = { title = "Selenis, Night Warrior", description = "I understand, now. What it means to be a Night Warrior.\n\nThe power, it was far too much for me to control. I surrendered to it almost immediately, and look what it did.... While I do not regret my decision or lament my fate, I do not wish to see anyone suffer as I did.\n\nCome, let's meet your friends. I will happily do what I can to help.", objectives = "" }
WordHunterWoW_QuestEN[58737] = { title = "Magni's Findings", description = "As if gettin' the Forge back up and runnin' wasn't good enough, I think we may have found the key tae takin' out N'Zoth once and for all in the archives of Mogu'shan Vaults!\n\nYe might want tae be sittin' down for this one, champion.", objectives = "Learn Magni's findings.", progress = "Pay attention, champion!", completion = "Looks like we got a plan!\n\nNow tae see what Wrathion's got cookin' up tae find Ny'alotha." }
WordHunterWoW_QuestEN[58740] = { title = "Subjugated Serpents", description = "Where the Zan-Tien march, the warserpents are sure to follow.\n\nI cannot stress to you enough how dangerous these beasts are. It is a shame to see them subjugated by the mogu, but we cannot afford to let them run rampant.\n\nI need you to put them down before they can wreak havoc on our lines.", objectives = "Kill 4 Onyx Warserpents in the Vale of Eternal Blossoms.", progress = "Have you taken care of the serpents?", completion = "It is unfortunate to see the cloud serpents cut down, but the Zan-Tien have driven them beyond recovery.\n\nDon't worry, we'll make them pay." }
WordHunterWoW_QuestEN[58741] = { title = "Cutting Stone", description = "One problem with waging war against other mogu is that weapons dull and break very quickly when used against foes of stone and metal. \n\nBeing the sole blacksmith among the Rajani, it is sometimes difficult to keep up with our warriors needs.\n\nIf you come across any weapons in your battles with the mogu, I'm sure I could put them to good use.", objectives = "Collect 10 Mogu Armaments in the Vale of Eternal Blossoms.", progress = "What have you found?", completion = "These weapons look to be in good enough shape.\n\nThey will serve our warriors well." }
WordHunterWoW_QuestEN[58742] = { title = "Retinus the Seeker", description = "", objectives = "Defeat Grixis Tinypop in a pet battle." }
WordHunterWoW_QuestEN[58743] = { title = "Dune Buggy", description = "", objectives = "Defeat Grixis Tinypop in a pet battle." }
WordHunterWoW_QuestEN[58744] = { title = "I Am The One Who Whispers", description = "", objectives = "Defeat Grixis Tinypop in a pet battle." }
WordHunterWoW_QuestEN[58745] = { title = "Watch Where You Step", description = "", objectives = "Defeat Grixis Tinypop in a pet battle." }
WordHunterWoW_QuestEN[58746] = { title = "Tiny Madness", description = "", objectives = "Defeat Grixis Tinypop in a pet battle." }
WordHunterWoW_QuestEN[58747] = { title = "Brain Tickling", description = "", objectives = "Defeat Grixis Tinypop in a pet battle." }
WordHunterWoW_QuestEN[58748] = { title = "Living Statues Are Tough", description = "", objectives = "Defeat Grixis Tinypop in a pet battle." }
WordHunterWoW_QuestEN[58749] = { title = "Flight of the Vil'thik", description = "", objectives = "Defeat Grixis Tinypop in a pet battle." }
WordHunterWoW_QuestEN[58750] = { title = "Take the Bull by the Horns", description = "I've carved out quite the reputation as a tauralus wrangler. Everyone needs a tauralus!\n\nYou do some work for me, and people will know who you are as well.\n\nTake this bone splinter and poke a few juicy nibblers. Use them to lure a tauralus to you, then ride it back to me.", objectives = "Ride 5 Bloodskin Tauraluses back to Dundae.", progress = "You want to be famous? Get the tauraluses I wanted?", completion = "These are some good tauraluses. Thanks for the help, mortal!" }
WordHunterWoW_QuestEN[58751] = { title = "A Common Peril", description = "Each house in Maldraxxus has two barons. Before the fall of my first house--the House of Eyes--our margrave sent my fellow baroness to investigate suspicious behavior in the House of Rituals.\n\nI have not heard from her since. Either she has found something... or has become another casualty of their treachery. \n\nHer orders took her to the Decay in the east. If you can find the baroness, give her this summons. \n\nWe were not friends, she and I, but she is a formidable combatant. We could use her might.", objectives = "Locate the lost baroness in the Renounced Bastille.", progress = "Someone new...but someone familiar.", completion = "Be thankful I am the one you found here.\n\nOthers in Maldraxxus may not have seen the potential in your strength." }
WordHunterWoW_QuestEN[58754] = { title = "Champions of the Swarm", description = "It is clear that Shek'zara is fully committed to this invasion. Our scouts have spotted some of her greatest champions among the battlefield.\n\nAny one of these mantid could prove too much for the soldiers of the Golden Lotus to overcome. We must hunt them down and eliminate them ourselves.\n\nAre you in?", objectives = "Defeat 3 rare mantid enemies in the Vale of Eternal Blossoms.", completion = "Impressive kill count. You almost kept up with me.\n\nMaybe next time, though." }
WordHunterWoW_QuestEN[58755] = { title = "Stashed Supplies", description = "The invading mantid have been making off with the Golden Lotus' supplies lately. They're probably hoping  they can starve us out.\n\nWell, they may be right if we can't get some of our supplies back. \n\nWhile you're taking the fight to the swarm, keep an eye out for anywhere they might have stashed our supplies. You'd be doing the Golden Lotus a big favor if you could recover some.", objectives = "Collect 3 Golden Lotus Supplies from Ambered Caches in the Vale of Eternal Blossoms.", progress = "Did you manage to find our supplies?", completion = "You've found them! What luck!\n\nThese supplies will help us hold out against the mantid, maybe even long enough to drive them back! \n\nThe Golden Lotus owes you one!" }
WordHunterWoW_QuestEN[58756] = { title = "Dread Menders", description = "The ambercasters are among the highest castes of mantid society. Through their magic, they can mend and form amber to their will, allowing hastened recovery of the mantid's forces after a battle.\n\nThey are strategic targets, and we should seek them out. \n\nCare to join us?", objectives = "Kill 6 Mantid ambercasters in the Vale of Eternal Blossoms.", completion = "With no one to mend their wounded soldiers, it's only a matter of time before the swarm is driven back to the wastes.\n\nYou did well." }
WordHunterWoW_QuestEN[58757] = { title = "Testing the Untested", description = "During a swarm, the mantid send their youngest in great numbers against the enemy to test their mettle. Those who survive join the swarm as true warriors of the mantid.\n\nWe should do our best to ensure that they don't make it through this test.", objectives = "Kill 12 Vil'thik Swarmborn in the Vale of Eternal Blossoms.", completion = "The mantid are foolish to send such untested creatures against a well-prepared foe.\n\nMay this be a lesson they never learn." }
WordHunterWoW_QuestEN[58758] = { title = "Rampaging Destroyers", description = "The last mantid swarm is still very fresh in the memory of the Golden Lotus. Prior to the advancement of the swarm, the mantid would send their massive kunchong to soften up the defenders' lines.\n\nIt would seem their tactics have not changed.\n\nWe must stop those kunchong if the Golden Lotus hope to mount a defensive against the swarm. I'm counting on you to strike them down.", objectives = "Kill 4 Kunchong Destroyers in the Vale of Eternal Blossoms.", progress = "Have the beasts been halted?", completion = "The kunchong are dangerous beasts. You are a brave <class> for taking them on.\n\nThe Golden Lotus thanks you." }
WordHunterWoW_QuestEN[58759] = { title = "The Empress' Guard", description = "The Zara'thik are the empress' elite guard. Empowered with plundered Azerite, they will stop at nothing short of absolute conquest of all of Pandaria.\n\nIf we allow them to advance past the Serpent's spine, the Golden Lotus will be no match for them.\n\nStop them at the wall, {class}.", objectives = "Kill 8 Zara'thik mantid in the Vale of Eternal Blossoms.", progress = "We must break the Zara'thik advance!", completion = "You seem to have halted their advance. That will have to do for now.\n\nI'll alert you if the situation worsens." }
WordHunterWoW_QuestEN[58760] = { title = "Blades of Amber", description = "The mantid are frail and easily broken, but the amber blades they wield are formidable.\n\nWith a bit of work, they could be reshaped into something suitable for the mogu.\n\nBring them to me, and I can see about repurposing them to service the Rajani.", objectives = "Collect 12 Amber Blades from Vil'thik mantid in the Vale of Eternal Blossoms.", progress = "Have you brought me some blades?", completion = "It surprises me how such a sharp and durable blade could be made from something as fragile as a tree.\n\nPerhaps we have something to learn from the mantid, after all." }
WordHunterWoW_QuestEN[58761] = { title = "Crushed Underfoot", description = "In the past, the mantid would safeguard their hatchlings in incubation chambers until they were ready to be tested in the swarm. \n\nThese Vil'thik are sloppy, however, allowing their larvae to scurry out in the open. \n\nWouldn't it be a shame if someone crushed them?\n\nNo, of course it wouldn't.", objectives = "Squash 10 Vil'thik Larvae in the Vale of Eternal Blossoms.", completion = "Ah to see the future of your enemy crushed underfoot.\n\nIt is a good feeling, is it not?" }
WordHunterWoW_QuestEN[58762] = { title = "Taken by the Swarm", description = "There's something different about this mantid swarm. Instead of just killing everything in sight like the mantid usually do, they've taken to capturing our defenders and holding them alive.\n\nI really don't want to know what they have in store for the captives. \n\nWhy don't you go rescue them so we don't have to find out?", objectives = "Free 6 Golden Lotus prisoners from Hardened Amber Cages in the Vale of Eternal Blossoms.", completion = "You've freed them? Oh, thank goodness!\n\nI cannot fathom what a mantid would want to do with live prisoners, but it cannot be good!" }
WordHunterWoW_QuestEN[58763] = { title = "Halting Production", description = "The mantid use amber in nearly all aspects of their lives, from the structures they live in to the weapons they wield. Of course, I'm more interested in the latter.\n\nIf we can deprive the mantid of their materials, we will deprive them of their means to create implements of war.\n\nFind where they keep their amber and make sure they are unable to use it.", objectives = "Destroy 6 Amber Vessels in the Vale of Eternal Blossoms.", completion = "Without their precious amber, the mantid will be unable to resupply.\n\nWell done, <class>." }
WordHunterWoW_QuestEN[58764] = { title = "Standards of the Swarm", description = "The brazen mantid think they've already won. Even now, they fly banners along the Serpent's Spine, announcing their dominance.\n\nThey must learn that Pandaria belongs to the pandaren.\n\nBurn their banners down.", objectives = "Burn 6 Zara'thik Banners within the Vale of Eternal Blossoms.", completion = "Their marks have been erased from the Vale. Soon, so will their forces.\n\nI hope to fight by your side when we finally drive them back over the Serpent's Spine." }
WordHunterWoW_QuestEN[58765] = { title = "Siege Breaker", description = "The Golden Lotus can hold their own against the mantid's warriors, of that I have no doubt. Their war wagons, on the other hand, have the capability of crippling an entire squad of our fighters in a single volley.\n\nIf we wish to maintain the upper hand in this battle, we will need someone to infiltrate their positions and sabotage their siege engines.\n\nI would like you to volunteer.", objectives = "Sabotage 3 Vil'thik War Wagons in the Vale of Eternal Blossoms.", completion = "Our scouts have reported several mantid war wagons seem to have been destroyed in spectacular fashion.\n\nI assume I have you to thank for this." }
WordHunterWoW_QuestEN[58769] = { title = "REUSE ME", description = "Suddenly the lack of fae and souls makes much more sense. These vile creatures must have taken them as they took my husband.\n\nBut I will get them back. If you are our new champion then you will help me for the good of Ardenweald.\n\n<Thiernas snorts.>\n\nDeath did not part us. I will not be torn from him now.", objectives = "Ride with Thiernax after the Drust." }
WordHunterWoW_QuestEN[58771] = { title = "Directions Not Included", description = "Look at this place! What a mess. The Locus is inactive and these \"Forsworn\" have taken over.\n\nWe need to restore the Locus, but I do not know how. This place is not of my design, built long, long ago.\n\nLuckily, the previous Forgelite Prime was prolific. Recorded everything! If we can find her designs, I can certainly work it out. Even without Mnemis's help.\n\nLook around. Plenty of scrolls strewn about. Meet me near the Locus when you find what I need.", objectives = "Find the Locus Manual among discarded scrolls in the Mnemonic Locus.", progress = "You find correct scroll?", completion = "You found it! And other interesting tomes as well. They will be properly catalogued when we are done." }
WordHunterWoW_QuestEN[58773] = { title = "The Thornspeaker Captive", description = "Good to know the old bear hasn't forgotten me.\n\nUnfortunately, neither have the Drust. I was enjoying a peaceful afterlife before they showed up.\n\nDo not bother trying to force open this cage. You can only unlock it with three separate keys, and each one is held by a different Drust commander.\n\nThey should be somewhere nearby. Find them.", objectives = "Rescue Kivarr from Eventide Grove in Ardenweald.", progress = "I would love to help you, but as you can see... I am not exactly free to leave.", completion = "The Drust locked me in this cage and dragged Kivarr away! If you release me, I can show you where they went!" }
WordHunterWoW_QuestEN[58774] = { title = "[REUSE AS WQ]", description = "They're draining us of our anima! Some of the weaker souls... They are close to danger. They need anima or they will lose cohesion and drift. Such a thing is dangerous, especially now with how imbalanced things are in Ardenweald.\n\nI can spare some of my own energy, but I will not have enough for everyone.\n\nChoose, champion. Who will be saved today?", objectives = "" }
WordHunterWoW_QuestEN[58775] = { title = "Meet the Queen", description = "{name}, we need only one more piece to complete the Crest of Ascension.\n\nEons ago, our Crest was originally crafted with the assistance of the fae. Deep within Ardenweald lies a portal they maintain to ferry souls back to their worlds. It is a source of great power and the final key to rebuilding the Crest.\n\nSeek out the Winter Queen in Ardenweald and plead our case. We've already sent Pelagos ahead as our envoy to arrange for your meeting.", objectives = "Gain an audience with the Winter Queen at the Heart of the Forest in Ardenweald.", completion = "We have lots of work ahead of us." }
WordHunterWoW_QuestEN[58776] = { title = "Hatching Problems", description = "The aqir are multiplying faster than we can put them down. If this pace continues, we will be outnumbered before long.\n\nThe only way to slow down their assault is to attack their hives directly and destroy their eggs, but we have been unsuccessful in doing so.\n\nThat's why I wish to conscript your services.\n\nWill you help?", objectives = "Destroy 6 Aqir Egg Clusters in Uldum.", completion = "Destroying those eggs should buy us the time we need to regroup before they can throw another wave at us.\n\nYour may just mean the difference between victory and defeat." }
WordHunterWoW_QuestEN[58777] = { title = "Put Your Foot Down", description = "<Zahra stomps on a slimy, slug-like creature as you approach.>\n\nYou see that? Doesn't look like much, but believe it or not, those bugs grow out of these things.\n\nThey're all over the places the aqir have taken over, feeding off of our dead and growing into these monstrosities.\n\nIf you happen to see any of them, do the world a favor and take your boot to 'em.", objectives = "Squish 8 Aqir Larvae in Uldum.", completion = "By the looks of your boots, I'd say you stomped out a good number of those creepy crawlies.\n\nDon't worry, it'll clean off... eventually." }
WordHunterWoW_QuestEN[58778] = { title = "Getting Ahead", description = "Morale's been down at the camp lately. Funny how getting chewed on by some bugs can spoil the mood of a place.\n\nI've got an idea to perk the troops back up, though. We need a trophy!\n\nSee if you can get me the head of one of those big tanky-looking ones so we can put it on display to show these bugs that we mean business! Just try to make sure it's not too mangled, okay?", objectives = "Collect 1 Goliath Trophy from Aqir Goliaths in Uldum.", progress = "Show me what ya got!", completion = "Wow, that thing is massive!\n\nIf a giant severed bug head doesn't lift the troops' spirits, I don't know what will!" }
WordHunterWoW_QuestEN[58779] = { title = "Taking the Skies", description = "I'd like to see if we can get some more of these flyers in the air to drive back the aqir, but it's nearly impossible to get back to the Obelisk of the Sun with all these bugs in the air.\n\nI think we're going to have to thin them out on the ground before we can hope to gain aerial superiority.\n\nCan I count on you to lend a hand?", objectives = "Kill 15 flying Aqir in Uldum.", progress = "How fares the bug smashing?", completion = "The skies look a little clearer now, thanks to you. Hopefully it'll be enough to get our aerial efforts off the ground.\n\nEither way, your help is appreciated." }
WordHunterWoW_QuestEN[58780] = { title = "Heralds of the Hive", description = "The aqir that have assaulted our camp seem to mainly consist of their shock troops. However, our scouts who dare venture behind their lines have spotted a different kind of creature -- tall and thin, wielding dangerous void magic.\n\nMy instinct tells me that these creatures are the leaders behind this invasion. They should be seen as targets of opportunity, and cut down wherever they're met.\n\nAre you up to the task?", objectives = "Kill 5 Aqir Dominators in Uldum.", progress = "What do you have to report?", completion = "Even a hydra will die if you sever enough of its heads.\n\nRemember that as the battle rages on." }
WordHunterWoW_QuestEN[58781] = { title = "Terrors from the Deep", description = "The Aqir threaten the livelihood of the Wastewanders with each passing day, but I have heard of greater terrors that have been unearthed with them.\n\nOur fighters are able, but I fear what might happen if one of these ancient terrors falls upon us. \n\nI know that you have experience putting down great foes. I would like to ask you to do the same for us. \n\nAfter all, we can hardly help protect the forge if we've been decimated by some long-buried monster.", objectives = "Defeat 3 rare Aqir enemies in Uldum.", completion = "Uldum is a degree safer today, because of you.\n\nI thank you on behalf of the Wastewanders." }
WordHunterWoW_QuestEN[58782] = { title = "Things Left Behind", description = "The invading aqir forced the Wastewanders to flee many of our settlements in Uldum. In our haste to escape, much was left behind.\n\nI understand you intend to take the fight to the beasts. While you're there, could you keep an eye out for any of the supplies we had to leave behind? \n\nYou can keep anything of use to you, of course.", objectives = "Collect 3 Wastewander Supplies from Infested Caches in Uldum.", progress = "Were you able to find anything?", completion = "You found the supplies? Thank goodness!\n\nThe desert nights can be punishing on the unprepared. These will help ensure our survival out here.\n\nThe Wastewanders owe you much, <class>." }
WordHunterWoW_QuestEN[58785] = { title = "Smack and Grab", description = "Bonetooths are the backbone of Maldraxxus's armed forces. Those that have been trained well are in demand amongst all of the houses.\n \nI always need new bonetooths to train, but they can be rather difficult to collect.\n\nBring me some of the younger ones, and I will reward you greatly. Be advised that you may need to weaken them before you are able to capture them.", objectives = "Capture 10 Neonate Bonetooths.", progress = "Bring me back some bonetooths!", completion = "I am pleased with your work!" }
WordHunterWoW_QuestEN[58787] = { title = "Trial of Ascension", description = "The Forsworn threat is ever looming, and our forces are dwindling. Now, more than ever, we need more Ascended.\n\nOur generous Archon has blessed us with a portion of our anima stores to ascend our top aspirants to join our forces.\n\nKleia is amongst the chosen, and thus must complete her final trial.\n\nAs Pelagos is not yet prepared to ascend, I request you be Kleia's partner for this process. It is arduous and should not be embarked on alone.\n\nShe must bear her first soul.", objectives = "Meet Kleia at the Court of Elation.", completion = "The Forsworn have taken the court. They are blocking us from our trial!" }
WordHunterWoW_QuestEN[58788] = { title = "Censers of Guidance", description = "The Forsworn are going to great lengths to prevent us from ascension.\n\nThey mobilize to stand in our way, to dismantle our chances to partake in our rituals.\n\nThey have stolen the resources we need to start our trial. Defeat them and retrieve the incense they carry so that we may continue on this path.", objectives = "Collect 10 Incense of Guidance from Forsworn forces.", progress = "Each censer will require considerable incense. We must make sure we gather enough.", completion = "Infusing this incense with our own anima shall lead us on our individual journeys." }
WordHunterWoW_QuestEN[58789] = { title = "Misguiding Mentors", description = "These aspirants... we trained together. Learned together.\n\nThe Forsworn have swayed them from the path, now leading them to their demise.\n\nThey betray the path. Take out the Ascended that lead these forces against us.", objectives = "Kill Strategist Palladia and Instructor Herus.", progress = "For an Ascended to use the trust their aspirants have in them...\n\nThey do not deserve their wings.", completion = "The sting of aspirants choosing to walk against the Archon's will is a feeling that will never be soothed." }
WordHunterWoW_QuestEN[58790] = { title = "To Cross the Veil", description = "Pallessa found a scroll detailing the ritual.\n\nWe will need to take our positions and speak a chant, surrendering some of our anima with every word.\n\nYour presence is vital. I ask you to use the censers to burn the incense as we meditate. The rest should unfold on its own.", objectives = "Aid Kleia in the Rite of Guidance.", completion = "I see you are a being of this world. Kleia should be honored to have you at her side." }
WordHunterWoW_QuestEN[58791] = { title = "A Day in the Life", description = "A Bearer's duty is to carry souls through the veil to Oribos, where they shall be judged and passed along to one of the realms of the Shadowlands.\n\nThis soul is ready to move on.\n\nDuring this trial, you will experience his final moments before his death.\n\nWhen you are prepared, you shall see how this soul passed.", objectives = "Witness Ben Howell's final moments.", completion = "Oh there you are, love. I've been looking for you!" }
WordHunterWoW_QuestEN[58792] = { title = "Where a Soul Belongs", description = "This soul is no longer tethered to his world of Azeroth.\n\nKleia must perform her duty and bear him to Oribos to be judged by the Arbiter.\n\nTake this vesper. When you are ready, it will call Ascended to ferry you back across the Veil to Oribos.\n\nGo in service.", objectives = "Use the Vesper of Veilflight to travel to Oribos, then witness Ben Howell's judgment.", progress = "It is the duty of all kyrian to ferry souls to Oribos.", completion = "I... need some time to process this." }
WordHunterWoW_QuestEN[58793] = { title = "Faith Through the Darkness", description = "This drought is... so much larger than I imagined.\n\nWhy did nobody tell us?\n\nThe burden of this knowledge weighs heavy... do we bear souls to their eternal torture?\n\nWe must return home.", objectives = "Return to Adrestes in Elysian Hold.", completion = "I am glad that Kleia has returned successfully to us. Though she questions, she is resolute in her duties.\n\nIf only I could say the same for all of the aspirants." }
WordHunterWoW_QuestEN[58794] = { title = "Stabbing Wasteward", description = "I've been finding a lot of tauralus corpses lately, and I know it's all because those bonetooths Caleesy loves so much!\n\nI spotted the one that's responsible for the slaughter just west of here. Get rid of it! \n\nAnd don't mention this to Caleesy!", objectives = "Slay the Satiated Sawtooth.", progress = "I hope you put an end to that creature.", completion = "You've done fine work! Just don't tell Caleesy about it." }
WordHunterWoW_QuestEN[58795] = { title = "Ascended", description = "With success over their trials, our aspirants shall now start the next chapter of their afterlives.\n\nThey have proven themselves through eons of training and cleansing, and will now earn ascendance.\n\nAs each aspirant is called, I ask you and Pelagos to please assist by ushering them up. It is a tradition we have practiced for eons, reinforcing the bonds that we share.", objectives = "Assist Pelagos with the ascension ceremony.", completion = "The Forsworn, now?\n\nThis is an all-out attack!" }
WordHunterWoW_QuestEN[58796] = { title = "The Forsworn Onslaught", description = "Loyalty's betrayal shall not go unnoticed.\n\nBut while the Paragons defend the city proper, it is up to us to defend Elysian Hold.\n\nI am very wounded... but I will hold strong. Pelagos and I will protect the survivors. You must aid in pushing back this assault!", objectives = "Repel the Forsworn invasion.", progress = "Devos... she goes too far.", completion = "And so the tides of battle turn.\n\nElysian Hold may be safe, but the Spires still need our aid!" }
WordHunterWoW_QuestEN[58797] = { title = "Forged by Trial", description = "{name}, my friend.\n\nI have thought of you as an ally for some time now. The thrill I felt when you decided to join us in Bastion... I knew you would be a boon unto our ranks.\n\nOur bond has been forged by the trials we face. Without you, I could have fallen to my newfound knowledge as Achillon did.\n\nI wish to cement our bond. I would be honored to soulbind with you.", objectives = "Complete the soulbinding ritual with Kleia.", progress = "You are an important part in my journey. I respect you greatly, and hope you feel the same.", completion = "You, me, and our dear Pelagos.\n\nI challenge anybody to name a better team." }
WordHunterWoW_QuestEN[58798] = { title = "The Spires of Ascension", description = "Our task is not complete yet.\n\nWe may have pushed back the Forsworn here in Elysian Hold, but it was only a distraction to split our forces.\n\nThe Archon and the Paragons fight to retake the Spires themselves.\n\nWe cannot hesitate to aid them in this time of need!", objectives = "Kill Devos, Paragon of Doubt in the Spires of Ascension.", completion = "This attack has taught us much. The Archon shall be convening with the remaining Paragons to discuss this Forsworn threat.\n\nWe shall call upon you once more when you are needed." }
WordHunterWoW_QuestEN[58799] = { title = "The Prime's Directive", description = "All centurion are made to serve the kyrian.\n\nThat they now work against ME, the Forgelite PRIME, is an insult to all centurions in Bastion. Look at them! Praetors! Goliaths! All... PURPLE!\n\nI hereby give you permission and expressly order you to extract their cores. I will repurpose them in a fitting manner. I will reclaim their anima to power the Locus.\n\nI can build more. Do not pity.", objectives = "Collect 12 Centurion Cores.", progress = "You have the cores?", completion = "Excellent. Their anima will be put to better use." }
WordHunterWoW_QuestEN[58800] = { title = "The Mnemonic Locus", description = "<Mikanikos examines the scroll you retrieved for him.>\n\nRight, right.\n\nSoul mirrors and Locus are tied together. If we restore anima to mirrors, it should repair the Locus back to full functionality. Thankfully, the cores you brought should be sufficient.\n\nAll I need to do is enable conduits. Simple!\n\nWell? Go on. You know how to use these, yes?", objectives = "Use the Anima Conduits to restore the Mnemonic Locus.", progress = "I wait to hear the hum of anima, yes.", completion = "I love the hum of anima. It has been a long time since I have heard it in such abundance." }
WordHunterWoW_QuestEN[58801] = { title = "Enter the Void", description = "<As your approach the idol, the dark shards you carry appear to melt into your hand. You are immediately overcome with unspeakable anguish. It quickly gives way to feelings of joy, serenity, and an overwhelming desire to... kill.\n\nA hissing voice creeps into your mind.> \n\nMy faithful servant. I will grant you but a small taste of my unimaginable power, all I ask in return is that you complete one simple task. Kill any who would oppose me, spare no one. Do not fail me...", objectives = "Without dying or leaving Void Wraith form, sacrifice 10 players to N'Zoth." }
WordHunterWoW_QuestEN[58802] = { title = "The Incredible Egg", description = "<The aqir seem to have been in the process of empowering this egg with void magic.\n\nIt looks to be far from hatching, so it should be safe to study to find out what they were planning to do with it. \n\nSomeone in the Explorers' League might be interested in taking a look.>", objectives = "Bring the Voidtouched Egg to H'partho Adoros in Ramkahen.", completion = "Fascinating! You say that the aqir were trying to empower this egg?\n\nYou did the right thing by bringing this egg into my care. Just think of the wonders we'll uncover when it hatches!\n\nYou look worried." }
WordHunterWoW_QuestEN[58803] = { title = "Match the Hatch", description = "Don't fret, I'm sure no ill will become of hatching this creature. After all, the aqir can't be born evil, can they?\n\nOf course, we have no idea how to take care of such an egg. I will need you to do some investigating.\n\nHead back to the aqir hives and see if you can find any other, similar eggs. If we can observe how they're being treated, we might be able to apply those learnings here.", objectives = "Investigate 7 Voidtouched Eggs in Uldum.", progress = "What have you learned among the aqir?", completion = "The eggs hatched while you were studying them, you say?\n\nThat's unfortunate, but it looks like you returned in one piece! \n\nI will study these notes and see if I can learn more about our little friend here. We may just find something that can help in the hatching process." }
WordHunterWoW_QuestEN[58804] = { title = "Void Incubation", description = "Well one thing is for certain with this egg, it requires great amounts of void energy in order to thrive. \n\nIt is fortunate for us that an Old God is attacking Azeroth at this very moment, yes?\n\nNo? Oh...\n\nIn any case, there should be an abundance of void energy wherever N'Zoth's minions strike. You should head out and find some.", objectives = "Collect 10 Crystallized Void in areas under assault by N'Zoth's forces.", progress = "Have you found a reliable source of void energy?", completion = "Brilliant! The void energy emanating off these crystals will be perfect to incubate the egg.\n\nDon't worry, I'm sure there won't be any side effects from carrying those around." }
WordHunterWoW_QuestEN[58805] = { title = "Continued Incubation", description = "The egg is doing well, but we're going to need more of those void crystals to keep it healthy.\n\nCould you go out and gather some?", objectives = "Collect 10 Crystallized Void in areas under assault by N'Zoth's forces.", progress = "Did you bring more void crystals?", completion = "Yes, this will do nicely.\n\nI will continue to tend to the egg and keep you updated on its progress." }
WordHunterWoW_QuestEN[58806] = { title = "Warmth of the Sun", description = "The desert nights in Uldum can get awfully cold. I fear for our little egg's ability to withstand these temperatures.\n\nThese Amathet to the East seem to have mastered the harnessing of the sun's energy. If we could borrow some of their expertise, we could use it to keep the egg nice and cozy.\n\nKeep your eyes open for something we can use.", objectives = "Collect an Amathet Solar Collector in Uldum.", progress = "Did you find anything among the Amathet?", completion = "You've found a solar collection device? Perfect!\n\nNow our egg will be nice and toasty through the chilly nights." }
WordHunterWoW_QuestEN[58807] = { title = "Wrapping Up", description = "One oddity I have observed about this egg is that it lacks the protective webbing commonly found throughout the aqir hives. \n\nI believe this webbing has protective qualities, and could be beneficial to our egg if we can acquire some.\n\nWhile you're out fighting the insects, see if you can't bring back some of their webbing so we can make a proper cocoon for our growing egg.", objectives = "Collect 30 pieces of Aqir Webbing from aqir casters in Uldum.", progress = "Did you find some suitable webbing?", completion = "Oh, this sure is sticky! It should do the trick, though.\n\nHere, give me a moment while I wrap the little guy up." }
WordHunterWoW_QuestEN[58808] = { title = "Encased in Amber", description = "You know who would probably know a lot about how to properly incubate this egg? The mantid!\n\nOf course, they're too busy trying to kill us to share their expertise, but there might be another way to benefit from their knowledge!\n\nPerhaps we could repurpose one of their incubation chambers. That could help speed up this process, I'm sure!\n\nIf you could find and mark one for me, I could airlift it out of there.", objectives = "Mark an Amber Incubator for H'partho to airlift in the Vale of Eternal Blossoms.", completion = "This is perfect! \n\nWhat a cozy little home this will make for our egg." }
WordHunterWoW_QuestEN[58809] = { title = "A Shocking Technique", description = "I have heard tales that the mogu use lightning to speed up the growth of their cloud serpents. I wonder if the same principle could be used for our aqir friend?\n\nThere's only one way to find out! Go to the Vale of Eternal Blossoms and see if you can get the parts together so we can create our own lightning rods. \n\nIf they work the same as they do for the cloud serpents, it should speed up the hatching process significantly.", objectives = "Collect 8 Lightning Rod Components from the Vale of Eternal Blossoms.", progress = "Were you able to collect the proper components?", completion = "I hope the mogu didn't give you too much trouble.\n\nIt will all be worth it, though, once we hatch our little friend here." }
WordHunterWoW_QuestEN[58810] = { title = "Coming Out of His Shell", description = "It looks like our egg is ready to hatch! Isn't this exciting!\n\nCome, let us welcome our new little friend to this world.", objectives = "Watch the Aqir Egg hatch in Ramkahen.", progress = "Oh, the anticipation!", completion = "Isn't he marvelous?\n\nWe still have a long way to go until we have a full-grown aqir, but even in his current state he is a sight to behold!" }
WordHunterWoW_QuestEN[58811] = { title = "A Balanced Diet", description = "Now that our larva is hatched, we'll need to figure out what we can feed it to keep it healthy. \n\nIt would seem that the aqir are carnivores, but the only things I've seen them eat are... well... us.\n\nOf course, we can't feed our little friend people, so we'll have to find an alternative. Perhaps we could substitute animal meat?", objectives = "Collect 12 Chunks of Meat from beasts in Uldum and the Vale of Eternal Blossoms.", progress = "He looks hungry, I hope you brought a snack.", completion = "It looks like animal meat is not his favorite. \n\nHe should be okay for now, we'll try something different later." }
WordHunterWoW_QuestEN[58812] = { title = "Meat Alternatives", description = "In the wild it is actually fairly common for insects to eat others of their species. I wonder if this rings true for the aqir as well.\n\nCould you bring back some meat from the aqir or mantid? We'll see if that's more palatable for our friend here.", objectives = "Collect 12 pieces of Insectoid Meat from Aqir, Mantid, or other insects in Uldum or the Vale of Eternal Blossoms.", progress = "I do hope this works.", completion = "Poor little thing, the insect meat gave him tummy troubles.\n\nWe'll have to try something else tomorrow." }
WordHunterWoW_QuestEN[58813] = { title = "Fetid Filets", description = "You know, it occurred to me that since this creature has been imbued with void energy, it may prefer a more... corrupted food source.\n\nI speak, of course, of the Minions of N'Zoth.\n\nIt's a long shot, but it's worth a try.", objectives = "Collect 12 pieces of Corrupted Flesh from creatures in areas under assault by N'Zoth's minions.", progress = "Who knew aqir would be such picky eaters?", completion = "Well done! Our little guy cleaned his plate!\n\nIt's a good thing, too. I was not looking forward to asking Phaoris for fresh tol'vir corpses." }
WordHunterWoW_QuestEN[58814] = { title = "[UNUSED]", description = "Qadarin isn't here but I know he is close. \n\nThe Drust spoke of a leader. I suspect Qadarin is being held with them. If they are draining us of our anima, Qadarin would be a significant source.\n\nThank you for helping me this far, {name}. Now, let us finish clearing this blight from Ardenweald.", objectives = "" }
WordHunterWoW_QuestEN[58816] = { title = "Getting Backstage", description = "The next thing we need to prepare the vessel is a set of Night's Veil Flowers.\n\nWe use these flowers in our ceremonies, but since the drought we've just used them as props in our plays. There are certainly some backstage at the Star Lake Amphitheater.\n\nI bet Moonberry is there for the rehearsal of their next play. As a bonus, this will work out quite nicely for me to get revenge on her.\n\n<Willowblossom flashes a wicked grin.>", objectives = "Retrieve a Wreath of Night's Veil Flowers from backstage at the Star Lake Amphitheater.", progress = "Do you have the flowers?", completion = "Mission accomplished! This will be so funny. Ah, sweet revenge." }
WordHunterWoW_QuestEN[58817] = { title = "Action Figures", description = "It occurs to me that our larva's current living situation is quite dull. We should try to find something to keep him entertained.\n\nAfter all, a happy larva is a healthy larva!\n\nI think the Amathet keep figures for worship of their gods. I'm sure they could also double as toys for our little friend here. See if you can find some!", objectives = "Collect 6 Amathet Figurines from Amathet creatures in Uldum.", progress = "Did you find any suitable toys?", completion = "Look how happy he is with his new toys!" }
WordHunterWoW_QuestEN[58818] = { title = "Bug Buddies", description = "Is it just me or does our little friend look lonely? It would make sense that aqir are social creatures, coming from a hive and all. It must be difficult for him not being around any of his kind.\n\nYou know, maybe you could find some friends for him. Nothing big and scary, of course, but perhaps some of the smaller scarabs could be safe enough to keep him company.\n\nWhat do you think?", objectives = "Catch 5 Docile Sandstone Hatchlings in Uldum.", completion = "Look, they're playing! At least, I think that's what that is.\n\nAnyway, having some friends should go a long way to keeping our larva healthy and happy. Well done!" }
WordHunterWoW_QuestEN[58820] = { title = "Bindings of Fleshcrafting", description = "These are the Bindings of Fleshcrafting! They empowered the Primus to shape the very flesh and bone of Maldraxxus.\n\nWe must return them to their rightful place, so their power can bolster us all.", objectives = "Place the Bindings of Fleshcrafting upon the Statue of the Primus.", completion = "I can feel their power. Perhaps they will give us the advantage we need." }
WordHunterWoW_QuestEN[58821] = { title = "Glorious Pursuits", description = "Perhaps Draka has forgotten her loyalties, but I will fulfill my mission.\n\nMy enemy--the lich Mor'Bitan--hides within the House of Rituals. For some reason, his underlings skulk in this marsh.\n\nWe have not learned why they are here, but my devoted have spotted Mor'Bitan's second-in-command, Mephiles the Loyal. He will have our answers.\n\nCollect him for me. Once you capture him, slay his kin. Weaken his resolve.\n\nI will prime my base for his interrogation.", objectives = "Kidnap Mephiles the Loyal, then kill 6 Morbid Disciples to intimidate him.", progress = "Any luck?", completion = "A simple task for such a storied hero." }
WordHunterWoW_QuestEN[58825] = { title = "Super Jelly", description = "My friends in the Golden Lotus have been telling me some interesting things about the new mantid swarm. Apparently they have developed a concentrated royal jelly that accelerates the growth of newly hatched mantid. \n\nIf this jelly works on mantid, logic would suggest it would work on aqir as well!\n\nSee if you can find a sufficient sample of this jelly to help with our larva's growth.", objectives = "Collect 8 Concentrated Royal Jelly in the Vale of Eternal Blossoms.", progress = "This gets me thinking.\n\nAfter we've raised this one, I wonder if we could hatch a mantid as well?", completion = "Just look at how he gobbled it up! \n\nLet's hope this does the trick." }
WordHunterWoW_QuestEN[58826] = { title = "A Bloody Treat", description = "I have heard that a clan of the mogu called the Dokani have mastered the harnessing of life force into a substance they call \"anima.\"\n\nIf this stuff is indeed life condensed into a liquid form, then it could have spectacular properties when applied to our aqir larva.\n\nGo see if you can bring back some of this anima in a form that we can use. We'll see if our little friend here likes it!", objectives = "Collect 8 Vials of Purified Anima from Dokani mogu in the Vale of Eternal Blossoms.", progress = "Have you returned with the anima?", completion = "He sure took a liking to that! I guess it helps that it's blood-flavored.\n\nI'll keep note of any changes the anima causes in our friend's growth." }
WordHunterWoW_QuestEN[58829] = { title = "They Grow So Fast", description = "Look! Our little larva friend has entered the pupa stage! \n\nWait... it looks like he's ready to emerge. \n\nGo on, give him a hand!", objectives = "Help the Aqir Larva emerge from its cocoon in Ramkahen.", progress = "Take care, our friend is likely still very fragile.", completion = "Congratulations! Our little larva is now a fully-fledged aqir hatchling!\n\nYou must be very proud." }
WordHunterWoW_QuestEN[58830] = { title = "Aqir Instincts", description = "In observing the aqir battling the Wastewanders, I have seen the newly hatched immediately join the aqiri assault. It would seem the need for combat is born into these creatures.\n\nWe should exercise this in our new hatchling, under your supervision of course. Take him out with you and show him how to fight our enemies. \n\nHe may not be able to fight for long, so don't call him until you're ready for training.\n\nWith luck, he will come to see us as part of his hive.", objectives = "Use H'partho's Whistle to summon your Aqir Hatchling and battle enemies in Uldum or Vale of Eternal Blossoms. Fighting tougher and rarer enemies will help your hatchling grow faster.", progress = "Take care of your hatchling. He will return here if he becomes too injured.", completion = "That must have been an exciting day for our little hatchling.\n\nHe'll need to rest up for now, but we can try again tomorrow!" }
WordHunterWoW_QuestEN[58831] = { title = "Honing Instincts", description = "It looks like our little friend is anxious and ready to practice more combat.\n\nWould you care to show him the ropes?", objectives = "Use H'partho's Whistle to summon your Aqir Hatchling and battle enemies in Uldum or Vale of Eternal Blossoms. Fighting tougher and rarer enemies will help your hatchling grow faster.", progress = "How goes the training?", completion = "The little guy is tuckered out after your adventures. \n\nDon't worry, I can tend to him here while you're off saving Uldum." }
WordHunterWoW_QuestEN[58832] = { title = "Trinkle Trinkle Little Twerp", description = "<On the note are the scribblings for a plan to steal silkstrider larvae and cook them.\n\nIt is signed by someone named Trinkle.>", objectives = "Kill Trinkle the Silk Eater.", progress = "Have you taken care of that nasty Trinkle?", completion = "Nasty spriggan!" }
WordHunterWoW_QuestEN[58833] = { title = "Calling in All Favors", description = "{name}, the time has come.\n\nWe cannot allow Kel'Thuzad to wield the Ritualists' sorcery as a weapon. He must be destroyed.\n\nRally our forces. We march on the House of Rituals!", objectives = "Meet Draka and allies at the House of Rituals.", completion = "We were brought together by chance, but now we fight as one.\n\nOur victory today will be one for all Maldraxxi." }
WordHunterWoW_QuestEN[58842] = { title = "The Curator", description = "I tasked the Curator with reacquiring the Medallion of Avarice.\n\nHowever, since her return from the Maw, her mind has become... a bit chaotic. Do be kind, will you?  \n\nI ask that you lend her assistance in her search. She is at the Crypt of the Forgotten.", objectives = "Meet the Curator at the Crypt of the Forgotten.", progress = "I require your assistance, Maw Walker.", completion = "We must retrieve those mirror shards before Denathrius's lackeys do. \n\nIt is the only way to access the crypt I concealed my medallion within." }
WordHunterWoW_QuestEN[58843] = { title = "The Vault of the Archon", description = "Behind me is the entrance to the Vault of the Archon. As you can see, it is warded against all unauthorized intrusion.\n\nTo make yourself an authorized entrant, place the offerings you collected before the guardians. You may then browse the contents of the vault at your leisure.\n\nDo consider that such access is coveted among the Forsworn and is the sole focus of their efforts here. I advise preparing for combat.", objectives = "Gain entrance into the Vault of the Archon.", completion = "I am very pleased to meet you. The Vault has not received visitors in some time." }
WordHunterWoW_QuestEN[58844] = { title = "Before the Dawn", description = "We shall need all we can muster if this day is to be ours.\n\nGather them all. The Watchers, Bearers, Centurions, and Collectors. Tell them that their Archon calls for them.\n\nOur Paragons will clear a staging ground at the Court of Elation for the final assault.", objectives = "Gather the Watchers, Bearers, Centurions, and Collectors.", completion = "I hope you are prepared, Maw Walker." }
WordHunterWoW_QuestEN[58846] = { title = "The Greater Good", description = "The Forsworn are our former brothers and sisters in arms...our former kin. But we must see this through.\n\nWe will hit them from all sides. Fight well, but do not forget that Lysonia is our ultimate objective. If she does not fall, then she will recruit more to their cause in time.\n\nFollow the path, {name}.", objectives = "Defeat Lysonia.", completion = "The day is ours at last, thanks to you." }
WordHunterWoW_QuestEN[58847] = { title = "Kyrestia's Grace", description = "I remember this particular soul...Uther. Devos brought him before us some time ago. She pleaded her case about his soul having a connection to the Maw.\n\nShe then took him under wing, ascending him before he was ready. He became her other hand alongside Lysonia, as it were.\n\nHe may proclaim a change of heart, but we shall see. Place him under guard. He may stay by the Archon's grace, but I will not take any chances with one so...broken.", objectives = "Escort Uther.", completion = "May Thenios's efforts be fruitful. I have never seen a soul so broken in all my eons." }
WordHunterWoW_QuestEN[58854] = { title = "Convene the Paragons", description = "We have defeated the Forsworn at every turn. Saved those not too far gone. Routed them from our blessed Archon's temples. Now only one remains.\n\nThe Temple of Loyalty.\n\nLysonia has grown desperate in defeat. Abandoned all we strive to uphold by embracing the Maw. She has rallied her most fervent loyalists to the temple, knowing we will come for her.\n\nWe shall need the Paragons to finish this. Summon them.", objectives = "Summon the Paragons to call them to action.", progress = "Without the Paragons we cannot prevail against Lysonia.", completion = "Now that the Paragons stand ready, we must rally the rest of our forces." }
WordHunterWoW_QuestEN[58856] = { title = "Who Are You Fooling?", description = "We cannot conduct the ritual without a very special guest. He's a silkstrider larva named Grubby and he's my best friend.\n\nUnfortunately, the nasty spriggans took him! What's worse is they cast illusions on what they steal, so no one can take it back!\n\nThe spriggans often carry trickster powder. If you can take some of that stuff, I can reverse their illusions and rescue Grubby.", objectives = "Loot Sicklethorn Trickster Powder from Sicklethorn spriggans to dispel illusions on Conspicuous Objects and find Grubby.", progress = "We need to find Grubby!", completion = "We found him!" }
WordHunterWoW_QuestEN[58857] = { title = "Seeds Away!", description = "I think we have a problem. Plucking the seed from this root must have shaken some burrowed gorm awake. This isn't good!\n\nGrab on to me. I will fly us out of here, but we must stop the gorm before they overrun the local Vorkai defenses!", objectives = "Stop the gorm from overrunning the Gormhive Defense Wall and then pouring into the rest of Ardenweald!", progress = "I can't believe this. Blue seeds, red seeds, flying faeries!", completion = "Okay, I think everything is finally ready, <name>." }
WordHunterWoW_QuestEN[58858] = { title = "More Fetid Filets", description = "Our little guy is getting hungry again. \n\nCould you pick him up a quick bite to eat?", objectives = "Collect 12 pieces of Corrupted Flesh from creatures in areas under assault by N'Zoth's minions.", progress = "My, this thing has an appetite.", completion = "Excellent! This will make sure he grows up big and strong!\n\nLet's hope he doesn't try to eat us then!" }
WordHunterWoW_QuestEN[58859] = { title = "Someone His Own Size", description = "While fighting alongside you no doubt provides excellent training for our hatchling, sometimes it is better to have him fight on his own against enemies his own size.\n\nI know of one such opponent nearby, observing the Amathet near the Obelisk of the Stars. You should seek it out.", objectives = "Defeat Retinus the Seeker in a pet battle with your Shadowbarb Hatchling in your party.", completion = "I bet that was quite an exhilarating battle!\n\nWe should try to get some more training in tomorrow." }
WordHunterWoW_QuestEN[58860] = { title = "Big Bad Beetle", description = "It could do our hatchling some good to face off against another aqir, to learn what his kind are capable of.\n\nI have found an opponent who could provide a challenging fight.", objectives = "Defeat the Aqir Sandcrawler in a pet battle with your Shadowbarb Hatchling in your party.", completion = "Looks like we've got a tough little hatchling on our hands!\n\nThat should be enough training for today, though." }
WordHunterWoW_QuestEN[58861] = { title = "The Mantids' Mettle", description = "Observing the combat techniques of the mantid may prove helpful for our hatchling's training, offering a different way to use the natural weapons of an insect.\n\nI have found a mantid opponent that our hatchling could face in the Vale of Eternal Blossoms. Take him there and see how he does.", objectives = "Defeat the Vil'thik Hatchling in a pet battle with your Shadowbarb Hatchling in your party.", progress = "How did our hatchling fare against the mantid?", completion = "It looks like our little guy learned much from his battle with the mantid.\n\nNo doubt he'll be ready to face fully grown opponents soon." }
WordHunterWoW_QuestEN[58862] = { title = "The Littlest Defender", description = "The Baruk mogu are known for animating ancient statues to serve as defenders of their territory. They are a resilient foe, and much can be learned from battling an enemy with such rigid defenses.\n\nFortunately, it seems like one of their Stoneshapers mistakenly animated a small idol. It has been discarded as useless to the mogu who made it, but it could prove a valuable training opportunity for our hatchling.\n\nFind this miniature defender in the Vale of Eternal Blossoms.", objectives = "Defeat the Baruk Stone Defender in a pet battle with your Shadowbarb Hatchling in your party.", completion = "I knew our little hatchling could handle the mogu creation!\n\nHis prowess grows with each passing day!" }
WordHunterWoW_QuestEN[58863] = { title = "A Custom Order", description = "I think it's safe to say that our little friend is no long a hatchling, but a fully grown aqir! He's grown so much, in fact, he could even carry you into battle.\n\nWait, that's a marvelous idea!\n\nYou should speak with Blacksmith Abasi about getting a saddle made.", objectives = "Speak with Blacksmith Abasi in Ramkahen.", progress = "What do you need?", completion = "I am certain I can craft a suitable saddle for that creature.\n\nHowever, I am going to need your help with some things first." }
WordHunterWoW_QuestEN[58865] = { title = "Otherworldly Armaments", description = "To craft a saddle for your beast, I'll need some special materials. Mainly, it will require metals much lighter than what we have available.\n\nI have noticed that the Black Empire cultists carry with them weapons made from otherworldly materials, which are impossibly light and strong. \n\nIf you could retrieve some of their weapons for me, I may be able to melt down this metal and shape it into a saddle for the aqir.", objectives = "Collect 12 Black Empire Armaments from Black Empire cultists in Uldum and the Vale of Eternal Blossoms.", progress = "Have you found my materials?", completion = "These weapons... they are both disturbing and fascinating.\n\nI will melt them down at once. Visit me tomorrow to claim your saddle." }
WordHunterWoW_QuestEN[58866] = { title = "My Own Drone", description = "The saddle is complete. I can't say I enjoyed working with that corrupted metal, but in the end I can easily say this is the finest saddle I have ever crafted.\n\nI know it looks... aggressive, but I assure you that your aqir will find it quite comfortable.\n\nI hope it serves you well.", objectives = "Bring the Otherworldly Saddle to H'Partho Adoros in Ramkahen.", progress = "Was the blacksmith able to help?", completion = "I am impressed, this is beyond what I thought Abasi capable of.\n\nIt looks like our little friend is ready to fly the nest. Remember to take good care of him!\n\nAnd do visit once and a while." }
WordHunterWoW_QuestEN[58869] = { title = "Battle for Hibernal Hollow", description = "This is where we make our stand. The Drust and their minions have us nearly overrun.\n\nBut we will not let them destroy Hibernal Hollow. Nor will they take our anima or our wildseeds.\n\nFight with us. Let us drive them out.", objectives = "Win the Battle for Hibernal Hollow.", completion = "We have won the battle...\n\n...But I fear we may have lost Ysera." }
WordHunterWoW_QuestEN[58871] = { title = "Broken Harts", description = "The curse on Qadarin is a powerful one.\n\nBut I will break it.\n\n<Thiernax snorts.>\n\nDeath did not part us. I will not be torn from him now.\n\n<Thiernax studies both you and Shandris with a serious look in his eyes.>\n\nLend me your aid, and in turn I will help you with your world's Night Warrior. I do not promise I can save her... but I will share all that I know.\n\nReturn to the Heart of the Forest and tell Lord Herne what has happened. We will meet there.", objectives = "Report to Lord Herne at the Heart of the Forest, then speak with Moonberry.", progress = "This is even worse than I had thought.", completion = "I bet those spriggan thought this would be pretty funny. Well, we're not laughing!" }
WordHunterWoW_QuestEN[58876] = { title = "Lost Flight", description = "<A small dragon emerges from one of the side chambers found within N'Zoth's great carapace. It appears confused.\n\nYou surmise that such chambers must have been used to corrupt the dragons, exposing them directly to N'Zoth's dark whispers. At a young age, they would be driven mad, moreso than any other members of the twilight dragonflight that you had met before.\n\nThere would be no turning back from such madness.\n\nBut maybe it's not too late for this one...>", objectives = "Bring the Spawn of Vexiona to Wrathion in the Chamber of Heart.\n\nProvided item:", completion = "I can sense great pain, confusion, and loss, within this little one. This poor creature has led a short, heartbreaking life.\n\nAs have many of my kind, at the hands of... others.\n\n<Wrathion looks pained for a moment.>\n\nSome day, little one, we will find ourselves again.\n\n<Wrathion touches the dragon's head and closes his eyes.>\n\nThere, your mind is cleared. \n\nThis one is still young, it has much to learn and much to see. I trust you will care for it?\n\nDo not let me down, hero." }
WordHunterWoW_QuestEN[58877] = { title = "Death's Power Grows", description = "Listen closely, {name}. A time of great destruction lies on the horizon that will challenge our very existence. Now more than ever, we must rise to the defense of Azeroth.\n\nIt is for this reason I have expanded the ranks of my champions to include your people. Your sacrifice sets you apart from all others. Hold your head high. Forevermore, you will be a death knight of the Ebon Blade.\n\nNow swear your fealty.", objectives = "Swear fealty to the Lich King.", progress = "Swear your fealty, <name>.", completion = "I accept your pledge. Serve us well.\n\nTo that end, new weapons worthy of a Knight of the Ebon Blade have been forged.\n\nChoose, my champion." }
WordHunterWoW_QuestEN[58879] = { title = "Alpaca It Up", description = "<Sniffs curiously in the general direction of your backpack, eyeing it intently.>", objectives = "<Sniffs curiously in the general direction of your backpack, eyeing it intently.>", progress = "<Sniffs curiously in the general direction of your backpack, eyeing it intently.>", completion = "<Munches enthusiastically on the Gersahl greens, while humming gleefully.>" }
WordHunterWoW_QuestEN[58881] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[58887] = { title = "Alpaca It In", description = "<The friendly alpaca seems grateful to you for continuing to bring its favorite snack.>", objectives = "<The friendly alpaca stares at you earnestly, clearly grateful for continuing to bring its favorite snack. It seems eager to join your adventures in the desert.>" }
WordHunterWoW_QuestEN[58900] = { title = "A Sure Bet", description = "You've made a name for yourself and earned the respect of everyone here, including Au'narim.\n\nYou are ready, {name}!\n\nAnzio is expecting us at the entrance to the Theater of Pain. You're going to be a champion!", objectives = "Meet Anzio at the entrance to the Theater of Pain.", completion = "You have traveled far for this moment." }
WordHunterWoW_QuestEN[58902] = { title = "Defender of Azeroth", description = "An excellent choice.\n\nTroubling times come. As one of the chosen few, it is both your burden and privilege to defend our world. It is a great honor.\n\nBut also know you will be met with the scorn of the ignorant. Oftentimes, mortals are incapable of seeing past our fearsome appearance. Ignore these fools and do what must be done.\n\nSpeak with your commander. Then, use his death gate to travel to the land of the living and choose your destiny.", objectives = "Speak with Highlord Darion Mograine. Then, use the highlord's death gate to travel to Stormwind. Once there, visit Chromie." }
WordHunterWoW_QuestEN[58903] = { title = "Defender of Azeroth", description = "An excellent choice.\n\nTroubling times come. As one of the chosen few, it is both your burden and privilege to defend our world. It is a great honor.\n\nBut also know you will be met with the scorn of the ignorant. Oftentimes, mortals are incapable of seeing past our fearsome appearance. Ignore these fools and do what must be done.\n\nSpeak with your commander. Then, use his death gate to travel to the land of the living and choose your destiny.", objectives = "Speak with Highlord Darion Mograine. Then, use the highlord's death gate to travel to Orgrimmar. Once there, talk to Chromie." }
WordHunterWoW_QuestEN[58904] = { title = "Shards of Corruption", description = "<You feel the pull of something dark and inhuman on your mind, it's writhing tendrils digging in, tugging at your sanity. You feel compelled to collect more shards... all of them.>", objectives = "Collect 20 Shards of Corruption.", progress = "<The Idol tugs at your very being. Demanding you to touch it.>", completion = "<You feel a foreboding presence in your mind, it seems... very pleased.>" }
WordHunterWoW_QuestEN[58905] = { title = "Picking Up Pelagos", description = "Pelagos should have the seed by now! Can't start the ritual without the seed. He's likely still at Claw's Edge.\n\nWe'll see you there!", objectives = "Meet up with Pelagos, Willowblossom, and Grubby at Claw's Edge.", completion = "Whoops. Wrong seeds. I hope we can still find a use for these." }
WordHunterWoW_QuestEN[58908] = { title = "Finding Your Way", description = "Stormwind has a lot to offer adventurers like us, but it's far too big to explore on foot. The captain has arranged for you to receive a mount to help you get around.\n\nShe said to speak with Curly at the stables in Old Town... but I can't seem to remember the way there.\n\nHave no worries, {name}! All we need to do is ask a guard for directions. If you ever need help finding something, the city guards will show you where to go.\n\nLet's ask a nearby guard for directions to the stable master in Old Town!", objectives = "Speak with Curly at the stables in Old Town.", progress = "Welcome to the stables, <class>. I've been expecting you.", completion = "So you're the newcomer that I've been hearing so much about?\n\nMy name's Curly. It's a pleasure to meet you, <name>!" }
WordHunterWoW_QuestEN[58909] = { title = "License to Ride", description = "The captain said you'd be coming here to pick up your mount. I hope you didn't have any problems finding the place!\n\nNow, before you ride off into the sunset, you'll need to learn how to... well, how to ride! Luckily, we have a riding trainer right here!\n\nSpeak with Darlene Stokx when you're ready to learn how to ride.", objectives = "Speak with Darlene Stokx to learn the Apprentice Riding skill.", completion = "Now that you've learned the basics, feel free to return any time you want to advance your riding skills or purchase additional mounts!" }
WordHunterWoW_QuestEN[58910] = { title = "What's Your Specialty?", description = "Hey, {name}! Have you decided on a combat specialization yet?\n\nSince you're a {class}, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class?\n\nChoosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use.\n\nLet's go speak with Mithlos Falconbriar to learn more about specializations!", objectives = "Speak with Mithlos Falconbriar to learn about combat specializations.", progress = "Greetings. Have you come to learn about combat specializations?", completion = "Excellent choice of specialization, <name>.\n\nFeel free to test out your new abilities on the training dummies outside." }
WordHunterWoW_QuestEN[58911] = { title = "Home Is Where the Hearth Is", description = "I don't know about you, but all this running around has got me thirsty!\n\nWhy don't we head over to the Pig and Whistle Tavern and rest our legs over some cool pints of moonberry juice?\n\nWhile we're there, speak with Meagan the innkeeper to make the Pig and Whistle Tavern your new home. That way, if you ever find yourself stranded without a flight master nearby, you can use your hearthstone to return to the inn.\n\nNot only is it faster than a gryphon, but you'll save a few copper in the process!", objectives = "Speak with Meagan Tillman to make the Pig and Whistle Tavern your home.", progress = "How can I help you today, <class>? Are you looking for a place to stay?", completion = "As long as the Pig and Whistle Tavern is your home, we'll keep the fire going for you while you're away!" }
WordHunterWoW_QuestEN[58912] = { title = "An Urgent Meeting", description = "I've been looking for you all over Stormwind, {name}.\n\nThe captain has delivered her report to the king. It appears that Stormwind requires your service yet again.\n\nThe leaders of the Alliance have gathered together for a meeting at Stormwind Keep, and your presence has been requested by King Wrynn himself. I was instructed to find you and deliver the message without delay.\n\nIt has been an honor serving with you, {name}. May the Light bless you on your journey.", objectives = "Speak with Captain Garrick at Stormwind Keep.", completion = "Excellent, you're here. King Wrynn and the others have been awaiting your arrival." }
WordHunterWoW_QuestEN[58914] = { title = "A Warrior's End", description = "Hey, {name}! You're a {class}, right? Maybe you can deal with this... situation.\n\nI was scouting the area with Lindie's device and saw a ghost who was offering power to any \"true\" warriors.\n\nI know you're still new at this, but why don't you try going over there? \n\nWe could use every advantage against these ogres.", objectives = "Speak with the strange ghost at the Darkmaul Bridge.", completion = "You are no hero of myth and legend... but I see potential within you.\n\nStand still, and I shall share with you my mightiest technique.\n\nAnd then I implore you to end my suffering." }
WordHunterWoW_QuestEN[58915] = { title = "Hjalmar's Final Execution", description = "You now wield my most powerful skill, young warrior. \n\nNow use it to finish me! These ogres trapped my spirit here long ago for daring to defy them.\n\nOnly through a glorious death will I finally be allowed to rest. \n\nIt is the only way I will see my brothers and sisters in the afterlife.", objectives = "Slay Hjalmar the Undying. You must use Execute in order to truly kill him.", completion = "Sounds like you had an adventure! Where do you think that ghost went after you fought it?" }
WordHunterWoW_QuestEN[58916] = { title = "Dread Priming", description = "Sire Denathrius has requested I help you prepare for the hunt. Every hunter must help prepare a soul here in the Grove of Terror.\n\nI have a stubborn soul here who's been quite uncooperative, Houndmaster Loksey. His time has come to be hunted.\n\n<The Fearstalker hands you a set of Hopebreaker Soul Chains.>\n\nDemoralize him. We can't let him leave here with any hope. The hunt is meant to break the souls so they become less... resistant to the processes of Revendreth.", objectives = "Prepare Houndmaster Loksey for the Penitent Hunt in the Grove of Terror.", completion = "This soul is nearly ready. \n\nWe have an opportunity to finish preparing this one and take care of a problem in the process." }
WordHunterWoW_QuestEN[58917] = { title = "A Rogue's End", description = "A rogue from the lost expedition, Coulston Nereus, tried scouting the island for any threats after they made landfall.\n\nThe last time Henry saw him, he was headed for a cave not far from here.\n\nCan you make contact with Coulston? He may be able to help with our rescue mission.\n\nOh, and be careful when heading north. Alaria spotted a vicious bear roaming the area.", objectives = "Use Stealth to sneak around and find the first expedition's rogue.", progress = "Did you get the roots? Make sure that bear is far away when you pick them.", completion = "Here's the secret to making these poisons. It took me ages to learn it.\n\nNow that I've taught it to you, it should be easy enough for you to make more whenever you need it." }
WordHunterWoW_QuestEN[58918] = { title = "Huwerath", description = "", objectives = "" }
WordHunterWoW_QuestEN[58923] = { title = "A Paladin's Service", description = "I found something strange while using Lindie's Scout-o-Matic that you should probably know about.\n\nThe ghost of a paladin appeared on the hill nearby. She looked straight at the Scout-o-Matic and asked for you.\n\nI don't understand a whole lot about paladins and the Light, but I think you may not want to ignore her.", objectives = "Speak with the paladin's ghost.", progress = "Greetings, <name>. It is good to finally see you.", completion = "Those who serve the Light will know its blessing. Accept this gift, <class>.\n\nCall upon it when your strength fails and when hope seems lost. The Light will protect you from harm." }
WordHunterWoW_QuestEN[58931] = { title = "Inquisitor Stelia's Sinstone", description = "You never truly escape your past, Maw Walker.\n\nEvery venthyr once entered Revendreth as a soul, burdened by the immoralities of their mortal lives.\n\nLike all souls, they carved their true names and most shameful transgressions into sinstones.\n\nKnowledge that intimate can be a potent weapon, if wielded properly.\n\nLocate the sinstones of the inquisitors aiding the Accuser so that you may kill them. Start with Stelia.\n\nAfter they're dead, bring me the Accuser's sinstone. I will deal with her myself.", objectives = "Collect Avowed Crypt Keys and open crypts until you locate Inquisitor Stelia's Sinstone.", progress = "Inquisitors hide their sinstones to protect themselves.", completion = "Good. Temel will know how to exploit this sinstone." }
WordHunterWoW_QuestEN[58932] = { title = "Temel, the Sin Herald", description = "<Before flying away, Echelon shouted an additional command.>\n\nExpropriate Temel as well. He will know how to exploit the sinstone properly.", objectives = "Defeat Cryptkeeper Kassir to earn Temel's obedience.", progress = "Temel will not come willingly.", completion = "<Echelon eyes Temel suspiciously.>\n\nI never liked this runt." }
WordHunterWoW_QuestEN[58933] = { title = "The Deadliest of Poisons", description = "You've got the poison. Now it's time to take out that ogre. Gutgruk the Tough.\n\nHe usually patrols around their citadel. Probably looking for your expedition as we speak!\n\nPoison your blades, then take that monster down.", objectives = "Kill Gutgruk the Tough.", completion = "We'll make sure Coulston Nereus is properly remembered for his sacrifice. \n\nIt's a good thing that poison stopped the ogre... otherwise we would've been in trouble!" }
WordHunterWoW_QuestEN[58936] = { title = "Beast Control", description = "The Grove of Terror's dredbats have become aggressive due to the lack of anima caused by the drought.   \n\nThis is a formal request to cull their numbers. We must re-establish dominance over our creations.\n\n-Flockmaster Sergio", objectives = "Kill 6 Dredbats in the Grove of Terror.", completion = "The balance is returning. Please accept this payment on behalf of myself and the other keepers of this place." }
WordHunterWoW_QuestEN[58937] = { title = "Evil Grubbies", description = "Oh no! This place is littered with mites!\n\nThey are cute like Grubby, but they grow into horrible gorm! If we cleared some of them out, then the Sylvari will have less to fight against later.\n\nThey can burrow away, so it's best to burn them up with Pelagos' red seeds. They'll be good for something after all.", objectives = "Burn 20 Evolving Mites with Pelagos' Flamelash Seeds.", progress = "How many more are there?", completion = "It will be hard for them to return." }
WordHunterWoW_QuestEN[58938] = { title = "Gorm Ruin Everything", description = "These red seeds will still prove useful. They come from a very dangerous plant and are quite unstable. If we are going to recover the blue seed we really need, then these might help.\n\nLet's clear out some of these gorm and search for the real seed.", objectives = "Kill 10 mature gorm.", progress = "We need to clear a path.", completion = "These seeds aren't just useful, they're dangerous!" }
WordHunterWoW_QuestEN[58939] = { title = "The Blue Seed", description = "I remember seeing a blue seed with red leaves nearby, but it was in a cave behind a wall of brambles. I didn't think of it at the time, but maybe you could use the red seeds to get us in?\n\nI wish I didn't mix up the instructions or we wouldn't be in this mess. But maybe it's all going to work out anyway. Let's go!", objectives = "Find the cave entrance, get through the blockage of brambles, and obtain the Ripened Anima Seed.", progress = "This has been quite the fun adventure. Wouldn't you say?", completion = "The seed!" }
WordHunterWoW_QuestEN[58941] = { title = "Alpha Bat", description = "Dredbats are quite useful to us. We make them just like stoneborn, but they lack their same... intelligence. With very little direction, they strike fear into stubborn souls' hearts.\n\nWith the anima drought, our dominion over them has waned. One, Duskterror, has wreaked the most havoc.\n\nThis presents us with an opportunity. Take this soul and draw her in. When she's weak, we can capture her for our own purposes.", objectives = "Hitch Houndmaster Loksey to the stake in the Grove of Terror. Then, weaken Duskterror to capture her.", progress = "Is Duskterror captured?", completion = "Now that Duskterror is captured, we have a little more control over these grounds." }
WordHunterWoW_QuestEN[58946] = { title = "The Divine's Shield", description = "This island has been cursed by necrotic magic. The Light can only just reach this place.\n\nCall upon its Divine Shield to step through the barrier before us unharmed and destroy this vile altar.\n\nShow the darkness on this island that you are protected by the Light's embrace.", objectives = "Cross the necrotic barrier with Divine Shield and destroy the Necrotic Altar. You can speak with Yorah if you need to reduce Divine Shield's cooldown.", progress = "Do you require aid? Use Divine Shield to safely pass through the necrotic barrier.", completion = "You have done well, <name>. Dispel this foul magic wherever you encounter it.\n\nMy task has been fulfilled. The Light calls to me. \n\nGood luck, and remember that the Light's warmth will always embrace you." }
WordHunterWoW_QuestEN[58947] = { title = "Test Your Mettle", description = "Many of the greatest Maldraxxi legends earned their fame fighting in the Theater of Pain. \n\nIf you want to follow in their footsteps, you need to prove you have what it takes to survive in there.\n\nDefeat Valuator Malus and Tester Sahaari in combat. Let's see what you can do!", objectives = "Valuator Malus and Tester Sahaari defeated.", progress = "Earn the right to proceed!", completion = "You've proven yourself worthy! I'll see if we can get you into a fight soon!" }
WordHunterWoW_QuestEN[58948] = { title = "Food on the Table", description = "I'm making a stew for dinner tonight, but it seems we're missing rabbit meat.\n\nWould you be able to go out back and collect some for me?\n\nOh and do be careful, I heard howling earlier. The wolves aren't normally out during the day.", objectives = "Collect 4 Rabbit Meat.", progress = "Shh shh, Gwendolyn. It's okay, baby girl.", completion = "This should be plenty. Thank you, love." }
WordHunterWoW_QuestEN[58949] = { title = "Millie's Garden", description = "Alma came by earlier and gave Millie some flower seeds to plant out in the garden.\n\nI love that our daughter is taking an interest in gardening, but I don't have time to wash her dress when she gets it covered in mud again!\n\nWould you help her with the digging so that she doesn't get too dirty?", objectives = "Use your shovel to till 3 Untilled Soil.", progress = "<Millie giggles.>\n\nHi daddy!", completion = "You're the best daddy ever!\n\n<Millie gives you a big hug around the knees.>\n\nHere, I made you some lemonade. I only have enough for one glass, so don't drink it too fast!" }
WordHunterWoW_QuestEN[58950] = { title = "Lumber for Lakeshire", description = "Magistrate Solomon requested a bundle of wood for his hearth. However, he's been too busy to come by and retrieve it.\n\nIf you wouldn't mind running it down to him at the town hall, I'm sure he'd appreciate it.", objectives = "Bring the Bundle of Lumber to Magistrate Solomon at the Lakeshire Town Hall.", progress = "The folks are on edge, Ben. It's my job to keep them at ease.", completion = "Thanks for delivering the lumber. I was going to go pick it up myself, but the townsfolk have been crying wolf all day." }
WordHunterWoW_QuestEN[58951] = { title = "Lakeshire's Last Stand", description = "There's no time to evacuate... not if the Scourge are here!\n\nBoard the windows! Get everybody inside! Our only hope is to hide.", objectives = "Make a stand against the Scourge invasion.", completion = "This poor soul.\n\nAn honest man... to die so gruesomely..." }
WordHunterWoW_QuestEN[58952] = { title = "Purging Flames", description = "", objectives = "" }
WordHunterWoW_QuestEN[58953] = { title = "A Priest's End", description = "You're a trained priest, right {name}? This might be up your alley.\n\nWe've spotted the bodies of other recruits from our expedition.\n\nI'm guessing they washed up on a different part of the island. They didn't make it very far.\n\nWhen you have a moment, could you say a few prayers over them? Just to help put their spirits at ease.\n\nWe'll give them a proper burial once we deal with the ogres.", objectives = "Find the corpses of the first expedition recruits.", completion = "There's no time fer chatting. I'm going tae bless ye with the power to resurrect.\n\nI'd give ye a bit more ceremony, but we got an urgent problem on our hands.\n\nIf we don't hurry, the souls of these poor recruits will be consumed by the ogre's necromancy!" }
WordHunterWoW_QuestEN[58960] = { title = "Resurrecting the Recruits", description = "The souls of these recruits aren't strong enough tae resist the dark magic bein' practiced on this island.\n\nUse Resurrect on the remains of these recruits. Beseech the Light tae give 'em another chance while their souls still linger.\n\nI've been stranded on this island for years, watchin' these ogres get away with all of this.\n\nIt's time tae make a stand.", objectives = "Resurrect the Expedition recruits.", progress = "Get goin' and save those recruits with resurrect!", completion = "Ye've got what it takes tae become a great <class> one day.\n\nMe? Oh, me body is long since decayed. But I can rest easy now that I know these ogres are going tae be stopped." }
WordHunterWoW_QuestEN[58961] = { title = "Ambushed Settlers", description = "", objectives = "" }
WordHunterWoW_QuestEN[58962] = { title = "A Warlock's Bargain", description = "While you were mowing down hordes of undead, I was scouting more of the area with Lindie's device.\n\nI saw what looked like a portal out near the bridge, along with the corpse of a warlock we thought was lost in the shipwreck.\n\nThink you can go investigate the area and try to close that portal? We have enough problems on this island as it is.", objectives = "Investigate the first expedition warlock's corpse.", progress = "I see you have the grimoire that enacted the binding ritual.", completion = "Our bargain has been struck.\n\nCall upon me from the Void, and I will answer.\n\n<The voidwalker looks at the worgen's corpse.>\n\nLet us see if you are stronger than those who came before you." }
WordHunterWoW_QuestEN[58974] = { title = "Ambushed Settlers", description = "", objectives = "" }
WordHunterWoW_QuestEN[58975] = { title = "Pest Removal", description = "", objectives = "" }
WordHunterWoW_QuestEN[58976] = { title = "Chasing a Memory", description = "The attack on the Temple of Purity is unprecedented in Bastion. At least, to my knowledge.\n\nWe need to know more. The fragment that the Paragon captured may contain the answers we seek.\n\nThere is a place nearby called the Mnemonic Locus. There, aspirants and ascended alike can call forth their memories and store them away. If we can look through this fragment's memories, perhaps we can learn more about the so-called Forsworn and, with luck, uncover their plan.\n\nI will meet you there. Go in service.", objectives = "Travel to the Mnemonic Locus.", completion = "<Mikanikos gestures irritably toward the Forsworn behind him.>\n\nAre you here to help fix THIS?" }
WordHunterWoW_QuestEN[58977] = { title = "What's In a Memory?", description = "It may be possible to extract memories from fragment, but I worry they will not be useful. This is not whole kyrian, but a tiny piece! A weird, broken piece. It cannot even speak!\n\nWe will apply extractor and see what comes out. Extractor might explode. It might not. For this? Worth the risk, I think.\n\nDo not know what will emerge. Could be memories. Could be nothing. Could be something else. May try to fight you! Stay on your guard, yes? Collect all that look Forsworn.\n\nSpeak when ready.", objectives = "Collect memories of the Forsworn from the Fragment of Lysonia.", progress = "Do you think we will get the information we need, <name>?", completion = "We did it. With any luck, her memories are within our grasp." }
WordHunterWoW_QuestEN[58978] = { title = "Lysonia's Truth", description = "If I had not seen it with my own eyes, I do not know that I would believe such a thing is possible.\n\nYou carry a significant piece of Lysonia within you, now. Go to the Soul Mirrors and open yourself to them. With luck, they will draw from her essence to draw forth a memory of the Forsworn.\n\nIf this works, we may know what they are planning within minutes!", objectives = "Stand before a Soul Mirror and witness memories from Lysonia's past.", completion = "<Mikanikos fumes silently.>" }
WordHunterWoW_QuestEN[58979] = { title = "I MADE You!", description = "I have had it with this insolence!\n\nI have an idea to reset this Mnemis's personality, but you will need to keep it busy.\n\nIt will try to fight you, through whatever means it posseses. I suggest you try not to perish. Kleia can hold her own, so hide behind her if so inclined.\n\nHop to it!", objectives = "Help Mikanikos reset Locus-Keeper Mnemis.", completion = "I hope you will forgive my behavior. I was not feeling quite like myself." }
WordHunterWoW_QuestEN[58980] = { title = "Mnemis, At Your Service", description = "Greetings, I am Locus-Keeper Mnemis and I would be delighted to assist you.\n\nI recall that you are trying to access a particular memory. Due to the contents, that memory can only be viewed within the Vault of the Archon.\n\nIn order to gain access to the Vault, you must collect offerings for the two guardians who watch over it. I have hidden these offerings from the Forsworn, as they are not authorized to enter.\n\nThe Forgelite Prime is the only one among you who can grant authorization. How convenient!", objectives = "Locate two offerings within the Walk of Recollection, then proceed to the Vault of the Archon.", progress = "Did you find the offerings of which I spoke?", completion = "Your search was fruitful. I am delighted to see you remain intact." }
WordHunterWoW_QuestEN[58981] = { title = "Hardened Hive", description = "", objectives = "" }
WordHunterWoW_QuestEN[58983] = { title = "Battle for Azeroth: Tides of War", description = "King Wrynn has called us together for an urgent war council.\n\nIt seems that there was some trouble with the Horde while we were away. The king was impressed with the valor and bravery that you demonstrated during our mission to Exile's Reach.\n\nNow that you've arrived, the meeting will begin without delay.", objectives = "Attend the War Council in Stormwind Keep.", progress = "Thank you for coming.", completion = "The Horde have forced our hand yet again.\n\nThis cannot stand." }
WordHunterWoW_QuestEN[58989] = { title = "Runeforging 101", description = "As knights of the Ebon Blade, we must always be prepared for a variety of martial situations. To this end, the dark art of runeforging is yours to command. With it, runes of great power can be engraved upon your weapons.\n\nAbove us in the Heart of Acherus are runeforges. Visit one and use your power to imbue a weapon with a rune of power.", objectives = "Use the Runeforging ability in your spellbook to engrave a rune upon your weapon.\n\nYou may freely replace the engraving at any time, so long as you are near a Runeforge.", progress = "Have you emblazoned a rune upon your weapon, <name>?", completion = "Remember, runeforges exist in only a few locations, including Acherus and certain places within Icecrown. You may only emblazon your weaponry at a Runeforge.\n\nReturn whenever you desire to replace the rune. Until then, suffer well." }
WordHunterWoW_QuestEN[58990] = { title = "Titanus Egg", description = "", objectives = "" }
WordHunterWoW_QuestEN[58991] = { title = "Curious Corruption", description = "<There appears to be something unusual about this particular item. Perhaps someone in the chamber can speak to its origin.>", objectives = "Seek answers in the Chamber of Heart about the corrupted item.", progress = "Find something interesting?", completion = "Titanic Purification system available." }
WordHunterWoW_QuestEN[58992] = { title = "Pie Not?", description = "I want to cook something warm, savory, and gooey!\n\nThat's right! I want to make a lovely bone marrow pie! When it's done, you'll be as full as a tick. I guarantee it! \n\nNow, just any old marrow won't do. I need the very best and rarest marrow.\n\nAnd that's where you come in! I need you to help Mama out and dig that marrow up. Yes... dig. \n\nOh and be ready to knock some heads. Maldraxxus doesn't take kindly to being carved up.", objectives = "Collect 4 Maldraxxi Bone Marrow.", progress = "Is there any kind of pie that's not just the best? Blood pie, bone marrow pie, bone marrow jelly...", completion = "Well, if this isn't the best batch of marrow I've ever seen! \n\nMama is going to cook you a feast today!" }
WordHunterWoW_QuestEN[58993] = { title = "Swarm Defense", description = "", objectives = "" }
WordHunterWoW_QuestEN[58995] = { title = "I Dreamed A Dream", description = "This is quite a ceremony, everyone is here. This ritual is essential to the recreation of the Crest of Ascension and the preservation of Bastion. \n\nWe owe the Winter Queen and Willowblossom a great debt. Someday, I hope we can repay them.", objectives = "Witness the ceremony.", progress = "Do you have the vessel?", completion = "She's... she's gone." }
WordHunterWoW_QuestEN[58996] = { title = "Abel's Fate", description = "Maw Walker, I have another task for you.\n\nSome time ago, I sent Soulwatcher Abel and a few others to slay some troublesome bonemaulers.\n\nThey have yet to return. Go find them, will you?", objectives = "Investigate Soulwatcher Abel's fate.", progress = "What became of Abel?", completion = "So they were defeated? And yet, you still stand.\n\nShame." }
WordHunterWoW_QuestEN[58997] = { title = "A Bittersweet Prize", description = "I... I don't know what to say.\n\nAll that is left is to return Willo... the vessel... to Polemarch Adrestes in Bastion. This sacrifice must not be in vain.", objectives = "Deliver the Vessel of Ardenweald to Polemarch Adrestes at Elysian Hold in Bastion.", completion = "You have brought the vessel we require for the completion of the Crest of Ascension. I understand it came at a great cost.\n\nWe must endeavor to repay our friends in Ardenweald one day." }
WordHunterWoW_QuestEN[59000] = { title = "Elements of Corruption", description = "Corruption behaves in mysterious ways. It spreads beyond Azeroth herself, touching our most intimate thoughts and sometimes corrupting various relics, as you've seen firsthand.\n\nThough I cannot speak to the effects of these matters directly, I am sure MOTHER has information surrounding these so-called items of corruption.", objectives = "Speak with MOTHER to learn about corrupted items.", progress = "What have you discovered?", completion = "Titanic Purification system online." }
WordHunterWoW_QuestEN[59002] = { title = "A Shaman's Duty", description = "Greetings, young one. Your companions cannot see me. Only you, for you have been trained in the ways of a shaman.\n\nThe shadow energies of this island have ensnared my pack. I need your aid to free them.\n\nGather veil blossoms from the surrounding area. Burn them on the campfire and breath deep of their smoke.\n\nThen you will be able to see my packmates and release them from their bonds.", objectives = "Gather 4 veil blossoms to burn on the campfire in order to rescue the ghost wolf's pack.", progress = "The veil blossoms shall grant you the sight you need to rescue my pack.", completion = "My pack and I are too weak to oppose the dark forces on this island.\n\nWe will use the last of our strength to grant you our power.\n\nUse it to rid the island of the ogres' necromancy.\n\nFree the countless souls they have trapped here." }
WordHunterWoW_QuestEN[59003] = { title = "Combustible Cocoons", description = "", objectives = "" }
WordHunterWoW_QuestEN[59004] = { title = "Splash Damage", description = "The Jailer's troops use anima charged runes to empower their armor. Without those runes, the troops will be significantly weaker! \n\nI developed this special formula to remove tough laundry stains, but it should be capable of removing magical runes as well!\n\nSplash my Putrification Potion on Rune-hardened troops, the bigger the better! Then collect the runes that fall off, so I can extract their anima.", objectives = "50 Anima Charged Runes collected off Rune-hardened Troops.", progress = "Have you cleaned things up?", completion = "Victory will be ours, Maw Walker!" }
WordHunterWoW_QuestEN[59007] = { title = "Soul Well", description = "", objectives = "" }
WordHunterWoW_QuestEN[59008] = { title = "Spriggan Snares", description = "I'm so glad you and Qadarin were passing by! These spriggans are crazy!\n\nGet me out of here!\n\nI was gathering some herbs from the garden when they nabbed me. I'm sure they've captured other souls, too!", objectives = "Free Cirrik and rescue 8 Captives.", progress = "This behavior is unexpectedly bold for the spriggans.", completion = "Capturing souls is a far more brazen act than the typical spriggan prank. I wonder what has changed..." }
WordHunterWoW_QuestEN[59009] = { title = "Her Rightful Place", description = "Mor'Bitan has met his end... and a painful one at that.\n\nYour fortitude contributed in no small part to my success. You have earned my allegiance... for the time being. \n\nThere is much left to do, should you truly desire ownership of this realm.\n\nLet us regroup at the Seat.", objectives = "Return to the Seat of the Primus with your runeblade.", progress = "Were you successful?", completion = "It is good to have allies. Even ones so stubborn." }
WordHunterWoW_QuestEN[59011] = { title = "In Death We Are Truly Tested", description = "Vyraz is the one who trapped me within the Maw. He has long been in league with the House of Rituals and the House of Constructs.\n\nNo doubt he intended to trap you within that hellish place as well.\n\nIt is time he be brought to justice for his treason. Stand with me, and we will face him as one.", objectives = "Confront Vyraz about the death of Margrave Krexus.", completion = "We are struggling to hold the line. We need to act fast." }
WordHunterWoW_QuestEN[59014] = { title = "King of the Hill", description = "Loksey is ready. It is finally time to begin the hunt.\n\nTake him to Wanecrypt. The Fearstalker and the other hunters will be there already.\n\nHurry now. She does not like to be kept waiting.", objectives = "Bring Houndmaster Loksey to the Fearstalker in Wanecrypt Hill.", progress = "Where's the soul?", completion = "Let us begin, shall we?" }
WordHunterWoW_QuestEN[59015] = { title = "Hostile Recollection", description = "", objectives = "" }
WordHunterWoW_QuestEN[59016] = { title = "Call to Arms: Uldum", description = "Our objectives in Uldum are being interrupted by the influx of Alliance scum.\n\nClear as many of them out of the area that you find, then report back.", objectives = "Slay Alliance within Uldum.", completion = "Good work, <class>." }
WordHunterWoW_QuestEN[59017] = { title = "Call to Arms: Vale of Eternal Blossoms", description = "Our objectives in Vale of Eternal Blossoms are being interrupted by the influx of Alliance scum.\n\nClear as many of them out of the area that you find, then report back.", objectives = "Slay Alliance within Vale of Eternal Blossoms.", completion = "Good work, <class>." }
WordHunterWoW_QuestEN[59018] = { title = "Call to Arms: Vale of Eternal Blossoms", description = "Our mission in Vale of Eternal Blossoms is being compromised by the Horde incursion. \n\nGet into Vale and take out as many as you can.", objectives = "Slay Horde within Vale of Eternal Blossoms.", completion = "Good work, <class>." }
WordHunterWoW_QuestEN[59019] = { title = "Call to Arms: Uldum", description = "Our mission in Uldum is being compromised by the Horde incursion. \n\nGet into Uldum and take out as many as you can.", objectives = "Slay Horde within Uldum.", completion = "Good work, <class>." }
WordHunterWoW_QuestEN[59020] = { title = "The Third Fall of Kel'Thuzad", description = "The time has come to purge Maldraxxus of treachery.\n\nOur armies are rallied. Our allies stand ready. The machine of war is in motion.\n\nWe must win this battle, or all of the Shadowlands will be lost.", objectives = "Remove Kel'Thuzad from Maldraxxus.", completion = "Kel'Thuzad escaped into the Banished One's hands, but at least his evil has been driven from Maldraxxus.\n\nWell fought, <name>. Now we focus on rebuilding our forces and restoring order to our realm." }
WordHunterWoW_QuestEN[59021] = { title = "Herald Their Demise", description = "Since the dawn of Revendreth, Temel has been charged with proclaiming the sins of souls for all to hear.\n\nEvery soul here, including venthyr, has been forced to endure his wrathful pronouncements on at least one occasion.\n\nHe will know how to wield Inquisitor Stelia's sinstone to break through her defenses.\n\nSimply command him to do so after you locate the inquisitor, and eliminate her.", objectives = "Order Temel to read from Inquisitor Stelia's sinstone, then kill her.", progress = "Is the inquisitor dead?", completion = "The ward on the Accuser's sinstone is weakened by the inquisitor's death.\n\nBut we must kill both inquisitors before the ward will fully fall, and we can access the Accuser's sinstone." }
WordHunterWoW_QuestEN[59023] = { title = "Ending the Inquisitor", description = "Inquisitor Vilhelm hides smugly in the back of the courtyard, flanked by several gargons and loyal venthyr.\n\nWe must kill him to break the ward on the Accuser's sinstone, so that Lord Chamberlain can use it in his battle.\n\nTemel will once again help you penetrate the inquisitor's defenses. Do not tarry.", objectives = "Order Temel to read from Inquisitor Vilhelm's sinstone, then kill him.", progress = "Once the inquisitor is dead, the warding spell will be broken.", completion = "Lord Chamberlain confirmed the kill. We should hurry." }
WordHunterWoW_QuestEN[59025] = { title = "Straight to the Heart", description = "The success of Mor'Bitan's treachery has made him complacent.\n\nLet him enjoy the feeling, for it ends here. We will lure him out with this ritual... and we will avenge my margrave.\n\nStand with me now, {name}. Together, we will make an example of this traitor.", objectives = "Kill Mor'Bitan.", progress = "He will regret crossing me.", completion = "Cursed lich--may his soul never be reborn." }
WordHunterWoW_QuestEN[59042] = { title = "A Good Heart", description = "Despite the beliefs of most people, Emeni has a kind heart.  Err...at least she will have one, once you give it to her!\n\nI can think of no one better than you, Maw Walker, to give Emeni a new heart. Perhaps this will warm her blood towards you. You might become friends or even soulbinds!\n\nPlease select and place a heart in Emeni's construct.", objectives = "Place a heart in Emenis' construct.", progress = "I hope you chose well!", completion = "You've done it, the construct is completed. The Slaughter Daughter lives again!" }
WordHunterWoW_QuestEN[59043] = { title = "Baker's Dozen", description = "Under this very tent, I've prepared delicacies that would make demigods cry tears of joy. I'm always in need of more baking supplies!\n\nThe brokers usually sell me eggs from parts near and far, but maybe this time you could help me out instead.\n\nYou familiar with gorm? Big insect-like creatures native to Ardenweald. Well, if you find me some eggs of theirs, I'll bake you up something nice in return! \n\nMama will even send Starchy to help you out.", objectives = "Travel to Ardenweald and collect 13 Hatchready Gorm Eggs.", completion = "Perfect! Mama just knew you had the skills to handle such a task!" }
WordHunterWoW_QuestEN[59063] = { title = "Curses!", description = "Oh, dear me, this is terrible! Just terrible!\n\nI know precisely which awful curse afflicts that poor soul! But these damnable spriggans keep stealing my scrolls, scattering them all over and ripping them apart! \n\nNow the falls are overrun with all manner of dangerous magic!\n\nThe spriggans have the pieces of the scroll you need. Gather them along with a binding from one of the major hexes, and you can put it all back together.", objectives = "Retrieve 5 pieces of Shredded Scroll from Rotbriar spriggans and a Tattered Binding from a Major Hex to create a Sealed Scroll of Soul Rot.", progress = "Hmm... Yes, this looks like it could be the one.", completion = "I knew Dreyden would have the scroll we need. We don't have time to waste!" }
WordHunterWoW_QuestEN[59068] = { title = "A Secret Never Spoken", description = "The first reagent listed in the scroll is a secret never spoken.\n\nWell, that's easy. I know who has tons of secrets! Watcher Vesperbloom, our resident snoop. She keeps the Wild Hunt informed of any nefarious behavior that takes place in the forest.\n\nI know she'd be willing to give us a secret to save Qadarin's soul from dissolving in excruciating pain.\n\nI'll have Thiernax meet you wherever she's hidden them. It'll keep his mind off what's happening to his husband.", objectives = "Obtain a Secret Never Spoken from Watcher Vesperbloom's records.", progress = "Whew! This page... It's seen sights no one should ever see.", completion = "You have no idea how tempted I am to open this and read it. Let's hurry up and create this counter-curse!" }
WordHunterWoW_QuestEN[59069] = { title = "A Token of Lost Love", description = "My sister, Alexstrasza, lost her prime consort, Korialstrasz, towards the end of our war with Deathwing.\n\nShe has loved many in her long life, but none as deeply as he. I know in my heart she loves him still.\n\nFind Alexstrasza in the Vermillion Redoubt and ask for a token of her lost love. It will surely prove a powerful reagent for the counter-curse.", objectives = "Speak with Alexstrasza at the Vermillion Redoubt in Twilight Highlands.", progress = "My sister loves with all of her heart...", completion = "This figurine... I have not seen it since...\n\nI gave this to her when we first became Aspects. Our duties would draw us apart for the first time in our lives. To know that she has kept it all this time...\n\n<Ysera wipes her eyes.>\n\nWe will put it to good use." }
WordHunterWoW_QuestEN[59070] = { title = "A Sacrifice of Anima", description = "The last thing we need for this counter-curse is some attuned anima.\n\nOf course, we don't have much to spare. That means this is more of a sacrifice than it normally would be.\n\nBut you know what? The spriggans made this mess, so they should help clean it up. Some really nasty ones have been causing mischief in Tirna Scithe. They should have the anima we need.\n\nThiernax looks like he could use some nice, vengeful, therapeutic spriggan stomping. I'll have him meet you there.", objectives = "Slay Spriggans in Tirna Scithe to collect Mischief-touched Anima.", progress = "Have you handled those spriggans yet?", completion = "HA! That will teach those spriggans! You mess with the mistrunner, you get the magical horn!\n\nNow we have the anima we need! And, conveniently, it's already attuned to the bad attitude of the one who cast the curse." }
WordHunterWoW_QuestEN[59071] = { title = "Mending a Broken Hart", description = "We have all the reagents for the counter-curse!\n\nHurry up and cast it before Qadarin's soul is lost, and Thiernax refuses to help you, and Tyrande is doomed to die horribly in the Maw, and everyone is sad!\n\nBut no pressure.", objectives = "Perform the counter curse.", progress = "I... I cannot thank you enough.", completion = "Were it not for your aid, Qadarin's soul would have been lost forever.\n\nI... I can do no less than offer my aid in return." }
WordHunterWoW_QuestEN[59076] = { title = "The Minions of Mayhem", description = "To all downtrodden and unappreciated hard workers of the Shadowlands: the time has come to rise up. Rise up and stick it to the fangs and the wings and the bonemen! Stick it to the brokers and the bossmons! I says we go into business for ourselves!\n\nCome to our secret meeting at the Ledge of Destiny.\n\nTo all not-downtrodden warlords, Maw Walkers, and morally flexible powerful denizens: We are currently hiring muscle. If interested, please attend. \n\nDon't tell the fuzz.", objectives = "Attend the publicly posted \"Secret Meeting.\"To all downtrodden and unappreciated hard workers of the Shadowlands: the time has come to rise up. Rise up and stick it to the fangs and the wings and the bonemen! Stick it to the brokers and the bossmons! I says we go into business for ourselves!\n\nCome to our secret meeting at the Ledge of Destiny.\n\nTo all not-downtrodden warlords, Maw Walkers, and morally flexible powerful denizens: We are currently hiring muscle. If interested, please attend. \n\nDon't tell the fuzz.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[59077] = { title = "The Plan", description = "So now that you solved all them problems with the Shadowlands its time for us minions to get a go of it. The gates are open, and now it ain't a big secret how the other realms do their thing.\n\nSee, I found these downtrodden minions workin' hard in their own realms and think we all got a bumb deal. I for one am tired of being the labor of the fangs. \n\nI have an enterprisin' plan for us to go into business for ourselves. Thing is, we need some muscle. Want in?", objectives = "" }
WordHunterWoW_QuestEN[59078] = { title = "The Hook", description = "Your part of the plan is as goes:\n\nWalk into bank, and point the lads at their targets. If things get mawed up then be ready to fight our way free.\n\nHelp us out and you'll get a cut.", objectives = "" }
WordHunterWoW_QuestEN[59079] = { title = "Portal to Paradise", description = "Right.\n\nNow, let's see if I can get this shiny hoistin'. It ain't like we stole someone who could tell us how to use it. \n\nBest stand back, just in case.", objectives = "" }
WordHunterWoW_QuestEN[59080] = { title = "Demons!", description = "", objectives = "" }
WordHunterWoW_QuestEN[59081] = { title = "Scum Scrape", description = "", objectives = "" }
WordHunterWoW_QuestEN[59082] = { title = "Next Realm!", description = "Keep them felfeeders off me long enough to work this amulet.", objectives = "" }
WordHunterWoW_QuestEN[59083] = { title = "Sticky Getaway", description = "", objectives = "" }
WordHunterWoW_QuestEN[59084] = { title = "Bybeen Dreadweaver", description = "", objectives = "" }
WordHunterWoW_QuestEN[59085] = { title = "Third Time is a Charm", description = "", objectives = "" }
WordHunterWoW_QuestEN[59086] = { title = "Manor of Minions", description = "", objectives = "" }
WordHunterWoW_QuestEN[59087] = { title = "That Darn Fox!", description = "You! You there!\n\nI, Clarion Song, need your assistance. Yes, yes, give yourself a moment to bask in my glory.\n\n<Clarion Song gives you a moment.>\n\nDone? Good. I need you to catch a troublesome vulpin kit. He is positively barbaric! Running amok, causing havoc, ruining my beauty rest! He's using a concealing charm to make himself invisible, but I know it's him!\n\nMake yourself useful and catch that kit!", objectives = "Find and Catch Renny the Vulpin kit.", progress = "Well? Did you catch it?", completion = "You, you actually caught that little mongrel?\n\nWell! I am pleasantly surprised. Now hand him over. We are going to go right to his parent. I have a few choice words for the esteemed Lord Renard. Member of the court he may be, I am too impossibly valuable to be constantly pestered by this ragamuffin child!" }
WordHunterWoW_QuestEN[59120] = { title = "Renny the Vulpin", description = "<The small vulpin kit runs up to you with a cheerful bounce and an air of mischief.\n\nYou, it seems, are interesting. Interesting enough that this child of Lord Renard of the Court of Winter has decided to tag along with you.\n\nWhat could possibly go wrong?>", objectives = "<For once it is easy to pick up the small vulpin.\n\nRenny gives you an unmistakable grin. This will be fine... right?><The small vulpin kit runs up to you with a cheerful bounce and an air of mischief.\n\nYou, it seems, are interesting. Interesting enough that this child of Lord Renard of the Court of Winter has decided to tag along with you.\n\nWhat could possibly go wrong?>You will receive:" }
WordHunterWoW_QuestEN[59126] = { title = "Supply Chain", description = "My friend! I could sure use your expertise right now.\n\nOne of our wagon convoys was attacked nearby! It was transporting critical supplies... and new goods for me to sell! \n\nIt's important--no--vital, that we recover as much of that equipment as possible.\n\nSo, you ready to go? Let's head out and salvage what we can!", objectives = "Secure the area and recover Atticus's Supply Ledger and 10 Ossein Battlemail", progress = "Did you find those items?", completion = "Atticus will set a box aside each week with spare supplies in case you need any of them." }
WordHunterWoW_QuestEN[59130] = { title = "The House of Plagues", description = "The House of Plagues was the first to fall in this conflict. We believed its demise was the result of a careless accident. If only we had known the truth sooner...\n\nBut perhaps not all their knowledge was lost. Before you arrived, our scouts reported signs of movement near the wreckage of their necropolis.\n\nIf any survivors remain, we'd be wise to add them to our ranks. But approach with caution. The toxic fallout may have left them mad... or worse.", objectives = "Search for survivors near the House of Plagues.", completion = "My apprentice! I have been searching everywhere for you!" }
WordHunterWoW_QuestEN[59147] = { title = "The Hand of Purification", description = "Nikolon was not alone.\n\n<Eridia stares grimly out over the temple grounds.>\n\nLong have I toiled over the aspirants in my care. Long have I tended to this temple under my Paragon. To know that so many have fallen, alone, is a blow.\n\nBut this... wanton destruction! It will not stand.\n\nYou will be my hand, {name}. Go forth. End them. All of them.\n\nMy duty demands that I tend to those that remain. I will find you near the bridge when the way is clear.", objectives = "\"Cleanse\" the Temple of Purity by slaying enemies.", completion = "Some stains must be scoured away." }
WordHunterWoW_QuestEN[59171] = { title = "Prey Upon Them", description = "My mission cannot progress without a supply of anima. \n\nFortunately, the necromancers nearby have been kind enough to gather some into their maldracite crystals.\n\nYou will relieve them of those crystals. They may be reluctant to part with them, but I trust you can be... persuasive.", objectives = "Collect 3 Anima-charged Maldracite.", progress = "Do not fail me.", completion = "Yes, these will do nicely." }
WordHunterWoW_QuestEN[59172] = { title = "War is Deception", description = "You have proven a useful ally, {name}.\n\nMephiles undoubtedly possesses a wealth of information for us. However, the House of Rituals is unforgiving when it comes to betrayal. He will not talk.\n\nNot that it matters. The House of Eyes has ways to... extract a prisoner's knowledge without the use of words.\n\nPlace the charged crystals around me. They will facilitate the interrogation.", objectives = "Prepare to interrogate Mephiles the Loyal.", progress = "Let us reveal the truth.", completion = "Draka may be content to forget our master, but I will not rest until he is avenged." }
WordHunterWoW_QuestEN[59173] = { title = "Short-Supply Reward", description = "", objectives = "" }
WordHunterWoW_QuestEN[59174] = { title = "Short-Supply Reward", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[59175] = { title = "The Eternal Revenge", description = "<On the shelves there are hundreds of other phylacteries of varying shapes and sizes.\n\nMany bear names - this one specifically has a etching with the name Mor'Bitan.\n\nLady Vashj would be interested in this phylactery.>", objectives = "Take the phylactery of Mor'Bitan back to Lady Vashj." }
WordHunterWoW_QuestEN[59179] = { title = "Daughter of the Night Warrior", description = "In my dreams, I see many things. Elven souls tortured in the Maw. A warrior of the night consumed by vengeance.\n\nAnd... Ardenweald's destruction.\n\nThese visions are ever shifting... ever vague. But I believe Tyrande Whisperwind is key to saving the night elves, as well as this realm.\n\nShandris Feathermoon, Tyrande's daughter, is touched by dreams as well.\n\nEven now, she travels to the Eternal City. Find her. If anyone can reach the heart of Tyrande, it is her.", objectives = "Find Shandris Feathermoon within Oribos.", completion = "<name>? You are a welcome sight in this strange place. \n\nPerhaps you already know that I have come to find my mother." }
WordHunterWoW_QuestEN[59181] = { title = "Into the Maw", description = "I have not seen Tyrande since she departed for Icecrown... but I see her in my dreams. She stalks a nightmarish landscape, brimming with the might of the Night Warrior.\n\nSuch power is too much for any mortal to bear for long. I shudder to think of the toll it has taken on my minn'do.\n\nHighlord Fordragon has told me of the Maw. If you truly have braved its horrors before, then I ask that you guide me through them as well.\n\nWe must find Tyrande and convince her to let go of the Night Warrior's rage.", objectives = "Take Shandris Feathermoon into the Maw.", completion = "I have seen bits and pieces of this dark realm in my dreams. Tyrande roams this place.\n\nWe must find her." }
WordHunterWoW_QuestEN[59183] = { title = "Drifting Sorrow", description = "", objectives = "" }
WordHunterWoW_QuestEN[59184] = { title = "Borr-Geth", description = "", objectives = "" }
WordHunterWoW_QuestEN[59185] = { title = "Entangling Web", description = "It would seem we have a means of luring Mor'Bitan to us. But what good is a web if the prey can run free?\n\nFor these rituals to work, the liches require a magical conduit. They draw runes with finely ground maldracite to channel anima.\n\nI have no doubt Mor'Bitan's necromancers have ground maldracite in the area. If we gather enough, we can draw a rune of binding to trap our target.\n\nWork with haste, {name}.", objectives = "Collect 8 jars of Maldracite Dust.", progress = "I'm waiting.", completion = "He will not escape this time." }
WordHunterWoW_QuestEN[59188] = { title = "Vaunted Vengeance", description = "So you are from my baroness's home world? It must be a special one to breed such powerful individuals.\n\nThe necromancers here have already begun preparation for Mor'Bitan's ritual. We should capitalize on their progress. \n\nThree necromancers act as the ritual's architects. Should we acquire their drafts, we could modify them to suit our purposes.\n\nCollect the plans... and feel free to savor your victims' torment.", objectives = "Collect Ritual Drafts from the three Architects.", progress = "We are hopeful for your success.", completion = "Yes... They will be made to know our pain." }
WordHunterWoW_QuestEN[59189] = { title = "The Recovery of Tyrande Whisperwind", description = "The Night Warrior's power is tearing Tyrande apart. Such rage... it is consuming her.\n\n<Shandris is silent a moment.>\n\nAnd yet, my mother speaks true. We cannot leave the souls of my people to suffer.\n\nWe shall follow Tyrande into Torghast. We must find a way to save the spirits of the kaldorei.\n\nAnd in the process, pray that we can save my minn'do as well.", objectives = "Enter Torghast to recover Tyrande Whisperwind.", completion = "I cannot fault my mother's intent... but she will be consumed before she finds justice for our people.\n\nWe must find another way to bring her back." }
WordHunterWoW_QuestEN[59190] = { title = "Seek Your Mark", description = "I see why Draka sent you in her stead--you accomplish what she could not.\n\nWe have all the pieces. Now, we must simply put them together.\n\nThe steps to the ritual are simple: place our fractured crystals in formation around the obelisk.\n\nThen comes the sigil--*our* sigil. Use the maldracite powder to draw a binding glyph at the obelisk's base.\n\nWhen you are through, return to me.", objectives = "Prepare the ritual.", progress = "Work swiftly.", completion = "Vengeance is nearly ours." }
WordHunterWoW_QuestEN[59196] = { title = "Go in Service", description = "We cannot waste any more time. We must get an audience with the Archon, before this next attack happens!\n\nWe need to find a way to get you to Elysian Hold... and quickly!\n\nHero's Rest is a place of respite for the aspirants of Bastion. You can see it floating above from across the fields.\n\nMeet me there when you can. I have a plan.", objectives = "Meet Kleia at Hero's Rest.", progress = "We must get moving.", completion = "The Polemarch? He is the right hand of the Archon!\n\nShe truly believes us. We still have a chance!" }
WordHunterWoW_QuestEN[59197] = { title = "Steward at Work", description = "Stewards are useful for many reasons.\n\nThey keep Bastion tidy, fix anything broken, and offer unrivaled companionship and support.\n\nYour new steward assistant should be able to repair the beacon. Then you can summon the Polemarch to Hero's Rest.", objectives = "Use Summon Steward to fix the Beacon of Invocation, then use it to summon Polemarch Adrestes.", completion = "Kalisthene has vouched for you by allowing usage of the beacon. For that reason, you have my attention." }
WordHunterWoW_QuestEN[59198] = { title = "On Swift Wings", description = "Our revered Archon has decided to grace you with an audience.\n\nIt is your duty to present your discoveries to her, then follow her wise judgment.\n\nShe holds audience in Elysian Hold, part of the sprawling Spires of Ascension, the home of the Ascended.\n\nWe shall carry you there, for it is a place for those who can fly.", objectives = "Fly with Adrestes to Elysian Hold.", completion = "The Archon's chambers are just above. I urge you to practice extreme deference while in her presence." }
WordHunterWoW_QuestEN[59199] = { title = "Kyrestia, the Firstborne", description = "I will escort you to hold audience with the Archon.\n\nI beseech you to present your information succinctly and directly.\n\nOur wise Archon will hear you and make a decision on the best course of action.", objectives = "Speak with Adrestes to address the Archon.", progress = "None shall doubt the Archon, in her infinite wisdom.", completion = "The Archon's grace is upon you, mortal." }
WordHunterWoW_QuestEN[59200] = { title = "The Wards of Bastion", description = "Each temple of Bastion is protected by a ward here in Elysian Hold. As long as the wards hold, no malevolent force can launch an assault.\n\nIt is concerning that the Forsworn were able to attack Purity in such force...\n\nYour orders are to examine the wards. As long as they hold, Bastion stands strong.", objectives = "Investigate the temple wards in Elysian Hold.", progress = "The wards each protect one of the temples of Bastion. If a ward is not active, that temple stands vulnerable.", completion = "It seems the Forsworn are in our very midst, even in the Spires.\n\nWe must send aid to the Temple of Courage posthaste." }
WordHunterWoW_QuestEN[59202] = { title = "Among the Chosen", description = "Only one rune remains...\n\nWe should return to the House of the Chosen and report to Margrave Krexus. He will want to know of our progress.", objectives = "Return to the House of the Chosen.", completion = "I will have my soldiers honor Krexus as he deserves." }
WordHunterWoW_QuestEN[59203] = { title = "Leave Me a Loan", description = "I run a myriad of businesses here. Betting rings, performance enhancers... whatever the customer is willing to purchase. \n\nHowever, a few of those customers are late with their payments. And a customer who does not pay is a customer without value.\n\nPlease ask them to surrender what they owe. I trust you know what to do if they refuse.", objectives = "Collect 6 Anima Vials from the arena spectators.", progress = "Do not try to cheat me out of anything I am owed. I will know.", completion = "Yes, you are more valuable than I first surmised." }
WordHunterWoW_QuestEN[59206] = { title = "Words of the Primus", description = "Even in his absence, the wisdom of the Primus rings true. This message must have been put here to await one who proved worthy of hearing it.\n\n<Draka peers at you.>\n\nYou came to Maldraxxus to learn why Bastion was invaded. Now you know that there is treachery in our ranks. And that there are noble souls here who will set things right.\n\nTell your allies in Oribos all you have witnessed. See that the warning of the Primus reaches the Eternal Ones.\n\nIt would be an honor to fight by your side again, {name}.", objectives = "Return to Oribos.", completion = "I am glad of your return, mortal.\n\nI pray you were successful in preventing the advent of war between Bastion and Maldraxxus." }
WordHunterWoW_QuestEN[59207] = { title = "Unshackled Knowledge", description = "These Forsworn are looting the artifacts contained in Kalliope's Rest. What is worse is they have captured many of the shrine's scholars.\n\nI fear they will interrogate these aspirants for knowledge about the artifacts held within the inner chamber of the shrine.\n\nMost escaped with me, but Lano, Eratus, and Tyrana have not returned yet.", objectives = "Free Curator Lano, Librarian Eratus, and Historian Tyrana.", completion = "We've already treated some of the kyrian you freed. Thank you for your aid, <class>." }
WordHunterWoW_QuestEN[59209] = { title = "Rebel Reinforcements", description = "<General Draven looks around.>\n\nWe require additional reinforcements.\n\nI know of two here that are fiercely loyal to the true purpose of Revendreth. The Fearstalker left them here to be consumed by the anima drought due to their allegiance.\n\nThey are both fully capable of assisting us in our mission.\n\nTake this anima stake and infuse them. Direct them to me, I will explain the situation.", objectives = "Recruit Watchmaster Boromod and Tactician Sakaa.", progress = "Are our allies infused?", completion = "Our numbers are bolstered. Our survival chance is only slightly less grim." }
WordHunterWoW_QuestEN[59210] = { title = "Tainted Cores", description = "This lich seeks a reward for his assault on the House of Eyes. But the power he craves will be his downfall.\n\nWe will use our knowledge of his secret ritual to lure him out of the House of Rituals. \n\nTake these crystals, {name}. Charge them with anima reclaimed from Mor'Bitan's slain minions.\n\nBut fracture them first, so that they shatter as the ritual nears completion... but not before Mor'Bitan believes that it has begun.\n\nThat is when we will strike.", objectives = "Fracture the three Depleted Anima Crystals, then charge the Fractured Anima Crystals with deceased Morbid Ritualists.", progress = "Is it done?", completion = "Well executed." }
WordHunterWoW_QuestEN[59211] = { title = "Forgotten Village", description = "", objectives = "" }
WordHunterWoW_QuestEN[59223] = { title = "By Any Other Name", description = "Excellent work, my apprentice! Our laboratory is back in working order!\n\nNow, there is one final ingredient we require to complete our potion for Margrave Stradama.\n\nYou will need to run along to the greenhouse. I've cultivated a sprig of dreadshade that should be ready to harvest.\n\nI will prepare the other reagents while you're away. Be safe, apprentice!", objectives = "Collect Dreadshade Extract for Marileth's potion.", progress = "Have you found it?", completion = "Come, my apprentice! Our efforts nearly bear fruit!" }
WordHunterWoW_QuestEN[59225] = { title = "[DNT] Azerite Reward Test Quest - BJI", description = "[DNT] This quest should award Azerite Armor and Azerite if you have a HoA, and armor stripped of powers and no azerite if you do not have a heart of azeroth yet.", objectives = "" }
WordHunterWoW_QuestEN[59229] = { title = "Gargantuan Seeker", description = "", objectives = "" }
WordHunterWoW_QuestEN[59230] = { title = "Dartanos, Flayer of Souls", description = "", objectives = "" }
WordHunterWoW_QuestEN[59231] = { title = "Fathomless Power", description = "Forgive me, apprentice... I felt a bit woozy for a moment! But you've done it! You've crafted the potion!\n\nI'm so proud of you. What joy your work brought to our margrave!\n\nWhat manner of teacher would I be were I to ask for your help and not offer my own in return? If you have research you must conduct, you have my full support!\n\nLet us venture to your laboratory, then. I wait with bated breath to behold your future achievements!", objectives = "Meet Marileth at the Seat of the Primus.", completion = "I see you've made a new ally... of a sort. And another rune has been empowered." }
WordHunterWoW_QuestEN[59232] = { title = "A Lesson in Humility", description = "Thank you for your service in deposing the Accuser and elevating Lord Chamberlain in her place.\n\nThe Accuser's unprompted betrayal has rendered her both undeserving and unfit to serve on the Court of Harvesters.\n\nNow, please, observe what happens to traitors in Revendreth.", objectives = "Witness the Accuser's judgment.", progress = "Please observe silently, Maw Walker.", completion = "I am nothing if not merciful and understanding.\n\nThe Accuser will be given every opportunity to repent her errors and learn from them." }
WordHunterWoW_QuestEN[59233] = { title = "The Prince's New Crown", description = "The crown is ready. I will entrust you to deliver it to Renathal.\n\nMake haste, {name}. This power will surely attract assailants if word gets out.\n\nYou may use the mirror to return. Know that I will be dispatching others to destroy it after your arrival. \n\nSafe travels, Maw Walker.", objectives = "Deliver the Crown of the Harvesters to Prince Renathal in Sinfall.", completion = "Excellent work, <name>. \n\nWith this crown, I can focus the magic of the Harvesters into an unstoppable force. Now we continue our mission to redeem Revendreth. As a token of my appreciation for all of your help, I open up our armory to you. Please pick your reward." }
WordHunterWoW_QuestEN[59234] = { title = "Mixing A Mess", description = "", objectives = "" }
WordHunterWoW_QuestEN[59242] = { title = "Their New Home", description = "It pains me to leave my mother behind... but the souls of my people must be brought to safety.\n\nI heard the attendants in Oribos speaking of a place called Ardenweald. A realm of ancient forests where the spirits of nature slumber.\n\nThis is a land you know well, is it not? I would see its wonders with my own eyes.\n\nPerhaps the spirits there will know how to save my minn'do from the Night Warrior's power.", objectives = "Take Shandris Feathermoon and the rescued night elf souls to Ysera at the Heart of the Forest in Ardenweald.", progress = "You've returned. But what of the others?", completion = "My heart aches for Tyrande. The might of the Night Warrior is empowering her to battle these monsters... but it will consume her if we do nothing.\n\nShandris and I will investigate a... promising whisper that I have heard. I shall call upon you when I know more." }
WordHunterWoW_QuestEN[59246] = { title = "Daughter of the Night Warrior", description = "In my dreams, I see many things. Elven souls tortured in the Maw. A warrior of the night consumed by vengeance.\n\nAnd... Ardenweald's destruction.\n\nThese visions are ever shifting... ever vague. But I believe Tyrande Whisperwind is key to saving the night elves, as well as this realm.\n\nShandris Feathermoon, Tyrande's daughter, is touched by dreams as well.\n\nEven now, she travels to the Eternal City. Find her. If anyone can reach the heart of Tyrande, it is her.", objectives = "Find Shandris Feathermoon within Oribos.", completion = "I will trust you for now, <name>.\n\nBut should you betray me, I will ensure you endure the same torments I do." }
WordHunterWoW_QuestEN[59254] = { title = "Enhanced Combat Tactics", description = "Alaria says that the quilboar kidnapped other members of her expedition.\n\nChances are we'll have to brave the quilboar's den. That's no small feat. They are far more aggressive and intelligent than the murlocs you faced earlier.\n\nI need to make sure I'm not sending you to your death. We're going to have one last sparring session.", objectives = "Spar with Captain Garrick.", completion = "Fine work, <name>. Let's speak with Alaria and hunt down those quilboar." }
WordHunterWoW_QuestEN[59256] = { title = "The Fearstalker", description = "The trap has been set and the Fearstalker has walked right in.\n\nJust as I expected, her pride has blinded her to the obvious. Have that vial I gave you earlier ready. It may prove useful in the fight ahead.\n\nWhen you are ready, we can spring the trap.", objectives = "Speak to the Accuser to trigger the trap, then kill the Fearstalker and collect the Medallion of Dread.", progress = "The Fearstalker must be defeated.", completion = "This medallion will serve us well. But we lack our leader to don it.\n\nWe must seek out more allies." }
WordHunterWoW_QuestEN[59258] = { title = "Home of the Tirnenn", description = "The Horned Hunter is no longer here. But I do know where he went.\n\nHe tracked his prey to the west of here, in the Elder Stand. These woods in particular have grown dangerous as of late, and we are currently beset by invading devourers.\n\nThey have overrun the roads between here and the Stand. I shall accompany you across the bridge, and see that you are delivered to the Horned Hunter.", objectives = "Fight your way into Tirna Scithe and find the Horned Hunter.", completion = "Now, let us speak of the hunt." }
WordHunterWoW_QuestEN[59259] = { title = "The Eternal Tormentor", description = "", objectives = "" }
WordHunterWoW_QuestEN[59262] = { title = "Broken Wings", description = "You help me? Really? Wow!\n\nLook at me. What am I?\n\nI have beak. Feathers. Scaly toes. I am bird, yes? \n\nBut birds have wings. And I have arms. Why I not have wings? \n\nI broken. I can not fly.\n\nLarion nearby, flies so gracefully. I must study her wings up close! \n\nYou help me?", objectives = "Bring KowalskosAriella's Wing.", progress = "If I can study a larion wing, surely I can learn!", completion = "Perfect! I will examine closely." }
WordHunterWoW_QuestEN[59263] = { title = "Feathers of Flight", description = "Now, let us see this next to my arm...\n\nLook! There many long feathers along the edges of the Larion's wing!\n\nAnd none on mine. This is why I can not fly!\n\nHmm. It will take lots of flight feathers to give me wings. \n\nYou help?", objectives = "Bring Kowalskos 100 Larion Flight Feathers.", progress = "Feathers... So many feathers...", completion = "Yes, these are enough feathers to make my arms into wings!" }
WordHunterWoW_QuestEN[59265] = { title = "Prying Eyes", description = "The Constructs would repurpose the carcass of our necropolis. But we will need its parts for our own ends.\n\nLet us deliver a warning to these scavengers.\n\nSlay the Constructs amid our wreckage. Pluck the eyes from their skulls. Such is our signature.\n\nThey will know to fear the darkness once more.", objectives = "Collect 20 Betrayer's Eyes from constructs in Akarek's Tears.", progress = "You offer gifts?", completion = "I see cowardice in these eyes. You have done well." }
WordHunterWoW_QuestEN[59291] = { title = "Conquest's Reward", description = "", objectives = "Your prowess on the field of battle is without peer." }
WordHunterWoW_QuestEN[59292] = { title = "Conquest's Reward", description = "", objectives = "Your prowess on the field of battle is without peer." }
WordHunterWoW_QuestEN[59293] = { title = "Special Formula", description = "You may think I'm naturally gassy, but it actually takes a lot of work to build it all up. This is all the result of a nice coating of Pox Nodules.\n\nHelp me refresh my coating.\n\nJust get me near the absorbing pox and I'll pull the nodules right off his slimy skin.", objectives = "Help Gas Bag collect Pox nodules.", progress = "Did you get what he needed?", completion = "He's smelly again? We'll at least he's happy, even if we are not." }
WordHunterWoW_QuestEN[59311] = { title = "How to Catch a Glimmerfly", description = "Yes! Proper tools collected. Now to catch glimmerflies!\n\nAnima drought more severe in northern pools. Many Starving Glimmerflies, most eager to drink from our animyllis blooms.\n\nPlace blooms, then while glimmerflies are drinking attach to filaments! Then return to me.", objectives = "Capture 5 Starving Glimmerflies in the Shimmering Pools, then return to Kowalskos.", progress = "Glimmerflies will surely help me fly!", completion = "<Kowalskos gets very excited> \n\nWow! It worked! I hope they hold me up, too!" }
WordHunterWoW_QuestEN[59314] = { title = "Sinfall", description = "I knew you could be counted on. Revendreth's revival relies on forging pacts with those outside of our realm. \n\nThe Prince never had any doubt that you would agree to join our cause. He summoned the Court of Harvesters in anticipation of your arrival. \n\nRenathal awaits you within Sinfall, where you will be presented to the court.", objectives = "Report to Prince Renathal in Sinfall.", completion = "I never doubted you for a moment, <name>." }
WordHunterWoW_QuestEN[59315] = { title = "The Court of Harvesters", description = "Partnerships such as ours will be key to Revendreth's revival. \n\nAs Harvesters, we have the ability to extend our powers to mortals, though the decision must be unanimous. To that extent, the court has gathered and is awaiting your arrival.\n\nLet's not keep them waiting.", objectives = "Stand before the Court of Harvesters and pledge your loyalty.", progress = "You will be welcomed by the court, I have no doubt, but first, you must swear an oath before the Harvesters.", completion = "Welcome to our humble court, <name>." }
WordHunterWoW_QuestEN[59316] = { title = "Binding Power", description = "To soulbind with another is not an irrevocable bond. However, it is not to be entered into lightly.\n\nYou will experience one another's pasts. Your hopes, fears, dreams, your very memories--if any still linger. You will become kindred spirits in the truest sense.\n\nOnce complete, your connection will transcend physical space and make you stronger in more than mere brawn.", objectives = "Complete the soulbinding ritual." }
WordHunterWoW_QuestEN[59317] = { title = "Strengthening the Bond", description = "Do you feel it, too? Our connection is stronger than I imagined could be possible. \n\nI have been told that the bond will continue to grow over time, though we do have the ability to accelerate the process. \n\nSinfall needs our strength. Perhaps it is best we engage in this method now.", objectives = "Strengthen your bond with Nadjia." }
WordHunterWoW_QuestEN[59319] = { title = "Advancing Our Efforts", description = "A venthyr's primary responsibility is ensuring that souls are unburdened of their pride, but they must see to other matters as well. \n\nWe must act beyond the bounds of Revendreth to ensure that the souls of the Shadowlands keep to their fate.\n\nAllow me to demonstrate with a simple task for your companion here. This will be the first of many strikes.", objectives = "Inspect the Command Table and start an adventure.", progress = "These calculated strikes will further our cause.", completion = "The mission will be a complete success, I have no doubt." }
WordHunterWoW_QuestEN[59321] = { title = "Sacred Covenant", description = "Our covenant is more than just pacts and promises. We have immense power, too. And that power we shall bestow upon you in a sacred ritual.\n\nOnce complete, you will be able to call upon our gifts with ease.", objectives = "Meet Prince Renathal in the ritual hall on the lower level of the sanctum.", completion = "Welcome, I must admit my eagerness to partake in this monumental occasion." }
WordHunterWoW_QuestEN[59322] = { title = "Shared Souls", description = "The power of the Harvesters flows through your mortal body. But you may wield even greater might by binding your soul to another.\n\nDoing so has no known drawbacks, but offers many advantages for both parties involved. \n\nThe Accuser will oversee the process. Meet her at the Forge of Bonds when you are ready.", objectives = "Meet The Accuser at the Forge of Bonds.The power of the Harvesters flows through your mortal body. But you may wield even greater might by binding your soul to another.\n\nDoing so has no known drawbacks, but offers many advantages for both parties involved. \n\nThe Accuser will oversee the process. Meet her at the Forge of Bonds when you are ready.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[59323] = { title = "Anima Awakening", description = "This ritual will bestow upon you our gift. \n\nWe will stir the anima within your soul, awakening a power that has only been known to Harvesters.   \n\nIt has never been performed on a mortal before, but I have been assured that it won't hurt a bit.", objectives = "Participate in the Harvesters's ritual.", progress = "Take your place when you are ready to begin.", completion = "So long as the pact remains, so shall our power." }
WordHunterWoW_QuestEN[59325] = { title = "A Stalwart Ally", description = "We have our work cut out for us, Maw Walker. The Harvesters will not relinquish their power without a fight. \n\nYou will need stalwart allies at your side. Ones that know how battles are fought within the Shadowlands. \n\nLet me be your guide. Together, we will see Revendreth return to its true purpose.", objectives = "Complete the soulbind process with General Draven.", completion = "Together we are stronger." }
WordHunterWoW_QuestEN[59327] = { title = "In the Ruin of Rebellion", description = "Well, here we are -- Sinfall.\n\nLast I saw, the Master was dragging Prince Renathal and his most loyal followers here in a prison convoy. However, this is a forbidden place, wrapped in rumors and mystery. I heard it was once the workshop of Denathrius, where he performed dark experiments.\n\nIntriguing to be sure, but we are here to find Renathal. Search below, but proceed with caution. I will send word for the Accuser to make her way here with what allies she can muster.", objectives = "Search Sinfall for any signs of Prince Renathal.", progress = "Flesh that walks and talks in the Shadowlands. Interesting.", completion = "I will sever your head from your body should you...\n\nWait...\n\nYou are still alive? That means you are... the Maw Walker?" }
WordHunterWoW_QuestEN[59339] = { title = "Enhanced Combat Tactics", description = "Alaria says that the quilboar kidnapped the rest of the expedition... including my son.\n\nChances are we'll have to brave the quilboar's den. That's no small feat. They are far more aggressive and intelligent than the murlocs you faced earlier.\n\nI need to make sure I'm not sending you to your death. We're going to have one last sparring session.", objectives = "Spar with Captain Garrick.", completion = "Fine work, <name>. Let's speak with Alaria and hunt down those quilboar." }
WordHunterWoW_QuestEN[59340] = { title = "Gallath's Bell", description = "", objectives = "" }
WordHunterWoW_QuestEN[59342] = { title = "Taming the Wilds", description = "As a hunter, you need a trustworthy beast at your side... or else these quilboar will slaughter you.\n\nWhen you're ready, I'll teach you how to tame such a beast. Then you must find one to be your loyal companion.", objectives = "Learn Tame Beast from Austin Huxworth, then use Tame Beast on any nearby wildlife.", progress = "I'll teach you how to tame beasts. Then you'll need to choose any animals nearby to tame.", completion = "You've got a loyal companion by your side. Take good care of them, and they'll take care of you." }
WordHunterWoW_QuestEN[59343] = { title = "Kindred Spirits", description = "I have come to the realization that you and I are meant to be the most kindred of spirits. \n\nYour enduring nature has enraptured me, and I'm afraid I cannot bear to imagine an afterlife without your beguiling presence. \n\nLet us bind our souls, and forever carry each other in both heart and mind.", objectives = "Complete the soulbinding ritual.", completion = "My heart swells, knowing that our souls are bound for all eternity." }
WordHunterWoW_QuestEN[59344] = { title = "Renavyth's Medallion", description = "", objectives = "" }
WordHunterWoW_QuestEN[59345] = { title = "Phantoriax's Warsword", description = "", objectives = "" }
WordHunterWoW_QuestEN[59346] = { title = "Indri's Flute", description = "", objectives = "" }
WordHunterWoW_QuestEN[59347] = { title = "A Monk's Focus", description = "You fought well against the harpies, but we all need to become stronger to face what lies ahead.\n\nThe first step is to find a nice place to meditate and focus yourself.\n\nA monk is only as strong as they are focused.\n\nCome. I know of such a place.", objectives = "Follow Kee-La and meditate with her.", progress = "Let us meditate. I find meditation always helps clear my mind.", completion = "There's something different about you, <name>. Let's see exactly what it is." }
WordHunterWoW_QuestEN[59348] = { title = "More Wings!", description = "Idea! Maybe I am too heavy. Maybe need more wings!\n\nGlimmerflies have lovely wings. With correct bait and strong rope, perhaps we can catch.\n\nPlease bring Animyllis Blooms. Their nectar is delicious for glimmerflies, and makes them drowsy!", objectives = "Collect 10 Animyllis Blooms.", progress = "Animyllis Bloom nectar is a glimmerfly's favorite sleepytime treat!", completion = "I enjoy these blooms. Such a unique odor, yes?" }
WordHunterWoW_QuestEN[59349] = { title = "One Last Spar", description = "Let us have a quick sparring session before we return to camp, {name}.\n\nI want to see how this island has pushed you to grow.", objectives = "Spar with Kee-La.", completion = "I'm glad to hear you and Kee-La sharpened your skills. We're going to need all our strength to push back the ogres." }
WordHunterWoW_QuestEN[59350] = { title = "A Druid's Form", description = "Thank you for rescuing me, {name}. Allow me to aid you in your druidic studies.\n\nTo escape from the pit, I took on the form of a stag. I may know of a way you can learn to do the same.\n\nCome with me. There is an ancient druid stone nearby. Let us use it to commune with the wilds.", objectives = "Commune with the nearby druid stone.", progress = "Come. The spirits of nature await us.", completion = "Good! I can sense the blessing of the spirits flowing through you.\n\nFocus, and you should find that you can take on a new form." }
WordHunterWoW_QuestEN[59351] = { title = "Strings and Things", description = "Glimmerflies are creatures of anima. Though they look delicate, they are quite strong!\n\nFilaments from etherwym tails are sturdy. They should help hold onto glimmerflies. \n\nCollect for me!", objectives = "Collect 10 Etherwyrm Filaments.", progress = "Etherwyrm Filaments are almost pure anima. Very hard to break!", completion = "<Kowalskos pulls on the filaments with all his might>\n\nSee? Very strong!" }
WordHunterWoW_QuestEN[59352] = { title = "A Mage's Knowledge", description = "Ye got some good spells fer a novice mage. Ye might even be as good as I am one day!\n\nBut ye don't know Polymorph! How could ye not know that?\n\nPolymorph's one of a mage's most useful spells. I can teach it tae ye, if ye can find me spellbook.\n\nLast I saw, the ogres threw me book in the lake. The LAKE!\n\nGo get me book, and I'll show ye how tae cast Polymorph.", objectives = "Recover Meredy Huntswell's book at the bottom of the nearby lake.", progress = "I hope me book isn't too damaged after sittin' at the bottom o' the lake.", completion = "Perfect! Let's see... ah, the page for Polymorph is fine! \n\nWell, it's missin' a few words, but once ye know the magic ye can skip over most o' this.\n\nHere, I'll teach it tae ye... and I'll show ye how it works!" }
WordHunterWoW_QuestEN[59354] = { title = "The Best Way to Use Sheep", description = "I'm not gonna send ye off without showin' ye how tae properly use this spell.\n\nYe wanna cast Polymorph if ye get yerself into a situation when two foes are fightin' ye at once. \n\nCole and I will spar with ye a bit tae make sure ye know what tae do.", objectives = "Practice using Polymorph against Meredy and Private Cole.", progress = "And don't ye worry, recruit. Ye won't be turnin' anyone into a sheep permanently!", completion = "I think ye got the hang o' it. Cast Polymorph if ye get yerself in over yer head." }
WordHunterWoW_QuestEN[59355] = { title = "A Hunter's Trap", description = "By now, most hunters would have been trained in the art of trapping. Allow me to get you up to speed.\n\nWe'll start with a freezing trap. In order to make one, you'll have to forage materials from your surroundings.\n\nMeredy can provide you with a mote of ice. Scavenge the area for the rest of what is required.\n\nAnd don't delay. You will need that freezing trap to deal with a problem that has cropped up within the camp.", objectives = "Scavenge parts in the area to create a Freezing Trap.", progress = "Did you get the supplies needed? Meredy should have the ice mote, while the other two should be nearby.", completion = "With a little work, this can become a trap you can use. \n\nPart of being a <class> means making use of what your surroundings provide." }
WordHunterWoW_QuestEN[59356] = { title = "Hunting the Stalker", description = "Now that you have your trap, there's a problem we need to deal with.\n\nA wild beast has been stalking our camp. It's already stolen some of our food. We have little enough as it is.\n\nYou and I will work together. Set your freezing trap and lure out whatever this creature is.\n\nOnce it is caught, I will determine if the beast can be tamed... or if it needs to be put down.", objectives = "Use your Freezing Trap within the Ogre Ruins to lure out the beast stalking the camp.", progress = "Use the Freezing Trap anywhere within the Ogre Ruins. Just don't do it right within the camp.", completion = "Thank you for the help, <name>. I have one last lesson to impart--calling a different companion to your side.\n\nThere are plenty of wild beasts on this island. See which ones you can tame." }
WordHunterWoW_QuestEN[59426] = { title = "Your Personal Assistant", description = "Here in Hero's Rest, we have a beacon that is the fastest way to draw the Polemarch's attention.\n\nIt has been quite some time since we have used it, and I am afraid that it has fallen into disrepair.\n\nI authorize you to receive a steward companion during your stay here in Bastion.\n\nI will call for some to convene here. You may select one to aid you.", objectives = "Select a steward to aid you, then return to Kalisthene.", progress = "Stewards are the force that keep Bastion running.", completion = "Whenever you need assistance, your steward will be available to provide many services." }
WordHunterWoW_QuestEN[59427] = { title = "We Need More Power", description = "Laurent's plan is a bit ambitious. \n\nMirrors are most reliable when used to traverse short distances. Traveling to the sanctuary will require a great deal of power, more than he or I have. \n\nThe shrouded have stores of anima in their compound. With enough of it, the mirror should be stable enough to get us where we need to go.", objectives = "Collect anima from around The Shrouded Asylum.", progress = "Long distance travel requires a great deal of power.", completion = "Yes, this will do." }
WordHunterWoW_QuestEN[59430] = { title = "A Plague on Your House", description = "Though the physical House of Plagues is lost, the knowledge contained within was not. There are survivors here that continue to research and develop new horrifying weapons. \n\nIn time we will restore the house and rise to even greater power, unleashing creations and plagues never before seen upon our enemies!\n\nPerhaps you can help? Speak with survivors and see if any of them can use your aid.", objectives = "Speak with House of Plagues survivors.", progress = "Have you spoken to anyone?", completion = "Working together will benefit both of us greatly!" }
WordHunterWoW_QuestEN[59441] = { title = "Soulsmith Yol-Mattar", description = "", objectives = "" }
WordHunterWoW_QuestEN[59520] = { title = "Plaguefall: Knee Deep In It", description = "There are many in the House of Plagues who survived its destruction only to later fall victim to the plagues released in the explosion. Margrave Stradama herself was driven mad from a mixture of twelve different airborne poxes!\n\nThese dangers still remain and spread out from the ruins, infecting new victims daily.\n\nI need you to travel into the ruins and recover samples from the victims there.", objectives = "Enter Plaguefall and recover 12 Poxedskin Samples and Margrave Stradama's Plasm.", progress = "Have you brought me the Poxedskin Samples?", completion = "Working together will benefit both of us greatly!" }
WordHunterWoW_QuestEN[59554] = { title = "A Fine Journey", description = "Aspirants new and ancient, take note! The heralded Agthia's Repose calls.\n\nMake the ceremonial journey and learn about the ancient fallen Paragon who saved this very realm!\n\nFind the Repose just a short ride southwest of Hero's Rest.", objectives = "Speak to Keeper Mnemis in Agthia's Repose.", completion = "What brings you to our humble grounds?" }
WordHunterWoW_QuestEN[59555] = { title = "Enemy at the Door", description = "The remaining houses of Maldraxxus have joined forces against us. Their armies besiege the Seat of the Primus, and our defenses cannot hold forever.\n\nOur reserves have met the enemy in battle. I need you to break the siege.\n\nReport to Heirmir and Marileth. They will give you the means to rain destruction on our foes.", objectives = "Ride Ragewing and destroy the enemy forces.", completion = "The enemy is licking their wounds! Our troops will hold the line for now, but we should be prepared for more assaults." }
WordHunterWoW_QuestEN[59556] = { title = "Welcome To Our House", description = "Your ties to the other covenants had me doubting you would return. I see now that was foolish of me.\n\nOutsider or not, you have stood bravely beside the armies of Maldraxxus. I am confident the Primus would have welcomed you into our ranks with pride.\n\nOne day, he might return as well. But we cannot afford to wait. \n\nIn the Primus's absence, I will name you a Necrolord of Maldraxxus.", objectives = "Speak with Baroness Draka to be inducted as a Necrolord in the Maldraxxus covenant hall.", progress = "There is no greater honor than to defend the Shadowlands as a Necrolord of Maldraxxus.", completion = "This is our war to win, Maw Walker. It is now yours, as well." }
WordHunterWoW_QuestEN[59578] = { title = "Let's Get Ready to Humble", description = "", objectives = "" }
WordHunterWoW_QuestEN[59581] = { title = "The Strength of Sinfall", description = "", objectives = "" }
WordHunterWoW_QuestEN[59583] = { title = "Welcome to Stormwind", description = "Now that we are back in Stormwind, I need to deliver my mission report to King Wrynn.\n\nIn the meantime, I've asked Lindie to accompany you around the city. There's a lot to see and do in Stormwind, so feel free to explore at your leisure.\n\nI'll send for you once I've delivered my report to the king.", objectives = "Meet with Lindie Springstock at the city gate.", completion = "Hey, <name>! It's good to see you!\n\nCaptain Garrick asked me to show you around the city. I'm so excited!" }
WordHunterWoW_QuestEN[59585] = { title = "We'll Make an Aspirant Out of You", description = "", objectives = "" }
WordHunterWoW_QuestEN[59586] = { title = "What's Your Specialty?", description = "Hey, {name}! Have you decided on a combat specialization yet?\n\nSince you're a {class}, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class?\n\nChoosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use.\n\nLet's go speak with Dalgrun Steelpine to learn more about specializations!", objectives = "Speak with Dalgrun Steelpine to learn about combat specializations.", progress = "Greetings. Have you come to learn about combat specializations?", completion = "Excellent choice of specialization, <name>.\n\nFeel free to test out your new abilities on the training dummies outside." }
WordHunterWoW_QuestEN[59587] = { title = "What's Your Specialty?", description = "Hey, {name}! Have you decided on a combat specialization yet?\n\nSince you're a {class}, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class?\n\nChoosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use.\n\nLet's go speak with Frazzle Frostfingers to learn more about specializations!", objectives = "Speak with Frazzle Frostfingers to learn about combat specializations.", progress = "Greetings. Have you come to learn about combat specializations?", completion = "Excellent choice of specialization, <name>.\n\nFeel free to test out your new abilities on the training dummies outside." }
WordHunterWoW_QuestEN[59588] = { title = "What's Your Specialty?", description = "Hey, {name}! Have you decided on a combat specialization yet?\n\nSince you're a {class}, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class?\n\nChoosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use.\n\nLet's go speak with Juisheng Halfclaw to learn more about specializations!", objectives = "Speak with Juisheng Halfclaw to learn about combat specializations.", progress = "Greetings. Have you come to learn about combat specializations?", completion = "Excellent choice of specialization, <name>.\n\nFeel free to test out your new abilities on the training dummies outside." }
WordHunterWoW_QuestEN[59589] = { title = "What's Your Specialty?", description = "Hey, {name}! Have you decided on a combat specialization yet?\n\nSince you're a {class}, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class?\n\nChoosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use.\n\nLet's go speak with Ezul'aan to learn more about specializations!", objectives = "Speak with Ezul'aan to learn about combat specializations.", progress = "Greetings. Have you come to learn about combat specializations?", completion = "Excellent choice of specialization, <name>.\n\nFeel free to test out your new abilities on the training dummies outside." }
WordHunterWoW_QuestEN[59590] = { title = "What's Your Specialty?", description = "Hey, {name}! Have you decided on a combat specialization yet?\n\nSince you're a {class}, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class?\n\nChoosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use.\n\nLet's go speak with Patrice Lancaster to learn more about specializations!", objectives = "Speak with Patrice Lancaster to learn about combat specializations.", progress = "Greetings. Have you come to learn about combat specializations?", completion = "Excellent choice of specialization, <name>.\n\nFeel free to test out your new abilities on the training dummies outside." }
WordHunterWoW_QuestEN[59591] = { title = "What's Your Specialty?", description = "Hey, {name}! Have you decided on a combat specialization yet?\n\nSince you're a {class}, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class?\n\nChoosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use.\n\nLet's go speak with Veruca Darkstream to learn more about specializations!", objectives = "Speak with Veruca Darkstream to learn about combat specializations.", progress = "Greetings. Have you come to learn about combat specializations?", completion = "Excellent choice of specialization, <name>.\n\nFeel free to test out your new abilities on the training dummies outside." }
WordHunterWoW_QuestEN[59592] = { title = "What's Your Specialty?", description = "Hey, {name}! Have you decided on a combat specialization yet?\n\nSince you're a {class}, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class?\n\nChoosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use.\n\nLet's go speak with Mulric Boldrock to learn more about specializations!", objectives = "Speak with Mulric Boldrock to learn about combat specializations.", progress = "Greetings. Have you come to learn about combat specializations?", completion = "Excellent choice of specialization, <name>.\n\nFeel free to test out your new abilities on the training dummies outside." }
WordHunterWoW_QuestEN[59593] = { title = "What's Your Specialty?", description = "Hey, {name}! Have you decided on a combat specialization yet?\n\nSince you're a {class}, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class?\n\nChoosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use.\n\nLet's go speak with Laphandrus Voidheart to learn more about specializations!", objectives = "Speak with Laphandrus Voidheart to learn about combat specializations.", progress = "Greetings. Have you come to learn about combat specializations?", completion = "Excellent choice of specialization, <name>.\n\nFeel free to test out your new abilities on the training dummies outside." }
WordHunterWoW_QuestEN[59594] = { title = "What's Your Specialty?", description = "Hey, {name}! Have you decided on a combat specialization yet?\n\nSince you're a {class}, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class?\n\nChoosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use.\n\nLet's go speak with Kualiang Thunderfist to learn more about specializations!", objectives = "Speak with Kualiang Thunderfist to learn about combat specializations.", progress = "Greetings. Have you come to learn about combat specializations?", completion = "Excellent choice of specialization, <name>.\n\nFeel free to test out your new abilities on the training dummies outside." }
WordHunterWoW_QuestEN[59596] = { title = "Collective Soul", description = "Souls in Maldraxxus are bound together in war. We draw strength and wisdom from those around us.\n\nShould you fall in battle, part of you would remain with your fellow soldiers. Just as they would remain with you. \n\nPlague Deviser Marileth has volunteered to teach you the process of soulbinding. From what I have seen, yours will be a powerful bond.", objectives = "Speak with Plague Deviser Marileth about the soulbinding process.", completion = "I'm so pleased to see you again, my apprentice!" }
WordHunterWoW_QuestEN[59597] = { title = "Come On, We're Simpatico!", description = "Soulbinding is a wondrous process! I invite you to bind with me to learn how it works, but in time you might bind with others. \n\nI have known many soulbinds, but the foremost of them all was Margrave Stradama! Her knowledge, talent and kindness became part of who I am. Now and forever, it is a bond we share.\n\nI only hope to be so useful to you, my apprentice! Bound together, I shall grant you all I can and aid you even when we are apart.", objectives = "Complete the soulbinding ritual with Plague Deviser Marileth.", completion = "Our shared knowledge will benefit all of Maldraxxus." }
WordHunterWoW_QuestEN[59598] = { title = "Good for the Soul", description = "Two souls are better than one! We can achieve far greater things together than we can if we were alone.\n\nHowever, it is not just the two of us against all threats. There are many more that will aid us in the coming battles.\n\nLet's speak with Merick to learn more on the subject. Don't be shy--I can introduce you!", objectives = "Speak with Merick.Two souls are better than one! We can achieve far greater things together than we can if we were alone.\n\nHowever, it is not just the two of us against all threats. There are many more that will aid us in the coming battles.\n\nLet's speak with Merick to learn more on the subject. Don't be shy--I can introduce you!You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[59599] = { title = "Retaining the Court", description = "", objectives = "" }
WordHunterWoW_QuestEN[59600] = { title = "Rotbriar Trouble", description = "", objectives = "" }
WordHunterWoW_QuestEN[59601] = { title = "Assault on the Vestibule", description = "", objectives = "" }
WordHunterWoW_QuestEN[59603] = { title = "In Shadowlands Service", description = "As Maldraxxi, we are responsible for ensuring the security of the Shadowlands. \n\nWhen enemies emerge, we are the ones who face them!\n\nThe threats to the Shadowlands are far more than any one of us can handle. That's where I come in.\n\nI will be your eyes on the field. Allow me to demonstrate with a simple task for Marileth, so that you may both reap the benefits of my services.", objectives = "Use the Command Table to send Marileth on an adventure.", progress = "An easy task to complete.", completion = "And so, it is as if you had led the battle personally! Impressive work, if I do say so myself." }
WordHunterWoW_QuestEN[59604] = { title = "Takin' Down the Beast", description = "", objectives = "" }
WordHunterWoW_QuestEN[59605] = { title = "Takin' Down the Beast", description = "", objectives = "" }
WordHunterWoW_QuestEN[59607] = { title = "Takin' Down the Beast", description = "", objectives = "Bad bat gon' get smashed! Need ammo! Ammo in Dredhollow!", progress = "Bad bat gon' get smashed! Need ammo! Ammo in Dredhollow!", completion = "Haha! Smash time!" }
WordHunterWoW_QuestEN[59609] = { title = "No Rest For the Dead", description = "Excellent work, my apprentice! You have completed your training and are now a true Necrolord.\n\nThat also means you've taken on additional responsibilities. Such is the burden of genius!\n\nI believe Baroness Draka wanted to have a word with you.", objectives = "Report to Baroness Draka.", completion = "I hope you're settled--there's no rest for the weary in Maldraxxus." }
WordHunterWoW_QuestEN[59615] = { title = "Every Dog Has Its Day", description = "Maw Walker, when I heard you were building constructs and a home for souls still loyal to Maldraxxus, I began my search for you!\n\nI am loyal and have always wanted a construct form, but the Margrave was unwilling to build one that suited my natural inclinations.  \n\nI lived my whole life with the curse, it's all I know, and it's all I still want.\n\nWould you build a construct for me?", objectives = "Take specifications for Neena's construct.", progress = "Are you willing to do this?", completion = "I know this soul, she is strong and very loyal. We would be well aided by building this most unusual construct." }
WordHunterWoW_QuestEN[59616] = { title = "Army of One", description = "Mevix will lead the attack, but you will finish it. There are no reinforcements, no cavalry.\n\nOnly you and your runeblade.\n\nShow me the might you wield, outsider. Lay siege to the House of Constructs and bring them to ruin!", objectives = "Meet Secutor Mevix near the House of Constructs.", completion = "Your voice... you are not one of the Maldraxxi?" }
WordHunterWoW_QuestEN[59617] = { title = "Stone Fiend Saboteurs", description = "", objectives = "" }
WordHunterWoW_QuestEN[59621] = { title = "Breaking a Few Eggs", description = "As you can see, we have a gorm problem.\n\nI'm not sure what has them so riled up. They've been getting bigger, more hostile. It must be due to the anima drought. If nothing stops them, they'll eat everything!\n\nTheir egg production is out of control. We can't let their population grow any larger. Please, go in to their nests and destroy as many of their eggs as you can find.", objectives = "Destroy 10 Gorm Eggs in the Banks of Life.", completion = "This should hopefully curtail their numbers. Thank you for your help." }
WordHunterWoW_QuestEN[59622] = { title = "Tending to the Tenders", description = "The eggs are a problem, but so are the gorm that take care of them.\n\nThe egg-tenders are the leaders of the hive when no matriarch is present. If left unchecked, they will simply produce more eggs and we will be right back where we started. Or worse, one of them could turn into a queen. \n\nThey are simply too large and hostile for us to properly contain. I see no other recourse than to put them down.", objectives = "Slay Egg-Tenders Tiom, Bloome and Erys.", completion = "The population will produce more tenders eventually. You have bought us valuable time." }
WordHunterWoW_QuestEN[59623] = { title = "What a Buzzkill", description = "What do you say? Fancy one more hunt?\n\nOne of those little flying pests has grown into a very large flying pest. Large, pristine gorm parts are hard to find in the best of times, and a smith always appreciates a challenge.\n\n<Cavina's voice drops as he leans in towards you.> Besides, I'm worried about the safety of my family and the rest of us in the grove.\n\nBring me the stinger from that big fella and I'll make it worth your while.\n\nDo we have a deal?", objectives = "Deliver Buzzkill's Stinger to Gormsmith Cavina.", progress = "I must say, I am looking forward to the opportunity to working with such a fine specimen.", completion = "Yeah, this is good gorm right here. I'll make you something special from it." }
WordHunterWoW_QuestEN[59625] = { title = "The Only Cure", description = "Maldraxxus is on the path to reclaiming its rightful role as defender of the Shadowlands. But the treasonous attack on Bastion remains a stain on our honor.\n\nWe had thought Gharmal's forces routed, but we've received word from the Paragon of Courage that reinforcements have begun arriving at her temple.\n\nThis threat must be eliminated.\n\nI have volunteered to spearhead this operation. Your support would be an asset, {name}.", objectives = "Meet with the Paragon of Courage in Bastion.", completion = "Your arrival is expected. We await results." }
WordHunterWoW_QuestEN[59641] = { title = "The Nation of Kul Tiras", description = "Kul Tiras is the greatest naval power on Azeroth, and a former member of the Alliance. But we've had little contact with them since Jaina's father, Lord Admiral Daelin Proudmoore, was killed at Theramore.\n\nMany have said that Jaina believed so deeply in the promise of peace between the Alliance and Horde that she betrayed her own father on that day. Perhaps she feels it is time to put the past to rest.\n\nLoathe as I am to put Jaina at risk... Kul Tiras must rejoin the Alliance.\n\nLight be with you.", objectives = "Speak with Lady Jaina Proudmoore in Stormwind Harbor.", completion = "Home again, after all this time." }
WordHunterWoW_QuestEN[59642] = { title = "Pulling Hairs", description = "The abominations are well organized and well supplied. We've not been able to gain any ground.\n\nA little disorganization in their supplies and reinforcements might give us an edge.\n\nI need you to work you way behind their lines and eliminate three abominations handling their supplies.Upon completion of this quest you will gain:", objectives = "Eliminate Strategist Orco, Lobber Jalrax, and Munitioner Vizic" }
WordHunterWoW_QuestEN[59643] = { title = "It's Race Day in the Ramparts!", description = "", objectives = "" }
WordHunterWoW_QuestEN[59644] = { title = "Blinded By The Light", description = "{name}, Sire Denathrius must be stopped. The anima he is stealing from the Shadowlands is weakening the bonds that seal the Jailer within the Maw. That must not happen.\n\nTime is short so we must strike quickly. I would like for you to head up to the surface, into that accursed Light, and align as many mirrors as you can find to the focusing mirror atop the portcullis.\n\nWe will shine a light on Castle Nathria so bright no venthyr will wish to step forth from that fortress to challenge us.", objectives = "Use the mirrors atop Sinfall to seal the gates of Castle Nathria.", progress = "Hopefully you did not get too scorched out there.", completion = "That should buy us some time and carve us a bit of a path. Now to take advantage of the situation." }
WordHunterWoW_QuestEN[59645] = { title = "Death Rains", description = "With its repeated invasions here, the House of Constructs continues to sully the honor of Maldraxxus.\n\nWe cannot salvage that honor until justice is done. May we mete it so thoroughly that none will ever attempt this desecration again.\n\nEliminate these traitors with me, {name}. Leave none standing.", objectives = "Slay 30 enemy forces.", progress = "See justice done.", completion = "Our will is done." }
WordHunterWoW_QuestEN[59648] = { title = "Peace by Piece", description = "These Maldraxxi fiends have reoccupied my temple. They have entrenched this resurgence with shields powered by necromancy.\n\nMy disciples--the ones who were not captured and executed by your treacherous compatriots--report the core of a necrotic bulwark to the south. We cannot counter their forces until the shield is brought down.\n\nSee it done. I will not tolerate your presence otherwise.", objectives = "Disable the Necrotic Bulwark in the South.", progress = "Do not keep me waiting.", completion = "We have only just begun." }
WordHunterWoW_QuestEN[59650] = { title = "No Hesitation, No Surrender", description = "I cannot fathom where the constructs acquired these reinforcements, but we are once again outnumbered. I seethe at the thought of my fallen disciples.\n\nYou will make this right.\n\nThe renegades have established a foothold in the northern region of the temple. Their necrotic magic has granted them a shield, defending them from ranged assault. Disable it.\n\nLet nothing impede you. This is the way of Courage.", objectives = "Disable the Northern Bulwark.", completion = "This will begin to set things right." }
WordHunterWoW_QuestEN[59653] = { title = "Don't Cross Courage", description = "We have rendered the enemy holdouts defenseless. My disciples will begin preparations to purge the corruption that your errant kind have left on our home.\n\nBut more still remain in the inner sanctum of the temple. Their defenses prevent us from flying in en masse, but I can secure a foothold myself. We will cross the breach and annihilate them.", objectives = "Cross the breach with Xandria.", progress = "We shall not waste time.", completion = "This is as close as I can take you. Make it count." }
WordHunterWoW_QuestEN[59656] = { title = "Well, Tell the Lady", description = "<Thorodir breathes a deep sigh of relief.>\n\nThat's that, I'd say. The Banks are largely safe now, thanks to you. We can handle the rest of the cleanup on our own now.\n\nThe Lady of the Falls will want to hear of your success here. Why not go tell her the good news?", objectives = "Report to the Lady of the Falls in Glitterfall Basin.", completion = "Ah, that is wonderful news. Thank you for your assistance." }
WordHunterWoW_QuestEN[59658] = { title = "Express Dominance", description = "", objectives = "" }
WordHunterWoW_QuestEN[59659] = { title = "Aerial Absolution", description = "My kyrian would have attempted to retaliate by now, but these vile interlopers are a devious sort.\n\nTheir necromancers pollute the air, tainting it with foul power that corrodes our very wings.\n\nI cannot advance an assault until they are eradicated. Deal with these befoulers, and I will deliver retribution to the rest.", objectives = "Slay the three befoulers.", completion = "Now we are ready." }
WordHunterWoW_QuestEN[59660] = { title = "A New Court", description = "My dear {name}, I have heard a delightful rumor that you are considering hosting a new court in Sinfall.\n\nIf that is true, you simply must permit me to recommend staff to help you host a perfect court.\n\n<Theotar pulls long parchments out of his pockets.>\n\nI have been developing ranked lists for every court staff position since the moment I stepped foot in Sinfall.\n\nI do not wish to be a braggart, but courts are kind of my specialty.", objectives = "Recruit the personnel needed to open the Ember Court.", completion = "This court isn't going to throw itself. Let's get to work!" }
WordHunterWoW_QuestEN[59661] = { title = "Ember Court Rehearsal", description = "Look, {name}. Venthyr have been throwing fancy courts for themselves ever since they were created.\n\nIt won't always be easy to impress them with our own court.\n\nDon't worry, I've got a plan.\n\nI've scheduled a rehearsal court for us to learn the ropes during a practice run.\n\nYou, me, Renathal, and a few socialites from the covenant who are eager to help us succeed.\n\nRelax. It'll be fun!", objectives = "Help Temel host the rehearsal for the Ember Court.", completion = "That went surprisingly well, all things considered. You and I have a real knack for this party-planning stuff.\n\nWe're ready to prepare our first real Ember Court!" }
WordHunterWoW_QuestEN[59674] = { title = "A Friendly Rivalry", description = "Ah, a fresh soul! Your perspective may prove useful to us.\n\nNemea and I have opposing viewpoints. She lauds her larion, creatures native to Bastion whom she raises and trains as her companions.\n\nHowever, I find that phalynx are the superior beings. They are efficient, obedient, and easy to work with.\n\nPlease, come learn both of our ways. Perhaps you can decide which of our ways of life is superior.", objectives = "Meet with Pelodis at Forgefire Outpost or Nemea at Nemea's Retreat.", completion = "I am honored that you came to me first. Allow me to show you my ways." }
WordHunterWoW_QuestEN[59676] = { title = "Harvester of Desire", description = "So, here's the sketch: we muck you up to look like one of the servants. This stuff is protected by anti-theft so if 'em clothes think they are being stolen they teleport back here, you an' all.\n\nYou \"should\" be able to reach the Countess with your message. Just smile, nod, do as you're told, don't talk to anyone, and don't make eye contact with anything that's got wings. They'll know you shouldn't be there.", objectives = "Infiltrate the Eternal Terrace and deliver Prince Renathal's message to the Countess.", progress = "Still got your head at least. They often try to take that first if they are mad at ya.", completion = "Ah, the Countess. Mistress of the court. Always assume she is never alone, and always capable of great treachery.\n\nMmm... treachery..." }
WordHunterWoW_QuestEN[59678] = { title = "Sustain, In Vain", description = "These turncoats have kept busy. They've opened more portals around the area, allowing themselves to replenish their numbers with little trouble.\n\nEven with her might, the Paragon cannot eliminate an endless army. Let us destroy these portals. Without reinforcements to sustain this contingent, it will surely fall.", objectives = "Disable 6 Necrotic Portals.", progress = "The time for mercy is behind us.", completion = "No longer can they sustain themselves. Good work." }
WordHunterWoW_QuestEN[59680] = { title = "Vesiphone's Vicious Vesper", description = "", objectives = "" }
WordHunterWoW_QuestEN[59698] = { title = "Wipe the Slate Clean", description = "At last, the skies belong to us once more... and in those skies, the storm of our vengeance brews.\n\nCome, you who claim to be true Maldraxxi. You wish to right the wrongs of those you once called allies?\n\nRain your justice upon them! Show no quarter!", objectives = "Fly with Xandria and slay Maldraxxi.", completion = "For Courage!" }
WordHunterWoW_QuestEN[59700] = { title = "The Last Labor", description = "The evil that threatens Bastion crumbles beneath us. But if we allow this cruel baroness to evade justice, we have not won this day.\n\nShe cowers in the necropolis above, casting her shadow on this once sacred temple.\n\nWe will pull the dagger from our backs. This wound will heal.", objectives = "Slay Baroness Antolyte.", progress = "This is all that remains.", completion = "May her memory fade from this place." }
WordHunterWoW_QuestEN[59701] = { title = "Common Ground", description = "Now that we have a stronghold from which to operate, we need to begin the next stage of my plan to wrest control of Revendreth from the Master.\n\nWe must convince the Court of Harvesters to convene. We must not have them come here, though. It would be suicide.\n\nGo to my old fortress, Darkwall Tower, and place these banners at the four most distant points of the tower. This will ensure the power of the Harvesters and the Master will not be able to interfere with a neutral meeting.", objectives = "Place four of Renathal's Banners at Darkwall Tower.", completion = "They may look like simple banners, but with the right words and a few appropriate spells, they turn this place into a temporary sanctuary." }
WordHunterWoW_QuestEN[59703] = { title = "Abombing Run", description = "", objectives = "" }
WordHunterWoW_QuestEN[59705] = { title = "Things Remembered", description = "", objectives = "" }
WordHunterWoW_QuestEN[59706] = { title = "Invitation for the Countess", description = "The Countess, Harvester of Desire.\n\nHer wits are sharper than most swords. While I have never seen her carry a weapon, you must assume she is never unprotected.\n\nHer mansion mirrors my own, on the Northeastern side of Castle Nathria. Her dominion was that of the Castle Ward, and it is her authority that keeps the nobles in line.\n\nShe will appreciate a secret message. I will send a dredger ahead with a plan to infiltrate her party. Meet him on the Bridge of Temptation. Good luck.", objectives = "Find Cudgelface on the Bridge of Temptation leading to the Eternal Terrace.", completion = "Glad you got here before 'em patrols. I ain't got a permit to park here." }
WordHunterWoW_QuestEN[59707] = { title = "Invitation for the Tithelord", description = "The Tithelord is a bully and a coward, just like every Harvester of Envy before him.\n\nHe is still a force beyond our current reckoning. I have sent Nadjia and Temel to Pridefall Hamlet in the south to ascertain the best, most non-lethal way to reach the Tithelord.\n\nMeet them there and use caution. The Tithelord would kill you in less than the blink of an eye if he thought it would gain him more power or authority.", objectives = "Speak with Nadjia the Mistblade at Pridefall Hamlet.", completion = "Ready to fall with grace?" }
WordHunterWoW_QuestEN[59708] = { title = "Invitation for the Stonewright", description = "The Medallion of Wrath is in the hands of the Stonewright. She is ancient, powerful, and responsible for creating the Stone Legion.\n\nShe is not someone to be subtle with. It is a very dangerous thing to ask, but would you meet with General Draven at the Dominance Gate? \n\nIf we are to see the Stonewright attend, she must know the severity of our request, which means both you and Draven walking right in the front door.", objectives = "Speak with General Draven at the Dominance Gate.", completion = "This will not be an easy day." }
WordHunterWoW_QuestEN[59709] = { title = "Afterlife Goes On", description = "A new dawn shines on Bastion. I had my reservations, but you have proven that honor yet remains in Maldraxxus.\n\nTake my hand once more. I will return you to the temple's entrance.\n\nLet all Maldraxxi know of our victory. And for the sake of peace, ensure that this never happens again.", objectives = "Fly with Xandria to the entrance of the Temple of Courage.", completion = "May our paths cross again." }
WordHunterWoW_QuestEN[59710] = { title = "A Curious Invitation", description = "Psst. You there. Yeah, you.\n\nYou that Maw Walker them fangs been going on about? Huh. I figured you'd be bigger.\n\nAnyway, the Taskmaster wants to ahhh ... \"extend his compliments and an invitation to visit his workings.\" That's a fancy word for a bunch of rocks me and my mates are diggin' up.\n\nIf you're keen an' all that, pop down to Feeder's Thicket and meet with the fang's courier, Araak. He'll get you sorted right out.", objectives = "Meet with Courier Araak.", progress = "The Taskmaster don't like waiting.", completion = "Well, looks like the master just left. What timing." }
WordHunterWoW_QuestEN[59711] = { title = "Harvester of Envy", description = "Thank you for meeting us at a minimum safe distance from the Caretaker's Manor. There are enough people around here that may still find the idea of me in a cage to be worth the trouble.\n\nIt is too dangerous for you or I to speak to the Tithelord. He is too impulsive and eager to please Denathrius. I recommend we send Temel. \n\nThe stone fiend is a common messenger for Revendreth and few aside from a handful of observers will bat an eye at his arrival. Just shove him when you are ready.", objectives = "Guide Temel through the Caretaker's Manor and deliver Prince Renathal's message to the Tithelord.", completion = "The Tithelord. I believe he is the two hundred and seventy fifth Caretaker to lord over the Village Ward. \n\nHe is as dangerously ambitious as every Harvester of Envy before him, and will help only if he believes he stands to gain more power." }
WordHunterWoW_QuestEN[59712] = { title = "The Lay of the Land", description = "So, yeah, not sure why he wants you. Based on a long time working for him, I'm gonna say he wants to use you to do something unsavory to further his interests. But, I'm biased. I could tell you so many stories.\n\nLet's go check on my friend, Nadjia.", objectives = "Check on Nadjia and investigate Taskmaster Matyas's camp.", progress = "Have you found Taskmaster Matyas's journal yet?", completion = "Appreciate you helping my friend. Keep this up and I'll be in your debt." }
WordHunterWoW_QuestEN[59713] = { title = "Active Ingredients", description = "Matyas will be difficult to handle until we can take my sinstone from him. We need something to knock him out. \n\nWill you fetch a few ingredients for me, mortal? I have a cunning plan.", objectives = "Gather ingredients for Nadjia's mixture.", progress = "Do you have the ingredients?", completion = "This should be enough to knock him out for long enough to take my sinstone." }
WordHunterWoW_QuestEN[59714] = { title = "A Fine Vintage", description = "We will need something special to use as the base of our mixture. To get him to drink it down he will have to believe you've brought him a gift. \n\nHe fancies himself quite the connoisseur. Some ancient and stuffy vintage will tempt him.\n\nCheck the old cellar near the ruins. It once held supplies. Perhaps a bottle still lingers in the depths. Araak and I will work out the other details.", objectives = "Bring Nadjia a fancy beverage.", progress = "Have you found a suitable beverage?", completion = "Ah, that's perfect. He will not be able to resist this." }
WordHunterWoW_QuestEN[59715] = { title = "Message for Matyas", description = "Alright. Everything is prepared. When you are ready, ask Courier Araak to summon Taskmaster Matyas as though you have just arrived.\n\nI am sure a gift of a favorite drink will tempt him and the poison we've concocted will incapacitate him long enough to take my sinstone from him.\n\nOur plan will work flawlessly!", objectives = "Summon Taskmaster Matyas back to camp.", completion = "Ah, the Maw Walker! I have heard so much about you." }
WordHunterWoW_QuestEN[59716] = { title = "Comfortably Numb", description = "A mortal in Revendreth. It's rumored that you can traverse the Maw? Astonishing. I have so many questions.\n\nBut, I must restrain my curiosity. I have a ... shall we say ... proposition for you that I feel would be advantageous for us both. If it is true that you are able to freely travel these lands then you have access to certain information I cannot reach. \n\nYou see how you could be useful to me? Come, let us discuss the matter further.", objectives = "Poison the Taskmaster to get Nadjia's sinstone.", progress = "My sinstone, please.", completion = "Oh, well done! I had a moment there when you drank the poison that I feared for you. But you're a hearty sort." }
WordHunterWoW_QuestEN[59717] = { title = "Things Remembered", description = "", objectives = "" }
WordHunterWoW_QuestEN[59718] = { title = "Parasol Peril", description = "", objectives = "" }
WordHunterWoW_QuestEN[59719] = { title = "The Court", description = "Well, we have quorum. You have done all you can do for us at this stage, Maw Walker.\n\nIt falls to me, now, to convince these ancient fools to forsake the greatest patron in all of their reality and throw their lot in with me, a failed rebel with a \"new\" plan.\n\nLet us see if I can still sway a crowd, as it were. Wish me luck.", objectives = "Witness the Court of Harvesters gathering.", completion = "Well, that could have gone better. I did not expect them to come around right away, but I had hoped at least one or two of them might.\n\nNow we must do it the hard way. We should leave before they send forces to re-capture this tower." }
WordHunterWoW_QuestEN[59720] = { title = "Harvester of Wrath", description = "We walk in the winged shadows of my brothers and sisters in arms, Stoneborn I have trained since they were first carved from stone.\n\nThis is an ancient rite. If we cross this bridge on foot, defeating any who would dare stop us, we may have an audience with the mother of the stoneborn. However, know that our safe return is not guaranteed, so try not to offend her.\n\nI do not look forward to this.", objectives = "Cross the Bridge of Defiance on foot.", completion = "I remember when the first stoneborn moved with the breath of anima infused by the Stonewright. \n\nNever, ever, confuse her sympathy for her creations as a weakness. She holds the Medallion of Wrath for a reason." }
WordHunterWoW_QuestEN[59721] = { title = "Becoming the Hunt", description = "<Reldorn grins at you.>\n\nHe knew you'd be back! The Horned Hunter went on ahead to prepare the hunting ground. He said you should join him as soon as you can. \n\nNow that you have the materials for the trap, you just need to reach him...\n\nIt's dangerous territory to traverse, but I've been devising a glamour that should help you avoid the attention of the roaming beasts. Maybe if it's useful, you could put in a good word for...\n\nAhem. Anyway, we should focus on your quarry. Good hunting, friend.", objectives = "Find Huln Highmountain within the Elder Stand.", completion = "You are just in time. My preparations are nearly complete." }
WordHunterWoW_QuestEN[59722] = { title = "Grand Theft Necropolis", description = "The necropolis is safe and secure, but we can only maintain a portal to the Seat of the Primus for a short time.\n\nKhaliiq will return with you and work on establishing a permanent portal connection.", objectives = "Use the portal to meet Khaliiq in the Seat of the Primus.", completion = "It's like we were never gone." }
WordHunterWoW_QuestEN[59724] = { title = "The Field of Honor", description = "Thanks to you, {name}, I am free of Matyas's control for the first time in ... well, a very long time. \n\nNow, together, we will seek my vengeance. \n\nI've laid a solemn duty upon you by naming you as my second for this duel. I know not the code in your homelands but in mine, it is your task to secure the field. Matyas and his followers are garrisoned at Witherfall Ruin nearby. Unless I miss my guess, that's where he will have run.\n\nI will prepare for the battle and join you soon.", objectives = "Clear Taskmaster Matyas's followers from Witherfall Ruins.", completion = "Well, he's certainly chosen a scenic location for a fight." }
WordHunterWoW_QuestEN[59725] = { title = "Archivist on the Edge", description = "If the curse isn't removed, Qadarin will waste away until nothing is left! \n\nWe used to bind and seal curses just like this all the time, but we haven't had to deal with one in ages. \n\nGo to Archivist Dreyden at the Grove of Memory. He will know which curse this is and can give you its scroll. \n\nBring it back so we can figure out what we need in order to cast a counter-curse.\n\nHurry, {name}!", objectives = "Speak with Archivist Dreyden at the Grove of Memory.", completion = "Please tell me you are here to help with the spriggan problem!" }
WordHunterWoW_QuestEN[59726] = { title = "It's a Trap", description = "At last, I will have my vengeance!\n\nI am certain Matyas will flee again if he sees me first so you will need to confront him on my behalf, friend. Then, while he's distracted, I will engage him.\n\nAt that point, your obligation as my second is a formality. You must assure Matyas does not dishonor the duel and cheat. When he inevitably does, I expect you'll help me defeat him.\n\nHe's just through the portcullis there.", objectives = "Approach Matyas to start the duel. Assist Nadjia when Matyas cheats.", progress = "Matyas will apologize, or he will die.", completion = "I would have allowed an apology, but he chose treachery and has paid the price." }
WordHunterWoW_QuestEN[59731] = { title = "An Expected Guest", description = "While we await word from Huln, another matter of importance has arisen.\n\nBwonsamdi has returned to Ardenweald. Lord Herne believes he is here to request an audience with the Winter Queen.\n\nThe loa of death, however, pursues a different purpose. One that I have glimpsed in my dreams.\n\nMeet with Bwonsamdi. Discover what fate has in store for the both of you.", objectives = "Meet Bwonsamdi in the Heart of the Forest within Ardenweald.", completion = "Ol' Bwonsamdi knew ya gonna come see me. I got someting ya wanna hear..." }
WordHunterWoW_QuestEN[59732] = { title = "Something Extra for the Winter Queen", description = "Ya did good wit' how ya handled Mueh'zala. Me be wantin' ta return da favor. We be friends, after all... riiiight?\n\nDat nasty loa be at me mercy now. Him been mutterin' about some tings he stole from ya Winter Queen. \n\nCome along ta me Necropolis. Ya can see what Ol' Bwonsamdi be talkin' about for yaself.\n\nYa gonna come back with someting nice for her majesty... reeeeeal nice.", objectives = "Travel with Bwonsamdi to the Necropolis in Nazmir.", completion = "While ya be here, why not help clean up some of da trash outside me Necropolis? For old time's sake, eh?\n\nDen we can be dealin' wit Mueh'zala." }
WordHunterWoW_QuestEN[59739] = { title = "The Problem with Containing a Death Loa", description = "Me know Mueh'zala still be hidin' someting. Ol' Bwonsamdi gonna find out what dat be.\n\nBut dis old loa's presence be drawin' all da undead in Nazmir ta me doorstep!\n\nMe be needin' some time ta get Mueh'zala talkin'. \n\nDere be a troll, Zel'han, leadin' da undead. Kill him and show Mueh'zala him broken armor.\n\nDat should end any hope he be havin' of escapin'.", objectives = "Kill Zel'han the Betrayer and recover his armor.", progress = "Zel'han be marchin' in here wit ya head. Me gonna enjoy seein' ya soul tortured in da Maw.", completion = "Me got plans older dan you, <race>. Slaying Zel'han mean noting ta me... ya understand?" }
WordHunterWoW_QuestEN[59740] = { title = "Repair and Restore", description = "You've already attuned several mirrors without incident. I do believe it's time you try your hand at repairing them instead.\n\nIt's quite easy once you've found the fragments, but there are a few things of note to keep in mind. \n\nRepaired mirrors are fragile and unpredictable. They often break with a single use, and it's never a guarantee that using one will translocate you somewhere safe. \n\nHere's a few shards to get you started. \n\nRestore the mirror to working order and see where it leads.", objectives = "Repair the Broken Mirror and reap the rewards.", progress = "I have complete faith in your abilities.", completion = "You found a boon? Well done! One never truly knows what awaits beyond the mirror." }
WordHunterWoW_QuestEN[59741] = { title = "Dark Mojo for a Dark Loa", description = "How many times must de Necropolis come under attack? I suppose no one ever said worshipping Bwonsamdi would be easy...\n\nBwonsamdi seeks to force Mueh'zala into revealing his secrets, and I must do my part to help.\n\nDe undead swarming de Necropolis are animated by Mueh'zala's dark mojo. \n\nBwonsamdi needs some of dat mojo to finish his ritual. Strike down de undead and claim it.", objectives = "Recover 100 Dark Mojo from undead attacking the Necropolis.", progress = "You got me dat mojo? I be usin' it ta control Mueh'zala durin' me ritual.", completion = "Look at all dis mojo! Dis be just what me need ta make little Mueh'zala talk.\n\nDon't ya be worryin' about da other undead out dere. Ol' Bwonsamdi got a plan for dem." }
WordHunterWoW_QuestEN[59742] = { title = "Delaying the Other Side", description = "Many of Bwonsamdi's worshippers did not make it inside when de undead began swarming de Necropolis.\n\nWe need a few more of dem to complete Bwonsamdi's ritual to uncover Mueh'zala's plans.\n\nTake dis powder and throw it on de worshippers who are stuck outside. It should dispel de dark magic dat afflicts dem.\n\nAs for de ones who are already dead... dey will serve Bwonsamdi beyond de grave. Dat is all we could ever ask for.", objectives = "Use Strange Powder on 6 Injured Bwonsamdi Worshippers.", completion = "Ah good, ya got me all da livin' souls I be needin'.\n\nDon't ya be worryin' about da ones who passed on. Ol' Bwonsamdi not lettin' dem go to da Maw." }
WordHunterWoW_QuestEN[59743] = { title = "The Spider on the Wall", description = "", objectives = "" }
WordHunterWoW_QuestEN[59747] = { title = "A Lost Soul", description = "Many of us struggled to free ourselves when Gharmal imprisoned our souls here, but none more than Bacilia.\n\nShe was a great champion, but the confinement drove her mad and darkness consumed her soul. Though we tried to reason with her over the course of eons, it is clear that there is no coming back for her.\n\nPlease end her misery.", objectives = "Bacilia the Lost slain.", progress = "Have you completed this task?", completion = "I sense that her suffering has ended." }
WordHunterWoW_QuestEN[59748] = { title = "No Peace In Death", description = "{name}. I have a favor to ask, if I may.\n\nThis realm... The sense of honor and purpose that guides its denizens calls to me. \n\nMy life was defined by such values. Maldraxxus, for a time, shared them with me... But I returned from the Maw to a land rife with treachery.\n\nI'd like to speak with the Paragon about Bastion.", objectives = "Talk to the Paragon of Courage with Alexandros.", completion = "Come. There is much to show you." }
WordHunterWoW_QuestEN[59749] = { title = "One Little Whisper", description = "Here be da deal, {name}. To get  Mueh'zala talkin', we gotta feed him a teeny bit a da life essence of everybody in dis room.\n\nWhy ya be lookin' at me like dat? When has ol' Bwonsamdi ever let ya down?\n\nMe gonna use da mojo ya got to pull da truth outta him while he be feedin'.\n\nOh, uh, just two more tings. First, I need ya to be ringin' an invitation to a special... friend.\n\nDen I be giving ya more of me mojo powder. Use it during da ritual if any o' me followers be gettin' too weak.", objectives = "Ring the gong to summon the special guest, then use mojo powder in the ritual to fuel Mueh'zala.", progress = "I be eager to hear what ol' Mueh'zala be have ta say...", completion = "Dere be one loa o' death, <name>. And it be ol' Bwonsamdi. \n\nYa best not forget dat." }
WordHunterWoW_QuestEN[59750] = { title = "How to Get a Head", description = "An eager rookie who wants to be champion of the arena? People love a story like yours, but the first step is to get you noticed. \n\nHere's the plan. Marcel Mullby needs bloodtusk skulls, but it takes a real fighter to get those!\n\nYou go kill some bloodtusks, use my knife to collect their heads, and deliver them to Mullby. That should get you recognition.", objectives = "Collect 12 Bloodtusk Skulls and deliver them to Marcel Mullby.", progress = "You deliver those skulls?", completion = "Good work, you're getting some recognition. I hear people talking about how you killed all those bloodtusks!" }
WordHunterWoW_QuestEN[59751] = { title = "Through the Shattered Sky", description = "When Sylvanas shattered the Helm of Domination, she was touched by the power it released.\n\nI can sense the echoes of that power, and I know where she has gone.\n\nIf you wish to rescue your leaders, the shattered helm can open a path. It cannot bring you back, however. That you must do on your own.\n\nThe risk is great, {name}, but there is no other way. We will begin the ritual at once.", objectives = "Complete the ritual at the Frozen Throne to open the rift into the Maw.", completion = "Not the most ideal of arrivals, but at least we are still in one piece.\n\nI have not seen any sign of Tyrande. Either she landed elsewhere or continued on without us. We should keep an eye out." }
WordHunterWoW_QuestEN[59752] = { title = "A Fractured Blade", description = "The chaotic energies of this place have scattered the Ebon Blade. \n\nI don't think Azeroth's blessings will reach you here, {class}. We will need allies if we are to survive this place.\n\nWe should find them quickly, before they are overcome.", objectives = "Rally 10 Knights of the Ebon Blade in the Crucible of the Damned.", progress = "We have no time for chatter. Let's find those knights!", completion = "We've been in this place mere moments and already our forces are depleted. It will have to do.\n\nTake this horn. It can be used to call upon the remaining Ebon Blade forces to rally against your foes." }
WordHunterWoW_QuestEN[59753] = { title = "Ruiner's End", description = "One of the... larger fiends... has several of our knights engaged...\n\nHurry to their aid... lest we lose more of our dwindling forces.\n\nGo... it is too late for me...", objectives = "Defeat Ruiner Maroth in the Crucible of the Damned.", progress = "Our allies fall as you stand idle.", completion = "I am loath to leave some of our knights behind, but it is obvious we cannot stand against such foes. \n\nWe must make sure their sacrifices are not in vain." }
WordHunterWoW_QuestEN[59754] = { title = "On Blackened Wings", description = "It's a relief to see friendly faces again. But we have little time for pleasantries.\n\nThrall is wounded, and we are being hunted by the denizens of this realm. We must seek shelter at once.\n\nCome, I believe I know of a place.", objectives = "Assist Jaina in escaping the Mawsworn in Calcis.", progress = "What are you doing? This is no time for talk!", completion = "Those images will keep our foes distracted for a time, but they will not give up their pursuit so easily.\n\nWe must make haste!" }
WordHunterWoW_QuestEN[59755] = { title = "A Flight from Darkness", description = "There's a cave not far from here. If we hurry, we can seek refuge.\n\nThose fiends will give chase if they spot us. Be prepared for a fight!", objectives = "Escort the assembled forces from Calcis to Forlorn Respite.", progress = "This way!", completion = "Rest here while you can, <name>.\n\nI will tell you what I know." }
WordHunterWoW_QuestEN[59756] = { title = "A Moment's Respite", description = "Anduin insisted that our allies would come for us. I confess I had begun to doubt him.\n\nI'm sure you have many questions. I'll do what I can to provide answers, but I'm afraid even after... \n\nWhat has it been... weeks? Longer? Time loses all meaning in a place of such darkness.\n\nForgive me. Let me tell you what little I can.", objectives = "Speak with Jaina in Forlorn Respite to learn what she knows about the Maw.", progress = "I will tell you what I can.", completion = "I need time to recover after that battle. Thrall could use rest, too.\n\nWhile we rest, perhaps you and Mograine can seek answers." }
WordHunterWoW_QuestEN[59757] = { title = "Field Seance", description = "If these souls have information we need, we will take it from them.\n\nEven after being shattered by the Banshee, the helm fragment given to you by Bolvar holds the power of Domination. With it, we should be able to take control of the spirits long enough to find out what they know.\n\nThey will need to be sufficiently weakened before we can break them. I'm confident you're more than capable of that task.", objectives = "Use the Shattered Helm of Domination to command 5 Malice Shadows in the Planes of Torment.", progress = "Do you wish to speak to me, or to the dead?", completion = "Useless! These souls are far too fragmented to provide us with anything.\n\nWait... what is that?" }
WordHunterWoW_QuestEN[59758] = { title = "Speaking to the Dead", description = "Look over to the ridge. There lies our quarry!\n\nNo telling how many souls are writhing together within that amalgam. With any luck, one of them might be coherent enough to give us answers.", objectives = "Use the Shattered Helm of Domination to command the Tormented Amalgamation in the Planes of Torment.", progress = "What are you waiting for?", completion = "Find enough mouths and one of them is bound to speak. \n\nLet's bring this thing back to the cave and find out what it knows." }
WordHunterWoW_QuestEN[59759] = { title = "The Lion's Cage", description = "Anduin is being kept in a place the shades call the Tremaculum. It's not far, but the way is perilous.\n\nI have tried more than once to free him from his captors, but the forces holding him are too great for me to handle alone.\n\nI'm counting on your presence to tip the scales.", objectives = "Find King Anduin Wrynn in the Tremaculum.", completion = "I knew in my heart the Light wouldn't fail us.\n\nYour presence here is the proof." }
WordHunterWoW_QuestEN[59760] = { title = "The Afflictor's Key", description = "Sylvanas thinks us broken. She believes she has already won.\n\nWe will show her how mistaken she is.\n\nFirst, I will need your help. The bonds that hold me are impossibly strong. We will need the key to free me of them.\n\nMy... imprisonment here has been overseen by a creature they call the Afflictor. The key is likely in its possession.", objectives = "Collect the Afflictor's Key from Phael the Afflictor in the Tremaculum and unlock the Mawforged Shackles.", progress = "Did you find the key?", completion = "I had almost forgotten the feeling of freedom.\n\nNow, let us take the fight to these fiends." }
WordHunterWoW_QuestEN[59761] = { title = "An Undeserved Fate", description = "I have seen many souls brought here during my detention. The Jailer seems to want to break them, to twist them into his service... or worse.\n\nNo soul deserves such a fate, {name}.\n\nThe Mawsworn here hold the keys to their chains. Free as many as you can and we'll get them away from here.", objectives = "Collect Mawsworn Keys from Mawsworn forces in the Tremaculum and use them to free 15 Shackled Souls.", progress = "Free those souls, <name>. They should not be bound here.", completion = "I knew I could trust you with this task. \n\nThough we face insurmountable odds, we must try to do what is right." }
WordHunterWoW_QuestEN[59762] = { title = "By and Down the River", description = "Our next step is clear. We must travel to Zovaal's Cauldron--a frightful place I've heard spoken of in fanatical whispers. It's a forge of sorts that lies across the River of Souls.\n\nI have only been there a handful of times, but I have seen Baine held captive by the soldiers there. If fortune favors us, he'll still be nearby.\n\nOnce he's safe, we can see about finding this waystone the shade spoke of.", objectives = "Cross the bridge over Gorgoa, the River of Souls.", progress = "We must hurry!", completion = "The Jailer has Baine!\n\nThis is worse than we feared..." }
WordHunterWoW_QuestEN[59765] = { title = "Wounds Beyond Flesh", description = "Even as Baine's flesh mends, his spirit draws closer to death. I have seen dark magic like this before... among the Shadowmoon clan.\n\nThe Jailer's minions must have inflicted a similar malady upon Baine. \n\nThe only cure for the Shadowmoon's curse was to find the object they used to poison the spirit and shatter it.\n\nThe sorcerers of this realm wield ornamental daggers. That might be what we're looking for.\n\nWe must find the one that they used on Baine--quickly!", objectives = "Collect a Wither Blade from a Mawsworn Soulrender in Detrithos.", progress = "We can only hope Baine's curse was inflicted by one of the sorcerers here.", completion = "We were fortunate to find the sorcerer who poisoned Baine's spirit.\n\nI will need your help breaking its link to the High Chieftain." }
WordHunterWoW_QuestEN[59766] = { title = "A Good Axe", description = "I was a damned fool for throwing my axe at that sea hag. We can't afford to lose focus.\n\nThe battle ahead won't be easy. I'll need another weapon to help us fight to the waystone.\n\nLooks like these soldiers have plenty of armaments. Let's keep an eye out for one I can use.", objectives = "Find a suitable weapon for Thrall amongst the Mawsworn Armaments in Detrithos.", progress = "There should be something I can use around here...", completion = "This lacks the balance and craftsmanship of a good Frostwolf axe, but it will have to do.\n\nLet's get moving." }
WordHunterWoW_QuestEN[59767] = { title = "The Path to Salvation", description = "We must move quickly if we wish to find the waystone. The soul mentioned it overlooks the Cauldron, which would put it somewhere upon the ridge on the other side.\n\nUnfortunately, this area is swarming with enemy forces. We'd best avoid engaging them, lest we draw the Jailer's attention.\n\nI can shield us from sight, but we all have to stay together.", objectives = "Lead your allies past Zovaal's Cauldron.", progress = "Stay close. We cannot risk being seen by the Jailer's forces.", completion = "We made it! \n\nIf we can activate this waystone, we just might be able to escape this place!" }
WordHunterWoW_QuestEN[59770] = { title = "Stand as One", description = "<Anduin examines the obelisk intently.>\n\nI've never seen markings like these before. I've studied titan artifacts, but this appears to be made by a different hand. \n\nHmm. It doesn't respond to me. I think Jaina's right. The waystone is reacting to your presence.\n\nPerhaps you'll have better luck activating it.\n\nStay on your guard. The Jailer's forces paid this no mind when it was dormant, but there's no telling what they'll do if that changes.", objectives = "Activate the Eroded Waystone in Cocyrus.", completion = "<The waystone appears to be waiting for something.\n\nYou reach out and touch its surface...>" }
WordHunterWoW_QuestEN[59771] = { title = "History of Corruption", description = "", objectives = "" }
WordHunterWoW_QuestEN[59772] = { title = "Research Ruination", description = "The Cult of the Damned continue their work within the halls of Aldur'thar. \n\nInfiltrate their chambers and destroy their research. It may not stop them, but it will buy us valuable time.", objectives = "Destroy 5 Research Notes at Aldur'thar.", progress = "Making progress?", completion = "We will see how long this postpones their efforts." }
WordHunterWoW_QuestEN[59773] = { title = "Seek the Ascended", description = "When you arrive in Bastion, seek out one of the kyrian. Explain that you require an audience with the Archon. Like the Arbiter, she is one of the Eternal Ones who rule over the Shadowlands.\n\nIf anyone can guide you to the truth, it is the Archon. Perhaps she will even know a way to end this anima drought.\n\nOnce you find the answers you seek, you are welcome to return to Oribos.\n\nPurpose guide your path, mortal.", objectives = "Journey to Bastion to inquire about the Maw kyrian.", completion = "The way is open again! Archon be praised!" }
WordHunterWoW_QuestEN[59774] = { title = "Welcome to Eternity", description = "Forgive my reaction. You see, the way from Oribos has been closed for quite some time. We did not know if it would ever open again.\n\nI welcome you, noble soul, to Bastion. Your deeds in life have earned you a most glorious fate! You are to become a kyrian, a winged bearer of the dead.\n\nMy name is Kleia. It would be an honor to introduce you to our beautiful realm. There is much you must learn before your journey can begin.\n\nGather yourself. When you are ready, we will venture on.", objectives = "Speak with Kleia.", completion = "The Greeter will soon answer all of your questions. That is its purpose, after all.\n\n<Kleia smiles at you.>\n\nI hope you are excited. I certainly am!" }
WordHunterWoW_QuestEN[59775] = { title = "Help Indigo find Penthia", description = "", objectives = "" }
WordHunterWoW_QuestEN[59776] = { title = "From the Mouths of Madness", description = "I cannot express my gratitude enough for your help, champion. \n\nWe mustn't linger, however. The Jailer's forces will soon be alerted to the disturbance here.\n\nLet us leave this place at once!", objectives = "Return to Lord Darion Mograine in Forlorn Respite and see what he has learned.", progress = "The fiend is ready to talk. Let's get on with it.", completion = "I cannot say I enjoyed wielding the Helm of Domination. The magic it holds is... unsettling to the dead.\n\nI gladly return it to your care." }
WordHunterWoW_QuestEN[59777] = { title = "Help Calix find Amethia", description = "", objectives = "" }
WordHunterWoW_QuestEN[59778] = { title = "Help Sawn find Varrik", description = "", objectives = "" }
WordHunterWoW_QuestEN[59779] = { title = "Help Moriaz find Buttons", description = "", objectives = "" }
WordHunterWoW_QuestEN[59781] = { title = "The Last Guy", description = "You're not the first newcomer wanting to become famous. There've been a lot like you around! \n\nThe last few wanted to prove themselves by killing a giant bloodtusk... none of them ever returned! You want to get recognition?\n\nGo find all those missing newcomers and kill the bloodtusk yourself.", objectives = "Find 5 Newcomer Corpses and slay Deadeye.", progress = "Did you prove yourself?", completion = "Too bad about the last few, but you're still here!" }
WordHunterWoW_QuestEN[59782] = { title = "The Deathspeaker's Devout", description = "Though Deathspeaker Kharos has long since been slain, the cultists in the nearby mountains continue his nefarious work.\n\nClearly emboldened by the Scourge's resurgence and the rift in the sky, they once again kidnap our crusaders and perform their abhorrent alchemical experiments.\n\nGo forth and purge those fanatics from their camp.", objectives = "Kill 6 Dark Ritualists and 6 Dark Zealots at Deathspeaker's Watch.", completion = "My, you made quick work of them.\n\nWe will continue to monitor the area and report any cultist activity to the justicar." }
WordHunterWoW_QuestEN[59783] = { title = "Cultist Captors", description = "Those damned cultists are relentless!\n\nThey caught us off guard and managed to drag a few of our crusaders back to their camp.\n\nLight only knows what they're doing to them up there...\n\nWord is you're quite capable of holding your own. Our numbers are stretched thin enough as it is... if you could rescue the captives, we'd be in your debt.\n\nYou can find the cultists lurking up in their mountain camp.", objectives = "Retrieve the Interrogator's Key from Interrogator Grell. Rescue 8 Captive Aspirants at Deathspeaker's Watch.", progress = "What news have you?", completion = "Why am I not surprised? You almost make it look too easy." }
WordHunterWoW_QuestEN[59789] = { title = "Tithe and Taxes", description = "", objectives = "" }
WordHunterWoW_QuestEN[59800] = { title = "Team Spirit", description = "Even if we're competing against each other, we're all Maldraxxi. That means we cheer on everyone, regardless of which side they're on.\n\nEnter the arena and douse the challengers with the contents of this flask. It may give them the edge they need to survive combat!", objectives = "Douse 15 Arena Challengers with the Flask of Team Spirit.", completion = "Nice work firing up the combatants. They'll remember you helped them... if they survive." }
WordHunterWoW_QuestEN[59801] = { title = "Take the Power", description = "Wait! Before you enter, I would ask something of you.\n\nWhile we have not had a wildseed in some time, we did keep stores of anima. It served us well in staving off the gorm.\n\nWhatever has happened to my village, I do not want this power to remain in their hands. It will better serve Ardenweald in other groves.\n\nKeep an eye out for any anima within the village. We will put it to better use elsewhere.", objectives = "Collect 8 Animacones.", progress = "Were you able to find any anima?", completion = "May this find use in the forest. May their losses not be in vain." }
WordHunterWoW_QuestEN[59802] = { title = "The Crumbling Village", description = "This journal belonged to Lewor, the leader of our grove. It says he found something to use against the gorm, but what if it caused all this?\n\nThere is only one way to be sure. Come with me to the village. Or what remains of it.", objectives = "Follow Partik.", completion = "N-no... the village. They are all...." }
WordHunterWoW_QuestEN[59803] = { title = "For Honor", description = "", objectives = "" }
WordHunterWoW_QuestEN[59804] = { title = "Gateways of Horror", description = "", objectives = "" }
WordHunterWoW_QuestEN[59805] = { title = "Maw Manifested", description = "Ya heard it from Mueh'zala himself... tanks to ol' Bwonsamdi. Dere be an ancient spirit trapped in da Maw. Me bettin' da Winter Queen gonna want it back.\n\nGood ting ya been goin' down dere yaself, hm? Should be nice an' easy for ya.\n\nMe gonna clean up da rest of da undead here. Meet ol' Bwonsamdi in Ardenweald when ya get back.", objectives = "Travel to the Maw to find the lost wild god of Ardenweald.", completion = "All me trainin' as a shadow hunter been leadin' ta dis moment. \n\nTrackin' a spirit inside da Maw and savin' dem from eternal torture..." }
WordHunterWoW_QuestEN[59808] = { title = "Muck It Up", description = "", objectives = "" }
WordHunterWoW_QuestEN[59809] = { title = "On De Other Side", description = "Ay dere, {name}... It be your ol' friend, Bwonsamdi!\n\nI hear ya be workin' for da Winter Queen. Seems ya be makin' quite a name for yaself!\n\nArdenweald be in grave danger, but da Queen... well, she be too proud to deal with ol' Bwonsamdi.\n\nYa wanna save da forest, mon? Come visit me on da Other Side.\n\nI gonna be waitin' for ya...", objectives = "Use the deathstone to travel to the Other Side.", completion = "Welcome to da Other Side!\n\nWhat ya tink, mon? Ya like what I done wit' da place?" }
WordHunterWoW_QuestEN[59810] = { title = "[DNT]Just A Small Request", description = "Morbi eget nibh eu nisl sollicitudin ultricies. Aliquam iaculis est quis aliquet auctor.\n\nAenean lobortis finibus justo eget vehicula. Fusce ut magna dolor. Donec vehicula a erat finibus volutpat. Nulla auctor sagittis vulputate. Vestibulum laoreet neque ut enim malesuada posuere.\n\nAenean sed tortor quam. In egestas non arcu vitae consequat. Cras augue ipsum, imperdiet nec dui id, ullamcorper ultrices nisi. Praesent accumsan leo sed accumsan lobortis.", objectives = "" }
WordHunterWoW_QuestEN[59811] = { title = "Taking Inventory", description = "Dark forces be at work, {class}. \n\nArdenweald be where loa go ta be reborn after dey die on Azeroth. But some of da loa who be sleepin' in Ardenweald have gone missin'!\n\nGotta be someone powerful behind it, takin' dem from right under da Winter Queen...\n\nOl' Bwonsamdi can't be havin' loa vanishin' from Ardenweald. Dat could be me someday! No, no... we gonna put a stop to dis!\n\nGo back ta Ardenweald and search for da missin' loa.", objectives = "Search the Tranquil Pools for missing loa pods.", progress = "Dark forces be at work in Ardenweald...", completion = "So Hakkar and Dambala be da ones gone missing? Hmm... we'd better find out where dey went!" }
WordHunterWoW_QuestEN[59812] = { title = "Following the Trail", description = "I got a bad feelin' about dis, mon.\n\nWildseeds don't just go missing... especially da kind wit' powerful loa in dem! Even da bad eggs like Hakkar and Dambala be protected by da Winter Queen. Someone... or someting... must be stealin' dem!\n\nBut why? Dey weren't even ready ta be reborn...\n\nSearch da area and see if ya can pick up da trail. Missing loa be bad for business... and Bwonsamdi be in enough trouble wit' da boss already!", objectives = "Search for clues leading to the missing loa.", progress = "Hakkar and Dambala both gone missin' at da same time? Oh, I got a bad feelin' about dis...", completion = "Da tracks lead into da grove up ahead. I got a feelin' Hakkar and Dambala be somewhere nearby..." }
WordHunterWoW_QuestEN[59813] = { title = "Minions of Mueh'zala", description = "Dese all be followers of Mueh'zala! Me shoulda known he be da one behind it all.\n\nMueh'zala be da loa of death from long ago. It be him who raised up Ol' Bwonsamdi, him who made me a loa.\n\nDat be before his worshippers started turnin' away from him. He always been a greedy one... but dis...\n\nMueh'zala be goin' too far dis time! We gotta stop him, or he gonna take all da loa in Ardenweald!", objectives = "Defeat High Priest Rakazodu and 8 Mueh'zala forces.", progress = "Mueh'zala be goin' too far dis time!", completion = "Ya did good! But dis be far from over..." }
WordHunterWoW_QuestEN[59814] = { title = "[DNT] Words of Mueh'zala", description = "", objectives = "" }
WordHunterWoW_QuestEN[59815] = { title = "Stolen Loa", description = "Hakkar and Dambala be somewhere in da grove.\n\nWe need ta hurry and find out what Mueh'zala be up to. Dem two loa been mighty powerful on Azeroth... powerful and evil. Who knows what Mueh'zala be plannin' for dem!\n\nSearch da Spirit Glen. Find da missing loa and see what Mueh'zala be meanin' ta do!", objectives = "Locate Hakkar the Soulflayer and Dambala.", progress = "We gotta know what be happenin' ta da missin' loa!", completion = "It all be makin' sense now. Mueh'zala be draining anima outta da other wildseeds so he can be wakin' Dambala and Hakkar before their time.\n\nDa Winter Queen gotta be told 'bout dis before it too late..." }
WordHunterWoW_QuestEN[59816] = { title = "[DNT] Bwonsamdi's Plan", description = "", objectives = "" }
WordHunterWoW_QuestEN[59817] = { title = "Winter Be Comin'", description = "Da boss be puttin' together an army of terrible loa. Hakkar and Dambala may only be da beginnin'. How da boss get so strong? I not be seein' him use power like dis before...\n\nDa Winter Queen not be fond of ol' Bwonsamdi, but we gonna need her help to stop Mueh'zala.\n\nYa be friendly wit' da Queen, no? If she be willin' to rally her forces, we might be able to stop Mueh'zala before it be too late.\n\nHead to da Heart of da Forest and speak wit' da Queen. She be our only hope now.", objectives = "Gain an audience with the Winter Queen.", progress = "We gotta convince da Winter Queen to join forces against Mueh'zala...", completion = "I am not eager to do any favors for Bwonsamdi, but Mueh'zala's actions cannot be ignored." }
WordHunterWoW_QuestEN[59818] = { title = "Gathering The Hunt", description = "Loath as I am to aid Bwonsamdi, Mueh'zala must be made to answer for his crimes.\n\nWe will eradicate his worshippers and drive them from the forest before they cause more harm.\n\nRally the groves and muster the Wild Hunt. Ardenweald has need of its protectors.\n\nMake haste, huntsman.", objectives = "Gather the Wild Hunt to Tirna Noch in Ardenweald.", completion = "You're just in time. The Wild Hunt is locked in battle with Mueh'zala's forces." }
WordHunterWoW_QuestEN[59819] = { title = "Cleansing the Forest", description = "The Winter Queen has commanded us to drive Mueh'zala's forces out of Ardenweald.\n\nThis won't be an easy battle. The death loa's army is strong, and several of our hunters have been gravely injured.\n\nCan we count on you to turn the tide in our favor, {name}?\n\nAid our fallen allies and vanquish Mueh'zala's minions!", objectives = "Aid the Wild Hunt in their fight against the forces of Mueh'zala.", progress = "The fight is far from over.", completion = "The Wild Hunt can handle pushing the rest of them out of the forest. Well done, <name>!" }
WordHunterWoW_QuestEN[59821] = { title = "Report to the Queen", description = "Mueh'zala's forces are routed, and it's only a matter of time before the Wild Hunt completely purges them from Ardenweald.\n\nBut something tells me that the struggle between Bwonsamdi and Mueh'zala is far from over. That creepy little mask has gone silent...\n\nYou should hurry back to the Heart of the Forest and report to the Winter Queen. She will decide what we do next.", objectives = "Speak with the Winter Queen.", completion = "Welcome news, indeed. I will not soon forget Mueh'zala's transgressions." }
WordHunterWoW_QuestEN[59822] = { title = "Tracking a Wild God", description = "Dis be a dark place, {name}. We gotta track down da spirit who be trapped here.\n\nMe tink me can pick up its trail... but dat be all dis ol' shadow hunter can do.\n\nIf me be tryin' ta fight wit' ya, da threads dat be tyin' me ta Azeroth might break. Den I gonna be stuck here, too.\n\nC'mon. We best be moving.", objectives = "Track down the missing spirits of Ardenweald.", completion = "We ain't done wit' dis place yet. Dere be loa trapped here!" }
WordHunterWoW_QuestEN[59824] = { title = "Loa Rescue", description = "We be here for Ashamane, but me sensin' loa bein' tortured up ahead. Three of dem, if me be right.\n\nMe don't know who dey be, but dey don't belong in da Maw.\n\nWe need ta be bringin' dem back ta Ardenweald, too!", objectives = "Find and rescue the three loa trapped within the Maw.", completion = "Rezan be needin' us!" }
WordHunterWoW_QuestEN[59825] = { title = "Seed Hunting", description = "", objectives = "" }
WordHunterWoW_QuestEN[59826] = { title = "Bet On Yourself", description = "Dear Maw Walker... my friend... you're going to lose. Everyone knows you can't compete in the arena. \n\nThe entire Challenger's Promenade knows it, the brokers in Oribos know it, even Zo'umlo knows it.\n\nI've brought in a special challenger just to prove the point. Face Mistress Dyrax in the Theater of Pain and prove us wrong... or prove us right.\n\nWe will be betting, so don't disappoint.", objectives = "Defeat Mistress Dyrax in the Theater of Pain, when she appears.", progress = "What did you prove?", completion = "Your performance has netted me a nice profit... Zo'umlo bet poorly." }
WordHunterWoW_QuestEN[59827] = { title = "Bet On Yourself", description = "Dear Maw Walker... my friend... you're going to lose. Everyone knows you can't compete in the arena. \n\nThe entire Challenger's Promenade knows it, the brokers in Oribos know it, even Zo'umlo knows it.\n\nI've brought in a special challenger just to prove the point. Face Devmorta in the Theater of Pain and prove us wrong... or prove us right.\n\nWe will be betting, so don't disappoint.", objectives = "Defeat Devmorta in the Theater of Pain, when he appears.", progress = "What did you prove?", completion = "Your performance has netted me a nice profit... Zo'umlo bet poorly." }
WordHunterWoW_QuestEN[59828] = { title = "Bet On Yourself", description = "Dear Maw Walker... my friend... you're going to lose. Everyone knows you can't compete in the arena. \n\nThe entire Challenger's Promenade knows it, the brokers in Oribos know it, even Zo'umlo knows it.\n\nI've brought in a special challenger just to prove the point. Face Ti'or in the Theater of Pain and prove us wrong... or prove us right.\n\nWe will be betting, so don't disappoint.", objectives = "Defeat Ti'or in the Theater of Pain, when she appears.", progress = "What did you prove?", completion = "Your performance has netted me a nice profit... Zo'umlo bet poorly." }
WordHunterWoW_QuestEN[59836] = { title = "Battles Won Long Ago", description = "", objectives = "" }
WordHunterWoW_QuestEN[59837] = { title = "Working for the Living", description = "I see you are wondering where we acquire all of the challengers we supply to this arena.\n\nWe scour countless realms in search of opponents to provide the Maldraxxi with firsthand combat experience. \n\nCurrently, I am in the process of procuring a new combatant--and with it, a lucrative betting opportunity. \n\nWould you make use of our portal and assist Zo'umlo in capturing Khogov the Expunger? You will be appropriately compensated, of course.", objectives = "Shattered Grove secured and Khogov the Expunger captured.", progress = "Have you successfully captured Khogov the Expunger?", completion = "Competing in the arena is but one way to contribute to this venture. There are many other tasks to perform, as well." }
WordHunterWoW_QuestEN[59838] = { title = "Scourge War Machines", description = "The Scourge's war machines make it exceedingly difficult for us to gain ground. They must be our top priority.\n\nThough they are well protected, we must destroy them if we are to clear a path for our ground forces and grant them an opportunity to strike.\n\nPlant these charges underneath the war machines and then clear the area.", objectives = "Destroy 5 Scourge War Machines in The Conflagration.", completion = "A job well done, <name>.\n\nNow our forces can advance without worrying about the enemy's weaponry." }
WordHunterWoW_QuestEN[59839] = { title = "WARNING: This is Only a Test!", description = "Where some see a problem, I see an opportunity. What this Scourge fiasco calls for is a creative solution!\n\nBehold--my \"secret weapon\"!\n\nControlled by none other than my Carefully Constructed Control Device, or C.C.C.D. for short!\n\nHmm, that name might need a little work.\n\nYou're the first to see it, so that means you'll be the first to test it. But don't worry, I'm pretty sure it's safe.\n\nGood luck!", objectives = "Successfully complete the testing of Fizzix Blastbolt's \"Secret Weapon\" at Deathspeaker's Watch.", progress = "So, how's it goin'?", completion = "Oh boy! Did you see the look on their faces?\n\nI mean, some of them didn't really have faces, but you know... their jaws and whatnot. Hah!\n\nThat was great. The possibilities are endless!" }
WordHunterWoW_QuestEN[59840] = { title = "Divine Gratitude", description = "Many thanks for restoring my power and vigor.\n\nMy path will now lead me back to my people, but it is only right that you are rewarded for your efforts.", objectives = "Accept the boon offered by the deity." }
WordHunterWoW_QuestEN[59846] = { title = "Finders-Keepers, Sinners-Weepers", description = "Oh hello, mortal. You have a real knack for arriving at the most opportune times. I wonder what Taskmaster Matyas wants with you. Curious.\n\nAs for me, again Matyas has used my sinstone against me. I was already enraged that he caged me and I assure you that this latest attack will not go unanswered. Yet, while he has my sinstone I am unable to act against him directly. So we must remedy that.\n\nYou question the laborers and I will read this journal while I regain my strength.", objectives = "Discover the secrets of Taskmaster Matyas's efforts in Feeder's Thicket.", progress = "Have you discovered anything useful?", completion = "Ah. A pity none of these are mine. Still they may prove useful." }
WordHunterWoW_QuestEN[59847] = { title = "Defending the Rampart", description = "The Scourge are assaulting our outpost! We must defend it at all costs!\n\nSlay as many of the fiends as you can!", objectives = "Defend against the Scourge attack atop the Ironwall Rampart." }
WordHunterWoW_QuestEN[59848] = { title = "Tea Tales: Theotar", description = "", objectives = "" }
WordHunterWoW_QuestEN[59850] = { title = "Tea Tales: Vulca", description = "", objectives = "" }
WordHunterWoW_QuestEN[59851] = { title = "Frozen Solid", description = "The breath of a frost wyrm can freeze even its largest foes in an instant. Our forces, unfortunately, have experienced this firsthand.\n\nTheir advance toward the citadel has come to a halt. I fear we may lose our foothold unless we act quickly.\n\nTake this potion and use it to free our forces from their frigid bonds. Light be with you.", objectives = "Rescue 12 Frozen Allies at the Court of Bones.", progress = "Always keep an eye to the sky.", completion = "Excellent work, <name>. We will see to it they recover in safety." }
WordHunterWoW_QuestEN[59852] = { title = "Tea Tales: Gubbins and Tubbins", description = "", objectives = "" }
WordHunterWoW_QuestEN[59853] = { title = "Tea Tales: Lost Sybille", description = "", objectives = "" }
WordHunterWoW_QuestEN[59855] = { title = "Major Mirror Disruptions", description = "", objectives = "" }
WordHunterWoW_QuestEN[59856] = { title = "Rezan, Loa of Kings", description = "Rezan be a powerful loa, one of great importance ta da Zandalari.\n\nWe need ta rescue him... but dis creature be projectin' a barrier of death. Notin' be gettin' in.\n\nUnless... I be usin' me own anima ta shield ya from its magic.\n\nYa gotta act fast and kill da monster dat be drainin' Rezan. Me anima not gonna last forever.\n\nSay da word when ya ready ta go.", objectives = "Accept some of Vol'jin's anima to protect yourself, then slay Exhaurbius to save Rezan.", progress = "We need ta save Rezan!", completion = "Me be feelin' Rezan's essence inside of me... he be trustin' me wit' a great gift.\n\nNo matter what be comin' next, me not gonna let him down." }
WordHunterWoW_QuestEN[59862] = { title = "A Savior for Lost Souls", description = "The forest sighs in greeting, Maw Walker.\n\nYour arrival was written in the stars, and awaited by the boughs. Now our work begins. \n\nLet us proceed.\n\nFollow this path into the grove.\n\nThese are but the first steps on our journey together.", objectives = "Walk with the Warden to the grove.", progress = "Our paths converge. Together we walk.", completion = "Your presence warms the grove.\n\nNow we learn, and grow." }
WordHunterWoW_QuestEN[59863] = { title = "Combat Nullifier 07-X", description = "While everyone is busy fending off our enemies with swords and magic, how about we try something different.\n\nBehold, my latest invention--the Combat Nullifier 07-X!\n\nWith this device, no enemy is truly your enemy any longer!\n\nNow, I haven't quite worked out the exact energy modulator calculations, but I am certain it works. Mostly.\n\nFor now, we'll need to \"borrow\" some energy from our enemies in order to operate it.\n\nGo ahead. Charge it up and give it a whirl!", objectives = "Charge the Power Containment Module to Blast 5 enemies with the Combat Nullifier 07-X at Sindragosa's Fall.", progress = "How's it going?", completion = "Whoa! That was a blast, huh?" }
WordHunterWoW_QuestEN[59865] = { title = "Glimmerflight", description = "This so exciting!\n\nCome, another test is in order. I can hardly wait!", objectives = "Observe Kowalskos' test flight.", completion = "I did it! I flew!\n\nI have adjustments I can make. Here, take these glimmerflies as thanks. I will collect more!" }
WordHunterWoW_QuestEN[59866] = { title = "Parting Ways", description = "Me don't know what fate be comin' for ol' Vol'jin... but it be waitin' for me in Ardenweald.\n\nAshamane, Hir'eek, Shadra... dey belong dere, too.\n\nWe best be gettin' outta here. Me had enough of da Maw for an eternity.", objectives = "Return the lost loa and Vol'jin to the Winter Queen in Ardenweald.", completion = "It fills me with joy to know that the spirits lost to the Maw are safe once more.\n\nNone can say what fate has in store for Vol'jin. The path on which he has embarked has never before been walked by a mortal soul.\n\nYet whatever awaits him, know that your efforts are what made it possible." }
WordHunterWoW_QuestEN[59867] = { title = "WANTED: Appraiser Vix", description = "For failure to pay debts upon lost wagers, theft of arena property, and for the slaughter of an authorized debt collector. All necessary violence is hereby sanctioned when confronting Vix.\n\nSpecial warning to be on the lookout for numerous associates who have demonstrated a violent attitude toward outsiders.\n\nElimination of this felon is of the highest priority.", objectives = "Eliminate Appraiser Vix", progress = "Eliminate Appraiser Vix.", completion = "Excellent work, Maw Walker. I shall dispatch Zo'umlo to retrieve our stolen property." }
WordHunterWoW_QuestEN[59868] = { title = "Offer of Freedom", description = "Just as I was, some of the Briarbane venthyr you encounter will have been compelled to serve Matyas. They likely will not want to fight you, but will have no choice. Once they are injured, they may be willing to pause to see if one of the sinstones you recovered earlier is theirs.\n\nFree those you can. The use of a sinstone to compel others isn't fair.", objectives = "Weaken Briarbane venthyr and then offer them a sinstone.", progress = "Have you released the compelled venthyr?", completion = "You've made some friends today." }
WordHunterWoW_QuestEN[59870] = { title = "[OLD NOT USED]", description = "", objectives = "" }
WordHunterWoW_QuestEN[59871] = { title = "Catalyze This", description = "The grove grows in power, and so shall the spirits it shelters.\n\nYou have nurtured a spirit to rebirth on your own. Now you must learn to make use of catalysts.\n\nWhen planted near a wildseed, catalysts grant the slumbering spirit strength beyond what it knew in life. Strength that it retains when reborn.\n\nCatalysts are special and rare, though I have one here for you to use. Others can be found across the Shadowlands.\n\nFor now, plant the catalyst and witness the potential it holds.", objectives = "Use the catalyst on the catalyst plot.", completion = "Nature holds as many secrets as it does gifts." }
WordHunterWoW_QuestEN[59872] = { title = "How to Save a God", description = "Many mortal souls suffer within the Maw. But so too do many spirits of Nature.\n\nAnima alone cannot heal wounds inflicted by the Jailer. Spirits plucked from his grasp must be planted anew and tended with care.\n\nThese wildseeds are unlike any other. This grove, unlike any other. Within them lies dormant hope, a chance for even the weakest spirit to be reborn.\n\nOne such as this. Lay this spirit to rest within a wildseed. Let its rebirth begin.", objectives = "Place the Soul Seed into the wildseed.", progress = "Let fate and compassion guide your hand.", completion = "Your skills take root, Maw Walker." }
WordHunterWoW_QuestEN[59873] = { title = "Greeting a God", description = "Soon, the moment of the spirit's rebirth will be nigh. A fate all but extinguished by the Maw, rekindled by grove and caretaker.\n\nTime will be the spirit's salve. Once enough of it has passed, lay your hands upon the wildseed and awaken them.", objectives = "Wait for the spirit to finish incubating, then open the wildseed.", progress = "Patience is the way of the forest.", completion = "And so a god is reborn by the hand of a mortal.\n\nThey greeted you with gratitude, yes? And perhaps surprise, as well." }
WordHunterWoW_QuestEN[59874] = { title = "The Maw", description = "{name}, your arrival has set Maldraxxus ablaze. If you have any honor, you will do as I ask.\n\nI believe I know where our answers may lie. The baron preceding Draka was lost to the Maw. It is said you have entered that dark abyss... and returned.\n\nIf the baron survived, he may know our next course of action.\n\nYou came here from Oribos. Return there, and see if you can find a way back to the Maw.", objectives = "Speak with Bolvar in Oribos.", completion = "What news from Maldraxxus, <name>?" }
WordHunterWoW_QuestEN[59876] = { title = "Field Reports", description = "The Scourge can strike anytime, anywhere.\n\nTo counter their unpredictability, the Argent Crusade has secured key locations along the southern road heading east. However, I have yet to receive any reports from our scouts in the field.\n\nWith the erratic nature of these attacks, I fear the worst.\n\nTravel the road and take stock of our outposts. I'll be expecting a full report when you return.\n\nLight be with you, {name}.", objectives = "Gather reports from officers in Elwynn Forest, Redridge Mountains and Duskwood.", progress = "Gregor sent you?", completion = "This is far worse than we thought.\n\nCommander Gregor must be told of the true extent of the Scourge's resurgence." }
WordHunterWoW_QuestEN[59877] = { title = "A Message from Icecrown", description = "We received word from our forces in Northrend. Justicar Trueheart requests our immediate assistance.\n\nAs you are an experienced {class}, I ask that you answer the call.\n\nThe urgency of this summons cannot be ignored, even if it means braving the terrors of Icecrown itself.\n\nI know you fear for the safety of everyone here. I will continue to coordinate our efforts and call in additional reinforcements.\n\nLight be with you, {name}.", objectives = "Report to Justicar Mariel Trueheart at the Argent Tournament Grounds in Icecrown.", completion = "You arrive just in time. Commander Gregor spoke highly of you." }
WordHunterWoW_QuestEN[59878] = { title = "Too Many Whelps", description = "We cannot hope to hold this ground if frostwyrms strafe the skies above us.\n\nCultists have been raising whelps from the dead nearby. The more of them we eliminate, the fewer monstrosities to breath deadly ice upon our forces.\n\nPut an end to their efforts.", objectives = "Kill 4 Wyrm Reanimators and 12 Frostbrood Whelps at Sindragosa's Fall.", completion = "A job well done, <name>. That should grant us a brief respite." }
WordHunterWoW_QuestEN[59879] = { title = "This Thing of Ours", description = "Au'narim is the top broker here. She keeps this place supplied with exotic creatures for us to fight in the arena. \n\nShe's noticed your efforts and wants to meet you!\n\nThis is important. A broker's backing could lead to an invitation to compete!", objectives = "Meet with Au'narim.", completion = "You must be one of these outsiders I hear so much about." }
WordHunterWoW_QuestEN[59882] = { title = "Sure Bet", description = "You appear to have great profit potential.\n\nThere are many interested parties willing to bet upon your performance in the Theater of Pain.\n\nGo now, Louison will arrange your appearance.", objectives = "Meet with LouisonYou appear to have great profit potential.\n\nThere are many interested parties willing to bet upon your performance in the Theater of Pain.\n\nGo now, Louison will arrange your appearance.You will receive:\n\nUpon completion of this quest you will gain:" }
